"""
llama3b_programs.py -- generated by make_programs.ipynb

Model:     meta-llama/Llama-3.2-3B
Shape:     28 layers x 24 heads = 672 programs
Signature: (sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]
Scoring:   soft IoU (min/max), higher is better

Self-contained: every helper the programs call is defined below. Generated
programs are written out verbatim -- there is no text-rewriting conversion step.
"""
from typing import Tuple

from transformers import PreTrainedTokenizerBase

import numpy as np

_MODEL_ID = 'meta-llama/Llama-3.2-3B'
_nlp = None
_emb = None


def _get_nlp():
    global _nlp
    if _nlp is None:
        import spacy
        _nlp = spacy.load("en_core_web_sm")
    return _nlp


def _get_embeddings():
    """Input-embedding matrix of the model under study, loaded once."""
    global _emb
    if _emb is None:
        from transformers import AutoModel
        m = AutoModel.from_pretrained(_MODEL_ID)
        _emb = m.get_input_embeddings().weight.detach().to("cpu").float().numpy()
    return _emb


def tokenize(sentence, tokenizer):
    """Model tokens for `sentence`, as strings. This is the tokenization every
    program must use -- the attention matrix is aligned to it."""
    ids = tokenizer(sentence, return_tensors="pt").input_ids[0]
    return tokenizer.convert_ids_to_tokens(ids)


def spacy_parse(sentence):
    """spaCy Doc: .pos_, .dep_, .head, .ent_type_, .lemma_ ..."""
    return _get_nlp()(sentence)


def _char_spans(sentence, tokenizer):
    """(start, end) char span per model token. Uses fast-tokenizer offsets when
    available, else falls back to cumulative decoded length."""
    try:
        enc = tokenizer(sentence, return_offsets_mapping=True)
        om = enc["offset_mapping"]
        if om and any(e > s for s, e in om):
            return [tuple(x) for x in om]
    except Exception:
        pass
    spans, pos = [], 0
    for t in tokenize(sentence, tokenizer):
        clean = t.lstrip("\u0120").lstrip("##").lstrip()
        idx = sentence.find(clean, pos) if clean else pos
        if idx < 0:
            idx = pos
        spans.append((idx, idx + len(clean)))
        pos = idx + max(len(clean), 1)
    return spans


def align_tokens_to_spacy(sentence, tokens, tokenizer):
    """For each model token, the indices of spaCy tokens it overlaps."""
    doc = _get_nlp()(sentence)
    spans = _char_spans(sentence, tokenizer)
    out = []
    for (s, e) in spans[:len(tokens)]:
        out.append([k for k, w in enumerate(doc)
                    if not (w.idx + len(w.text) <= s or w.idx >= e)])
    while len(out) < len(tokens):
        out.append([])
    return out


def align_spacy_to_tokens(sentence, tokens, tokenizer):
    """Inverse map: for each spaCy token, the model-token indices covering it."""
    doc = _get_nlp()(sentence)
    fwd = align_tokens_to_spacy(sentence, tokens, tokenizer)
    out = [[] for _ in doc]
    for ti, sids in enumerate(fwd):
        for si in sids:
            if si < len(out):
                out[si].append(ti)
    return out


def get_modifying_adjectives(token):
    """spaCy children of `token` that are adjectival modifiers."""
    return [c for c in token.children if c.dep_ in ("amod", "advmod")]


def embedding_similarity(tokens, i, j, tokenizer):
    """Cosine similarity between tokens[i] and tokens[j] in the model's own
    input-embedding space. Use this instead of string equality to catch
    morphological and semantic relatives ("heard"/"hear", "cat"/"kitten")."""
    emb = _get_embeddings()
    try:
        a = emb[tokenizer.convert_tokens_to_ids(tokens[i])]
        b = emb[tokenizer.convert_tokens_to_ids(tokens[j])]
    except Exception:
        return 0.0
    na, nb = np.linalg.norm(a), np.linalg.norm(b)
    if na == 0 or nb == 0:
        return 0.0
    return float(np.dot(a, b) / (na * nb))


def make_row_stochastic(matrix):
    """Normalize each row to sum to 1; uniform-causal fallback for dead rows."""
    m = np.asarray(matrix, dtype=np.float64).copy()
    m[m < 0] = 0.0
    for i in range(m.shape[0]):
        s = m[i].sum()
        if s <= 0:
            m[i, : i + 1] = 1.0 / (i + 1)
        else:
            m[i] /= s
    return m


def apply_causal_mask(matrix):
    """Zero the strict upper triangle: token i may only attend to j <= i."""
    return np.tril(np.asarray(matrix, dtype=np.float64))



def prog_L0H0(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with local grammatical attention; commas recruit clause anchors,
    while quoted clause onsets avoid treating the opening quote as content."""
    tokens = tokenize(sentence, tokenizer)
    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_punctuation_boundaries", attention

    attention[0, 0] = 1.0

    for i in range(1, n):
        current_ids = alignment[i]
        previous_ids = alignment[i - 1]
        word = doc[current_ids[0]] if current_ids else None
        previous = doc[previous_ids[-1]] if previous_ids else None

        pos = word.pos_ if word is not None else ""
        dep = word.dep_ if word is not None else ""
        previous_pos = previous.pos_ if previous is not None else ""

        # Probabilities assigned to BOS, previous token, and self.
        bos, prev, own = 0.86, 0.09, 0.03

        if pos in ("NOUN", "PROPN", "ADJ", "VERB"):
            bos, prev, own = 0.94, 0.025, 0.015
            if pos == "VERB" and dep in ("aux", "auxpass", "cop"):
                bos, prev, own = 0.48, 0.43, 0.07
        elif pos == "DET" or dep == "poss":
            bos, prev, own = 0.24, 0.70, 0.04
            if previous_pos in ("ADP", "VERB", "AUX", "ADV"):
                bos, prev, own = 0.055, 0.91, 0.015
            elif previous_pos in ("PUNCT", "SPACE"):
                bos, prev, own = 0.64, 0.25, 0.09
        elif pos == "PRON":
            bos, prev, own = 0.23, 0.70, 0.05
            if previous_pos in ("VERB", "AUX", "ADP"):
                bos, prev, own = 0.075, 0.88, 0.025
        elif pos == "PART":
            bos, prev, own = 0.12, 0.83, 0.03
            if dep == "case":
                bos, prev, own = 0.09, 0.86, 0.03
        elif pos == "AUX":
            bos, prev, own = 0.49, 0.42, 0.07
            if previous_pos == "PRON":
                bos, prev, own = 0.13, 0.81, 0.04
        elif pos == "ADP":
            bos, prev, own = 0.35, 0.54, 0.09
            if previous_pos in ("VERB", "ADJ"):
                bos, prev, own = 0.19, 0.75, 0.04
        elif pos == "ADV":
            bos, prev, own = 0.72, 0.19, 0.07
        elif pos in ("CCONJ", "SCONJ"):
            bos, prev, own = 0.28, 0.46, 0.24
        elif pos == "PUNCT":
            bos, prev, own = 0.57, 0.28, 0.13
        elif pos == "SPACE":
            bos, prev, own = 0.48, 0.37, 0.13

        # Lexical subpieces retain the content-word sink preference; grammatical
        # suffixes and adverbial continuations instead bind locally.
        continuation = (
            current_ids
            and previous_ids
            and current_ids[0] == previous_ids[-1]
        )
        if continuation and pos in ("ADV", "PART", "AUX"):
            bos, prev, own = 0.16, 0.78, 0.04

        if tokens[i] in tokenizer.all_special_tokens:
            bos, prev, own = 0.96, 0.01, 0.01
        else:
            # Boundary-only corrections conserve total mass and leave own intact.
            if pos == "PUNCT" and word.text == ",":
                anchors = []
                for j in range(i - 2, max(0, i - 13), -1):
                    ids = alignment[j]
                    anchor = doc[ids[-1]] if ids else None
                    if anchor is not None and (
                        anchor.pos_ in ("VERB", "AUX", "ADP", "CCONJ", "SCONJ")
                        or anchor.text in (",", ";", ":", ".", "!", "?")
                    ):
                        if not anchors or ids[-1] != alignment[anchors[-1]][-1]:
                            anchors.append(j)
                        if len(anchors) == 2:
                            break
                if anchors:
                    moved = bos - 0.05
                    bos = 0.05
                    prev += 0.20
                    share = (moved - 0.20) / len(anchors)
                    for j in anchors:
                        attention[i, j] += share

            elif (
                not continuation
                and previous is not None
                and previous.text in ('"', "'", "“", "‘", "«")
                and word is not None
                and (word.tag_ in ("WDT", "WP", "WP$", "WRB")
                     or pos in ("VERB", "AUX"))
            ):
                bos += prev - 0.08
                prev = 0.08

        attention[i, 0] += bos
        attention[i, i - 1] += prev
        attention[i, i] += own

        # Small causal recency tail captures weaker, non-dominant edges.
        for j in range(max(0, i - 6), i + 1):
            attention[i, j] += 0.02 * (0.5 ** (i - j))

    return (
        "bos_sink_with_punctuation_boundaries",
        make_row_stochastic(attention),
    )


def prog_L0H1(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Syntactically gated previous-token copying, with a two-token skip at
    fragmented words and negation boundaries; other weights remain unchanged.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "previous_token_with_fragment_skip", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    spans = _char_spans(sentence, tokenizer)

    words = []
    surfaces = []
    for i in range(n):
        candidates = alignment[i]
        word = None
        for k in candidates:
            if not doc[k].is_space:
                word = doc[k]
                break
        words.append(word)

        if i < len(spans):
            start, end = spans[i]
            surfaces.append(sentence[start:end].strip())
        else:
            surfaces.append(tokens[i].lstrip("Ġ").strip())

    attention[0, 0] = 1.0

    for i in range(1, n):
        if i == 1:
            attention[i, 0] = 0.85
            attention[i, i] = 0.15
            continue

        current = words[i]
        previous = words[i - 1]
        cp = current.pos_ if current is not None else ""
        pp = previous.pos_ if previous is not None else ""
        cd = current.dep_ if current is not None else ""
        pd = previous.dep_ if previous is not None else ""

        p_previous = 0.64
        self_share = 0.42

        if pp == "DET":
            if cp in ("ADJ", "ADV", "NUM"):
                p_previous = 0.88
            elif cp in ("NOUN", "PROPN"):
                p_previous = 0.80
        elif pd == "poss" and cp in ("ADJ", "NOUN", "PROPN"):
            p_previous = 0.78
        elif pp == "ADJ" and cp in ("NOUN", "PROPN", "ADJ"):
            p_previous = 0.76
        elif pp == "NUM" and cp == "NOUN":
            p_previous = 0.85
        elif pp == "PART" and cp == "VERB":
            p_previous = 0.81
        elif pp == "AUX" and cp in ("VERB", "ADJ", "ADV", "PART"):
            p_previous = 0.77
        elif pp == "CCONJ" and cp != "PUNCT":
            p_previous = 0.82
        elif pp == "ADP" and cp in ("DET", "PRON", "ADV"):
            p_previous = 0.75
        elif pp == "VERB" and cp in ("DET", "PRON"):
            p_previous = 0.71
        elif pp == "VERB" and cp in ("VERB", "ADV", "PART"):
            p_previous = 0.80
        elif pp in ("NOUN", "PROPN", "PRON") and cp in ("VERB", "AUX"):
            p_previous = 0.70

        if current is not None and previous is not None:
            if current.i != previous.i:
                linked = (
                    current.head.i == previous.i
                    or previous.head.i == current.i
                )
                if linked and cp != "PUNCT" and pp != "PUNCT":
                    p_previous = min(0.92, p_previous + 0.025)
            else:
                # Internal subword transitions are less uniformly dominant.
                p_previous = 0.62

        if pp == "PUNCT" and cp != "PUNCT":
            p_previous = 0.73

        if cp == "PUNCT":
            p_previous = 0.43
            self_share = 0.78
            if pp == "PUNCT":
                p_previous = 0.64
                self_share = 0.62

        if not surfaces[i]:
            p_previous = 0.88
            self_share = 0.45

        # Keep the copying edge's mass independent of sequence length.
        residual = 1.0 - p_previous
        attention[i, i - 1] = p_previous
        attention[i, i] = residual * self_share
        attention[i, 0] += residual * 0.42

        remaining = residual * (1.0 - self_share - 0.42)
        if remaining > 0.0:
            distances = i - np.arange(1, i - 1)
            weights = np.exp(-distances / 2.0)
            total = weights.sum()
            if total > 0.0:
                attention[i, 1:i - 1] += remaining * weights / total
            else:
                attention[i, 0] += remaining
        elif remaining < 0.0:
            attention[i, 0] += remaining

        # Fragmented words and contracted negation can split the copying
        # edge between the previous two model tokens. Transfer mass only
        # between those edges, preserving self, BOS, and the decay tail.
        if i >= 3 and current is not None and previous is not None:
            skip_target = None
            if (
                cd == "neg"
                and pp in ("AUX", "VERB")
                and cp != "PUNCT"
            ):
                skip_target = 0.48
            elif pd == "neg" and cp in ("VERB", "ADJ", "ADV"):
                skip_target = 0.34
            elif current.i == previous.i and cp != "PUNCT":
                skip_target = 0.27

            if skip_target is not None:
                transfer = min(
                    attention[i, i - 1],
                    max(0.0, skip_target - attention[i, i - 2]),
                )
                attention[i, i - 1] -= transfer
                attention[i, i - 2] += transfer

    return "previous_token_with_fragment_skip", make_row_stochastic(attention)


def prog_L0H2(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with subword binding; commas and opening quotes form secondary sinks.
    Repair false lexical binding across malformed Unicode punctuation.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_punctuation_anchors", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    spans = _char_spans(sentence, tokenizer)
    special_tokens = set(tokenizer.all_special_tokens)

    attention[0, 0] = 1.0

    for i in range(1, n):
        sids = aligned[i]
        word = doc[sids[0]] if sids else None
        start, end = spans[i] if i < len(spans) else (0, 0)
        surface = sentence[start:end]
        clean = tokens[i].lstrip("Ġ▁")

        # Bind fragments of a single lexical token to its first model piece.
        anchor = None
        if (
            tokens[i] not in special_tokens
            and word is not None
            and not word.is_punct
            and not word.is_space
            and surface
            and surface[0].isalnum()
            and i < len(spans)
            # A shared spaCy token alone is insufficient around broken quotes.
            and sentence[word.idx:start].isalnum()
        ):
            for j in range(i - 1, 0, -1):
                if sids[0] not in aligned[j]:
                    break
                js, je = spans[j]
                fragment = sentence[js:je].strip()
                if fragment and any(c.isalnum() for c in fragment):
                    if je <= start:
                        anchor = j

        if anchor is not None:
            binding = 0.975
            attention[i, anchor] = binding
            attention[i, 0] = 0.020
            attention[i, i] = 0.005
            continue

        # Sink strength is highest early in the sequence and at punctuation.
        progress = 1.0 - np.exp(-max(i - 5, 0) / 28.0)
        sink = 0.990 - 0.105 * progress

        if word is not None:
            if word.pos_ in ("PRON", "PART"):
                sink -= 0.025
            elif word.pos_ in ("AUX", "CCONJ", "SCONJ", "DET", "ADP"):
                sink += 0.008

        if clean and all(c.isspace() for c in clean):
            sink = 0.980
        elif not clean:
            sink = 0.980
        elif all(not c.isalnum() and not c.isspace() for c in clean):
            if "." in clean:
                sink = 0.995
            elif "," in clean:
                sink = 0.971 - 0.030 * progress
            elif "!" in clean or "?" in clean:
                sink = 0.985 if len(clean) == 1 else 0.923
            else:
                sink = 0.968 - 0.035 * progress

        sink = float(np.clip(sink, 0.80, 0.997))
        positions = np.arange(1, i + 1)
        residual = np.exp(-(i - positions) / 3.0)
        residual /= residual.sum()
        attention[i, 1:i + 1] = (1.0 - sink) * residual
        attention[i, 0] = sink

    # Targeted corrections move only BOS mass: self-attention and the original
    # causal residual remain unchanged.
    surfaces = [
        sentence[s:e].strip() for s, e in spans[:n]
    ]
    surfaces += [""] * (n - len(surfaces))
    commas = []
    opening_quotes = []

    for i in range(1, n):
        surface = surfaces[i]
        sids = aligned[i]
        word = doc[sids[0]] if sids else None
        extra = np.zeros(n, dtype=np.float64)

        lexical = bool(surface) and any(c.isalnum() for c in surface)
        bound = attention[i, 0] == 0.020

        if lexical and not bound and tokens[i] not in special_tokens:
            for rank, j in enumerate(reversed(commas[-4:])):
                mass = 0.14 * np.exp(-(i - j - 1) / 24.0) * (0.55 ** rank)
                if (
                    rank == 0
                    and i == j + 1
                    and word is not None
                    and word.dep_ == "conj"
                    and word.pos_ in ("NOUN", "PROPN")
                ):
                    mass = 0.40
                extra[j] += mass

            if opening_quotes:
                j = opening_quotes[-1]
                if i - j <= 4:
                    peak = 0.29 if word is not None and word.pos_ == "PRON" else 0.21
                    extra[j] += peak * np.exp(-(i - j - 1) / 1.2)

            if (
                surface.startswith(("'", "’"))
                and word is not None
                and word.pos_ in ("PART", "AUX")
                and i > 1
            ):
                extra[i - 1] += 0.09 if word.dep_ == "case" else 0.135

        # Byte fragments of non-ASCII punctuation should follow the local
        # punctuation chain, not bind to a distant lexical fragment.
        nonascii = bool(surface) and any(ord(c) > 127 for c in surface)
        previous_nonascii = i > 1 and any(ord(c) > 127 for c in surfaces[i - 1])
        if nonascii and not bound:
            if previous_nonascii:
                extra[i - 1] += 0.54
                if i > 2 and any(ord(c) > 127 for c in surfaces[i - 2]):
                    extra[i - 1] += 0.06
                    extra[i - 2] += 0.28
                elif i > 2 and any(c in "!?" for c in surfaces[i - 2]):
                    extra[i - 1] = 0.173
                    extra[i - 2] += 0.205
            elif i > 1 and any(c in "!?" for c in surfaces[i - 1]):
                extra[i - 1] += 0.62
        elif (
            lexical
            and not bound
            and previous_nonascii
            and i > 2
            and any(ord(c) > 127 for c in surfaces[i - 2])
        ):
            extra[i - 2] += 0.15

        total = extra.sum()
        if total > 0.0:
            extra *= min(1.0, max(0.0, attention[i, 0] - 0.05) / total)
            attention[i, 0] -= extra.sum()
            attention[i] += extra

        if "," in surface:
            commas.append(i)
        if (
            surface
            and all(c in "\"“«" for c in surface)
            and commas
            and i == commas[-1] + 1
        ):
            opening_quotes.append(i)

    return "bos_sink_with_punctuation_anchors", make_row_stochastic(attention)


def prog_L0H3(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with a secondary, local punctuation-boundary sink.
    Preserve the baseline diagonal; redirect only BOS mass after boundaries.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_boundary_anchor", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0
    last_boundary = None

    for i in range(1, n):
        positions = alignment[i]
        pos = doc[positions[-1]].pos_ if positions else ""

        if pos in ("NOUN", "PROPN"):
            floor = 0.87
        elif pos == "ADJ":
            floor = 0.85
        elif pos == "VERB":
            floor = 0.80
        elif pos == "ADV":
            floor = 0.78
        elif pos in ("PUNCT", "SPACE"):
            floor = 0.55
        else:
            floor = 0.69

        if tokens[i].isspace():
            floor = 0.57

        # Original BOS preference and diffuse residual remain unchanged.
        sink_mass = floor + (0.985 - floor) * np.exp(-(i - 1) / 9.0)

        distances = i - np.arange(1, i + 1, dtype=np.float64)
        residual = 0.65 + 0.35 * np.exp(-distances / 8.0)
        residual /= residual.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

        # A preceding clause/sentence boundary attracts a small local tail.
        # Only the BOS and boundary entries change, never the diagonal.
        if last_boundary is not None and i - last_boundary <= 12:
            transfer = min(
                attention[i, 0],
                0.11 * np.exp(-(i - last_boundary - 1) / 8.0),
            )
            attention[i, 0] -= transfer
            attention[i, last_boundary] += transfer

        if any(mark in tokens[i] for mark in (",", ";", ":", ".", "!", "?")):
            last_boundary = i

    return "bos_sink_with_boundary_anchor", attention


def prog_L0H4(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with local word assembly: contraction joins require actual
    character adjacency without intervening whitespace, not adjacent offsets alone.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_guarded_assembly", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    spans = _char_spans(sentence, tokenizer)
    special_tokens = tokenizer.all_special_tokens

    representatives = []
    for indices in alignment:
        representatives.append(
            next((doc[k] for k in indices if not doc[k].is_space),
                 doc[indices[0]] if indices else None)
        )

    attention[0, 0] = 1.0

    for i in range(1, n):
        word = representatives[i]
        pos = word.pos_ if word is not None else ""
        dep = word.dep_ if word is not None else ""
        distance = np.log1p(i - 1)

        if pos in ("NOUN", "PROPN", "ADJ", "NUM"):
            base = 0.990
        elif pos == "VERB":
            base = 0.960
        elif pos == "ADV":
            base = 0.940
        elif pos == "AUX":
            base = 0.865
        elif pos == "PRON":
            base = 0.855
        elif pos == "DET":
            base = 0.845
        elif pos in ("ADP", "PART", "SCONJ", "CCONJ"):
            base = 0.825
        elif pos == "PUNCT":
            base = 0.760
        else:
            base = 0.875

        if word is not None and word.ent_type_:
            base += 0.015
        if dep in ("poss", "possessive"):
            base -= 0.055
        if word is not None and word.is_space:
            base = 0.895

        bos_mass = float(np.clip(base - 0.027 * distance - 0.001 * i,
                                 0.35, 0.99))
        if i == 1:
            bos_mass = 0.983

        local_target = None
        local_mass = 0.0

        # Pieces belonging to one spaCy word assemble at its preceding piece.
        if tokens[i] not in special_tokens:
            shared = [
                j for j in range(1, i)
                if any(k in alignment[j] for k in alignment[i])
            ]
            if shared:
                local_target = shared[-1]
                local_mass = 0.85

            # spaCy may split a contraction even though its pieces are contiguous.
            if local_target is None and i < len(spans):
                start, end = spans[i]
                previous_end = spans[i - 1][1]
                fragment = sentence[start:end]
                if (
                    start == previous_end
                    and fragment
                    # Leading whitespace belongs to many tokenizer spans:
                    # contiguous offsets alone do not imply a contraction.
                    and not fragment[0].isspace()
                    and i > 1
                    and (
                        fragment[0] in ("'", "’")
                        or (
                            pos in ("PART", "AUX")
                            and representatives[i - 1] is not None
                            and representatives[i - 1].pos_ != "PUNCT"
                        )
                    )
                ):
                    local_target = i - 1
                    local_mass = 0.83

        # A particle/preposition following an adjective can select that adjective.
        if (
            local_target is None
            and pos in ("PART", "ADP")
            and i > 1
            and representatives[i - 1] is not None
            and representatives[i - 1].pos_ == "ADJ"
        ):
            local_target = i - 1
            local_mass = 0.80

        positions = np.arange(1, i + 1)
        residual = np.exp(-(i - positions) / 3.0) + 0.08
        residual /= residual.sum()

        if local_target is not None:
            bos_mass = min(bos_mass, 0.12)
            attention[i, 0] = bos_mass
            attention[i, 1:i + 1] = (
                1.0 - bos_mass - local_mass
            ) * residual
            attention[i, local_target] += local_mass
        else:
            attention[i, 0] = bos_mass
            attention[i, 1:i + 1] = (1.0 - bos_mass) * residual

    return "bos_sink_with_guarded_assembly", make_row_stochastic(attention)


def prog_L0H5(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS-sink head, strongest on content tokens, with local syntactic fallback
    and punctuation self-attention or quote-boundary attention."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "content_gated_bos_sink", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, indices in enumerate(alignment):
        for k in indices:
            inverse[k].append(i)

    special_tokens = set(tokenizer.all_special_tokens)
    words = []
    for indices in alignment:
        candidates = [doc[k] for k in indices if not doc[k].is_space]
        lexical = [w for w in candidates if not w.is_punct]
        words.append(lexical[0] if lexical else (candidates[0] if candidates else None))

    attention[0, 0] = 1.0
    open_quote = None
    last_quote = None

    for i in range(1, n):
        raw = tokens[i]
        clean = raw.lstrip("Ġ▁").strip()
        word = words[i]
        pos = word.pos_ if word is not None else ""
        dep = word.dep_ if word is not None else ""
        punctuation = bool(clean) and all(
            not c.isalnum() and not c.isspace() for c in clean
        )
        quote = any(c in clean for c in ('"', "“", "”", "«", "»"))

        sink = {
            "PROPN": 0.93,
            "NOUN": 0.83,
            "ADJ": 0.82,
            "VERB": 0.57,
            "ADV": 0.57,
            "NUM": 0.71,
            "ADP": 0.40,
            "DET": 0.39,
            "CCONJ": 0.48,
            "SCONJ": 0.34,
            "PRON": 0.28,
            "AUX": 0.23,
            "PART": 0.26,
            "INTJ": 0.81,
            "PUNCT": 0.27,
        }.get(pos, 0.61)

        if word is not None:
            if word.ent_type_:
                sink = max(sink, 0.88)
            if word.tag_.startswith("W"):
                sink = max(sink, 0.88)
            if pos in ("NOUN", "ADJ", "VERB") and i <= 8:
                sink += 0.06
            if pos == "VERB" and dep in ("xcomp", "ccomp"):
                sink -= 0.12
            if pos in ("DET", "PRON") and word.is_sent_start:
                sink = max(sink, 0.64)

        if not clean:
            sink = 0.67
        if punctuation:
            sink = 0.25 if "," in clean else 0.39
            if quote:
                sink = 0.19
        if raw in special_tokens:
            sink = 0.95
        if i == 1:
            sink = 0.985

        sink = float(np.clip(sink, 0.08, 0.995))
        weights = np.zeros(i + 1, dtype=np.float64)

        # Most non-sink mass stays local, rather than following distant entities.
        distances = i - np.arange(1, i + 1)
        weights[1:] = 0.16 * np.exp(-distances / 3.0)
        weights[i] += 0.38

        for j in range(max(1, i - 10), i):
            previous = words[j]
            if previous is not None:
                if previous.pos_ in ("NOUN", "PROPN", "VERB", "ADJ"):
                    weights[j] += 0.16 * np.exp(-(i - j) / 5.0)

        if word is not None:
            # Only use syntactic anchors that are causally available.
            head = word.head
            if head.i != word.i:
                candidates = [j for j in inverse[head.i] if 0 < j < i]
                if candidates:
                    weights[candidates[-1]] += 0.85

            if pos in ("AUX", "VERB", "ADP", "PART"):
                for j in range(max(1, i - 6), i):
                    previous = words[j]
                    if previous is not None and previous.tag_.startswith("W"):
                        weights[j] += 1.8

            if pos == "AUX":
                for child in head.children:
                    if child.dep_ in ("nsubj", "nsubjpass", "csubj"):
                        candidates = [j for j in inverse[child.i] if 0 < j < i]
                        if candidates:
                            weights[candidates[0]] += 0.8

        if punctuation:
            weights[i] += 2.0 if "," in clean else 0.55

        if quote:
            if open_quote is not None:
                weights[open_quote] += 3.0
                open_quote = None
            else:
                if last_quote is not None:
                    weights[last_quote] += 1.3
                open_quote = i
            last_quote = i

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (
            (1.0 - sink) * weights[1:] / weights[1:].sum()
        )

    return "content_gated_bos_sink", attention


def prog_L0H6(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with sparse auxiliary, pronominal, and possessive key anchors.
    Transfer only BOS mass to missed anchors, preserving baseline self-attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_sparse_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    sink_strength = {
        "DET": 35.0,
        "ADP": 22.0,
        "PART": 24.0,
        "AUX": 18.0,
        "PRON": 17.0,
        "PROPN": 25.0,
        "NOUN": 15.0,
        "VERB": 12.0,
        "ADJ": 9.0,
        "ADV": 10.0,
        "CCONJ": 17.0,
        "SCONJ": 19.0,
        "NUM": 20.0,
        "INTJ": 22.0,
    }
    initial_mass = {
        "DET": 0.956,
        "PRON": 0.900,
        "PROPN": 0.967,
        "ADP": 0.938,
        "ADV": 0.940,
        "NUM": 0.949,
        "SCONJ": 0.930,
        "CCONJ": 0.932,
    }

    attention[0, 0] = 1.0
    for i in range(1, n):
        raw = tokens[i]
        clean = raw.replace("Ġ", " ").replace("Ċ", "\n").strip()
        aligned = alignment[i]
        word = doc[aligned[0]] if aligned else None
        pos = word.pos_ if word is not None else ""

        strength = sink_strength.get(pos, 15.0)

        if not clean:
            strength = 38.0
        elif any(c in "\"'“”‘’«»" for c in clean):
            strength = 34.0
        elif all(not c.isalnum() for c in clean):
            strength = 24.0 if any(c in ".!?" for c in clean) else 11.0
        elif word is not None:
            if word.ent_type_:
                strength *= 1.10
            if word.dep_ == "poss":
                strength *= 1.12

        # A fixed sink competes with a growing pool of ordinary causal keys.
        sink_mass = strength / (strength + float(i) ** 0.80)
        if i == 1:
            sink_mass = initial_mass.get(pos, 0.935)

        distances = i - np.arange(1, i + 1, dtype=np.float64)
        residual = 0.75 + 0.25 * np.exp(-distances / 10.0)
        residual[-1] += 0.15
        residual /= residual.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

        # Sparse exceptions: leave self-attention and all non-anchor keys intact.
        if word is not None and pos in {
            "VERB", "ADJ", "ADV", "NOUN", "PRON", "DET", "ADP", "AUX"
        } and any(c.isalnum() for c in clean):
            additions = np.zeros(i, dtype=np.float64)
            for j in range(1, i):
                key_alignment = alignment[j]
                if not key_alignment:
                    continue
                # Do not count continuation pieces as separate linguistic anchors.
                if j > 1 and key_alignment[0] in alignment[j - 1]:
                    continue
                key = doc[key_alignment[0]]
                if key.i == word.i:
                    continue

                distance = i - j
                target = 0.0
                if key.pos_ == "PRON" or key.dep_ == "poss":
                    target = 0.12 * np.exp(-(distance - 1) / 25.0)
                if key.pos_ == "AUX" and pos in {"VERB", "ADJ", "ADV", "AUX"}:
                    target = max(
                        target, 0.18 * np.exp(-(distance - 1) / 40.0)
                    )
                if key.pos_ == "PART" and key.dep_ in {"neg", "poss", "case"}:
                    target = max(
                        target, 0.18 * np.exp(-(distance - 1) / 30.0)
                    )
                if (
                    j == 1 and i == 2
                    and key.pos_ == "DET" and key.dep_ == "det"
                    and pos == "NOUN" and key.head.i == word.i
                ):
                    target = max(target, 0.30)

                additions[j] = max(0.0, target - attention[i, j])

            total = additions.sum()
            if total > 0.0:
                budget = min(total, 0.28, 0.45 * attention[i, 0])
                attention[i, 1:i] += additions[1:i] * (budget / total)
                attention[i, 0] -= budget

    return "bos_sink_with_sparse_anchors", attention


def prog_L0H7(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with punctuation echo; possessive, quoted, and coordinated
    discourse additionally promotes earlier nominal anchors and closing quotes."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_discourse_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special = tokenizer.all_special_tokens
    pos = []
    punct = []
    whitespace = []
    words = []

    for i, token in enumerate(tokens):
        clean = token.replace("Ġ", " ").replace("Ċ", "\n").strip()
        mapped = alignment[i]
        word = doc[mapped[0]] if mapped else None
        words.append(word)
        pos.append(word.pos_ if word is not None else "")
        whitespace.append(not clean and token not in special)
        is_punct = (
            bool(clean)
            and token not in special
            and all(not ch.isalnum() for ch in clean)
        )
        punct.append(clean if is_punct else "")

    attention[0, 0] = 1.0
    nominal = ("NOUN", "PROPN")
    functional = ("DET", "ADP", "AUX", "PART", "SCONJ", "CCONJ")
    quotes = "\"“”"
    discourse_context = (
        any(w.dep_ == "poss" for w in doc)
        or any(w.dep_ == "conj" and w.pos_ in nominal for w in doc)
        or any(any(ch in quotes for ch in p) for p in punct)
    )

    for i in range(1, n):
        attention[i, 0] = 6.0

        for j in range(1, i + 1):
            distance = i - j
            weight = 0.70
            if j == i:
                weight = 0.90

            if punct[j]:
                weight *= 0.35
            if whitespace[j]:
                weight *= 0.25

            if not punct[i] and not punct[j] and not whitespace[i] and not whitespace[j]:
                if j < i:
                    similarity = embedding_similarity(tokens, i, j, tokenizer)
                    weight *= np.exp(3.0 * np.clip(similarity - 0.30, -0.35, 0.55))
                    if pos[i] in nominal and pos[j] in nominal:
                        weight *= 1.25
                    if pos[i] in functional and pos[j] == pos[i]:
                        weight *= 1.15

                    # Discourse referents are stronger keys than diffuse affinity
                    # predicts, especially possessors and related nominal objects.
                    if (
                        discourse_context
                        and distance <= 24
                        and pos[j] in nominal
                        and pos[i] in nominal + ("PRON", "VERB", "ADJ", "ADV")
                        and words[j] is not None
                        and words[j].dep_ in (
                            "poss", "nsubj", "nsubjpass", "dobj",
                            "obj", "pobj", "attr", "conj",
                        )
                        and (
                            words[i] is None
                            or words[i].i != words[j].i
                        )
                    ):
                        weight += 1.8 + 4.0 * np.clip(similarity - 0.15, 0.0, 0.55)
                        if words[j].dep_ == "poss":
                            weight += 2.4

            if punct[i]:
                weight *= 0.10
                if punct[j] == punct[i]:
                    if j == i:
                        weight = 2.0
                    else:
                        near = 0.12 if distance == 1 else (0.70 if distance == 2 else 1.0)
                        weight = 55.0 * near * np.exp(-max(distance - 3, 0) / 3.0)
                elif punct[j]:
                    weight += 0.35 * np.exp(-distance / 12.0)

                # Closing dialogue boundaries can match despite differing
                # terminal punctuation, e.g. question-quote versus bang-quote.
                if (
                    j < i
                    and punct[j] != punct[i]
                    and any(ch in quotes for ch in punct[i])
                    and any(ch in quotes for ch in punct[j])
                    and any(ch in ".?!" for ch in punct[j])
                ):
                    weight += 7.0 * np.exp(-distance / 30.0)

            if pos[i] == "CCONJ" and punct[j] and j < i:
                near = 0.08 if distance == 1 else (0.55 if distance == 2 else 1.0)
                weight += 24.0 * near * np.exp(-max(distance - 3, 0) / 3.5)

            if whitespace[i]:
                weight *= 0.25
                if whitespace[j] and j < i:
                    weight += 3.0 * np.exp(-distance / 30.0)

            attention[i, j] = weight

    return "bos_sink_with_discourse_anchors", make_row_stochastic(attention)


def prog_L0H8(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS-sink head with local punctuation-boundary and auxiliary-to-verb routing.
    Most tokens retain a strong sink preference plus diffuse causal background."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_boundary_auxiliary", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special_tokens = set(tokenizer.all_special_tokens)

    words = []
    clean = []
    punctuation = []
    whitespace = []

    for i, token in enumerate(tokens):
        text = token.replace("Ġ", " ").replace("Ċ", "\n").strip()
        clean.append(text)
        whitespace.append(not text and token not in special_tokens)
        punctuation.append(
            bool(text)
            and token not in special_tokens
            and all(not char.isalnum() for char in text)
        )

        word = None
        for k in alignment[i]:
            if not doc[k].is_space:
                word = doc[k]
                break
        words.append(word)

    attention[0, 0] = 1.0

    for i in range(1, n):
        word = words[i]
        pos = word.pos_ if word is not None else ""
        dep = word.dep_ if word is not None else ""

        # Sink strength decreases gently as additional competing keys accumulate.
        sink = 0.59 + 0.23 * np.exp(-(i - 1) / 16.0)
        if pos in ("DET", "PROPN"):
            sink += 0.065
        elif pos in ("NOUN", "ADJ", "AUX"):
            sink += 0.025
        elif pos in ("PRON", "VERB", "CCONJ", "SCONJ"):
            sink -= 0.055
        if dep == "poss":
            sink += 0.045
        if punctuation[i]:
            sink -= 0.10
        sink = float(np.clip(sink, 0.45, 0.94))

        target = None
        strength = 0.0
        previous = i - 1

        # Tokens immediately after punctuation often copy that boundary.
        if previous > 0 and punctuation[previous]:
            target = previous
            strength = 0.55
            if "," in clean[previous]:
                strength = 0.69
                if pos == "CCONJ":
                    strength = 0.92
                elif pos in ("SCONJ", "ADV"):
                    strength = 0.82
                elif punctuation[i]:
                    strength = 0.84
            elif whitespace[i]:
                strength = 0.85
            elif any(c in clean[previous] for c in ('"', "“", "‘")):
                strength = 0.53

        # Repeated commas can form a weaker punctuation-to-punctuation chain.
        if "," in clean[i]:
            for j in range(i - 1, 0, -1):
                if "," in clean[j]:
                    distance = i - j
                    candidate = 0.58 * np.exp(-max(distance - 2, 0) / 12.0)
                    if candidate > strength:
                        target, strength = j, float(candidate)
                    break

        # Base-form predicates can route to preceding infinitival/modal markers.
        # Restrict routing to the first model piece of the predicate.
        first_piece = (
            word is not None
            and (words[i - 1] is None or words[i - 1].i != word.i)
        )
        if first_piece and pos in ("VERB", "AUX") and word.tag_ == "VB":
            for j in range(i - 1, max(0, i - 5), -1):
                auxiliary = words[j]
                if auxiliary is None or auxiliary.i == word.i:
                    continue
                if punctuation[j]:
                    break
                linked = auxiliary.head.i == word.i
                infinitival = (
                    auxiliary.pos_ == "PART"
                    and auxiliary.dep_ in ("aux", "mark")
                )
                modal = auxiliary.tag_ == "MD" and auxiliary.dep_ == "aux"
                if linked and (infinitival or modal):
                    candidate = 0.79 if infinitival else 0.66
                    candidate -= 0.045 * max(i - j - 1, 0)
                    if candidate > strength:
                        target, strength = j, candidate
                    break

        # Residual attention is causal and mildly recency-biased.
        background = np.exp(-(i - np.arange(i + 1)) / 7.0) + 0.06
        background[i] *= 0.65
        background[0] = 0.0

        if target is not None:
            background[target] = 0.0
            sink = min(sink, max(0.04, 1.0 - strength - 0.07))

        remaining = 1.0 - sink - strength
        total = background.sum()
        if total > 0.0:
            attention[i, :i + 1] = remaining * background / total
        else:
            sink += remaining

        attention[i, 0] += sink
        if target is not None:
            attention[i, target] += strength

    return "bos_sink_boundary_auxiliary", make_row_stochastic(attention)


def prog_L0H9(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """A BOS sink with local exceptions: opening quotes retrieve commas,
    and adjacent nominal complements retrieve their nominal heads.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_exceptions", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    specials = set(tokenizer.all_special_tokens)
    attention[0, 0] = 1.0
    boundaries = 0

    for i in range(1, n):
        indices = aligned[i]
        word = doc[indices[-1]] if indices else None
        is_special = tokens[i] in specials
        is_punctuation = (
            not is_special
            and bool(indices)
            and all(doc[k].is_punct or doc[k].is_space for k in indices)
        )

        if boundaries == 0:
            sink = max(0.990, 0.999 - 0.0002 * i)
        else:
            sink = max(0.80, 0.988 - 0.0008 * i - 0.012 * boundaries)

        if is_punctuation:
            sink = max(0.65, sink - 0.12)

        # Distribute the small non-sink component over recent causal keys.
        recent = np.arange(1, i + 1)
        weights = np.exp((recent - i) / 3.0)
        weights /= weights.sum()
        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * weights

        if word is not None and not is_special:
            previous_indices = aligned[i - 1]

            # A later piece of an adverb can attend strongly to its stem.
            continuation = (
                word.pos_ == "ADV"
                and word.i in previous_indices
                and not tokens[i].startswith(("Ġ", "▁"))
            )
            if continuation:
                attention[i] *= 0.056
                attention[i, i - 1] += 0.944

            # Adjacent adjectival complements occasionally override the sink.
            elif word.pos_ == "ADP" and word.dep_ == "prep":
                head = word.head
                if head.pos_ == "ADJ" and head.i in previous_indices:
                    # A comma-detached adjective is not this local exception.
                    detached = head.i > 0 and doc[head.i - 1].is_punct
                    if not detached:
                        attention[i] *= 0.034
                        attention[i, i - 1] += 0.966

                elif head.pos_ in ("NOUN", "PROPN") and head.i in previous_indices:
                    # Transfer only BOS mass; retain the default self weight.
                    transfer = max(0.0, attention[i, 0] - 0.001)
                    attention[i, 0] -= transfer
                    attention[i, i - 1] += transfer

        # Opening quotes following a comma retrieve that delimiter rather
        # than BOS, with a smaller contribution to earlier comma anchors.
        clean = tokens[i].lstrip("Ġ▁").strip()
        previous_clean = tokens[i - 1].lstrip("Ġ▁").strip()
        if (
            not is_special
            and clean in ('"', "“", "‘")
            and previous_clean == ","
        ):
            earlier_commas = [
                j for j in range(1, i - 1)
                if tokens[j].lstrip("Ġ▁").strip() == ","
            ]
            transfer = max(0.0, attention[i, 0] - 0.115)
            attention[i, 0] -= transfer
            if earlier_commas:
                attention[i, i - 1] += 0.80 * transfer
                attention[i, earlier_commas] += (
                    0.20 * transfer / len(earlier_commas)
                )
            else:
                attention[i, i - 1] += transfer

        if is_punctuation:
            boundaries += 1

    return (
        "bos_sink_with_local_exceptions",
        make_row_stochastic(apply_causal_mask(attention)),
    )


def prog_L0H10(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with persistent comma-key leakage, strongest for opening quotes.
    Preserve the baseline except for extra attention to earlier comma anchors.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_comma_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    punctuation = np.zeros(n, dtype=bool)
    whitespace = np.zeros(n, dtype=bool)
    comma = np.zeros(n, dtype=bool)
    quote = np.zeros(n, dtype=bool)

    for i in range(1, n):
        aligned = [doc[k] for k in alignment[i]]
        if aligned:
            punctuation[i] = all(w.is_punct for w in aligned)
            whitespace[i] = all(w.is_space for w in aligned)
        else:
            clean = tokens[i].replace("Ġ", " ").replace("Ċ", "\n")
            whitespace[i] = bool(clean) and clean.isspace()
            punctuation[i] = (
                bool(clean.strip())
                and all(not c.isalnum() and not c.isspace() for c in clean)
                and tokens[i] not in tokenizer.all_special_tokens
            )

        clean = tokens[i].replace("Ġ", " ").replace("Ċ", "\n").strip()
        if tokens[i] not in tokenizer.all_special_tokens:
            comma[i] = clean == ","
            quote[i] = bool(clean) and all(c in "\"'“”‘’«»" for c in clean)

    attention[0, 0] = 1.0
    boundary_seen = False

    for i in range(1, n):
        boundary_seen = boundary_seen or punctuation[i]
        leakage = 0.00125 if boundary_seen else 0.00014

        positions = np.arange(1, i + 1)
        weights = np.ones(i, dtype=np.float64)
        weights += 0.35 * np.exp(-(i - positions) / 3.0)
        weights *= np.where(punctuation[1:i + 1], 2.0, 1.0)

        query_scale = 6.0 if punctuation[i] else 1.0
        if whitespace[i]:
            query_scale *= 2.0

        attention[i, 0] = 1.0
        attention[i, 1:i + 1] = leakage * query_scale * weights

        # Earlier commas remain salient after the boundary. Do not modify
        # comma-query rows or add anything to the query's own diagonal entry.
        anchors = np.flatnonzero(comma[:i])
        if anchors.size and not comma[i]:
            if quote[i]:
                attention[i, anchors] += 0.10
                attention[i, anchors[-1]] += 0.10
            else:
                attention[i, anchors] += 0.045

    return (
        "bos_sink_with_comma_anchors",
        make_row_stochastic(attention),
    )


def prog_L0H11(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with punctuation leakage; quoted passages additionally retrieve
    earlier quote boundaries and clause starts, without changing self-attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_quote_memory", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    key_weights = np.full(n, 0.00015, dtype=np.float64)
    punctuation = np.zeros(n, dtype=bool)

    for j in range(1, n):
        aligned = [doc[k] for k in alignment[j]]
        punctuation[j] = any(w.is_punct for w in aligned)

        if punctuation[j]:
            # Quotes contribute less than clause and sentence boundaries.
            is_quote = any(
                w.tag_ in ("``", "''") or w.text in ('"', "'", "“", "”", "‘", "’")
                for w in aligned
            )
            key_weights[j] = 0.006 if is_quote else 0.022
        elif aligned and all(w.is_space for w in aligned):
            key_weights[j] = 0.001

    attention[0, 0] = 1.0
    for i in range(1, n):
        # Most queries overwhelmingly select the initial attention sink.
        leakage_scale = 1.5 if punctuation[i] else 1.0
        attention[i, 0] = 1.0
        attention[i, 1:i + 1] = leakage_scale * key_weights[1:i + 1]

    attention = make_row_stochastic(attention)

    # Restrict the additional retrieval path to dialogue-like punctuation.
    # Single apostrophes alone must not activate it for ordinary possessives.
    if any(q in sentence for q in ('"', "“", "”", "â€")):
        raw = [t.lstrip("Ġ").replace("Ċ", "\n") for t in tokens]
        quote = np.zeros(n, dtype=bool)
        malformed = np.zeros(n, dtype=bool)
        comma = np.zeros(n, dtype=bool)
        terminal = np.zeros(n, dtype=bool)
        clitic = np.zeros(n, dtype=bool)
        space = np.zeros(n, dtype=bool)
        starts = np.zeros(n, dtype=bool)
        conjunction = np.zeros(n, dtype=bool)

        # Recognize byte-split, mojibake quotation marks by source offsets,
        # rather than treating their alphabetic fragments as content words.
        spans = _char_spans(sentence, tokenizer)
        broken_spans = []
        for p in range(len(sentence)):
            if sentence.startswith("â€", p):
                end = p + 2
                if end < len(sentence) and sentence[end] in ("œ", "“", "”"):
                    end += 1
                broken_spans.append((p, end))

        for j in range(1, n):
            aligned = [doc[k] for k in alignment[j]]
            quote[j] = any(c in raw[j] for c in ('"', "“", "”"))
            comma[j] = "," in raw[j]
            terminal[j] = any(c in raw[j] for c in ".!?")
            clitic[j] = (
                raw[j].startswith(("'", "’"))
                and any(w.pos_ in ("PART", "AUX") or w.tag_ == "POS"
                        for w in aligned)
            )
            space[j] = raw[j] == "" or raw[j].isspace()
            conjunction[j] = any(w.pos_ == "CCONJ" for w in aligned)
            if j < len(spans):
                s, e = spans[j]
                malformed[j] = any(s < b and e > a for a, b in broken_spans)
            if aligned and not punctuation[j] and not malformed[j]:
                starts[j] = (
                    j == 1
                    or any(w.is_sent_start for w in aligned)
                    or quote[j - 1]
                    or malformed[j - 1]
                )

        for i in range(1, n):
            memory = np.zeros(i, dtype=np.float64)
            prior_quotes = np.flatnonzero(quote[:i] | malformed[:i])
            prior_starts = np.flatnonzero(starts[:i])

            if quote[i] or malformed[i] or clitic[i]:
                if prior_quotes.size:
                    memory[prior_quotes] = 1.0
                    if malformed[i] or clitic[i]:
                        memory[prior_quotes[malformed[prior_quotes]]] *= 2.0
                    mass = 0.55 if quote[i] or malformed[i] else 0.45
                else:
                    mass = 0.10
                if prior_starts.size:
                    memory[prior_starts] += 0.20
            elif terminal[i]:
                memory[prior_quotes] = 1.0
                memory[prior_starts] += 0.55
                mass = 0.42
            elif comma[i]:
                previous_commas = np.flatnonzero(comma[:i])
                if previous_commas.size:
                    memory[previous_commas[-2:]] = 1.0
                recent_conjunctions = np.flatnonzero(conjunction[max(1, i - 6):i])
                memory[max(1, i - 6) + recent_conjunctions] += 0.65
                memory[prior_starts] += 0.35
                mass = 0.28 if previous_commas.size else 0.12
            elif space[i] and (quote[i - 1] or terminal[i - 1]):
                memory[prior_quotes] = 1.0
                memory[prior_starts] += 0.30
                mass = 0.28
            else:
                continue

            memory[0] = 0.0
            total = memory.sum()
            if total > 0.0:
                # Move only BOS mass to strictly earlier keys. The original
                # diagonal and all unrelated weights remain exactly intact.
                moved = min(mass, 0.85 * attention[i, 0])
                attention[i, 0] -= moved
                attention[i, :i] += moved * memory / total

    return "bos_sink_with_quote_memory", attention


def prog_L0H12(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with positional dilution; earlier commas act as secondary sinks.
    Comma routing transfers only BOS mass, preserving the original self-attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_comma_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    # These are coarse priors, not evidence for a syntactic routing mechanism.
    pos_strength = {
        "AUX": 0.55,
        "DET": 0.25,
        "VERB": 0.20,
        "ADJ": 0.15,
        "ADV": 0.10,
        "PROPN": 0.60,
        "NOUN": -0.10,
        "PRON": -0.05,
        "ADP": 0.05,
        "CCONJ": -0.05,
        "SCONJ": 0.00,
        "PART": -0.10,
        "NUM": -0.10,
        "PUNCT": -1.45,
        "SYM": -1.10,
        "SPACE": 0.45,
    }

    comma_positions = [
        j for j in range(1, n)
        if tokens[j].replace("Ġ", " ").replace("Ċ", "\n").strip() == ","
    ]

    attention[0, 0] = 1.0
    for i in range(1, n):
        sids = alignment[i]
        if sids:
            strength = sum(
                pos_strength.get(doc[k].pos_, 0.0) for k in sids
            ) / len(sids)
        else:
            clean = tokens[i].replace("Ġ", " ").replace("Ċ", "\n")
            if clean.isspace():
                strength = 0.45
            elif clean.strip() and all(
                not c.isalnum() for c in clean.strip()
            ):
                strength = -1.45
            else:
                strength = 0.0

        # Odds of attending away from BOS grow with available context.
        leakage_odds = (0.015 + 0.0037 * (i - 1)) * np.exp(-strength)
        sink_mass = 1.0 / (1.0 + leakage_odds)
        attention[i, 0] = sink_mass

        distances = i - np.arange(1, i + 1, dtype=np.float64)
        residual = 1.0 + 0.35 * np.exp(-distances / 4.0)
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * residual / residual.sum()
        )

        # Only lexical queries after a comma receive the additional routing.
        # Earlier commas persist as weak anchors rather than local-only targets.
        prior_commas = [j for j in comma_positions if j < i]
        clean = tokens[i].replace("Ġ", " ").replace("Ċ", "\n")
        if prior_commas and any(c.isalnum() for c in clean):
            keys = np.asarray(prior_commas, dtype=np.int64)
            extra = 0.075 / (1.0 + 0.015 * (i - keys))
            extra /= 1.0 + 0.15 * (len(keys) - 1)
            total = extra.sum()
            extra *= min(1.0, 0.30 * attention[i, 0] / total)
            attention[i, 0] -= extra.sum()
            attention[i, keys] += extra

    return "bos_sink_with_comma_anchors", attention


def prog_L0H13(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with token-local linguistic gating.
    Names, punctuation, whitespace, and subword fragments strengthen the sink.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "linguistically_gated_bos_sink", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    spans = _char_spans(sentence, tokenizer)
    special_tokens = set(tokenizer.all_special_tokens)

    word_pieces = [[] for _ in doc]
    for i, indices in enumerate(alignment):
        if tokens[i] not in special_tokens:
            for k in indices:
                word_pieces[k].append(i)

    pos_strength = {
        "PROPN": 125.0,
        "NOUN": 10.5,
        "PRON": 9.5,
        "DET": 12.0,
        "VERB": 9.5,
        "AUX": 9.0,
        "ADJ": 8.5,
        "ADV": 10.0,
        "ADP": 12.0,
        "CCONJ": 15.0,
        "SCONJ": 9.0,
        "PART": 10.5,
        "NUM": 25.0,
        "INTJ": 18.0,
        "PUNCT": 24.0,
        "SPACE": 65.0,
        "SYM": 30.0,
        "X": 22.0,
    }

    attention[0, 0] = 1.0

    for i in range(1, n):
        raw = tokens[i]
        clean = raw.lstrip("Ġ▁").strip()
        indices = alignment[i]
        word = None

        if indices:
            word = max(
                (doc[k] for k in indices),
                key=lambda w: (
                    not w.is_space,
                    not w.is_punct,
                    len(w.text),
                ),
            )

        strength = pos_strength.get(word.pos_, 10.0) if word is not None else 10.0

        if i == 1 and word is not None:
            strength = {
                "PRON": 15.5,
                "DET": 8.6,
                "NUM": 36.0,
                "ADP": 15.0,
                "ADV": 17.0,
            }.get(word.pos_, strength)

        if word is not None:
            if word.ent_type_ == "PERSON":
                strength = max(strength, 125.0)

            pieces = word_pieces[word.i]
            if len(pieces) > 1 and word.pos_ not in {
                "PART", "AUX", "PUNCT", "SPACE"
            }:
                if i == pieces[0]:
                    strength *= 2.0
                else:
                    strength *= 5.5

        whitespace = not clean
        if i < len(spans):
            start, end = spans[i]
            if end > start and sentence[start:end].isspace():
                whitespace = True

        if whitespace:
            strength = 65.0
        elif clean and all(not c.isalnum() for c in clean):
            strength = 13.0 + 0.8 * min(i, 18)
            if any(c in "\"'“”‘’" for c in clean):
                strength = max(strength, 26.0)
            if any(c in ".!?" for c in clean):
                strength = max(strength, 31.0)
        elif word is None and clean:
            strength = 35.0

        # No non-BOS destination preference is supported by the supplied edges.
        attention[i, :i + 1] = 1.0
        attention[i, 0] = strength
        attention[i, :i + 1] /= strength + i

    return "linguistically_gated_bos_sink", attention


def prog_L0H14(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, strengthened at the opening and at punctuation.
    POS and subword boundaries modulate sink strength; residual attention is local.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_residual", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        text = tokens[i].replace("Ġ", " ").replace("▁", " ").strip()
        indices = aligned[i]
        word = doc[indices[0]] if indices else None
        pos = word.pos_ if word is not None else ""

        sink = 0.56
        if pos == "DET":
            sink = 0.72
        elif pos == "PROPN":
            sink = 0.78
        elif pos == "CCONJ":
            sink = 0.70
        elif pos in ("PRON", "ADP", "PART"):
            sink = 0.61
        elif pos in ("AUX", "VERB"):
            sink = 0.54
        elif pos in ("ADJ", "ADV"):
            sink = 0.50

        if text and all(c in ".,;:" for c in text):
            sink = 0.79 if "." in text else 0.75
        elif text and all(c in "\"'“”‘’" for c in text):
            sink = 0.69
        elif text and all(c in "!?\"'“”‘’" for c in text):
            sink = 0.55
        elif not text:
            sink = 0.63

        if word is not None and i > 1 and indices:
            if indices[0] in aligned[i - 1] and pos != "PUNCT":
                sink = min(0.88, sink + 0.13)

        # Strong opening-token bias fades over the first few positions.
        opening = np.exp(-(i - 1) / 1.35)
        sink = sink + (0.945 - sink) * opening
        sink = float(np.clip(sink, 0.35, 0.98))

        # Only BOS is strongly identifiable from the supplied edges.
        # Spread the unobserved remainder over self, recent, and older tokens.
        distances = i - np.arange(1, i + 1)
        residual = (
            0.50 * np.exp(-distances / 1.5)
            + 0.25 * np.exp(-distances / 6.0)
            + 0.25 / i
        )
        residual /= residual.sum()
        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual

    return "bos_sink_with_local_residual", attention


def prog_L0H15(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Local lookback with BOS fallback; quoted clause onsets provide extra anchors.
    Contracted imperative onsets remain salient across the next few tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    matrix = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "local_lookback_with_quote_onsets", matrix

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = align_spacy_to_tokens(sentence, tokens, tokenizer)

    words = [doc[a[0]] if a else None for a in alignment]
    special = [t in tokenizer.all_special_tokens for t in tokens]
    bos = 0 if special[0] else None
    first = 1 if bos is not None else 0

    # Detect lexical onsets immediately after an opening quotation mark.
    # Character adjacency identifies contractions without lexical exceptions.
    quote_onsets = {}
    for k in range(first, n):
        word = words[k]
        if special[k] or word is None or word.pos_ in ("PUNCT", "SPACE"):
            continue
        if not inverse[word.i] or k != inverse[word.i][0]:
            continue
        p = k - 1
        while p >= first and not tokens[p].strip("Ġ▁ \t\r\n"):
            p -= 1
        if p < first or special[p]:
            continue
        if not any(c in tokens[p] for c in ('"', '“', '‘')):
            continue
        if any(c in tokens[p] for c in ".!?"):
            continue
        if words[p] is not None and words[p].pos_ not in ("PUNCT", "SPACE"):
            continue
        contracted = False
        if word.pos_ in ("VERB", "AUX") and word.i + 1 < len(doc):
            following = doc[word.i + 1]
            contracted = (
                following.idx == word.idx + len(word.text)
                and following.pos_ in ("PRON", "PART", "AUX")
            )
        quote_onsets[k] = contracted

    for i in range(n):
        if i == 0:
            matrix[i, i] = 1.0
            continue

        query = words[i]
        for j in range(i + 1):
            distance = i - j
            if distance == 0:
                weight = 0.10
            elif distance == 1:
                weight = 0.24
            elif distance == 2:
                weight = 1.55
            elif distance == 3:
                weight = 1.28
            elif distance == 4:
                weight = 0.78
            else:
                weight = 0.46 * np.exp(-(distance - 5) / 3.2)

            key = words[j]
            if query is not None and key is not None and j < i:
                same_word = query.i == key.i
                if same_word:
                    weight *= 0.45
                else:
                    if query.head.i == key.i and distance <= 7:
                        weight *= 1.45
                    if key.pos_ in ("VERB", "AUX") and 2 <= distance <= 4:
                        weight *= 1.20
                    if key.pos_ == "ADP" and query.pos_ in ("NOUN", "PROPN"):
                        if 2 <= distance <= 4:
                            weight *= 1.25
                    if key.tag_ in ("WDT", "WP", "WP$", "WRB"):
                        if 1 <= distance <= 5:
                            weight *= 1.75
                    if key.pos_ == "DET" and query.pos_ in ("NOUN", "ADJ", "AUX"):
                        if 2 <= distance <= 3:
                            weight *= 1.35

            if j == first and 1 <= distance <= 4:
                weight *= 1.35

            # Sentence-ending punctuation can anchor several following tokens,
            # including a closing quote merged into the punctuation token.
            if not special[j] and j < i:
                terminal = any(c in tokens[j] for c in ".!?")
                punctuation = key is not None and key.pos_ == "PUNCT"
                if terminal and punctuation and distance <= 8:
                    weight += 4.0 * np.exp(-(distance - 1) / 3.4)

            matrix[i, j] = weight

        if bos is not None:
            matrix[i, bos] = 0.85 + 1.6 * np.exp(-max(i - 3, 0) / 2.2)

            # A continuation piece has little standalone lexical information.
            if query is not None and inverse[query.i]:
                if i != inverse[query.i][0]:
                    matrix[i, bos] += 1.1

            # The initial rows are dominated by the BOS sink, before a local
            # two/three-token context has become available.
            target = None
            if i == 1:
                target = 0.91
                if query is not None and query.pos_ == "PRON":
                    target = 0.93
                elif query is not None and query.pos_ == "ADP":
                    target = 0.92
            elif i == 2:
                target = 0.57
                if query is not None:
                    if query.pos_ in ("NOUN", "PROPN"):
                        target = 0.49
                    elif query.pos_ in ("VERB", "AUX", "DET", "ADP"):
                        target = 0.63
            elif i == 3:
                target = 0.43
                if query is not None and query.pos_ == "PROPN":
                    target = 0.56
                elif query is not None and query.pos_ == "ADV":
                    target = 0.50

            if target is not None:
                other_mass = matrix[i, 1:i + 1].sum()
                matrix[i, 1:i + 1] *= (1.0 - target) / other_mass
                matrix[i, bos] = target

        # Only quoted onsets and their immediate continuations are adjusted.
        if i in quote_onsets and bos is not None and i > 3:
            matrix[i, bos] += 1.6
        for anchor, contracted in quote_onsets.items():
            distance = i - anchor
            if not 1 <= distance <= 4:
                continue
            # Do not carry the onset anchor beyond intervening punctuation.
            if any(
                words[k] is not None and words[k].pos_ == "PUNCT"
                for k in range(anchor + 1, i)
            ):
                continue
            if contracted:
                matrix[i, anchor] += (1.8, 6.0, 4.0, 2.2)[distance - 1]
            elif distance == 1 and (
                words[anchor].pos_ in ("VERB", "AUX")
                or words[anchor].tag_ in ("WDT", "WP", "WP$", "WRB")
            ):
                matrix[i, anchor] += 1.8

    return (
        "local_lookback_with_quote_onsets",
        make_row_stochastic(apply_causal_mask(matrix)),
    )


def prog_L0H16(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Predict a BOS sink, with competing punctuation anchors in quoted dialogue.
    Dialogue anchors receive mass from BOS without changing self-attention."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_dialogue_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    pos_adjustment = {
        "DET": 0.75,
        "AUX": 0.80,
        "PRON": 0.45,
        "CCONJ": 0.40,
        "SCONJ": 0.35,
        "PART": 0.20,
        "ADP": 0.10,
        "ADV": 0.10,
        "VERB": -0.05,
        "ADJ": -0.20,
        "NOUN": -0.45,
        "PROPN": -0.85,
        "NUM": -0.20,
        "PUNCT": -0.50,
        "SPACE": -0.20,
    }

    # Activate only for quoted, comma-delimited dialogue.
    dialogue = any(c in sentence for c in '"“”') and "," in sentence
    anchor_strength = np.zeros(n, dtype=np.float64)
    if dialogue:
        for j in range(1, n):
            text = tokens[j].lstrip("Ġ▁").strip()
            if not text or not all(c in ",.!?\"“”" for c in text):
                continue
            if any(c in text for c in ".!?"):
                anchor_strength[j] = 0.075
            elif "," in text:
                anchor_strength[j] = 0.055
            elif any(c in text for c in '"“”'):
                anchor_strength[j] = 0.035

    attention[0, 0] = 1.0
    for i in range(1, n):
        linked = alignment[i]
        adjustment = 0.0
        if linked:
            word = doc[linked[-1]]
            adjustment = pos_adjustment.get(word.pos_, 0.0)

        clean = tokens[i].lstrip("Ġ▁").strip()
        if clean and all(c in ".!?\"'”’" for c in clean):
            adjustment = 0.35

        # A fixed, unusually strong sink competes with a growing causal prefix.
        # Sublinear growth permits substantial sink attention even late in text.
        sink_logit = 4.35 + adjustment
        competing_mass = float(i) ** 0.92
        sink_probability = 1.0 / (
            1.0 + competing_mass * np.exp(-sink_logit)
        )

        # The default residual and its decay remain unchanged.
        distance = i - np.arange(1, i + 1, dtype=np.float64)
        residual = 1.0 + 0.20 * np.exp(-distance / 4.0)
        residual /= residual.sum()

        attention[i, 0] = sink_probability
        attention[i, 1:i + 1] = (1.0 - sink_probability) * residual

        # Transfer only BOS mass to earlier dialogue boundaries. Excluding i
        # preserves the original self-attention weight exactly.
        if dialogue and linked and word.pos_ not in ("PUNCT", "SPACE"):
            strength = {
                "NOUN": 1.6,
                "PROPN": 1.8,
                "VERB": 1.1,
                "ADJ": 1.2,
                "ADV": 1.0,
            }.get(word.pos_, 0.65)
            additions = (
                strength
                * anchor_strength[1:i]
                * np.exp(-(i - np.arange(1, i)) / 35.0)
            )
            total = float(additions.sum())
            if total > 0.0:
                transfer = min(total, 0.24, 0.40 * attention[i, 0])
                attention[i, 0] -= transfer
                attention[i, 1:i] += additions * (transfer / total)

    return "bos_sink_with_dialogue_anchors", attention


def prog_L0H17(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink and clause anchors, with dependency-local retrieval of
    nonfinite predicates and nominal governors by linking function tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    matrix = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_local_governors", matrix

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special = set(tokenizer.all_special_tokens)
    words = []
    for indices in aligned:
        words.append(doc[indices[-1]] if indices else None)

    bos = 0
    first = next(
        (i for i, t in enumerate(tokens)
         if t not in special and words[i] is not None),
        0,
    )

    # Anchor strength is a key-side property, shared by all subsequent queries.
    anchors = np.full(n, 0.25, dtype=np.float64)
    finite = np.zeros(n, dtype=bool)
    for j, w in enumerate(words):
        if w is None or tokens[j] in special:
            anchors[j] = 0.12
            continue
        finite[j] = (
            w.pos_ in ("VERB", "AUX")
            and (
                "Fin" in w.morph.get("VerbForm")
                or w.dep_ == "ROOT"
            )
        )
        if finite[j]:
            anchors[j] = 2.4
        elif w.pos_ == "PRON":
            anchors[j] = 1.7
        elif w.pos_ == "DET":
            anchors[j] = 0.8
        elif w.pos_ in ("NOUN", "PROPN"):
            anchors[j] = 0.45
        elif w.is_punct:
            anchors[j] = 0.15
    anchors[first] = max(anchors[first], 3.8)

    for i, w in enumerate(words):
        if i == 0:
            matrix[i, 0] = 1.0
            continue

        distance = i - np.arange(i + 1)
        weights = anchors[:i + 1] / (1.0 + 0.035 * distance)
        weights = weights.copy()
        weights[bos] = 0.0
        weights[i] += 0.65

        if w is None:
            sink = 0.30
        elif w.pos_ in ("NOUN", "PROPN", "ADJ", "VERB"):
            sink = 0.70 / (1.0 + 0.012 * max(0, i - 4))
            if w.pos_ == "ADJ":
                sink += 0.10
            if w.pos_ == "VERB" and w.dep_ in ("xcomp", "ccomp"):
                sink -= 0.12
        elif w.pos_ == "ADV":
            sink = 0.56
        elif w.pos_ in ("DET", "PRON"):
            sink = 0.13
        elif w.pos_ == "AUX":
            sink = 0.17
        elif w.is_punct or w.pos_ in ("CCONJ", "SCONJ", "ADP", "PART"):
            sink = 0.10
        else:
            sink = 0.28

        if i == first:
            if w is not None and w.pos_ in ("DET", "NUM", "PROPN"):
                sink = 0.41
            elif w is not None and w.pos_ == "PRON":
                sink = 0.61
            else:
                sink = 0.64

        if w is not None:
            # Function tokens tend to preserve an earlier clause anchor.
            if w.pos_ in ("AUX", "CCONJ", "SCONJ", "ADP", "PART") or w.is_punct:
                previous = [
                    j for j in range(first, i)
                    if finite[j]
                ]
                if previous:
                    weights[previous[-1]] += 5.0
                weights[first] += 2.0

            # Articles favor earlier determiner/phrase-onset positions.
            if w.pos_ == "DET" and "Yes" not in w.morph.get("Poss"):
                previous = [
                    j for j in range(first, i)
                    if words[j] is not None and words[j].pos_ == "DET"
                ]
                if previous:
                    weights[previous[-1]] += 4.5
                weights[first] += 2.0

            # Approximate antecedent retrieval using only linguistic features.
            if w.pos_ == "PRON" or "Yes" in w.morph.get("Poss"):
                candidates = []
                for j in range(first, i):
                    antecedent = words[j]
                    if antecedent is None or antecedent.i >= w.i:
                        continue
                    if antecedent.pos_ not in ("PRON", "NOUN", "PROPN"):
                        continue
                    compatibility = 1.0
                    for feature in ("Gender", "Number", "Person"):
                        a = set(w.morph.get(feature))
                        b = set(antecedent.morph.get(feature))
                        if a and b and not a.intersection(b):
                            compatibility *= 0.12
                    subject = antecedent.dep_ in (
                        "nsubj", "nsubjpass", "csubj", "poss"
                    )
                    score = compatibility * (2.8 if subject else 0.8)
                    if antecedent.pos_ == "PRON":
                        score *= 1.6
                    score /= 1.0 + 0.025 * (i - j)
                    candidates.append((score, j))
                if candidates:
                    score, j = max(candidates)
                    weights[j] += 11.0 * score
                    sink *= 0.75

            # Linking tokens can retrieve a local governor that the finite-
            # predicate heuristic misses. Skip future heads, but do not cross
            # an already available governor to select a more distant ancestor.
            if (
                w.pos_ in ("ADP", "PART", "CCONJ", "SCONJ")
                and w.dep_ in ("prep", "case", "aux", "mark", "cc")
            ):
                head = w.head
                for _ in range(3):
                    if head.i < w.i:
                        if head.pos_ in ("NOUN", "PROPN", "ADJ", "VERB", "ADV"):
                            candidates = [
                                j for j in range(first, i)
                                if words[j] is not None
                                and words[j].i == head.i
                                and tokens[j] not in special
                            ]
                            if candidates:
                                j = candidates[-1]
                                if not finite[j]:
                                    weights[j] += 5.0
                        break
                    if head.head.i == head.i:
                        break
                    head = head.head

        sink = float(np.clip(sink, 0.04, 0.92))
        total = weights.sum()
        if total > 0:
            matrix[i, :i + 1] = (1.0 - sink) * weights / total
            matrix[i, bos] += sink
        else:
            matrix[i, bos] = 1.0

    return "bos_sink_local_governors", make_row_stochastic(matrix)


def prog_L0H18(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with local phrase binding and selective clause/particle binding.
    Missed adjacent scopal links draw mass only from BOS, preserving the diagonal.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_scopal_binding", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special_tokens = set(tokenizer.all_special_tokens)
    words = []
    for indices in alignment:
        candidates = [doc[k] for k in indices if not doc[k].is_space]
        words.append(candidates[-1] if candidates else None)

    attention[0, 0] = 1.0

    for i in range(1, n):
        word = words[i]
        previous = words[i - 1] if i > 1 else None
        raw = tokens[i]
        surface = raw.lstrip("Ġ▁")
        is_special = raw in special_tokens
        is_space = not surface or surface.isspace()
        is_punctuation = (
            word is not None and word.is_punct
        ) or (
            bool(surface)
            and all(not c.isalnum() and not c.isspace() for c in surface)
        )

        # Sink strength decreases as more competing keys accumulate.
        sink = 0.31 + 0.57 * np.exp(-i / 22.0)
        if word is not None:
            if word.pos_ == "DET" or word.dep_ == "poss":
                sink += 0.12
            elif word.pos_ in ("CCONJ", "SCONJ", "AUX"):
                sink += 0.06
            elif word.pos_ in ("NOUN", "PROPN"):
                sink -= 0.05

        if is_space:
            sink = 0.44 + 0.30 * np.exp(-i / 24.0)
        if is_punctuation:
            sink = 0.43 + 0.44 * np.exp(-i / 32.0)
            if any(c in ".!?" for c in surface):
                sink = 0.67 + 0.22 * np.exp(-i / 35.0)
        if i == 1:
            sink = 0.89
        if is_special:
            sink = 0.95
        sink = float(np.clip(sink, 0.20, 0.96))

        # Residual attention is predominantly local but not exclusively diagonal.
        positions = np.arange(1, i + 1)
        residual = (
            0.55 * np.exp(-(i - positions) / 3.2)
            + 0.20 * np.exp(-(i - positions) / 14.0)
        )
        residual[-1] += 0.45
        attention[i, 1:i + 1] = (1.0 - sink) * residual / residual.sum()
        attention[i, 0] = sink

        strength = 0.0
        target = i - 1

        if word is not None and previous is not None and not is_punctuation:
            if word.i == previous.i:
                # Orthographic continuations usually bind to the preceding piece.
                if word.pos_ != "PART" and word.tag_ != "POS":
                    strength = 0.76
            elif previous.i + 1 == word.i:
                ppos = previous.pos_
                pos = word.pos_

                if pos == "ADP":
                    if ppos in ("VERB", "AUX"):
                        strength = 0.77
                    elif ppos == "ADV":
                        strength = 0.73
                    elif ppos in ("NOUN", "PROPN"):
                        strength = 0.43
                    elif ppos == "ADJ":
                        strength = 0.52

                    if word.head.i == previous.i:
                        strength += 0.05

                elif pos == "PART" and word.dep_ in ("aux", "mark"):
                    if ppos in ("VERB", "ADJ"):
                        strength = 0.68

                elif pos == "ADV" and word.dep_ == "prt":
                    if ppos == "VERB":
                        strength = 0.79

                elif pos in ("ADJ", "ADV", "DET"):
                    if previous.dep_ in ("advmod", "quantmod") and (
                        previous.head.i == word.i
                    ):
                        strength = 0.67

                elif pos in ("NOUN", "PROPN"):
                    if previous.dep_ == "nummod" and previous.head.i == word.i:
                        strength = 0.66
                    elif previous.dep_ == "amod" and previous.head.i == word.i:
                        strength = 0.43
                    elif previous.dep_ == "compound" and previous.head.i == word.i:
                        strength = 0.48

                # Some prepositions instead favor their own position.
                if pos == "ADP" and ppos in ("NOUN", "PROPN") and strength < 0.50:
                    attention[i] *= 0.78
                    attention[i, i] += 0.22

        if strength > 0.0 and target > 0:
            strength = float(np.clip(strength, 0.0, 0.84))
            attention[i] *= 1.0 - strength
            attention[i, target] += strength

        # Only repair previously unhandled adjacent scopal/particle links.
        # Transfer BOS mass rather than rescaling the original residual.
        if (
            strength == 0.0
            and target > 0
            and word is not None
            and previous is not None
            and previous.i + 1 == word.i
            and not is_special
            and not is_space
            and not is_punctuation
        ):
            desired = 0.0
            if word.pos_ == "SCONJ":
                if (
                    previous.pos_ == "ADV"
                    and previous.dep_ == "advmod"
                    and previous.head.i == word.i
                ):
                    desired = 0.82
                elif word.dep_ == "mark" and previous.pos_ == "VERB":
                    desired = 0.58
            elif (
                word.pos_ == "ADV"
                and word.head.i == previous.i
                and previous.pos_ == "VERB"
                and (
                    word.tag_ == "RP"
                    or (
                        word.dep_ == "advmod"
                        and previous.dep_ in ("ccomp", "xcomp")
                    )
                )
            ):
                desired = 0.82

            if desired > 0.0:
                transfer = min(
                    max(0.0, desired - attention[i, target]),
                    0.90 * attention[i, 0],
                )
                attention[i, 0] -= transfer
                attention[i, target] += transfer

    return (
        "bos_sink_scopal_binding",
        make_row_stochastic(apply_causal_mask(attention)),
    )


def prog_L0H19(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with persistent grammatical anchors: some BOS mass migrates to
    preceding definite determiners, coordinators, and complement introducers.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_persistent_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    words = [
        doc[indices[0]] if indices else None
        for indices in alignment
    ]
    special = [
        token in tokenizer.all_special_tokens for token in tokens
    ]

    # Locate the first model piece of each linguistic token.
    first_piece = {}
    for i, indices in enumerate(alignment):
        if special[i]:
            continue
        for k in indices:
            if k not in first_piece:
                first_piece[k] = i

    attention[0, 0] = 1.0

    for i in range(1, n):
        word = words[i]
        pos = word.pos_ if word is not None else ""
        dep = word.dep_ if word is not None else ""
        early = np.exp(-(i - 1) / 12.0)

        sink = 0.30 + 0.35 * early
        if pos in ("VERB", "AUX"):
            sink = 0.34 + 0.61 * early
        elif pos == "PROPN":
            sink = 0.53 + 0.44 * early
        elif pos == "ADJ":
            sink = 0.41 + 0.45 * early
        elif pos == "DET":
            sink = 0.50 + 0.34 * early
        elif pos == "PRON":
            sink = 0.29 + 0.59 * early

        if i == 1:
            sink = 0.92

        surface = tokens[i].lstrip("Ġ▁").strip()
        terminal = bool(surface) and any(c in ".!?" for c in surface)
        if terminal:
            sink = 0.66 + 0.14 * np.exp(-i / 25.0)

        # A diffuse causal background, with stronger nearby function-word keys.
        keys = np.arange(1, i + 1)
        weights = 0.10 * np.exp(-(i - keys) / 10.0)
        weights[-1] += 0.15

        for j in range(1, i + 1):
            previous = words[j]
            if special[j] or previous is None:
                continue
            distance = i - j
            if previous.pos_ in ("DET", "ADP", "AUX", "CCONJ", "PRON"):
                weights[j - 1] += 0.35 * np.exp(-distance / 6.0)
            if previous.pos_ in ("ADP", "CCONJ", "AUX"):
                weights[j - 1] += 0.20 * np.exp(-distance / 13.0)

        # Nominal queries often select their preceding definite determiner.
        determiner = None
        if word is not None and pos in ("NOUN", "PROPN"):
            for child in word.children:
                if child.dep_ == "det" and child.i in first_piece:
                    j = first_piece[child.i]
                    if 0 < j < i:
                        if "Def" in child.morph.get("Definite"):
                            determiner = j
                            break
            if determiner is not None:
                gap = i - determiner
                strength = np.exp(-max(gap - 1, 0) / 2.5)
                sink *= 1.0 - 0.76 * strength
                weights[determiner - 1] += 4.0 * strength

        # Verbal queries can select a preceding subject, especially locally.
        if word is not None and pos in ("VERB", "AUX"):
            for child in word.children:
                if child.dep_ in ("nsubj", "nsubjpass", "csubj"):
                    j = first_piece.get(child.i, -1)
                    if 0 < j < i:
                        strength = np.exp(-(i - j - 1) / 3.0)
                        weights[j - 1] += 1.1 * strength
                        if child.pos_ == "PRON" and i - j <= 2:
                            sink *= 0.64

        # Degree modifiers and quantifiers can point back to an auxiliary.
        if pos in ("ADV", "ADJ", "DET") and dep in (
            "advmod", "predet", "acomp", "attr"
        ):
            for j in range(i - 1, max(0, i - 5), -1):
                previous = words[j]
                if previous is not None and previous.pos_ == "AUX":
                    weights[j - 1] += 1.7
                    sink *= 0.68
                    break

        sink = float(np.clip(sink, 0.08, 0.99))
        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * weights / weights.sum()

        # Special case: persistent grammatical anchors compete with BOS.
        # Transfer only BOS mass; preserve self-attention and all other edges.
        if (
            word is not None
            and not special[i]
            and not terminal
            and pos in ("DET", "PRON", "VERB", "AUX", "ADJ", "NOUN", "ADP", "PART")
            and first_piece.get(word.i) == i
            and determiner is None
        ):
            anchors = []
            for j in range(max(1, i - 24), i):
                previous = words[j]
                if (
                    special[j]
                    or previous is None
                    or first_piece.get(previous.i) != j
                    or previous.i == word.i
                ):
                    continue

                strength = 0.0
                if (
                    previous.pos_ == "DET"
                    and "Def" in previous.morph.get("Definite")
                    and i - j >= 2
                ):
                    strength = 1.0
                elif previous.pos_ == "CCONJ" and previous.dep_ == "cc":
                    strength = 1.1
                elif (
                    previous.dep_ == "mark"
                    and previous.head.dep_ in ("ccomp", "xcomp")
                ):
                    strength = 1.1
                elif (
                    previous.pos_ == "PART"
                    and previous.dep_ in ("aux", "mark")
                    and previous.head.pos_ in ("VERB", "AUX")
                    and "Inf" in previous.head.morph.get("VerbForm")
                ):
                    strength = 0.8

                if strength:
                    anchors.append(
                        (j, strength * np.exp(-(i - j - 1) / 24.0))
                    )

            if anchors:
                if pos == "DET":
                    fraction = (
                        0.95 if "Ind" in word.morph.get("Definite") else 0.35
                    )
                elif pos in ("PRON", "ADJ", "NOUN"):
                    fraction = 0.80
                elif pos == "VERB":
                    fraction = 0.78
                elif pos == "AUX":
                    fraction = 0.55
                else:
                    fraction = 0.50

                total = sum(score for _, score in anchors)
                persistence = min(1.0, max(score for _, score in anchors))
                transfer = attention[i, 0] * fraction * persistence
                attention[i, 0] -= transfer
                for j, score in anchors:
                    attention[i, j] += transfer * score / total

    return "bos_sink_with_persistent_anchors", make_row_stochastic(attention)


def prog_L0H20(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with long-context residual recovery and weaker quoted endings.
    Special cases redistribute off-diagonal mass, preserving self-attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_residual_recovery", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special_tokens = tokenizer.all_special_tokens

    attention[0, 0] = 1.0

    for i in range(1, n):
        clean = tokens[i].replace("\u0120", " ").replace("\u010a", "\n").strip()
        aligned = alignment[i]
        word = None
        if aligned:
            word = doc[aligned[0]]
            for k in aligned:
                if not doc[k].is_space and not doc[k].is_punct:
                    word = doc[k]
                    break

        strength = 1.0
        if word is not None:
            pos = word.pos_
            if pos == "DET":
                strength = 1.65
            elif pos == "AUX":
                strength = 1.45
            elif pos == "CCONJ":
                strength = 1.45
            elif pos == "PROPN":
                strength = 1.40
            elif pos == "ADJ":
                strength = 1.20
            elif pos == "VERB":
                strength = 1.05
            elif pos == "NOUN":
                strength = 0.90
            elif pos in ("ADP", "PART"):
                strength = 0.80

        if clean and any(c in ".!?" for c in clean):
            strength = 5.50
        elif clean and all(c in ",;:" for c in clean):
            strength = 1.45
        elif not clean:
            strength = 1.30
        elif tokens[i] in special_tokens:
            strength = 2.0

        sink_mass = 6.5 * strength
        background_mass = float(i) ** 0.78
        sink_probability = sink_mass / (sink_mass + background_mass)

        distances = i - np.arange(1, i + 1, dtype=np.float64)
        residual = 0.75 + 0.25 * np.exp(-distances / 8.0)
        attention[i, 1:i + 1] = (
            (1.0 - sink_probability) * residual / residual.sum()
        )
        attention[i, 0] = sink_probability

        # A combined terminator/closing-quote token is not a pure BOS reset.
        # Release only BOS mass; leave the original diagonal untouched.
        quoted_ending = (
            any(c in ".!?" for c in clean)
            and any(c in "\"'”’»" for c in clean)
        )
        if quoted_ending and i > 1:
            weights = attention[i, 1:i].copy()
            total = weights.sum()
            if total > 0.0:
                released = 0.40 * attention[i, 0]
                attention[i, 0] -= released
                attention[i, 1:i] += released * weights / total

        # At longer positions, some diffuse old-context mass remains at BOS.
        # Indefinite determiners and punctuation retain the original behavior.
        elif (
            i >= 18
            and word is not None
            and word.pos_ not in ("PUNCT", "SPACE")
            and tokens[i] not in special_tokens
            and not any(c in ".!?" for c in clean)
            and (
                word.pos_ != "DET"
                or "Def" in word.morph.get("Definite")
            )
        ):
            recovered = 0.38 * attention[i, 1:i - 2].copy()
            attention[i, 1:i - 2] -= recovered
            recovered_mass = recovered.sum()

            previous = None
            for k in alignment[i - 1]:
                if not doc[k].is_space and not doc[k].is_punct:
                    previous = doc[k]
                    break

            anchor_mass = 0.0
            if (
                previous is not None
                and previous.i not in aligned
                and previous.pos_ in ("DET", "ADP", "PRON", "PART", "SCONJ")
            ):
                anchor_mass = 0.20 * recovered_mass
                attention[i, i - 1] += anchor_mass
            attention[i, 0] += recovered_mass - anchor_mass

    return "bos_sink_with_residual_recovery", attention


def prog_L0H21(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Lexical BOS sink with boundary-token exceptions: standalone exclamations
    favor BOS, while whitespace queries favor context; retain original diagonals.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "lexical_bos_boundary_exception", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    sink_prior = {
        "NOUN": 0.975,
        "PROPN": 0.980,
        "VERB": 0.965,
        "ADJ": 0.970,
        "ADV": 0.875,
        "NUM": 0.950,
        "PRON": 0.620,
        "AUX": 0.560,
        "DET": 0.170,
        "ADP": 0.280,
        "CCONJ": 0.270,
        "SCONJ": 0.400,
        "PART": 0.380,
        "INTJ": 0.935,
        "PUNCT": 0.090,
        "SPACE": 0.080,
        "SYM": 0.900,
        "X": 0.930,
    }
    key_strength = np.ones(n, dtype=np.float64)
    attention[0, 0] = 1.0

    for i in range(1, n):
        raw = tokens[i]
        clean = raw.lstrip("Ġ▁").strip()
        overlapping = alignment[i]
        word = None
        if overlapping:
            word = max(
                (doc[k] for k in overlapping),
                key=lambda w: (
                    not w.is_space,
                    not w.is_punct,
                    len(w.text),
                ),
            )

        pos = word.pos_ if word is not None else "X"
        probability = sink_prior.get(pos, 0.850)

        if pos in ("NOUN", "PROPN", "VERB", "ADJ", "NUM"):
            # Early lexical queries are often almost entirely absorbed by BOS.
            early = np.exp(-((i / 11.0) ** 3))
            probability += (0.9995 - probability) * early
            key_strength[i] = 1.25
        elif pos in ("PUNCT", "SPACE"):
            key_strength[i] = 0.65
        else:
            key_strength[i] = 0.85

        if word is not None:
            if word.dep_ in ("aux", "auxpass", "cop"):
                probability = 0.550
            elif word.dep_ == "poss":
                probability = 0.780
            elif word.tag_ == "MD":
                probability = 0.920
            elif word.tag_ in ("WDT", "WP", "WP$", "WRB"):
                probability = 0.850
            elif word.dep_ == "prt":
                probability = 0.700

        # Sentence-ending marks merged with closing quotes behave differently
        # from ordinary separators.
        if clean and all(not c.isalnum() for c in clean):
            if ("?" in clean or "!" in clean) and any(
                c in clean for c in ('"', "'", "”", "’")
            ):
                probability = 0.945
            else:
                probability = 0.090

        if i == 1:
            probability = 0.910 if pos == "DET" else 0.998

        probability = float(np.clip(probability, 0.01, 0.9997))
        attention[i, 0] = probability

        positions = np.arange(1, i + 1)
        distances = i - positions
        residual = key_strength[1:i + 1] * (
            0.25 + np.exp(-distances / 3.0)
        )
        residual[-1] *= 1.6 if pos == "PUNCT" else 1.15
        attention[i, 1:i + 1] = (
            (1.0 - probability) * residual / residual.sum()
        )

        # Boundary-only exception. Transfer mass between BOS and prior context,
        # preserving the original self-weight and relative contextual decay.
        is_whitespace = bool(raw) and not clean
        is_exclamation = bool(clean) and "!" in clean and all(
            c in "!?" for c in clean
        )
        if is_whitespace or is_exclamation:
            context_mass = attention[i, 1:i].sum()
            if context_mass > 0.0:
                target = 0.065 if is_whitespace else 0.650
                target = min(target, 1.0 - attention[i, i])
                attention[i, 1:i] *= (
                    (1.0 - attention[i, i] - target) / context_mass
                )
                attention[i, 0] = target

    return "lexical_bos_boundary_exception", make_row_stochastic(attention)


def prog_L0H22(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention-sink head: every query attends to the initial token.
    The examples provide no evidence for a linguistic correction."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n:
        attention[:, 0] = 1.0
    return "bos_attention_sink", attention


def prog_L0H23(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink: essentially all attention goes to the first token,
    with no reliably supported syntactic or semantic modulation.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention_matrix = np.zeros((n, n), dtype=np.float64)
    if n:
        attention_matrix[:, 0] = 1.0
    return "bos_attention_sink", attention_matrix


def prog_L1H0(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with mild positional dilution and POS-dependent leakage.
    Residual attention is diffuse and weakly biased toward recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_pos_leakage", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    pos_factors = {
        "PRON": 0.75,
        "AUX": 0.80,
        "VERB": 0.85,
        "ADV": 0.90,
        "PART": 0.90,
        "SCONJ": 0.90,
        "CCONJ": 1.00,
        "ADP": 1.05,
        "DET": 1.20,
        "ADJ": 1.15,
        "NOUN": 1.65,
        "PROPN": 1.75,
        "NUM": 1.40,
        "PUNCT": 1.25,
        "SPACE": 1.50,
    }

    for i in range(1, n):
        pos = ""
        if alignment[i]:
            pos = doc[alignment[i][0]].pos_

        factor = pos_factors.get(pos, 1.20)
        # Early queries have little competition; later leakage saturates.
        odds = (0.023 + 0.105 * (1.0 - np.exp(-(i - 1) / 7.0))) * factor

        # Initial determiners have a somewhat weaker sink preference.
        if pos == "DET":
            odds += 0.022 * np.exp(-(i - 1) / 2.0)

        sink_mass = 1.0 / (1.0 + odds)
        attention[i, 0] = sink_mass

        distances = i - np.arange(1, i + 1)
        background = 0.65 + 0.35 * np.exp(-distances / 6.0)
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * background / background.sum()
        )

    return "bos_sink_with_pos_leakage", attention


def prog_L1H1(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with a local syntactic-anchor exception for predicates and possessives.
    Transfer only BOS mass to the anchor, preserving self-attention and other edges.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_syntactic_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        aligned = alignment[i]
        word = doc[aligned[0]] if aligned else None
        surface = tokens[i].replace("Ġ", " ").replace("Ċ", "\n")
        stripped = surface.strip()

        sink = 0.63 + 0.12 * np.exp(-max(i - 2, 0) / 3.0)

        if word is not None:
            pos = word.pos_
            dep = word.dep_

            if pos == "PROPN":
                sink = 0.93
            elif pos == "PRON":
                sink = 0.78
                if dep in ("nsubj", "nsubjpass", "csubj"):
                    sink += 0.055
            elif pos == "DET":
                sink += 0.055
            elif pos in ("VERB", "ADJ"):
                sink -= 0.045
            elif pos == "AUX":
                sink += 0.065
            elif pos in ("SCONJ", "CCONJ"):
                sink += 0.055
            elif pos == "ADV":
                sink += 0.015

            if word.is_sent_start:
                sink = max(sink, 0.86)

            if i > 1 and alignment[i - 1]:
                if aligned[0] in alignment[i - 1]:
                    sink += 0.10

        if not stripped:
            sink = 0.92
        elif all(not c.isalnum() for c in stripped):
            if any(c in ".!?" for c in stripped):
                sink = 0.85
            elif any(c in "\"'“”‘’" for c in stripped):
                sink = 0.85
            else:
                sink = max(sink, 0.76)

        if i == 1:
            sink = 0.977

        sink = float(np.clip(sink, 0.45, 0.97 if i > 1 else 0.99))
        positions = np.arange(1, i + 1)
        residual = 0.35 + np.exp(-(i - positions) / 5.0)
        residual /= residual.sum()

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual

        # A directly adjacent syntactic anchor can compete with BOS.
        if i > 1 and word is not None and alignment[i - 1]:
            previous = doc[alignment[i - 1][-1]]
            if previous.i < word.i and not word.is_sent_start:
                linked = previous.head.i == word.i or word.head.i == previous.i
                target = 0.0
                if linked:
                    if word.pos_ in ("VERB", "AUX", "ADJ"):
                        if previous.pos_ == "AUX":
                            target = 0.32
                        elif previous.pos_ == "PRON" and previous.dep_ in (
                            "nsubj", "nsubjpass", "csubj"
                        ):
                            target = 0.30
                        elif word.pos_ == "VERB" and previous.pos_ == "PART":
                            target = 0.32
                        elif word.pos_ == "VERB" and previous.pos_ == "VERB":
                            target = 0.40
                        elif word.pos_ == "ADJ" and previous.dep_ == "advmod":
                            target = 0.21
                    elif word.pos_ == "NOUN" and previous.dep_ == "poss":
                        target = 0.35

                transfer = min(
                    max(target - attention[i, i - 1], 0.0),
                    max(attention[i, 0] - 0.22, 0.0),
                )
                attention[i, 0] -= transfer
                attention[i, i - 1] += transfer

    return "bos_sink_with_local_syntactic_anchors", attention


def prog_L1H2(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Dominant beginning-of-sequence attention sink with mild POS modulation.
    Remaining attention follows a weak causal recency prior.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_weak_recency", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.93
        aligned = alignment[i]

        if aligned:
            word = doc[aligned[0]]
            if word.pos_ == "PROPN":
                sink_mass = 0.96
            elif word.pos_ in ("NOUN", "ADJ", "DET", "ADP"):
                sink_mass = 0.945
            elif word.pos_ in ("VERB", "AUX"):
                sink_mass = 0.905
            elif word.pos_ in ("PUNCT", "SPACE"):
                sink_mass = 0.89

        if i == 1:
            sink_mass = 0.96

        positions = np.arange(1, i + 1, dtype=np.float64)
        residual = 0.5 / i + 0.5 * np.exp(-(i - positions) / 3.0)
        residual /= residual.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_weak_recency", attention


def prog_L1H3(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with selective retrieval of an already-seen syntactic governor
    or preceding wordpiece; preserve the original diagonal and local residual."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_governor_exceptions", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    word_tokens = [[] for _ in doc]
    for ti, indices in enumerate(alignment):
        for k in indices:
            word_tokens[k].append(ti)

    attention[0, 0] = 1.0

    for i in range(1, n):
        words = [doc[k] for k in alignment[i]]
        if words:
            word = words[-1]
            pos = word.pos_
            if pos in ("NOUN", "PROPN", "VERB", "AUX"):
                sink = 0.950
            elif pos in ("PRON", "ADJ", "ADV"):
                sink = 0.935
            elif pos in ("ADP", "PART", "SCONJ"):
                sink = 0.875
            elif pos in ("DET", "CCONJ"):
                sink = 0.905
            else:
                sink = 0.925

            if word.dep_ in ("nsubj", "nsubjpass", "ROOT"):
                sink += 0.010
            if word.is_sent_start:
                sink += 0.020
        else:
            # Standalone whitespace and special tokens tend to be strong sinks.
            clean = tokens[i].replace("Ġ", " ").replace("Ċ", "\n")
            sink = 0.980 if not clean.strip() else 0.940

        # The earliest queries have especially concentrated BOS attention.
        sink += 0.030 * np.exp(-(i - 1) / 2.0)
        sink = float(np.clip(sink, 0.84, 0.995))
        if i == 1:
            sink = 0.995

        attention[i, 0] = sink
        distances = i - np.arange(1, i + 1)
        residual = np.exp(-0.45 * distances)
        attention[i, 1:i + 1] = (
            (1.0 - sink) * residual / residual.sum()
        )

        # Exceptions move only BOS mass: the diagonal and all unrelated
        # residual entries remain exactly as in the original model.
        if words and i > 1:
            target = None
            strength = 0.0
            previous_pieces = [j for j in word_tokens[word.i] if 0 < j < i]

            if previous_pieces and word.pos_ in ("NOUN", "PROPN", "VERB"):
                # Continuation pieces retrieve the preceding piece of the word.
                target = previous_pieces[-1]
                strength = 0.30 if len(previous_pieces) == 1 else 0.22
            else:
                governor = word.head
                distance = word.i - governor.i

                if 0 < distance <= 8 and governor.pos_ == "VERB":
                    if word.dep_ in ("prep", "agent"):
                        strength = 0.38
                    elif word.dep_ in ("dobj", "obj", "iobj", "dative"):
                        strength = 0.40 if word.pos_ == "PRON" else 0.20
                    elif word.dep_ in ("advmod", "prt"):
                        strength = 0.38
                        if governor.tag_ == "VBG":
                            strength = 0.65
                    elif word.dep_ in ("nsubj", "nsubjpass"):
                        strength = 0.20
                    elif word.dep_ in ("aux", "auxpass") and word.pos_ == "PART":
                        strength = 0.10

                # A determiner/possessive can precede its nominal head but
                # still retrieve that noun's already-seen verbal governor.
                if word.dep_ in ("det", "poss") and governor.pos_ in ("NOUN", "PROPN"):
                    nominal = governor
                    if nominal.head.pos_ == "VERB":
                        governor = nominal.head
                        distance = word.i - governor.i
                        if (
                            nominal.dep_ in ("dobj", "obj", "iobj", "dative")
                            and 0 < distance <= 4
                        ):
                            strength = 0.24 if word.dep_ == "det" else 0.15
                    elif nominal.head.pos_ == "ADP":
                        governor = nominal.head.head
                        distance = word.i - governor.i
                        if governor.pos_ == "VERB" and 0 < distance <= 8:
                            strength = 0.12

                # Clause-opening markers may retrieve a preceding predicate,
                # even though their immediate syntactic head is still future.
                if word.dep_ == "mark" and word.head.i > word.i:
                    governor = word.head.head
                    distance = word.i - governor.i
                    if governor.pos_ == "ADJ" and 0 < distance <= 2:
                        strength = 0.30

                if strength > 0.0:
                    candidates = [
                        j for j in word_tokens[governor.i] if 0 < j < i
                    ]
                    if candidates:
                        target = candidates[-1]

            if target is not None:
                transfer = min(
                    max(0.0, strength - attention[i, target]),
                    max(0.0, attention[i, 0] - 0.10),
                )
                attention[i, 0] -= transfer
                attention[i, target] += transfer

    return "bos_sink_with_governor_exceptions", attention


def prog_L1H4(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with a local predicate bias and a preposition–determiner bridge.
    Prepositional noun phrases can retain attention on their introducing preposition.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_preposition_bridge", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    words = [doc[indices[-1]] if indices else None for indices in alignment]
    special_tokens = tokenizer.all_special_tokens
    attention[0, 0] = 1.0

    for i in range(1, n):
        word = words[i]
        previous = words[i - 1]
        target = i - 1
        sink_mass = 0.92
        local_strength = 0.70

        if word is not None:
            pos = word.pos_
            if word.is_punct:
                sink_mass = 0.96
            elif pos == "PROPN":
                sink_mass = 0.96
            elif pos in ("VERB", "AUX"):
                sink_mass = 0.94
            elif pos == "CCONJ":
                sink_mass = 0.95
            elif pos in ("ADP", "SCONJ", "PART"):
                sink_mass = 0.89
            elif pos == "NOUN":
                sink_mass = 0.90
            elif pos in ("ADJ", "ADV"):
                sink_mass = 0.85
            elif pos == "DET":
                sink_mass = 0.69
            elif pos == "PRON":
                sink_mass = 0.70

            if previous is not None:
                if pos == "PRON" and previous.pos_ == "AUX":
                    sink_mass = 0.27
                    local_strength = 0.97
                elif pos == "DET" and previous.pos_ == "VERB":
                    sink_mass = 0.30
                    local_strength = 0.97
                elif (
                    pos == "NOUN"
                    and previous.pos_ == "DET"
                    and word.dep_ in ("dobj", "obj", "npadvmod")
                ):
                    for j in range(i - 2, max(0, i - 5), -1):
                        candidate = words[j]
                        if candidate is not None and candidate.i == word.head.i:
                            target = j
                            sink_mass = 0.48
                            local_strength = 0.95
                            break

        # The first ordinary token and special tokens remain reliable sinks.
        if i == 1:
            sink_mass = 0.982
        if tokens[i] in special_tokens:
            sink_mass = 0.98

        # Preserve the original causal recency tail and self-attention.
        residual = np.zeros(i + 1, dtype=np.float64)
        if i > 1:
            distances = i - np.arange(1, i + 1)
            residual[1:] = np.exp(-distances / 2.0)
            residual /= residual.sum()
            residual *= 1.0 - local_strength
            residual[max(1, target)] += local_strength
        else:
            residual[i] = 1.0

        attention[i, :i + 1] = (1.0 - sink_mass) * residual
        attention[i, 0] = sink_mass

        # Narrow exception: ADP + determiner/possessive (+ object noun).
        # Move only BOS mass; leave self-attention and the decay tail intact.
        if (
            i > 1
            and word is not None
            and previous is not None
            and tokens[i] not in special_tokens
        ):
            bridge = None
            desired = 0.0
            if previous.pos_ == "ADP" and (
                word.pos_ == "DET" or word.dep_ == "poss"
            ):
                bridge = i - 1
                desired = 0.78 if bridge == 1 else 0.43
            elif (
                word.pos_ == "NOUN"
                and word.dep_ in ("pobj", "obj")
                and word.head.pos_ == "ADP"
                and (previous.pos_ == "DET" or previous.dep_ == "poss")
                and previous.head.i == word.i
            ):
                for j in range(i - 2, max(0, i - 5), -1):
                    candidate = words[j]
                    if candidate is not None and candidate.i == word.head.i:
                        bridge = j
                        possessive = previous.dep_ == "poss"
                        if candidate.tag_ == "TO":
                            desired = 0.08 if possessive else 0.14
                        else:
                            desired = 0.58 if possessive else 0.30
                        break

            if bridge is not None:
                transfer = min(
                    attention[i, 0],
                    max(0.0, desired - attention[i, bridge]),
                )
                attention[i, 0] -= transfer
                attention[i, bridge] += transfer

    return "bos_sink_with_preposition_bridge", make_row_stochastic(attention)


def prog_L1H5(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with selective attention to governors of prepositions and complements.
    Transfer only sink mass on these dependency links, preserving local/self attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_governor_residual", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    sink_by_pos = {
        "NOUN": 0.975,
        "PROPN": 0.982,
        "VERB": 0.950,
        "AUX": 0.963,
        "ADJ": 0.945,
        "PRON": 0.947,
        "DET": 0.941,
        "ADV": 0.913,
        "NUM": 0.946,
        "ADP": 0.850,
        "PART": 0.870,
        "CCONJ": 0.901,
        "SCONJ": 0.895,
        "INTJ": 0.953,
        "PUNCT": 0.890,
        "SPACE": 0.850,
        "SYM": 0.890,
        "X": 0.920,
    }

    # Sparse exceptions: map spaCy queries to earlier governing words.
    word_tokens = [[] for _ in doc]
    for ti, overlapping in enumerate(alignment):
        if ti > 0:
            for wi in overlapping:
                word_tokens[wi].append(ti)

    governor_links = {}
    for w in doc:
        links = []
        infinitive_marker = (
            w.pos_ == "PART"
            and w.dep_ in ("aux", "mark")
            and w.head.pos_ in ("VERB", "AUX")
        )
        if infinitive_marker:
            governor = w.head.head
            if governor.i < w.i and governor.i != w.head.i:
                links.append((governor.i, 0.55))
        elif w.pos_ == "ADP" and w.dep_ in ("prep", "agent", "dative"):
            if w.head.i < w.i and w.head.pos_ in ("VERB", "AUX", "NOUN"):
                mass = 0.40 if w.head.pos_ in ("VERB", "AUX") else 0.32
                links.append((w.head.i, mass))
        elif w.dep_ == "xcomp" and w.head.i < w.i:
            marked = any(
                c.i < w.i and c.pos_ == "PART" and c.dep_ in ("aux", "mark")
                for c in w.children
            )
            mass = (0.62 if w.pos_ == "AUX" else 0.22) if marked else 0.52
            links.append((w.head.i, mass))

        if w.pos_ == "VERB" and not links:
            modals = [
                c for c in w.children
                if c.dep_ == "aux" and c.tag_ == "MD" and c.i < w.i
            ]
            if modals:
                modal = modals[-1]
                past = "Past" in modal.morph.get("Tense")
                links.append((modal.i, 0.44 if past else 0.12))
                for c in w.children:
                    if c.dep_ in ("nsubj", "nsubjpass") and c.i < modal.i:
                        links.append((c.i, 0.12 if past else 0.03))
                        break

        # Carry a weaker governor trace into the immediately following article.
        if w.pos_ == "DET" and w.i > 0:
            previous = doc[w.i - 1]
            if previous.pos_ in ("ADP", "PART"):
                links.extend(
                    (target, 0.36 * mass)
                    for target, mass in governor_links.get(previous.i, [])
                )
        if links:
            governor_links[w.i] = links

    attention[0, 0] = 1.0
    for i in range(1, n):
        overlapping = alignment[i]
        word = None
        if overlapping:
            word = doc[overlapping[0]]
            for k in overlapping:
                if not doc[k].is_space and not doc[k].is_punct:
                    word = doc[k]
                    break

        if word is not None:
            sink = sink_by_pos.get(word.pos_, 0.930)
            if word.ent_type_ and word.pos_ in ("NOUN", "PROPN"):
                sink = min(0.989, sink + 0.003)
        else:
            clean = tokens[i].replace("Ġ", " ").replace("Ċ", "\n")
            sink = 0.850 if not clean.strip() else 0.915

        if i == 1:
            if word is not None and word.pos_ in ("PRON", "DET", "ADP"):
                sink = 0.998
            elif word is not None and word.pos_ == "PROPN":
                sink = 0.987
            else:
                sink = 0.991

        attention[i, 0] = sink

        # Original residual distribution, unchanged.
        positions = np.arange(1, i + 1, dtype=np.float64)
        residual = 0.35 / i + 0.65 * np.exp(-(i - positions) / 3.0)
        residual /= residual.sum()
        attention[i, 1:i + 1] = (1.0 - sink) * residual

        # Only the sink and explicitly detected governor edges are changed.
        if (
            i > 1
            and word is not None
            and word_tokens[word.i]
            and i == word_tokens[word.i][0]
            and word.i in governor_links
        ):
            transfers = []
            for target, mass in governor_links[word.i]:
                candidates = [j for j in word_tokens[target] if 0 < j < i]
                if candidates:
                    transfers.append((candidates[-1], mass))
            total = sum(mass for _, mass in transfers)
            if total > 0.0:
                scale = min(1.0, max(0.0, sink - 0.12) / total)
                for j, mass in transfers:
                    amount = scale * mass
                    attention[i, 0] -= amount
                    attention[i, j] += amount

    return "bos_sink_governor_residual", make_row_stochastic(attention)


def prog_L1H6(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with a punctuation-boundary exception in dialogue.
    Boundary redistribution preserves the original diagonal and default decay.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_boundary_exception", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    pos = [""] * n
    entities = [False] * n
    for i, indices in enumerate(alignment):
        if indices:
            word = doc[indices[-1]]
            pos[i] = word.pos_
            entities[i] = bool(word.ent_type_)

    attention[0, 0] = 1.0

    for i in range(1, n):
        # Sink odds decline sublinearly with the available context length.
        log_odds = np.log(16.0) - 0.84 * np.log(float(i))

        if pos[i] in ("NOUN", "PROPN"):
            log_odds += 0.35
        elif pos[i] in ("VERB", "AUX", "ADJ"):
            log_odds += 0.03
        elif pos[i] in ("PRON", "DET"):
            log_odds -= 0.18
        elif pos[i] in ("CCONJ", "SCONJ", "ADV", "PART"):
            log_odds -= 0.23
        elif pos[i] == "PUNCT":
            log_odds -= 0.16

        if entities[i]:
            log_odds += 0.10

        # Strong early-position anchoring is largely independent of syntax.
        if i == 1:
            log_odds = np.log(16.0)

        sink_mass = 1.0 / (1.0 + np.exp(-log_odds))
        attention[i, 0] = sink_mass

        positions = np.arange(1, i + 1)
        distances = i - positions
        residual = (
            1.0
            + 0.45 * np.exp(-distances / 3.0)
            + 0.15 / np.sqrt(positions)
        )
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * residual / residual.sum()
        )

    # Exception: terminal punctuation releases BOS mass; dialogue boundaries
    # become additional off-diagonal anchors for the following clause.
    terminal = []
    for token in tokens:
        surface = token.lstrip("ĠĊ").strip()
        terminal.append(
            any(c in ".!?" for c in surface)
            and not any(c.isalnum() for c in surface)
        )

    dialogue = (
        any(c in sentence for c in ('"', "“", "”", "«", "»"))
        or sum(terminal) > 1
    )
    boundary = None

    for i in range(1, n):
        if i > 1 and (terminal[i] or (dialogue and boundary is not None)):
            old_sink = attention[i, 0]
            self_mass = attention[i, i]
            new_sink = old_sink

            if terminal[i]:
                new_sink *= 0.55
            elif pos[i] in ("NOUN", "PROPN", "ADJ", "ADP"):
                # Content tokens can retain BOS anchoring well into dialogue.
                odds = old_sink / max(1.0 - old_sink, 1e-12)
                new_sink = (odds * np.exp(0.45)) / (
                    1.0 + odds * np.exp(0.45)
                )
            elif pos[i] in ("PRON", "DET", "ADV", "CCONJ", "SCONJ", "PUNCT"):
                new_sink *= 0.80

            new_sink = min(new_sink, 1.0 - self_mass)
            keys = np.arange(1, i)
            weights = attention[i, 1:i].copy()
            weights *= 1.0 + 2.0 / np.sqrt(keys)
            if dialogue and boundary is not None:
                weights *= 1.0 + 4.0 * np.exp(
                    -np.abs(keys - boundary) / 1.5
                )

            attention[i, 0] = new_sink
            attention[i, 1:i] = (
                (1.0 - self_mass - new_sink) * weights / weights.sum()
            )
            # attention[i, i] is deliberately unchanged.

        if terminal[i]:
            boundary = i

    return "bos_sink_with_boundary_exception", attention


def prog_L1H7(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with diffuse residual attention; quoted dialogue adds weak
    attention to earlier context, quotation boundaries, and early predicates.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_dialogue_residual", attention

    # Activate the additional pathway only for explicitly quoted dialogue.
    quote_indices = [
        j for j in range(1, n)
        if any(c in tokens[j] for c in ('"', '“', '”'))
    ]
    dialogue = len(quote_indices) >= 2
    predicate_indices = []

    if dialogue:
        doc = spacy_parse(sentence)
        alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
        for j in range(1, quote_indices[0]):
            if any(doc[k].pos_ in ("VERB", "AUX") for k in alignment[j]):
                predicate_indices.append(j)
                if len(predicate_indices) == 2:
                    break

    attention[0, 0] = 1.0

    for i in range(1, n):
        # Original default weights, including all self-attention terms.
        attention[i, 0] = 1.0
        attention[i, 1:i + 1] = 0.0028

        distances = i - np.arange(1, i + 1)
        attention[i, 1:i + 1] += 0.004 * np.exp(-distances / 2.0)

        # The first ordinary token has a somewhat stronger self competitor.
        attention[i, i] += 0.040 * np.exp(-(i - 1) / 1.2)

        if dialogue and i > 1:
            # Add only to strictly earlier ordinary keys, preserving the
            # original raw BOS and self weights.
            attention[i, 1:i] += 0.0011
            attention[i, 1] += 0.005

            for j in predicate_indices:
                if j < i:
                    attention[i, j] += 0.013 / len(predicate_indices)

            for q, j in enumerate(quote_indices):
                if j < i:
                    attention[i, j] += 0.008 if q % 2 == 0 else 0.003

            # Clause-ending punctuation releases more mass from the sink.
            if any(c in tokens[i] for c in (",", ".", "?", "!", ";", ":")):
                attention[i, 1:i] += 0.0015

    return (
        "bos_sink_with_dialogue_residual",
        make_row_stochastic(attention),
    )


def prog_L1H8(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Predict a POS-modulated BOS sink with boundary-triggered attention release.
    At sentence/quote boundaries, release sink mass without changing self-attention."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_boundary_release", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    sink_by_pos = {
        "NOUN": 0.945,
        "PROPN": 0.925,
        "ADJ": 0.890,
        "NUM": 0.890,
        "VERB": 0.805,
        "AUX": 0.765,
        "PRON": 0.785,
        "DET": 0.735,
        "ADP": 0.755,
        "ADV": 0.765,
        "PART": 0.745,
        "CCONJ": 0.605,
        "SCONJ": 0.655,
        "INTJ": 0.800,
        "PUNCT": 0.380,
        "SPACE": 0.525,
        "SYM": 0.550,
        "X": 0.650,
    }

    attention[0, 0] = 1.0
    for i in range(1, n):
        aligned = alignment[i]
        sink = 0.80

        if aligned:
            # Prefer the longest aligned linguistic token.
            word = doc[aligned[0]]
            for k in aligned:
                candidate = doc[k]
                if len(candidate.text.strip()) > len(word.text.strip()):
                    word = candidate

            sink = sink_by_pos.get(word.pos_, 0.80)

            if word.pos_ == "VERB":
                if word.dep_ in ("ccomp", "xcomp"):
                    sink += 0.045
                elif word.dep_ == "ROOT":
                    sink -= 0.035
            elif word.pos_ == "ADJ" and word.dep_ == "amod":
                sink += 0.035
            elif word.pos_ == "PRON" and word.dep_ == "poss":
                sink -= 0.065

        elif not tokens[i].lstrip("Ġ▁").strip():
            sink = 0.525

        # The first ordinary token has an especially strong positional sink.
        if i == 1:
            sink = 0.96

        sink = float(np.clip(sink, 0.05, 0.98))
        attention[i, 0] = sink

        # Preserve the original causal recency prior, including its diagonal.
        positions = np.arange(1, i + 1)
        local = np.exp(-(i - positions) / 2.5)
        attention[i, 1:i + 1] = (1.0 - sink) * local / local.sum()

        # Terminal punctuation and quotation boundaries summarize preceding
        # material rather than acting as ordinary POS-modulated sink tokens.
        # Inspect token punctuation directly, even if spaCy mislabels it.
        surface = tokens[i].lstrip("Ġ▁").strip()
        punctuation_only = (
            bool(surface)
            and all(c in ".,!?;:…\"'“”‘’«»()[]{}—–-" for c in surface)
        )
        terminal = any(c in ".!?…" for c in surface)
        quotation = any(c in "\"“”«»" for c in surface)
        if i > 1 and punctuation_only and (terminal or quotation):
            target_sink = 0.18 if terminal else 0.28
            released = max(0.0, sink - target_sink)
            if released > 0.0:
                # Add a broad historical component; leave the original
                # recency contribution and self-attention exactly intact.
                history = np.ones(i - 1, dtype=np.float64)
                for j in range(1, i):
                    if alignment[j]:
                        pos = doc[alignment[j][0]].pos_
                        if pos in ("VERB", "AUX", "PRON"):
                            history[j - 1] = 1.5
                        elif pos in ("PUNCT", "SPACE"):
                            history[j - 1] = 0.35
                attention[i, 0] -= released
                attention[i, 1:i] += released * history / history.sum()

    return "bos_sink_with_boundary_release", attention


def prog_L1H9(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with mild positional decay and linguistic modulation.
    Residual attention is diffuse and weakly biased toward recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_weak_recency", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.985 - 0.15 * (1.0 - np.exp(-(i - 1) / 18.0))

        aligned = alignment[i]
        if aligned:
            word = doc[aligned[-1]]
            if word.pos_ in ("NOUN", "PROPN"):
                sink_mass += 0.018
            elif word.pos_ in ("VERB", "AUX"):
                sink_mass -= 0.012
            elif word.pos_ in ("ADV", "SCONJ"):
                sink_mass -= 0.025
            elif word.pos_ == "PUNCT":
                sink_mass -= 0.065
            elif word.is_space:
                sink_mass -= 0.080

        sink_mass = float(np.clip(sink_mass, 0.65, 0.995))

        # The supplied edges constrain the sink much more than the residual.
        distances = i - np.arange(1, i + 1)
        residual = 0.65 / i + 0.35 * (
            np.exp(-distances / 5.0)
            / np.exp(-distances / 5.0).sum()
        )
        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_weak_recency", attention


def prog_L1H10(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token sink with sparse local exceptions for nominal composition,
    possessive boundaries, clause punctuation, and fragmented non-ASCII text.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_sink", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    function_pos = {
        "ADP", "AUX", "CCONJ", "SCONJ", "DET", "PRON", "PART"
    }

    # Limit the encoding-fragment exception to mixed non-ASCII text.
    noisy_text = (
        sum(ord(c) > 127 for c in sentence) >= 2
        and any(ord(c) > 127 and not c.isalpha() and not c.isspace()
                for c in sentence)
    )

    for i in range(1, n):
        aligned = alignment[i]
        pos = doc[aligned[0]].pos_ if aligned else ""

        if pos in function_pos:
            sink_mass = 0.979
        elif pos == "PUNCT":
            sink_mass = 0.952
        elif pos == "ADV":
            sink_mass = 0.971
        else:
            sink_mass = 0.967

        # The first ordinary token has a particularly strong sink preference.
        if i == 1:
            sink_mass = 0.984

        # Longer prefixes allow slightly more non-sink attention.
        sink_mass -= min(0.012, 0.00025 * max(0, i - 1))

        positions = np.arange(1, i + 1, dtype=np.float64)
        residual = 0.65 / i + 0.35 * (
            np.exp(-(i - positions) / 5.0)
            / np.exp(-(i - positions) / 5.0).sum()
        )

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

        # Move mass only from the sink to a detected preceding constituent.
        # In particular, leave the original diagonal and diffuse tail intact.
        if i > 1 and aligned and alignment[i - 1]:
            current = doc[aligned[0]]
            previous = doc[alignment[i - 1][-1]]
            shared = any(k in alignment[i - 1] for k in aligned)
            extra = 0.0

            if shared and pos in {"NOUN", "PROPN"}:
                earlier_piece = (
                    i > 2
                    and any(k in alignment[i - 2] for k in aligned)
                )
                extra = 0.20 if earlier_piece else 0.11
            elif not shared:
                if (pos in {"NOUN", "PROPN"}
                        and previous.pos_ == "ADJ"
                        and previous.dep_ == "amod"
                        and previous.head.i == current.i):
                    extra = 0.12
                elif (pos in {"NOUN", "PROPN"}
                      and previous.pos_ in {"NOUN", "PROPN"}
                      and previous.dep_ == "compound"
                      and previous.head.i == current.i):
                    extra = 0.105
                elif pos == "ADJ" and previous.pos_ == "ADJ":
                    if previous.head.i == current.head.i:
                        extra = 0.065
                elif current.dep_ == "case" and previous.dep_ == "poss":
                    extra = 0.11
                elif previous.text == ",":
                    extra = 0.08 if pos == "CCONJ" else 0.022

            if noisy_text:
                current_nonascii = any(
                    ord(c) > 127 for k in aligned for c in doc[k].text
                )
                previous_nonascii = any(
                    ord(c) > 127
                    for k in alignment[i - 1] for c in doc[k].text
                )
                if current_nonascii:
                    extra = max(extra, 0.28 if previous_nonascii else 0.07)
                    if i > 2 and any(
                        ord(c) > 127
                        for k in alignment[i - 2] for c in doc[k].text
                    ):
                        extra = max(extra if not previous_nonascii else 0.16, 0.07)
                elif previous_nonascii:
                    extra = max(extra, 0.045)

            if extra:
                transfer = min(extra, attention[i, 0])
                attention[i, 0] -= transfer
                attention[i, i - 1] += transfer

    return "first_token_sink", make_row_stochastic(attention)


def prog_L1H11(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with weak leakage and persistent comma/whitespace boundary sinks.
    Transfer extra BOS mass to earlier boundaries without changing self-attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_boundary_leakage", attention

    # Boundary keys compete with BOS; early commas are especially strong.
    boundary_strength = np.zeros(n, dtype=np.float64)
    for j in range(1, n):
        clean = tokens[j].lstrip("\u0120")
        if "," in clean:
            boundary_strength[j] = 0.020 + 0.050 * np.exp(-j / 4.0)
        elif not clean.strip():
            boundary_strength[j] = 0.028

    attention[0, 0] = 1.0
    for i in range(1, n):
        # The examples suggest slightly more leakage at later positions.
        leakage = np.minimum(0.018 + 0.0012 * i, 0.16)
        positions = np.arange(1, i + 1, dtype=np.float64)
        recent = np.exp((positions - i) / 6.0)
        recent /= recent.sum()
        residual = 0.7 / i + 0.3 * recent

        attention[i, 0] = 1.0 - leakage
        attention[i, 1:i + 1] = leakage * residual

        # Only earlier boundary keys receive additional mass; leave the
        # original diagonal, diffuse residual, and recency decay untouched.
        anchors = np.flatnonzero(boundary_strength[:i])
        if anchors.size:
            extra = boundary_strength[anchors] * np.exp(-(i - anchors) / 80.0)
            query = tokens[i].lstrip("\u0120")
            if any(mark in query for mark in (".", "!", "?")):
                extra *= 1.6
            elif "," in query or '"' in query or not query.strip():
                extra *= 1.3
            elif boundary_strength[i - 1] > 0:
                extra *= 1.3

            total = extra.sum()
            scale = np.minimum(1.0, 0.35 * attention[i, 0] / total)
            extra *= scale
            attention[i, anchors] += extra
            attention[i, 0] -= extra.sum()

    return "bos_sink_with_boundary_leakage", attention


def prog_L1H12(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with localized backward attention at dialogue boundaries and clitics.
    Special cases transfer only BOS mass, preserving self-attention and decay.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_boundary_backoff", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.83
        aligned = alignment[i]

        if aligned:
            word = doc[aligned[0]]
            pos = word.pos_

            if pos in ("NOUN", "PROPN"):
                sink_mass = 0.94
            elif pos == "ADJ":
                sink_mass = 0.88
            elif pos == "VERB":
                sink_mass = 0.85
            elif pos == "PRON":
                sink_mass = 0.84
            elif pos in ("DET", "NUM"):
                sink_mass = 0.85
            elif pos in ("AUX", "ADP", "CCONJ", "SCONJ", "PART", "ADV"):
                sink_mass = 0.79
            elif pos == "PUNCT":
                sink_mass = 0.83

            if word.ent_type_:
                sink_mass = max(sink_mass, 0.93)

        # Token-level punctuation also handles merged punctuation/quote tokens.
        clean = tokens[i].replace("Ġ", " ").replace("Ċ", "\n").strip()
        if clean and all(c in ".,!?;:\"'()[]{}—–…" for c in clean):
            sink_mass = 0.93 if any(c in ".!?" for c in clean) else 0.83

        if i == 1:
            sink_mass = 0.985

        attention[i, 0] = sink_mass
        positions = np.arange(1, i + 1, dtype=np.float64)
        residual = np.exp(-(i - positions) / 2.0)
        residual /= residual.sum()
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

        # Sparse corrections: all unselected entries, including self, stay fixed.
        if i > 1:
            previous = doc[alignment[i - 1][-1]] if alignment[i - 1] else None
            target, desired = i - 1, 0.0

            if clean == ",":
                desired = (
                    0.35 if previous is not None
                    and previous.pos_ in ("VERB", "AUX", "PRON", "INTJ")
                    else 0.23
                )
            elif clean and all(c in "\"'“”‘’" for c in clean):
                desired = 0.17
            elif (
                aligned and previous is not None
                and word.pos_ == "VERB"
                and previous.pos_ == "PROPN"
                and previous.dep_ in ("nsubj", "nsubjpass")
                and previous.head.i == word.i
            ):
                desired = 0.38
            elif (
                aligned and clean.startswith(("'", "’"))
                and word.dep_ in ("case", "poss", "neg")
            ):
                desired = 0.38
                if word.dep_ == "neg":
                    for j in range(i - 1, max(0, i - 4), -1):
                        if alignment[j]:
                            candidate = doc[alignment[j][-1]]
                            if candidate.pos_ in ("PRON", "NOUN", "PROPN"):
                                target = j
                                break

            if desired > 0.0:
                transfer = min(
                    max(0.0, desired - attention[i, target]),
                    max(0.0, attention[i, 0] - 0.45),
                )
                attention[i, 0] -= transfer
                attention[i, target] += transfer

    return "bos_sink_boundary_backoff", attention


def prog_L1H13(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Predict a dominant BOS attention sink, strongest early and on nominal tokens.
    Distribute residual attention causally with a mild recency preference.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_linguistic_gating", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special_tokens = set(tokenizer.all_special_tokens)

    pos_sink = {
        "NOUN": 0.90,
        "PROPN": 0.94,
        "ADJ": 0.81,
        "VERB": 0.72,
        "AUX": 0.66,
        "ADV": 0.65,
        "ADP": 0.69,
        "DET": 0.73,
        "PRON": 0.57,
        "CCONJ": 0.66,
        "SCONJ": 0.59,
        "PART": 0.66,
        "NUM": 0.80,
        "INTJ": 0.72,
        "PUNCT": 0.65,
        "SPACE": 0.95,
        "SYM": 0.86,
        "X": 0.83,
    }

    attention[0, 0] = 1.0
    for i in range(1, n):
        raw = tokens[i]
        clean = raw.lstrip("Ġ▁").strip()
        sids = alignment[i]
        words = [doc[k] for k in sids if not doc[k].is_space]

        if raw in special_tokens:
            sink = 0.95
        elif not clean:
            sink = 0.95
        elif words:
            word = max(
                words,
                key=lambda w: pos_sink.get(w.pos_, 0.70)
            )
            sink = pos_sink.get(word.pos_, 0.70)
            if word.ent_type_ and word.pos_ in ("NOUN", "PROPN"):
                sink = max(sink, 0.93)
            if word.pos_ == "PUNCT":
                if any(c in clean for c in ".!?"):
                    sink = 0.84
                elif any(c in clean for c in ",;:"):
                    sink = 0.58
        else:
            sink = 0.76

        if i == 1:
            sink = 0.987
        elif i == 2:
            sink = max(sink, 0.94)
        elif i == 3:
            sink = max(sink, 0.80)

        sink = float(np.clip(sink, 0.45, 0.995))
        attention[i, 0] = sink

        distances = i - np.arange(1, i + 1, dtype=np.float64)
        residual = 0.35 + np.exp(-distances / 4.0)
        attention[i, 1:i + 1] = (1.0 - sink) * residual / residual.sum()

    return "bos_sink_with_linguistic_gating", attention


def prog_L1H14(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention-sink head with weak POS-dependent gating.
    Residual attention is diffuse and mildly biased toward recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_weak_linguistic_gating", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        mass = 0.935
        aligned = alignment[i]
        if aligned:
            word = doc[aligned[0]]
            if word.pos_ == "DET":
                mass = 0.955
            elif word.pos_ == "PUNCT":
                mass = 0.950
            elif word.pos_ == "VERB":
                mass = 0.945
            elif word.pos_ in ("NOUN", "PROPN", "ADJ", "ADV"):
                mass = 0.925

        clean = tokens[i].replace("\u0120", " ").replace("\u010a", "\n")
        if clean.isspace():
            mass = 0.960
        elif clean and all(c in ".,!?;:…\"'“”‘’()[]{}—–-" for c in clean):
            mass = 0.950

        if i == 1:
            mass = 0.978

        attention[i, 0] = mass
        distances = i - np.arange(1, i + 1, dtype=np.float64)
        residual = 0.5 + 0.5 * np.exp(-distances / 24.0)
        attention[i, 1:i + 1] = (1.0 - mass) * residual / residual.sum()

    return "bos_sink_with_weak_linguistic_gating", attention


def prog_L1H15(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with enhanced previous-token attention at quotation/spacing boundaries.
    Transfer only BOS mass at those boundaries, preserving the original residual.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_boundary_predecessor", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    spans = _char_spans(sentence, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        surface = tokens[i].lstrip("Ġ").lstrip("▁")
        aligned = alignment[i]
        word = doc[aligned[-1]] if aligned else None
        sink_mass = 0.645

        if word is not None:
            if word.pos_ in ("NOUN", "PROPN"):
                sink_mass = 0.685
            elif word.pos_ == "PUNCT":
                sink_mass = 0.700
            elif word.pos_ in ("DET", "ADP", "AUX"):
                sink_mass = 0.660
            elif word.pos_ in ("PRON", "CCONJ", "SCONJ"):
                sink_mass = 0.625

            # Internal word pieces often have especially strong sink attention.
            if i < len(spans):
                start, end = spans[i]
                if end > start and start > word.idx:
                    sink_mass += 0.100

        if not surface.strip():
            sink_mass = 0.705
        elif surface and all(c in ".,;:!?\"'“”‘’()[]{}—–-" for c in surface):
            sink_mass = 0.700
            if any(c in ".!?" for c in surface):
                sink_mass = 0.745 if i == n - 1 else 0.690

        # The earliest positions have a much stronger positional signature.
        if i == 1:
            sink_mass = 0.950
        elif i == 2:
            sink_mass = 0.720

        sink_mass = float(np.clip(sink_mass, 0.55, 0.96))
        attention[i, 0] = sink_mass

        distance = i - np.arange(1, i + 1, dtype=np.float64)
        local = np.exp(-distance / 3.0)
        local /= local.sum()
        residual = 0.55 * local + 0.45 / i
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

        # Boundary tokens attract the following lexical token especially strongly.
        # Only the BOS and predecessor entries change; self-attention is untouched.
        if i > 2 and word is not None and word.pos_ not in ("PUNCT", "SPACE"):
            previous = tokens[i - 1].lstrip("Ġ").lstrip("▁")
            whitespace_boundary = (
                not previous.strip()
                and tokens[i - 1] not in tokenizer.all_special_tokens
            )
            quote_boundary = (
                bool(previous)
                and all(c in ".,;:!?\"'“”‘’()[]{}—–-" for c in previous)
                and any(c in "\"“”" for c in previous)
            )
            if whitespace_boundary or quote_boundary:
                target = 0.420 if whitespace_boundary else 0.500
                if quote_boundary and any(c in ".!?" for c in previous):
                    target = 0.360
                transfer = min(
                    max(0.0, target - attention[i, i - 1]),
                    attention[i, 0],
                )
                attention[i, 0] -= transfer
                attention[i, i - 1] += transfer

    return "bos_sink_with_boundary_predecessor", make_row_stochastic(attention)


def prog_L1H16(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with a two-token-back residual focus in longer, multi-predicate text.
    Preserve the original onset, self-attention, and default decay elsewhere.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_lag2", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    local_lag_pattern = (
        n >= 25
        and sum(w.pos_ in ("VERB", "AUX") for w in doc) >= 3
    )

    for i in range(1, n):
        surface = tokens[i].replace("Ġ", " ").replace("Ċ", "\n")
        stripped = surface.strip()
        words = [doc[k] for k in alignment[i] if k < len(doc)]
        word = next((w for w in words if not w.is_space), None)

        sink_mass = 0.685
        if word is not None:
            if word.pos_ in ("VERB", "AUX"):
                sink_mass += 0.035
            elif word.pos_ in ("CCONJ", "SCONJ", "ADP"):
                sink_mass += 0.045
            elif word.pos_ in ("ADJ", "ADV"):
                sink_mass -= 0.015

            if word.dep_ in ("ROOT", "conj"):
                sink_mass += 0.015
            if word.is_sent_start:
                sink_mass += 0.065

        if not stripped:
            sink_mass = 0.83
        elif all(c in ",.;:!?\"'“”‘’()[]{}—–-" for c in stripped):
            if stripped == ",":
                sink_mass = 0.815
            elif stripped == ".":
                sink_mass = 0.82
            elif any(c in "!?" for c in stripped):
                sink_mass = 0.745
            else:
                sink_mass = 0.775

        # The first few queries show an especially consistent positional ramp.
        if i == 1:
            sink_mass = 0.998
        elif i == 2:
            sink_mass = 0.95
        elif i == 3:
            sink_mass = max(sink_mass, 0.835)

        sink_mass = float(np.clip(sink_mass, 0.0, 1.0))
        attention[i, 0] = sink_mass

        distances = i - np.arange(1, i + 1, dtype=np.float64)
        residual = 1.0 + 0.65 * np.exp(-distances / 4.0)
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * residual / residual.sum()
        )

        if local_lag_pattern and i >= 3:
            # Redistribute only historical mass; leave the diagonal untouched.
            moved = 0.75 * attention[i, 1:i].sum()
            attention[i, 1:i] *= 0.25
            attention[i, i - 2] += 0.80 * moved
            attention[i, i - 3 if i >= 4 else i - 1] += 0.20 * moved

            sink_transfer = min(
                attention[i, 0], 0.07 if i == 3 else 0.03
            )
            attention[i, 0] -= sink_transfer
            attention[i, i - 2] += sink_transfer

    return "bos_sink_with_local_lag2", attention


def prog_L1H17(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with a sparse recurrence channel for repeated or related keys.
    Recurrence takes mass only from BOS, preserving the original diagonal."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_recurrence", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        aligned = alignment[i]
        word = doc[aligned[-1]] if aligned else None

        sink_mass = 0.950
        if word is not None:
            if word.pos_ in ("ADP", "DET", "CCONJ", "SCONJ", "PART"):
                sink_mass = 0.975
            elif word.pos_ == "AUX":
                sink_mass = 0.958
            elif word.pos_ in ("PRON", "ADJ", "ADV"):
                sink_mass = 0.945
            elif word.pos_ in ("NOUN", "PROPN"):
                sink_mass = 0.943
            elif word.pos_ == "VERB":
                sink_mass = 0.935
            elif word.is_punct:
                sink_mass = 0.960
                if word.text == ",":
                    sink_mass = 0.983
                elif word.text in ('"', "“", "”", "‘", "’"):
                    sink_mass = 0.978
            elif word.is_space:
                sink_mass = 0.947

        # More competing keys gradually weaken, but never displace, the sink.
        sink_mass -= 0.0015 * max(0, i - 12)
        sink_mass = float(np.clip(sink_mass, 0.80, 0.992))

        positions = np.arange(1, i + 1, dtype=np.float64)
        residual = 0.65 + np.exp(-(i - positions) / 6.0)
        residual /= residual.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

        # Special case: retrieve earlier occurrences without changing self
        # attention or the default residual distribution.
        surface = tokens[i].lstrip("Ġ").strip()
        quotes = ('"', "“", "”", "‘", "’")
        matches = []
        strength = 0.0

        for j in range(1, i - 1):
            if tokens[j] in tokenizer.all_special_tokens:
                continue
            previous = doc[alignment[j][-1]] if alignment[j] else None
            prior_surface = tokens[j].lstrip("Ġ").strip()

            if not surface:
                if not prior_surface:
                    matches.append((j, 1.0))
                    strength = 0.55
                continue

            if word is None or previous is None:
                continue
            if aligned[-1] == alignment[j][-1]:
                continue

            if word.is_punct:
                if not previous.is_punct:
                    continue
                shared_quote = any(q in surface and q in prior_surface for q in quotes)
                if surface == prior_surface or shared_quote:
                    matches.append((j, 1.0))
                    strength = (
                        0.28 if surface in quotes
                        else 0.19 if shared_quote
                        else 0.10
                    )
                continue

            if word.pos_ != previous.pos_ or previous.is_punct:
                continue

            similarity = embedding_similarity(tokens, i, j, tokenizer)
            threshold = 0.70 if word.pos_ == "VERB" else 0.82
            if similarity < threshold:
                continue
            matches.append((j, similarity))
            if word.pos_ in ("NOUN", "PROPN"):
                strength = 0.68
            elif word.pos_ == "VERB":
                strength = 0.60
            elif word.pos_ == "DET":
                strength = 0.40 if word.is_sent_start else 0.065
            elif word.pos_ == "ADP":
                strength = 0.11
            else:
                strength = 0.20

        if matches:
            best_similarity = max(score for _, score in matches)
            targets = [
                j for j, score in matches
                if score >= best_similarity - 0.025
            ]
            targets.sort(reverse=True)
            weights = 0.30 ** np.arange(len(targets), dtype=np.float64)
            weights /= weights.sum()
            transfer = strength * np.exp(-(i - targets[0]) / 55.0)
            transfer = min(float(transfer), float(attention[i, 0]))
            attention[i, 0] -= transfer
            for j, weight in zip(targets, weights):
                attention[i, j] += transfer * weight

    return "bos_sink_with_recurrence", attention


def prog_L1H18(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with weak POS modulation; fragmented words and contractions
    selectively transfer additional BOS mass to the current token.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_fragment_self_boost", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.89
        aligned = alignment[i]
        if aligned:
            word = doc[aligned[0]]
            if word.pos_ == "ADP":
                sink_mass = 0.925
            elif word.pos_ == "PART":
                sink_mass = 0.915
            elif word.pos_ == "DET":
                sink_mass = 0.907
            elif word.pos_ == "PUNCT":
                sink_mass = 0.902
            elif word.pos_ == "AUX":
                sink_mass = 0.900

        positions = np.arange(1, i + 1, dtype=np.float64)
        residual = (
            0.65 / i
            + 0.35
            * np.exp(-(i - positions) / 4.0)
            / np.exp(-(i - positions) / 4.0).sum()
        )
        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

        # Restrict the correction to subword continuations, clitics,
        # and non-ASCII text split into byte-level fragments.
        continuation = (
            i > 1
            and bool(aligned)
            and any(k in alignment[i - 1] for k in aligned)
            and not doc[aligned[0]].is_punct
        )
        clitic = (
            bool(aligned)
            and doc[aligned[0]].pos_ in ("AUX", "PART")
            and tokens[i].lstrip("Ġ").startswith(("'", "’"))
        )
        unicode_fragment = (
            bool(aligned)
            and any(not doc[k].text.isascii() for k in aligned)
            and (
                any(k in alignment[i - 1] for k in aligned)
                or (
                    i + 1 < n
                    and any(k in alignment[i + 1] for k in aligned)
                )
            )
        )

        if continuation or clitic or unicode_fragment:
            target_self = 0.18
            if clitic:
                target_self = 0.20
            if unicode_fragment:
                target_self = 0.24 if continuation else 0.18

            transfer = min(
                attention[i, 0],
                max(0.0, target_self - attention[i, i]),
            )
            attention[i, 0] -= transfer
            attention[i, i] += transfer

    return "bos_sink_with_fragment_self_boost", make_row_stochastic(attention)


def prog_L1H19(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with a selective intra-word/clitic link.
    Split-word continuations borrow BOS mass without changing self-attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_continuation_links", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        surface = tokens[i].replace("\u0120", " ").replace("\u010a", "\n")
        stripped = surface.strip()
        words = [doc[k] for k in alignment[i]]
        pos = words[0].pos_ if words else ""
        dep = words[0].dep_ if words else ""

        sink = 0.905
        if pos in ("DET", "PRON", "CCONJ", "SCONJ"):
            sink = 0.923
        elif pos == "ADP":
            sink = 0.915
        elif pos == "VERB":
            sink = 0.912
        elif pos in ("AUX", "PART"):
            sink = 0.875
        elif pos == "PROPN":
            sink = 0.885

        if dep in ("mark", "cc", "poss"):
            sink += 0.010

        if not stripped:
            sink = 0.941
        elif any(c in ".!?" for c in stripped):
            sink = 0.975 if stripped == "." else 0.940
        elif any(c in ",;:" for c in stripped):
            sink = 0.946
        elif any(c in "\"“”" for c in stripped):
            sink = 0.945
        elif words and all(w.is_punct for w in words):
            sink = 0.935

        if i == 1:
            sink = max(sink, 0.925)

        distances = i - np.arange(1, i + 1, dtype=np.float64)
        residual = 0.5 / i + 0.5 * (
            np.exp(-distances / 4.0) / np.exp(-distances / 4.0).sum()
        )
        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual

        # Only intervene on lexical continuations, not ordinary word boundaries.
        if i > 1 and stripped and words:
            shared = [
                w for w in words
                if w.i in alignment[i - 1] and not w.is_punct
            ]
            clitic = (
                stripped[0] in ("'", "’")
                and any(
                    w.dep_ in ("neg", "case", "poss") or w.pos_ == "PRON"
                    for w in words
                )
            )
            continuation = (
                surface == surface.lstrip()
                and (stripped[0].isalnum() or stripped[0] in ("'", "’"))
                and bool(shared)
            )
            if continuation or clitic:
                target = 0.24
                if continuation and pos in ("PROPN", "ADV"):
                    target = 0.34
                elif continuation and pos == "NOUN":
                    target = 0.20
                elif clitic and dep in ("case", "poss"):
                    target = 0.12

                # Negative clitics can additionally bind the local subject.
                negative = next((w for w in words if w.dep_ == "neg"), None)
                if negative is not None:
                    target = 0.13
                    subjects = [
                        c.i for c in negative.head.children
                        if c.dep_ in ("nsubj", "nsubjpass")
                    ]
                    for j in range(i - 2, 0, -1):
                        if any(k in subjects for k in alignment[j]):
                            delta = min(
                                max(0.0, 0.30 - attention[i, j]),
                                attention[i, 0],
                            )
                            attention[i, j] += delta
                            attention[i, 0] -= delta
                            break

                delta = min(
                    max(0.0, target - attention[i, i - 1]),
                    attention[i, 0],
                )
                attention[i, i - 1] += delta
                attention[i, 0] -= delta

    return "bos_sink_with_continuation_links", attention


def prog_L1H20(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with targeted previous-piece attention for subword continuations.
    Continuations redirect BOS mass without changing self-attention or other leakage.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_continuation_leakage", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.950
        aligned = alignment[i]
        if aligned:
            word = doc[aligned[-1]]
            pos = word.pos_

            if pos == "PROPN":
                sink_mass = 0.973
            elif pos == "NOUN":
                sink_mass = 0.964
            elif pos == "PRON":
                sink_mass = 0.966
            elif pos == "ADJ":
                sink_mass = 0.960
            elif pos == "VERB":
                sink_mass = 0.950
            elif pos == "AUX":
                sink_mass = 0.933
            elif pos in ("ADP", "DET", "PART"):
                sink_mass = 0.940
            elif pos in ("CCONJ", "SCONJ", "ADV"):
                sink_mass = 0.948
            elif pos == "PUNCT":
                sink_mass = 0.960
            elif pos == "SPACE":
                sink_mass = 0.933

            if word.dep_ in ("nsubj", "nsubjpass", "csubj"):
                sink_mass += 0.005

        clean = tokens[i].replace("\u0120", " ").replace("\u010a", "\n").strip()
        if clean and all(c in ".!?" for c in clean):
            sink_mass = 0.973
        if i == 1:
            sink_mass = 0.985

        sink_mass = float(np.clip(sink_mass, 0.925, 0.990))
        attention[i, 0] = sink_mass

        # Preserve the original leakage and self-attention exactly.
        distances = i - np.arange(1, i + 1, dtype=np.float64)
        local = np.exp(-distances / 3.0)
        local /= local.sum()
        residual = 0.5 * local + 0.5 / i
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

        # Only attached lexical pieces and grammatical clitics trigger this path.
        if (
            i > 1
            and aligned
            and clean
            and not tokens[i].startswith(("\u0120", "\u010a"))
            and (clean[0].isalpha() or clean[0] in ("'", "’"))
        ):
            shared_word = any(k in alignment[i - 1] for k in aligned)
            clitic = (
                clean[0] in ("'", "’")
                and word.pos_ in ("PART", "AUX", "PRON")
                and word.dep_ in ("neg", "case", "aux", "auxpass")
            )
            if shared_word or clitic:
                target = 0.055
                if word.dep_ == "neg":
                    target = 0.210
                elif word.pos_ == "ADV":
                    target = 0.225
                elif word.pos_ == "VERB":
                    target = 0.070
                elif word.pos_ == "AUX":
                    target = 0.025

                transfer = min(
                    attention[i, 0],
                    max(0.0, target - attention[i, i - 1]),
                )
                attention[i, 0] -= transfer
                attention[i, i - 1] += transfer

    return "bos_sink_with_continuation_leakage", make_row_stochastic(attention)


def prog_L1H21(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with position-dependent dilution and mild POS modulation.
    Residual attention is diffuse, with a weak preference for nearby tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_positional_dilution", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    pos_adjustment = {
        "ADP": 0.085,
        "CCONJ": 0.055,
        "SCONJ": 0.045,
        "PRON": 0.025,
        "AUX": 0.015,
        "DET": -0.025,
        "NOUN": -0.035,
        "PROPN": 0.020,
        "VERB": -0.055,
        "ADJ": -0.070,
        "ADV": -0.020,
        "PART": 0.015,
        "PUNCT": 0.075,
        "SPACE": 0.080,
    }

    for i in range(1, n):
        mapped = alignment[i]
        adjustment = 0.0
        if mapped:
            adjustment = np.mean([
                pos_adjustment.get(doc[k].pos_, 0.0) for k in mapped
            ])

        # The strong early sink gradually loses mass as context accumulates.
        sink_mass = 0.32 + 0.62 * np.exp(-i / 22.0)
        sink_mass += adjustment * (1.0 - np.exp(-i / 4.0))

        # Continuation pieces and isolated whitespace often retain extra sink mass.
        token = tokens[i]
        if token.isspace() or token == "\u0120":
            sink_mass += 0.075
        elif mapped and i > 1 and any(k in alignment[i - 1] for k in mapped):
            sink_mass += 0.060

        sink_mass = float(np.clip(sink_mass, 0.20, 0.97))
        attention[i, 0] = sink_mass

        distances = i - np.arange(1, i + 1)
        residual = 0.75 + 0.25 * np.exp(-distances / 5.0)
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * residual / residual.sum()
        )

    return "bos_sink_with_positional_dilution", attention


def prog_L1H22(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with local phrase-completion attraction.
    Completed modifier phrases briefly divert BOS mass to their local anchors.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_phrase_completion", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    # Record word-final model tokens and only the newly introduced local links.
    word_ends = {}
    for ti, word_ids in enumerate(alignment):
        for wi in word_ids:
            if ti > 0:
                word_ends[wi] = ti
    phrase_links = [{} for _ in range(n)]

    for i in range(1, n):
        words = [doc[k] for k in alignment[i]]
        pos = {word.pos_ for word in words}
        deps = {word.dep_ for word in words}

        sink_mass = 0.82 + 0.12 * np.exp(-(i - 1) / 3.0)

        if "PROPN" in pos:
            sink_mass += 0.105
        elif "PRON" in pos:
            sink_mass += 0.035
        elif "AUX" in pos:
            sink_mass += 0.025
        elif "DET" in pos:
            sink_mass += 0.015

        if "prt" in deps:
            sink_mass += 0.08
        if "poss" in deps:
            sink_mass += 0.035

        clean = tokens[i].replace("Ġ", " ").replace("Ċ", "\n")
        if clean.isspace():
            sink_mass += 0.075
        elif words and all(word.is_punct for word in words):
            sink_mass -= 0.035

        if i == 1:
            sink_mass = 0.985

        sink_mass = float(np.clip(sink_mass, 0.74, 0.985))
        attention[i, 0] = sink_mass

        distances = i - np.arange(1, i + 1, dtype=np.float64)
        residual = 0.75 / i + 0.25 * (
            np.exp(-distances / 4.0)
            / np.exp(-distances / 4.0).sum()
        )
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

        # Special case: a nearby modifier becomes an anchor when its phrase
        # completes. Transfer BOS mass only, preserving self and other edges.
        links = phrase_links[i]
        for word in words:
            for modifier in word.children:
                j = word_ends.get(modifier.i, -1)
                if (
                    modifier.dep_ in ("amod", "advmod")
                    and modifier.pos_ in ("ADJ", "ADV")
                    and modifier.i == word.i - 1
                    and 0 < j < i
                    and i - j <= 2
                ):
                    boost = 0.36 if modifier.dep_ == "amod" else 0.28
                    links[j] = max(links.get(j, 0.0), boost)

            if word.dep_ == "case" and word.tag_ == "POS":
                j = word_ends.get(word.head.i, -1)
                if 0 < j < i and i - j <= 2:
                    links[j] = max(links.get(j, 0.0), 0.20)

            # An early comma closes an introductory nominal/adverbial phrase.
            if word.text == "," and word.i > 0 and i <= 5:
                previous = doc[word.i - 1]
                j = word_ends.get(previous.i, -1)
                if (
                    previous.pos_ in ("NOUN", "PRON", "ADV")
                    and previous.dep_ in ("pobj", "npadvmod", "obl", "advmod")
                    and 0 < j < i
                ):
                    links[j] = max(links.get(j, 0.0), 0.35)

        # A weaker, one-token echo captures continuation beyond the completion.
        transfers = dict(links)
        for j, boost in phrase_links[i - 1].items():
            transfers[j] = max(transfers.get(j, 0.0), 0.27 * boost)

        total = sum(transfers.values())
        if total > 0.0:
            scale = min(1.0, max(0.0, attention[i, 0] - 0.35) / total)
            for j, boost in transfers.items():
                mass = scale * boost
                attention[i, 0] -= mass
                attention[i, j] += mass

    return "bos_sink_with_phrase_completion", attention


def prog_L1H23(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with a quoted-discourse exception: redistribute some sink mass
    to self-attention and nearby discourse boundaries after dialogue begins."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_dialogue_residual", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    # Only quoted discourse activates the additional redistribution.
    quote_positions = [
        j for j in range(1, n)
        if any(c in tokens[j] for c in ('"', '“', '”', '«', '»'))
    ]

    for i in range(1, n):
        sink_mass = 0.89 - 0.0018 * min(i, 80)
        sink_mass += 0.035 * np.exp(-(i - 1) / 5.0)

        aligned = alignment[i]
        if aligned:
            word = doc[aligned[0]]
            if word.pos_ == "PROPN":
                sink_mass += 0.035
            elif word.pos_ in ("ADJ", "ADV", "NUM"):
                sink_mass += 0.020
            elif word.pos_ in ("DET", "CCONJ", "SCONJ"):
                sink_mass -= 0.030
            elif word.pos_ == "PUNCT":
                sink_mass -= 0.120
        elif tokens[i].isspace():
            sink_mass -= 0.060

        sink_mass = float(np.clip(sink_mass, 0.62, 0.96))
        attention[i, 0] = sink_mass

        distances = i - np.arange(1, i + 1)
        residual = 0.65 * np.exp(-distances / 3.0) + 0.35
        residual /= residual.sum()
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

        if quote_positions and i >= quote_positions[0]:
            previous_quotes = [j for j in quote_positions if j < i]
            is_punct = bool(aligned) and all(
                doc[k].pos_ == "PUNCT" for k in aligned
            )
            transfer = (
                0.045 + 0.0007 * min(i, 60)
                + 0.012 * min(len(previous_quotes), 4)
            )
            if is_punct:
                transfer += 0.10
                if i > 40 and any(c in tokens[i] for c in ".!?"):
                    transfer += 0.04
            transfer = min(transfer, attention[i, 0] - 0.30)

            # Additive correction leaves the original residual intact.
            attention[i, 0] -= transfer
            self_share = 0.45 if is_punct else 0.70
            attention[i, i] += self_share * transfer

            if is_punct and "," in tokens[i]:
                anchors = list(range(max(1, i - 2), i))
            else:
                anchors = previous_quotes[-3:]
            if anchors:
                attention[i, anchors] += (
                    (1.0 - self_share) * transfer / len(anchors)
                )
            else:
                attention[i, i] += (1.0 - self_share) * transfer

    return "bos_sink_with_dialogue_residual", attention


def prog_L2H0(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, strongest for early tokens and nominal content.
    Remaining attention is weak, causal, and biased toward recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_linguistic_modulation", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink = 0.90
        if alignment[i]:
            word = doc[alignment[i][-1]]
            pos = word.pos_

            if pos == "PROPN":
                sink = 0.980
            elif pos == "NOUN":
                sink = 0.963
            elif pos == "ADJ":
                sink = 0.923
            elif pos == "AUX":
                sink = 0.922
            elif pos == "VERB":
                sink = 0.882
            elif pos == "DET":
                sink = 0.909
            elif pos == "PRON":
                sink = 0.874
            elif pos in ("ADP", "ADV", "CCONJ", "SCONJ", "PART"):
                sink = 0.868
            elif pos == "PUNCT":
                sink = 0.906

            if word.ent_type_:
                sink = max(sink, 0.967)
            if word.dep_ in ("poss", "case"):
                sink = max(sink, 0.915)

        # Early queries have fewer competing keys and a particularly strong sink.
        sink += (1.0 - sink) * 0.55 * np.exp(-(i - 1) / 3.0)
        if i == 1:
            sink = 0.991

        attention[i, 0] = sink
        positions = np.arange(1, i + 1, dtype=np.float64)
        residual = 0.35 / i + 0.65 * np.exp(-(i - positions) / 4.0)
        residual /= residual.sum()
        attention[i, 1:i + 1] = (1.0 - sink) * residual

    return "bos_sink_with_linguistic_modulation", attention


def prog_L2H1(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, with slightly stronger suppression of non-BOS
    attention for early tokens and nominal content."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_lexical_modulation", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        aligned = alignment[i]
        pos_tags = {doc[k].pos_ for k in aligned}
        deps = {doc[k].dep_ for k in aligned}

        sink_mass = 0.950
        if pos_tags & {"NOUN", "PROPN"}:
            sink_mass = 0.982
        elif "ADJ" in pos_tags:
            sink_mass = 0.974
        elif pos_tags & {"VERB", "AUX"}:
            sink_mass = 0.953
        elif "PUNCT" in pos_tags:
            sink_mass = 0.960

        if any(doc[k].ent_type_ for k in aligned):
            sink_mass += 0.004
        if deps & {"poss", "case"}:
            sink_mass += 0.008

        # Early queries have almost no alternative to the initial sink.
        sink_mass += (0.999 - sink_mass) * np.exp(-(i - 1) / 2.5)
        sink_mass = float(np.clip(sink_mass, 0.925, 0.999))

        # The examples constrain the sink much more than the residual.
        # Use a conservative mixture of diffuse and local causal attention.
        positions = np.arange(1, i + 1)
        residual = 0.25 / i + 0.75 * (
            np.exp(-(i - positions) / 2.0)
            / np.exp(-(i - positions) / 2.0).sum()
        )
        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_lexical_modulation", make_row_stochastic(attention)


def prog_L2H2(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with weak, recency-weighted leakage.
    Linguistic features modestly adjust leakage rather than select target words.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_weak_local_leakage", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        # Strong sink throughout; competition grows mildly with context length.
        leakage = 0.012 + 0.045 * (1.0 - np.exp(-max(i - 2, 0) / 35.0))

        if alignment[i]:
            word = doc[alignment[i][0]]
            if word.pos_ in ("PROPN", "VERB", "NOUN"):
                leakage -= 0.004
            elif word.pos_ in ("DET", "PRON"):
                leakage += 0.010
            elif word.pos_ == "PUNCT":
                leakage += 0.018

        if i == 1:
            leakage = 0.003

        leakage = float(np.clip(leakage, 0.002, 0.10))
        attention[i, 0] = 1.0 - leakage

        # The supplied edges do not identify specific non-BOS targets:
        # use a conservative mixture of diffuse and local residual attention.
        distances = i - np.arange(1, i + 1)
        residual = 0.5 / i + 0.5 * (
            np.exp(-distances / 4.0) / np.exp(-distances / 4.0).sum()
        )
        attention[i, 1:i + 1] = leakage * residual

    return "bos_sink_with_weak_local_leakage", make_row_stochastic(attention)


def prog_L2H3(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with a clause-boundary exception: transfer some BOS mass to
    earlier predicate and punctuation anchors, leaving self-attention unchanged.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_clause_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    # Record each linguistic anchor once, even when split into subword tokens.
    anchors = np.zeros(n, dtype=np.float64)
    boundaries = np.zeros(n, dtype=np.float64)
    seen = set()
    for j in range(1, n):
        if alignment[j]:
            sid = alignment[j][0]
            if sid not in seen:
                seen.add(sid)
                word = doc[sid]
                if word.pos_ in ("VERB", "AUX") and (
                    "Fin" in word.morph.get("VerbForm")
                    or word.dep_ in ("ROOT", "conj", "ccomp")
                ):
                    anchors[j] = 1.5
                elif word.is_punct and any(c in word.text for c in ',;:.!?'):
                    anchors[j] = 1.0
                    boundaries[j] = 1.0

    for i in range(1, n):
        # The first-token sink dominates, even well beyond the initial phrase.
        sink = 0.980 - 0.065 * np.log(float(i)) - 0.001 * i

        indices = alignment[i]
        if indices:
            word = doc[indices[0]]
            correction = 0.0
            if word.pos_ in ("NOUN", "PROPN"):
                correction += 0.025
            elif word.pos_ in ("PRON", "DET", "CCONJ", "SCONJ"):
                correction -= 0.012
            elif word.pos_ == "SPACE":
                correction -= 0.040

            # Early nominal subjects often retain exceptionally strong BOS mass.
            if i <= 4 and word.dep_ in ("nsubj", "nsubjpass"):
                correction += 0.025

            if word.ent_type_:
                correction += 0.010

            # With only one preceding position, lexical corrections are minor.
            sink += correction * min(1.0, (i - 1) / 3.0)

        sink = float(np.clip(sink, 0.45, 0.992))

        positions = np.arange(1, i + 1, dtype=np.float64)
        distances = i - positions
        local = np.exp(-distances / 7.0)
        local /= local.sum()
        residual = 0.60 / i + 0.40 * local

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual

        # Exception for clause closure and post-boundary continuation.
        # Only BOS and earlier anchors change; the original diagonal is retained.
        boundary_count = float(boundaries[1:i + 1].sum())
        if i >= 6 and boundary_count > 0:
            weights = anchors[1:i] * np.exp(-(i - positions[:-1]) / 32.0)
            total = weights.sum()
            if total > 0:
                transfer = 0.030 + 0.020 * np.log1p(boundary_count)
                if boundaries[i]:
                    transfer += 0.030
                    if indices and any(c in doc[indices[0]].text for c in ".!?"):
                        transfer += 0.065
                transfer = min(transfer, 0.25 * attention[i, 0])
                attention[i, 0] -= transfer
                attention[i, 1:i] += transfer * weights / total

    return "bos_sink_with_clause_anchors", make_row_stochastic(attention)


def prog_L2H4(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with gradually increasing non-BOS leakage.
    The observed structure is primarily positional rather than syntactic.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_position_decay", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        sink_mass = 0.985 / (1.0 + 0.0028 * (i - 1))
        attention[i, 0] = sink_mass

        # Unobserved non-BOS edges receive a conservative, uniform causal prior.
        attention[i, 1:i + 1] = (1.0 - sink_mass) / i

    return "bos_sink_with_position_decay", attention


def prog_L2H5(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with stronger preceding-word attention in copular-adjective
    and quoted-dialogue contexts, preserving the original self-attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_contextual_local_boost", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for ti, word_ids in enumerate(alignment):
        for wi in word_ids:
            inverse[wi].append(ti)

    # Restrict the added path to the contexts showing excess sink attention.
    has_copular_adjective = any(
        w.pos_ == "ADJ"
        and (
            (w.dep_ in ("acomp", "attr") and w.head.pos_ == "AUX")
            or any(c.dep_ == "cop" and c.pos_ == "AUX" for c in w.children)
        )
        for w in doc
    )
    has_dialogue = any(
        w.is_punct and any(c in w.text for c in ('"', "“", "”", "«", "»"))
        for w in doc
    )
    local_context = has_copular_adjective or has_dialogue

    attention[0, 0] = 1.0
    for i in range(1, n):
        word_ids = alignment[i]
        word = doc[word_ids[-1]] if word_ids else None

        sink_mass = 0.805 + 0.150 * np.exp(-(i - 1) / 1.8)
        if word is not None:
            if word.is_punct:
                sink_mass += 0.025
            elif word.pos_ in ("PROPN", "AUX"):
                sink_mass += 0.020
            elif word.pos_ in ("NOUN", "DET", "PRON"):
                sink_mass += 0.010
            elif word.pos_ in ("VERB", "ADP"):
                sink_mass -= 0.015

            # Continuation pieces often retain particularly strong sink attention.
            pieces = inverse[word.i]
            if pieces and i > pieces[0]:
                sink_mass += 0.035
        elif tokens[i].replace("Ġ", " ").replace("Ċ", "\n").isspace():
            sink_mass += 0.025

        sink_mass = float(np.clip(sink_mass, 0.74, 0.975))

        positions = np.arange(1, i + 1)
        residual = 0.55 / i + 0.45 * (
            np.exp(-(i - positions) / 5.0)
            / np.exp(-(i - positions) / 5.0).sum()
        )

        if word is not None and word.head.i != word.i:
            head_positions = [j for j in inverse[word.head.i] if 0 < j <= i]
            if head_positions:
                residual *= 0.95
                for j in head_positions:
                    residual[j - 1] += 0.05 / len(head_positions)

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual / residual.sum()

        # Transfer only BOS mass: retain every original non-target weight,
        # including self-attention, without renormalizing the row.
        if local_context and i >= 4 and word is not None:
            targets = []
            for wi in range(word.i - 1, max(-1, word.i - 3), -1):
                previous = [j for j in inverse[wi] if 0 < j < i]
                if previous:
                    targets.append(previous[-1])

            if targets:
                boost = 0.060
                if word.pos_ in ("DET", "PROPN", "AUX"):
                    boost = 0.035
                elif word.is_punct:
                    boost = 0.045
                elif word.pos_ == "VERB":
                    boost = 0.075

                is_copular_adjective = (
                    word.pos_ == "ADJ"
                    and (
                        (word.dep_ in ("acomp", "attr") and word.head.pos_ == "AUX")
                        or any(
                            c.dep_ == "cop" and c.pos_ == "AUX"
                            for c in word.children
                        )
                    )
                )
                if is_copular_adjective:
                    boost = 0.150
                elif inverse[word.i] and i > inverse[word.i][0]:
                    boost = 0.095

                boost = min(boost, max(0.0, attention[i, 0] - 0.60))
                attention[i, 0] -= boost
                if len(targets) == 1:
                    attention[i, targets[0]] += boost
                else:
                    attention[i, targets[0]] += 0.70 * boost
                    attention[i, targets[1]] += 0.30 * boost

    return "bos_sink_with_contextual_local_boost", attention


def prog_L2H6(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention-sink head with weak POS-dependent strength.
    Non-sink attention is a small, diffuse causal recency background.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_pos_modulated", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.975
        aligned = alignment[i]
        if aligned:
            word = doc[aligned[0]]
            if word.pos_ in ("DET", "PRON"):
                sink_mass += 0.013
            elif word.pos_ == "AUX":
                sink_mass += 0.008
            elif word.pos_ in ("VERB", "CCONJ", "SCONJ"):
                sink_mass += 0.004
            elif word.pos_ in ("NOUN", "PROPN", "ADJ", "ADP"):
                sink_mass -= 0.004

            if word.dep_ in ("nsubj", "nsubjpass", "poss"):
                sink_mass += 0.003
        else:
            sink_mass = 0.986

        if i == 1:
            sink_mass = 0.996

        sink_mass = np.clip(sink_mass, 0.955, 0.997)
        positions = np.arange(1, i + 1, dtype=np.float64)
        background = 0.5 / i + 0.5 * (
            np.exp(-(i - positions) / 8.0)
            / np.exp(-(i - positions) / 8.0).sum()
        )
        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * background

    return "bos_sink_pos_modulated", attention


def prog_L2H7(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with a sparse exception for nearby predicate–argument anchors.
    Redirect only BOS mass; preserve the original self-attention and diffuse residual.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_argument_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    word_tokens = [[] for _ in doc]
    for ti, word_ids in enumerate(alignment):
        for wi in word_ids:
            word_tokens[wi].append(ti)

    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.955
        if alignment[i]:
            word = doc[alignment[i][-1]]
            if word.pos_ == "AUX":
                sink_mass = 0.981
            elif word.pos_ == "PRON":
                sink_mass = 0.977
            elif word.pos_ == "PUNCT":
                sink_mass = 0.970
            elif word.pos_ in ("ADJ", "ADV"):
                sink_mass = 0.965
            elif word.pos_ in ("NOUN", "PROPN"):
                sink_mass = 0.945
            elif word.pos_ == "ADP":
                sink_mass = 0.940
            elif word.pos_ == "PART":
                sink_mass = 0.975

        if i == 1:
            sink_mass = 0.991

        # Original diffuse residual, unchanged.
        distances = i - np.arange(1, i + 1, dtype=np.float64)
        residual = 0.5 + 0.5 * np.exp(-distances / 8.0)
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * residual / residual.sum()
        )
        attention[i, 0] = sink_mass

        # Sparse exception: arguments and their introductory modifiers retain
        # a nearby predicate, preposition, or nominal prepositional anchor.
        if i > 1 and alignment[i]:
            word = doc[alignment[i][-1]]
            if word.pos_ in ("DET", "PRON", "NOUN", "PROPN", "ADJ", "ADP"):
                node = word
                crossed_prep = False
                for _ in range(3):
                    if node.dep_ in (
                        "nsubj", "nsubjpass", "csubj", "csubjpass",
                        "aux", "auxpass", "mark", "conj",
                    ):
                        break
                    parent = node.head
                    if parent.i == node.i:
                        break

                    crossed_prep = crossed_prep or node.pos_ == "ADP"
                    distance = word.i - parent.i
                    anchor = (
                        parent.pos_ == "VERB"
                        and node.dep_ in ("dobj", "obj", "iobj", "dative", "prep")
                    ) or (
                        parent.pos_ == "ADP" and node.dep_ in ("pobj", "obj")
                    ) or (
                        parent.pos_ in ("NOUN", "PROPN")
                        and crossed_prep
                        and node.dep_ in ("prep", "nmod")
                    )

                    if anchor and 0 < distance <= 4:
                        candidates = word_tokens[parent.i]
                        # Require the entire anchor word to precede this query.
                        if candidates and 0 < candidates[-1] < i:
                            j = candidates[-1]
                            if parent.pos_ == "VERB":
                                strength = {
                                    "DET": 0.20,
                                    "PRON": 0.24,
                                    "NOUN": 0.15,
                                    "PROPN": 0.15,
                                    "ADJ": 0.10,
                                    "ADP": 0.18,
                                }[word.pos_]
                            else:
                                strength = 0.16 if word.pos_ == "DET" else 0.13

                            transfer = strength * np.exp(
                                -(distance - 1) / 2.5
                            )
                            transfer = min(transfer, attention[i, 0])
                            attention[i, 0] -= transfer
                            attention[i, j] += transfer
                            break

                    if parent.pos_ in ("VERB", "AUX", "PUNCT"):
                        break
                    node = parent

    return "bos_sink_with_argument_anchors", attention


def prog_L2H8(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with modest position-dependent dilution.
    Dialogue and clause-internal content slightly increase diffuse local attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_leakage", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0
    in_quote = False

    for i in range(1, n):
        text = tokens[i].replace("Ġ", " ").replace("▁", " ").strip()
        words = [doc[k] for k in aligned[i]]
        pos = words[0].pos_ if words else ""
        dep = words[0].dep_ if words else ""

        sink = 0.972 - min(0.045, 0.00075 * i)
        if in_quote:
            sink -= 0.085
        if pos in ("CCONJ", "SCONJ", "AUX"):
            sink += 0.010
        elif pos in ("NOUN", "PROPN", "ADJ"):
            sink -= 0.012
        if dep in ("poss", "prep"):
            sink += 0.006

        if text and all(c in ".,;:!?" for c in text):
            sink += 0.012
        if not text:
            sink += 0.008

        quote_count = sum(c in "\"“”" for c in text)
        if quote_count:
            sink -= 0.025

        if i == 1:
            sink = 0.945 if pos == "DET" else 0.991

        sink = float(np.clip(sink, 0.80, 0.995))
        attention[i, 0] = sink

        positions = np.arange(1, i + 1)
        local = np.exp(-(i - positions) / 4.0)
        local = 0.65 * local / local.sum() + 0.35 / i
        attention[i, 1:i + 1] = (1.0 - sink) * local

        if quote_count % 2:
            in_quote = not in_quote

    return "bos_sink_with_local_leakage", make_row_stochastic(attention)


def prog_L2H9(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with weak, gradually increasing causal leakage.
    Residual attention mixes local recency with a diffuse prefix background.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_weak_leakage", attention

    attention[0, 0] = 1.0

    for i in range(1, n):
        leakage = min(0.10, 0.005 + 0.001 * i)
        positions = np.arange(1, i + 1)
        residual = np.exp(-(i - positions) / 4.0)
        residual /= residual.sum()
        residual = 0.7 * residual + 0.3 / i

        attention[i, 0] = 1.0 - leakage
        attention[i, 1:i + 1] = leakage * residual

    return "bos_sink_with_weak_leakage", attention


def prog_L2H10(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with slowly increasing, weak recency-weighted leakage.
    Position dominates; the examples do not establish a reliable syntactic preference.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_recency_leakage", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        leakage = min(0.18, 0.003 + 0.0016 * (i - 1))
        positions = np.arange(1, i + 1, dtype=np.float64)
        residual = 0.5 + 0.5 * np.exp(-(i - positions) / 8.0)
        residual /= residual.sum()

        attention[i, 0] = 1.0 - leakage
        attention[i, 1:i + 1] = leakage * residual

    return "bos_sink_with_recency_leakage", attention


def prog_L2H11(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with a sparse dialogue-return exception: narrative predicates
    retrieve the opening clause's boundary or copular predicate.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    for i in range(n):
        if i == 0:
            attention[0, 0] = 1.0
        else:
            sink_mass = 1.0 / (1.0 + 0.012 + 0.00065 * i)
            attention[i, 0] = sink_mass
            attention[i, 1:i + 1] = (1.0 - sink_mass) / i

    # Only dialogue-return rows can depart from the original prediction.
    if sentence.count('"') >= 2:
        doc = spacy_parse(sentence)
        aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
        inverse = align_spacy_to_tokens(sentence, tokens, tokenizer)
        inside_quote = False
        first_open = None
        last_close = None
        verb_since_close = False
        seen_verbs = set()

        for i, token in enumerate(tokens):
            if '"' in token:
                for _ in range(token.count('"')):
                    if not inside_quote:
                        if first_open is None:
                            first_open = i
                        inside_quote = True
                    else:
                        inside_quote = False
                        last_close = i
                        verb_since_close = False
                continue

            if inside_quote or last_close is None:
                continue

            for si in aligned[i]:
                word = doc[si]
                if word.pos_ not in ("VERB", "AUX") or si in seen_verbs:
                    continue
                seen_verbs.add(si)

                eligible = (
                    not verb_since_close
                    and word.pos_ == "VERB"
                    and any(c.dep_ in ("prep", "ccomp", "xcomp")
                            for c in word.children)
                    and any(c.dep_ in ("nsubj", "nsubjpass")
                            for c in word.children)
                )
                verb_since_close = True
                if not eligible:
                    continue

                targets = []
                # A copular opening supplies a two-token predicate anchor.
                for earlier in doc:
                    if earlier.pos_ != "AUX":
                        continue
                    aux_ids = [j for j in inverse[earlier.i]
                               if 0 < j < first_open]
                    if not aux_ids:
                        continue
                    for child in earlier.children:
                        if child.pos_ != "ADJ" or child.dep_ not in ("acomp", "attr"):
                            continue
                        adj_ids = [j for j in inverse[child.i]
                                   if 0 < j < first_open]
                        if adj_ids:
                            targets = [(aux_ids[-1], 0.18),
                                       (adj_ids[-1], 0.23)]
                            break
                    if targets:
                        break

                if not targets:
                    boundaries = [
                        j for j in range(1, first_open)
                        if "," in tokens[j]
                    ]
                    if boundaries:
                        targets = [(boundaries[-1], 0.15)]

                # Transfer only from BOS; retain self-attention and every
                # non-target causal weight exactly as originally computed.
                for j, mass in targets:
                    if 0 < j < i:
                        delta = min(mass, attention[i, 0])
                        attention[i, 0] -= delta
                        attention[i, j] += delta

    return "bos_sink_with_dialogue_return", attention


def prog_L2H12(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink: nearly all attention targets position zero.
    A small residual is distributed over recent causal positions.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_weak_recency", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        sink_mass = 0.95 + 0.035 * np.exp(-(i - 1) / 2.5)
        positions = np.arange(1, i + 1)
        residual = np.exp(-(i - positions) / 4.0)
        residual /= residual.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_weak_recency", attention


def prog_L2H13(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention-sink head with mild POS-dependent strength.
    Residual attention is weak, causal, and biased toward nearby tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_pos_modulated", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    sink_strength = {
        "NOUN": 0.974,
        "PROPN": 0.978,
        "ADJ": 0.948,
        "DET": 0.949,
        "NUM": 0.955,
        "PRON": 0.918,
        "VERB": 0.915,
        "AUX": 0.910,
        "ADV": 0.918,
        "ADP": 0.922,
        "PART": 0.910,
        "CCONJ": 0.892,
        "SCONJ": 0.914,
        "PUNCT": 0.884,
        "SPACE": 0.925,
    }

    attention[0, 0] = 1.0
    for i in range(1, n):
        strength = 0.930
        if alignment[i]:
            word = doc[alignment[i][-1]]
            strength = sink_strength.get(word.pos_, strength)
            if word.ent_type_ and word.pos_ in ("NOUN", "PROPN"):
                strength += 0.003

        if i == 1:
            strength = 0.986
        elif i <= 4:
            strength += 0.008

        strength = float(np.clip(strength, 0.85, 0.995))
        attention[i, 0] = strength

        positions = np.arange(1, i + 1)
        residual = 0.35 / i + 0.65 * np.exp(-(i - positions) / 3.0)
        residual /= residual.sum()
        attention[i, 1:i + 1] = (1.0 - strength) * residual

    return "bos_sink_pos_modulated", make_row_stochastic(attention)


def prog_L2H14(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with gradually weakening positional dominance.
    Residual attention is diffuse and mildly recency-biased.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_position_decay", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    attention[0, 0] = 1.0
    pos_adjustment = {
        "ADP": 0.025,
        "PRON": 0.010,
        "NOUN": 0.005,
        "PROPN": -0.015,
        "AUX": -0.015,
        "ADV": -0.015,
        "PART": -0.020,
    }

    for i in range(1, n):
        sink_mass = 0.56 + 0.42 * np.exp(-(i - 1) / 19.0)

        aligned = alignment[i]
        if aligned:
            word = doc[aligned[0]]
            sink_mass += pos_adjustment.get(word.pos_, 0.0)
            if word.is_punct:
                sink_mass -= 0.015

        if i == 1:
            sink_mass = 0.98

        sink_mass = float(np.clip(sink_mass, 0.45, 0.99))
        attention[i, 0] = sink_mass

        positions = np.arange(1, i + 1)
        distances = i - positions
        residual = 0.35 + np.exp(-distances / 7.0)
        residual /= residual.sum()
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_position_decay", make_row_stochastic(attention)


def prog_L2H15(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with sparse successor-of-repeat attention in multi-turn dialogue.
    Repeated linguistic cues weakly retrieve the token following an earlier cue.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n > 0:
        attention[:, 0] = 1.0

    # Leave the original sink unchanged outside multi-turn quoted dialogue.
    if sentence.count('"') + sentence.count('“') + sentence.count('”') >= 4:
        doc = spacy_parse(sentence)
        aligned = align_spacy_to_tokens(sentence, tokens, tokenizer)
        strengths = {
            "PROPN": 0.34,
            "NOUN": 0.13,
            "VERB": 0.32,
            "DET": 0.04,
            "PRON": 0.09,
            "ADP": 0.12,
        }

        for k, word in enumerate(doc):
            if word.pos_ not in strengths or not aligned[k]:
                continue
            i = aligned[k][-1]
            best_similarity, target = 0.0, None
            threshold = 0.72 if word.pos_ == "VERB" else 0.80

            for h in range(k - 1, -1, -1):
                if doc[h].pos_ != word.pos_ or not aligned[h]:
                    continue
                previous = aligned[h][-1]
                successor = previous + 1
                if not (0 < successor < i):
                    continue
                similarity = embedding_similarity(tokens, i, previous, tokenizer)
                if similarity >= threshold and similarity > best_similarity:
                    best_similarity, target = similarity, successor

            if target is not None:
                mass = strengths[word.pos_]
                if word.pos_ == "NOUN":
                    if any(c in tokens[target] for c in '.!?"”'):
                        mass = 0.23
                    elif word.dep_ in ("nsubj", "nsubjpass"):
                        mass = 0.10
                attention[i, 0] -= mass
                attention[i, target] += mass

        # Boundary-token induction: commas retrieve earlier quote openings;
        # opening quotes retrieve the beginning of an earlier quoted turn.
        previous_open = None
        inside_quote = False
        previous_close = None
        for i in range(1, n):
            text = tokens[i].replace("Ġ", " ").strip()
            if any(c in text for c in '"“”'):
                if not inside_quote:
                    if previous_open is not None and previous_open + 1 < i:
                        attention[i, 0] -= 0.045
                        attention[i, previous_open + 1] += 0.045
                    previous_open = i
                else:
                    if previous_close is not None and previous_close + 1 < i:
                        attention[i, 0] -= 0.05
                        attention[i, previous_close + 1] += 0.05
                    previous_close = i
                inside_quote = not inside_quote
            elif text == "," and previous_open is not None:
                if previous_open < i:
                    attention[i, 0] -= 0.02
                    attention[i, previous_open] += 0.02

    return "bos_sink_with_dialogue_induction", attention


def prog_L2H16(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Hypothesis: this head is a near-exclusive first-token/BOS attention sink,
    largely independent of linguistic features."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention_matrix = np.zeros((n, n), dtype=np.float64)
    if n:
        attention_matrix[:, 0] = 1.0
    return "first_token_attention_sink", attention_matrix


def prog_L2H17(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Mostly a BOS sink, with sparse induction attention to the successor
    of an earlier, strongly matching token."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    for i in range(n):
        if i == 0:
            attention[i, 0] = 1.0
        else:
            attention[i, 0] = 0.99
            attention[i, 1:i + 1] = 0.01 / i

    # Only induction edges are added; self-attention and other residual
    # weights remain unchanged. Their mass comes exclusively from BOS.
    if n > 3:
        doc = spacy_parse(sentence)
        aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
        words = [doc[sids[0]] if sids else None for sids in aligned]
        thresholds = {
            "NOUN": 0.88, "PROPN": 0.90, "VERB": 0.72,
            "DET": 0.80, "ADP": 0.94, "PRON": 0.96,
            "PUNCT": 0.97,
        }

        for i in range(3, n):
            word = words[i]
            if word is None or word.pos_ not in thresholds:
                continue
            if not tokens[i].lstrip("Ġ").strip():
                continue

            best_j, best_similarity = None, thresholds[word.pos_]
            for j in range(1, i - 1):
                previous = words[j]
                if previous is None or previous.pos_ != word.pos_:
                    continue
                # Do not mistake pieces of the same word for repetitions.
                if previous.i == word.i:
                    continue
                similarity = embedding_similarity(tokens, i, j, tokenizer)
                if similarity >= best_similarity:
                    best_j, best_similarity = j, similarity

            if best_j is None:
                continue

            target = best_j + 1
            successor = words[target]
            pos = word.pos_
            if pos == "VERB":
                mass = 0.20
            elif pos in ("NOUN", "PROPN"):
                mass = 0.13
                if successor is not None:
                    if successor.pos_ == "ADP":
                        mass = 0.30
                    elif successor.pos_ in ("AUX", "VERB"):
                        mass = 0.10
                    elif successor.is_punct:
                        mass = 0.30 if any(
                            c in successor.text for c in ".!?"
                        ) else 0.085
            elif pos == "DET":
                mass = 0.10 if best_j == 1 else 0.015
            elif pos == "ADP":
                mass = 0.09
            elif pos == "PRON":
                mass = 0.012
            else:
                mass = 0.06

            attention[i, 0] -= mass
            attention[i, target] += mass

    return "bos_sink_with_sparse_successor_induction", attention


def prog_L2H18(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """A dominant beginning-of-sequence attention sink, with mild POS modulation.
    The small residual follows a diffuse causal recency prior."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_pos_modulation", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        words = [doc[k] for k in alignment[i]]
        word = max(words, key=lambda w: len(w.text)) if words else None

        sink_mass = 0.90
        if word is not None:
            if word.pos_ in ("NOUN", "PROPN"):
                sink_mass = 0.935
            elif word.pos_ in ("VERB", "ADJ"):
                sink_mass = 0.925
            elif word.pos_ == "ADP":
                sink_mass = 0.925
            elif word.pos_ in ("DET", "NUM"):
                sink_mass = 0.90
            elif word.pos_ == "ADV":
                sink_mass = 0.88
            elif word.pos_ in ("AUX", "PART", "CCONJ", "SCONJ"):
                sink_mass = 0.855
            elif word.pos_ == "PRON":
                sink_mass = 0.85
            elif word.is_punct:
                sink_mass = 0.82

            # Initial nominal subjects show especially strong sink behavior.
            if i <= 4 and word.dep_ in ("nsubj", "nsubjpass"):
                sink_mass = max(sink_mass, 0.97)

        if i == 1:
            sink_mass = 0.965
        elif i <= 4:
            sink_mass = min(0.98, sink_mass + 0.015)

        positions = np.arange(1, i + 1, dtype=np.float64)
        residual = 0.35 + np.exp(-(i - positions) / 4.0)
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * residual / residual.sum()
        )
        attention[i, 0] = sink_mass

    return "bos_sink_with_pos_modulation", attention


def prog_L2H19(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with sparse successor-copy induction and shifted antecedent attention.
    Special cases transfer only BOS mass, preserving the causal background and diagonal."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_sparse_successor", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        # Original default behavior.
        residual = 0.004 + 0.0004 * i
        aligned = alignment[i]
        if aligned:
            if any(doc[k].is_punct for k in aligned):
                residual *= 1.8
            elif any(doc[k].pos_ in ("PRON", "DET", "PART") for k in aligned):
                residual *= 1.2

        residual = min(residual, 0.08)
        positions = np.arange(1, i + 1, dtype=np.float64)
        background = 0.5 + np.exp(-(i - positions) / 8.0)
        background /= background.sum()

        attention[i, 0] = 1.0 - residual
        attention[i, 1:i + 1] = residual * background

        current = doc[aligned[0]] if aligned else None
        target, mass = None, 0.0

        # Repeated lexical/quotation cues retrieve the earlier cue's successor.
        for j in range(i - 4, 0, -1):
            previous = doc[alignment[j][0]] if alignment[j] else None
            if j > 1 and alignment[j] and alignment[j] == alignment[j - 1]:
                continue
            end = j
            while end + 1 < i and alignment[j] and alignment[end + 1] == alignment[j]:
                end += 1
            successor = end + 1
            if successor >= i:
                continue

            matched = False
            amount = 0.0
            if current is not None and previous is not None:
                if current.pos_ == previous.pos_ and current.pos_ in (
                    "NOUN", "PROPN", "VERB", "DET"
                ):
                    similarity = embedding_similarity(tokens, i, j, tokenizer)
                    threshold = 0.82 if current.pos_ == "VERB" else 0.96
                    matched = similarity >= threshold
                    amount = 0.40 if current.pos_ != "DET" else 0.06
                    if current.pos_ == "DET" and current.is_sent_start:
                        amount = 0.28
                elif current.is_punct and previous.is_punct:
                    # Restrict punctuation induction to quotation contexts.
                    quoted = any(c in tokens[successor] for c in ('"', "“", "”"))
                    matched = tokens[i] == tokens[j] and (
                        quoted or any(c in tokens[i] for c in ('"', "“", "”"))
                    )
                    amount = 0.32
            if matched:
                target, mass = successor, amount
                break

        # Personal/possessive pronouns can retrieve the successor of an
        # earlier compatible subject or possessive cue.
        if current is not None and current.pos_ == "PRON" and current.dep_ in (
            "nsubj", "nsubjpass", "dobj", "obj", "poss"
        ):
            for j in range(i - 3, 0, -1):
                if not alignment[j]:
                    continue
                antecedent = doc[alignment[j][0]]
                if antecedent.i >= current.i or antecedent.dep_ not in (
                    "nsubj", "nsubjpass", "poss"
                ):
                    continue
                if antecedent.pos_ not in ("NOUN", "PROPN", "PRON", "DET"):
                    continue
                number = current.morph.get("Number")
                gender = current.morph.get("Gender")
                if number and antecedent.morph.get("Number") and (
                    number != antecedent.morph.get("Number")
                ):
                    continue
                if gender and antecedent.morph.get("Gender") and (
                    gender != antecedent.morph.get("Gender")
                ):
                    continue
                if current.dep_ != "poss" and (
                    antecedent.head.i >= current.head.i
                ):
                    continue
                end = j
                while end + 1 < i and alignment[end + 1] == alignment[j]:
                    end += 1
                if end + 1 >= i:
                    continue
                target = end + 1
                if current.dep_ == "poss":
                    mass = 0.10
                elif current.dep_ in ("dobj", "obj"):
                    mass = 0.55
                else:
                    mass = 0.55 if (
                        gender and gender == antecedent.morph.get("Gender")
                    ) else 0.18
                break

        if target is not None and 0 < target < i:
            transfer = min(mass, attention[i, 0])
            attention[i, 0] -= transfer
            attention[i, target] += transfer

    return "bos_sink_sparse_successor", attention


def prog_L2H20(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with selective third-person anaphoric leakage.
    Later personal/possessive pronouns retrieve an earlier referent's predicate context.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_anaphoric_leakage", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    # Inverse alignment for the narrowly gated anaphoric correction.
    word_positions = [[] for _ in doc]
    for ti, word_ids in enumerate(alignment):
        for wi in word_ids:
            word_positions[wi].append(ti)

    for i in range(1, n):
        # Almost all mass goes to the initial token, irrespective of syntax.
        sink_mass = 0.978 - 0.008 * (1.0 - np.exp(-i / 16.0))

        if alignment[i]:
            word = doc[alignment[i][0]]
            if word.is_punct or word.is_space:
                sink_mass -= 0.035
            elif word.pos_ == "PRON":
                sink_mass -= 0.018
            elif word.pos_ in ("DET", "AUX", "PART"):
                sink_mass -= 0.008
            elif word.pos_ in ("NOUN", "PROPN", "ADJ"):
                sink_mass += 0.006
        elif tokens[i].isspace():
            sink_mass -= 0.045

        # The small non-sink component is uncertain; use a diffuse local prior.
        positions = np.arange(1, i + 1)
        local_weights = 0.25 + np.exp(-(i - positions) / 4.0)
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * local_weights / local_weights.sum()
        )
        attention[i, 0] = sink_mass

        # Only third-person anaphoric queries receive the additional pathway.
        if not alignment[i]:
            continue
        word = doc[alignment[i][0]]
        possessive = "Yes" in word.morph.get("Poss")
        if (
            "3" not in word.morph.get("Person")
            or not (word.pos_ == "PRON" or possessive)
            or word_positions[word.i][0] != i
        ):
            continue

        candidates = [
            w for w in doc[:word.i]
            if (
                (
                    "3" in w.morph.get("Person")
                    and (w.pos_ == "PRON" or "Yes" in w.morph.get("Poss"))
                )
                or (
                    w.pos_ in ("NOUN", "PROPN")
                    and w.dep_ in ("nsubj", "nsubjpass", "nsubj:pass")
                )
            )
            and word_positions[w.i]
        ]
        if not candidates:
            continue

        anchor = candidates[-1]
        nominal_anchor = anchor.pos_ in ("NOUN", "PROPN")
        anchor_possessive = "Yes" in anchor.morph.get("Poss")
        context = np.zeros(len(doc), dtype=np.float64)

        # Retrieve the short predicate/complement span following the referent.
        for offset in range(1, 5):
            wi = anchor.i + offset
            if wi >= word.i:
                break
            target = doc[wi]
            if target.pos_ in ("PRON", "DET") or target.is_space:
                continue
            if nominal_anchor:
                weight = 0.75 if offset <= 3 else 0.15
                if target.pos_ == "ADV":
                    weight *= 0.5
            else:
                weight = 0.32 ** (offset - 1)
                if target.pos_ == "ADP":
                    weight *= 4.0
                elif target.is_punct:
                    weight *= 3.0
            context[wi] += weight

        if nominal_anchor:
            context[anchor.i] += 0.8
            for child in anchor.children:
                if child.dep_ == "poss":
                    for marker in child.children:
                        if marker.dep_ == "case":
                            context[marker.i] += 0.7

        if anchor_possessive:
            governor = anchor.head.head
            if governor.i < word.i and governor.i != anchor.i:
                context[governor.i] += 0.9
                if governor.head.i < word.i and governor.head.i != governor.i:
                    predicate = governor.head
                    context[predicate.i] += 0.4
                    for child in predicate.children:
                        if child.i < word.i and child.pos_ in ("AUX", "ADV"):
                            context[child.i] += 0.3

        retrieval = np.zeros(n, dtype=np.float64)
        for wi, weight in enumerate(context):
            valid = [j for j in word_positions[wi] if 0 < j < i]
            if valid and weight > 0.0:
                retrieval[valid] += weight / len(valid)

        if retrieval.sum() > 0.0:
            if nominal_anchor:
                extra_mass = 0.68
            elif possessive:
                extra_mass = 0.61 if anchor_possessive else 0.36
            else:
                extra_mass = 0.56
            extra_mass = min(extra_mass, attention[i, 0])
            # Transfer only BOS mass; preserve the original self/local weights.
            attention[i, 0] -= extra_mass
            attention[i] += extra_mass * retrieval / retrieval.sum()

    return "bos_sink_with_anaphoric_leakage", make_row_stochastic(attention)


def prog_L2H21(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, strongest on opening phrases and nominal content.
    Remaining attention is weak, causal, and mildly biased toward nearby tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_linguistic_modulation", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0
    opening_phrase = True

    for i in range(1, n):
        words = [doc[k] for k in alignment[i]]
        word = words[-1] if words else None

        sink = 0.88
        if word is not None:
            pos = word.pos_
            dep = word.dep_

            if pos in ("NOUN", "PROPN"):
                sink = 0.945
                if dep in ("nsubj", "nsubjpass", "csubj"):
                    sink += 0.025
                if word.ent_type_:
                    sink += 0.01
            elif pos == "ADJ":
                sink = 0.925
            elif pos == "NUM":
                sink = 0.92
            elif pos == "PUNCT":
                sink = 0.90
            elif pos in ("VERB", "AUX"):
                sink = 0.865
            elif pos == "DET":
                sink = 0.875
            elif pos == "PRON":
                sink = 0.845
            elif pos in ("ADP", "PART"):
                sink = 0.79
            elif pos in ("ADV", "CCONJ", "SCONJ"):
                sink = 0.865

            if opening_phrase and pos not in ("VERB", "AUX"):
                sink += 0.04
            if pos in ("VERB", "AUX"):
                opening_phrase = False
        elif tokens[i].strip("\u0120\u2581 \t\r\n") == "":
            sink = 0.95

        # The first non-BOS query is almost entirely absorbed by BOS;
        # the opening positional effect diminishes quickly.
        positional_sink = 0.995 * np.exp(-0.055 * (i - 1))
        sink = float(np.clip(max(sink, positional_sink), 0.0, 0.999))

        positions = np.arange(1, i + 1)
        residual = 0.25 + np.exp(-(i - positions) / 4.0)
        residual /= residual.sum()

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual

    return "bos_sink_with_linguistic_modulation", attention


def prog_L2H22(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with mild positional and syntactic modulation.
    Small residual attention is distributed causally with a recency bias.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_linguistic_modulation", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        aligned = [doc[k] for k in alignment[i]]
        positions = {word.pos_ for word in aligned}

        sink_mass = 0.945 + 0.045 * np.exp(-(i - 1) / 5.0)

        if positions & {"NOUN", "PROPN"}:
            sink_mass += 0.022
        elif positions & {"ADJ", "ADP", "DET"}:
            sink_mass += 0.009
        elif positions & {"PRON", "PART"}:
            sink_mass -= 0.015
        elif positions & {"CCONJ", "SCONJ", "ADV"}:
            sink_mass -= 0.025

        if aligned and all(word.is_punct for word in aligned):
            sink_mass -= 0.085

        # The first ordinary token has almost no competition with the sink.
        if i == 1:
            sink_mass = 0.993

        sink_mass = float(np.clip(sink_mass, 0.78, 0.997))
        attention[i, 0] = sink_mass

        distances = i - np.arange(1, i + 1)
        residual = 0.75 * np.exp(-distances / 4.0) + 0.25 / i
        residual /= residual.sum()
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_linguistic_modulation", attention


def prog_L2H23(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with a selective backward link to object-phrase governors.
    Move only BOS mass to preceding verbs/prepositions; preserve self-attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_object_governors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    # First model token of each word: do not apply phrase-level corrections
    # again to continuation pieces.
    first_piece = {}
    for ti, sids in enumerate(alignment):
        if ti > 0:
            for sid in sids:
                if sid not in first_piece:
                    first_piece[sid] = ti

    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.85
        sids = alignment[i]
        if sids:
            word = doc[sids[-1]]
            pos = word.pos_
            dep = word.dep_

            if pos == "AUX":
                sink_mass = 0.960
            elif pos == "VERB":
                sink_mass = 0.935
            elif dep in ("nsubj", "nsubjpass", "csubj", "csubjpass"):
                sink_mass = 0.935
            elif pos == "PRON":
                sink_mass = 0.885
            elif pos in ("NOUN", "PROPN"):
                sink_mass = 0.785
            elif pos == "DET":
                sink_mass = 0.810
            elif pos == "ADJ":
                sink_mass = 0.815
            elif pos in ("ADP", "SCONJ", "CCONJ"):
                sink_mass = 0.855
            elif pos == "PART":
                sink_mass = 0.925
            elif pos == "ADV":
                sink_mass = 0.865
            elif pos == "PUNCT":
                sink_mass = 0.915

            if dep in ("ROOT", "aux", "auxpass", "cop"):
                sink_mass = max(sink_mass, 0.945)

            if i == 1:
                sink_mass = 0.972
                if pos == "PRON":
                    sink_mass = 0.994
                elif pos in ("PROPN", "ADV", "ADP", "SCONJ", "NUM"):
                    sink_mass = 0.987
            else:
                sink_mass += 0.035 * np.exp(-(i - 2) / 3.0)
        elif tokens[i].isspace() or tokens[i].strip("Ġ▁") == "":
            sink_mass = 0.940

        sink_mass = float(np.clip(sink_mass, 0.72, 0.995))
        attention[i, 0] = sink_mass

        # Preserve the original residual, including its self-attention weight.
        distances = i - np.arange(1, i + 1)
        residual = 0.6 + 0.4 * np.exp(-distances / 6.0)
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * residual / residual.sum()
        )

        # Special case: an object or its nominal modifiers attend backward
        # to their governing verb/preposition, not diffusely to the context.
        if sids and first_piece.get(word.i) == i:
            node = word
            while (
                node.dep_ in ("det", "predet", "amod", "compound", "poss", "nmod")
                and node.head.i != node.i
                and node.head.pos_ in ("NOUN", "PROPN", "PRON")
            ):
                node = node.head

            governor = node.head
            verbal_object = (
                node.dep_ in ("dobj", "obj", "iobj", "dative")
                and governor.pos_ == "VERB"
            )
            prepositional_object = (
                node.dep_ in ("pobj", "obj")
                and governor.pos_ == "ADP"
            )

            if verbal_object or prepositional_object:
                j = first_piece.get(governor.i)
                if j is not None and 0 < j < i:
                    nominal = word.pos_ in ("NOUN", "PROPN")
                    if prepositional_object:
                        # Prepositions introducing a second argument retain
                        # stronger attention throughout the following phrase.
                        parent = governor.head
                        second_argument = (
                            parent.pos_ == "VERB"
                            and any(
                                child.dep_ in ("dobj", "obj", "iobj", "dative")
                                for child in parent.children
                            )
                        )
                        target = (
                            (0.14 if nominal else 0.30)
                            if second_argument
                            else (0.07 if nominal else 0.16)
                        )
                    else:
                        target = 0.11 if nominal else 0.18

                    transfer = min(
                        max(0.0, target - attention[i, j]),
                        max(0.0, attention[i, 0] - 0.45),
                    )
                    attention[i, 0] -= transfer
                    attention[i, j] += transfer

    return "bos_sink_with_object_governors", attention


def prog_L3H0(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with a slowly weakening positional prior.
    Linguistic features modulate sink strength; residual attention is diffuse and local.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_linguistic_modulation", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        words = [doc[k] for k in alignment[i]]
        sink_logit = 3.70 - 0.70 * np.log(float(i))

        if words:
            word = words[-1]
            pos = word.pos_
            if word.is_punct:
                sink_logit += 0.55
            elif word.is_space:
                sink_logit += 0.45
            elif pos in ("NOUN", "PROPN"):
                sink_logit += 0.30
            elif pos in ("DET", "ADP"):
                sink_logit += 0.10
            elif pos in ("VERB", "AUX"):
                sink_logit -= 0.45
            elif pos in ("PRON", "ADV", "PART"):
                sink_logit -= 0.35
            elif pos == "ADJ":
                sink_logit -= 0.10

            if word.ent_type_:
                sink_logit += 0.10
        elif tokens[i].isspace() or tokens[i].strip("Ġ▁") == "":
            sink_logit += 0.45

        sink_mass = 1.0 / (1.0 + np.exp(-sink_logit))
        if i == 1:
            sink_mass = 0.985

        # No non-BOS edge is established by the examples: use a weak,
        # broadly distributed recency prior for the remaining probability.
        distances = i - np.arange(1, i + 1, dtype=np.float64)
        residual = 0.75 / i + 0.25 * (
            np.exp(-distances / 4.0) /
            np.exp(-distances / 4.0).sum()
        )
        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_linguistic_modulation", make_row_stochastic(attention)


def prog_L3H1(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """A dominant beginning-of-sequence attention sink with weak local leakage.
    Linguistic features modestly adjust the strength of the sink.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_leakage", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.970
        aligned = alignment[i]
        if aligned:
            word = doc[aligned[0]]
            if word.pos_ in ("NOUN", "PROPN", "ADJ", "ADV", "ADP"):
                sink_mass = 0.978
            elif word.pos_ in ("VERB", "AUX", "PRON", "DET", "CCONJ", "SCONJ"):
                sink_mass = 0.960
            elif word.is_punct:
                sink_mass = 0.940

        # The observed edges identify the sink, not a specific residual target;
        # use a conservative mixture of diffuse and recency-weighted leakage.
        positions = np.arange(1, i + 1)
        local = np.exp(-(i - positions) / 3.0)
        local /= local.sum()
        residual = 0.5 * local + 0.5 / i

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_local_leakage", make_row_stochastic(attention)


def prog_L3H2(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, strongest initially and on lexical content tokens.
    Residual attention is diffuse and mildly biased toward recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_lexical_modulation", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    pos_adjustment = {
        "NOUN": 0.12,
        "PROPN": 0.14,
        "ADJ": 0.07,
        "VERB": 0.00,
        "AUX": -0.035,
        "ADV": -0.015,
        "ADP": 0.005,
        "DET": -0.025,
        "PRON": -0.085,
        "CCONJ": -0.045,
        "SCONJ": -0.055,
        "PART": -0.025,
        "NUM": 0.025,
        "PUNCT": -0.065,
        "SPACE": -0.045,
    }

    for i in range(1, n):
        sink_mass = 0.75 + 0.22 * np.exp(-(i - 1) / 2.4)
        aligned = alignment[i]

        if aligned:
            word = doc[aligned[-1]]
            sink_mass += pos_adjustment.get(word.pos_, 0.0)
            if word.ent_type_:
                sink_mass += 0.015
            if word.pos_ in ("NOUN", "PROPN") and word.dep_ in (
                "nsubj", "nsubjpass", "attr", "pobj", "dobj", "obj"
            ):
                sink_mass += 0.015

        if i == 1:
            sink_mass = 0.985

        sink_mass = float(np.clip(sink_mass, 0.56, 0.985))

        # Keep the unobserved non-sink structure conservative rather than
        # introducing unsupported long-distance syntactic links.
        distances = i - np.arange(1, i + 1)
        residual = 0.35 + np.exp(-distances / 4.0)
        residual /= residual.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_lexical_modulation", make_row_stochastic(attention)


def prog_L3H3(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with near-total mass on the initial token.
    Residual attention is diffuse and mildly biased toward recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    for i in range(n):
        if i == 0:
            attention[i, 0] = 1.0
            continue

        sink_mass = 0.970 + 0.025 * np.exp(-(i - 1) / 1.5)
        distances = i - np.arange(1, i + 1)
        residual = 0.8 / i + 0.2 * (
            np.exp(-distances / 4.0)
            / np.exp(-distances / 4.0).sum()
        )

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_diffuse_residual", attention


def prog_L3H4(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention-sink head with weak token-type modulation.
    Residual attention follows a diffuse causal prior with a small recency bias.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_weak_local_residual", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        clean = tokens[i].replace("Ġ", " ").replace("Ċ", "\n").replace("▁", " ")
        aligned = alignment[i]
        sink_mass = 0.925

        if aligned:
            word = doc[aligned[0]]
            if word.pos_ in ("NOUN", "PROPN", "VERB"):
                sink_mass -= 0.010
            elif word.pos_ in ("AUX", "PRON", "DET", "PART"):
                sink_mass += 0.006

            if word.is_punct:
                sink_mass = 0.945
            elif word.is_space:
                sink_mass = 0.965

        if not clean.strip():
            sink_mass = 0.965
        elif clean.strip() and all(
            not c.isalnum() and not c.isspace() for c in clean
        ):
            sink_mass = 0.945

        if tokens[i] in tokenizer.all_special_tokens:
            sink_mass = 0.970

        if i == 1:
            sink_mass = 0.975

        # The examples constrain the sink strongly, but not residual targets;
        # avoid imposing a strong syntactic mechanism on the remaining mass.
        positions = np.arange(1, i + 1, dtype=np.float64)
        residual = (
            0.65 / i
            + 0.35 * np.exp(-(i - positions) / 4.0)
            / np.exp(-(i - positions) / 4.0).sum()
        )

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_weak_local_residual", make_row_stochastic(attention)


def prog_L3H5(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with a small, causally local residual.
    The observed head is primarily positional rather than syntactic.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_local_residual", attention

    attention[0, 0] = 1.0

    for i in range(1, n):
        # Dominant BOS mass, with weak dilution as the context grows.
        sink_mass = 0.95 + 0.035 * np.exp(-(i - 1) / 24.0)

        # The examples do not identify reliable non-BOS targets; use a
        # conservative mixture of diffuse causal and short-range attention.
        positions = np.arange(1, i + 1, dtype=np.float64)
        local = np.exp(-(i - positions) / 3.0)
        local /= local.sum()
        residual = 0.5 * local + 0.5 / i

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_local_residual", attention


def prog_L3H6(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Predict a dominant BOS attention sink, reinforced at boundaries and early positions.
    Allocate the weak remaining attention to a diffuse, recency-biased causal background.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_boundary_modulated", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        clean = tokens[i].replace("\u0120", " ").replace("\u010a", "\n").strip()
        aligned = alignment[i]
        pos = doc[aligned[-1]].pos_ if aligned else ""
        dep = doc[aligned[-1]].dep_ if aligned else ""

        # The initial position is almost entirely absorbed by the sink;
        # later lexical positions retain a substantial, but smaller, sink.
        sink = 0.75 + 0.20 * np.exp(-(i - 1) / 4.0)

        if pos in ("NOUN", "ADJ", "VERB", "ADV"):
            sink -= 0.025
        elif pos == "AUX":
            sink += 0.045
        elif pos in ("CCONJ", "SCONJ"):
            sink += 0.075
        elif pos == "PROPN":
            sink += 0.035

        if dep in ("cc", "mark"):
            sink += 0.015

        # Punctuation and standalone whitespace strongly favor the sink.
        if not clean:
            sink = 0.87 + 0.04 * np.exp(-i / 20.0)
        elif clean in (".", "!", "?"):
            sink = 0.93 + 0.02 * np.exp(-i / 25.0)
        elif clean in (",", ";", ":"):
            sink = 0.86 + 0.09 * np.exp(-i / 12.0)
        elif pos == "PUNCT":
            sink = 0.78 + 0.12 * np.exp(-i / 15.0)

        if i == 1:
            sink = 0.97

        sink = float(np.clip(sink, 0.60, 0.98))
        distances = i - np.arange(1, i + 1)
        background = 0.7 * np.exp(-distances / 4.0) + 0.3
        background /= background.sum()

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * background

    return "bos_sink_boundary_modulated", attention


def prog_L3H7(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, strongest near the start and on nominal anchors.
    Remaining attention is weakly distributed over recent causal context.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_nominal_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        early = np.exp(-(i - 1) / 5.0)
        feature_scale = 1.0 - np.exp(-(i - 1) / 3.0)
        sink_mass = 0.80 + 0.185 * early

        feature_bonus = 0.0
        for sid in alignment[i]:
            word = doc[sid]
            bonus = 0.0

            if word.pos_ == "PROPN":
                bonus += 0.125
            elif word.pos_ == "NOUN":
                bonus += 0.085
            elif word.pos_ == "PRON":
                bonus += 0.015
            elif word.pos_ == "DET":
                bonus += 0.025
            elif word.pos_ in ("VERB", "AUX"):
                bonus += 0.015

            if word.dep_ in ("nsubj", "nsubjpass", "csubj"):
                bonus += 0.035
            if word.ent_type_:
                bonus += 0.015

            if word.dep_ == "amod" and word.head.pos_ in ("NOUN", "PROPN"):
                bonus += 0.045

            if word.is_punct:
                bonus -= 0.015

            feature_bonus = max(feature_bonus, bonus)

        sink_mass += feature_scale * feature_bonus
        sink_mass = float(np.clip(sink_mass, 0.76, 0.985))

        # A diffuse residual avoids inventing a strong secondary target
        # unsupported by the observed, overwhelmingly BOS-directed edges.
        positions = np.arange(1, i + 1)
        residual = 0.65 + 0.35 * np.exp(-(i - positions) / 5.0)
        residual /= residual.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_nominal_anchors", attention


def prog_L3H8(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with sparse boundary retrieval: function words retrieve preceding
    boundaries, and subjects can retrieve a fronted prepositional phrase.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_sparse_boundary_retrieval", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.92
        if alignment[i]:
            word = doc[alignment[i][0]]
            if word.pos_ in ("NOUN", "PROPN", "ADJ"):
                sink_mass += 0.025
            elif word.pos_ == "VERB":
                sink_mass += 0.015
            elif word.pos_ in ("PUNCT", "CCONJ", "SCONJ"):
                sink_mass -= 0.025

        if i == 1:
            sink_mass = 0.98

        # Only a small residual is assigned outside the first-position sink.
        distances = i - np.arange(1, i + 1)
        leakage = 0.5 / i + 0.5 * (
            np.exp(-distances / 4.0) / np.exp(-distances / 4.0).sum()
        )
        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * leakage

        # Transfer only BOS mass; preserve self-attention and all other edges.
        transfers = []
        if i > 1 and alignment[i]:
            word = doc[alignment[i][0]]
            previous = doc[alignment[i - 1][-1]] if alignment[i - 1] else None

            # Fire only at a new spaCy word, not within a split word.
            if previous is not None and previous.i != word.i:
                if word.pos_ in ("DET", "PRON"):
                    if previous.pos_ == "ADP":
                        transfers.append((i - 1, 0.11))
                    elif word.pos_ == "PRON" and previous.pos_ in ("CCONJ", "ADV"):
                        transfers.append((i - 1, 0.13))
                    elif word.pos_ == "DET" and previous.text in (",", ";", ":"):
                        transfers.append((i - 1, 0.10))

                # A nominal complement boundary can retain its nominal head.
                if word.pos_ == "ADP" and word.head.pos_ in ("NOUN", "PROPN"):
                    for j in range(i - 1, 0, -1):
                        if word.head.i in alignment[j]:
                            transfers.append((j, 0.15))
                            break
                elif (
                    word.pos_ == "DET"
                    and previous.pos_ == "ADP"
                    and previous.head.pos_ in ("NOUN", "PROPN")
                ):
                    for j in range(i - 2, 0, -1):
                        if previous.head.i in alignment[j]:
                            transfers.append((j, 0.11))
                            break

            # A fronted PP can act as a secondary sink at its clause subject.
            if (
                word.dep_ in ("nsubj", "nsubjpass")
                and len(doc) > 0
                and doc[0].pos_ == "ADP"
                and doc[0].dep_ == "prep"
                and doc[0].head.i == word.head.i
            ):
                for j in range(1, i):
                    if 0 in alignment[j]:
                        transfers.append((j, 0.43))
                        break

        # Explicit quotation boundaries, including standalone whitespace tokens.
        if i > 1:
            current_text = tokens[i].lstrip("Ġ")
            previous_text = tokens[i - 1].lstrip("Ġ")
            if current_text in ('"', "“", "‘") and not previous_text.strip():
                transfers.append((i - 1, 0.35))
            elif (
                previous_text in ('"', "“", "‘")
                and alignment[i]
                and doc[alignment[i][0]].pos_ == "VERB"
                and doc[alignment[i][0]].dep_ == "ROOT"
            ):
                transfers.append((i - 1, 0.24))

        for j, mass in transfers:
            if 0 < j < i:
                moved = min(mass, max(0.0, attention[i, 0] - 0.35))
                attention[i, 0] -= moved
                attention[i, j] += moved

    return "bos_sink_with_sparse_boundary_retrieval", attention


def prog_L3H9(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Dominant beginning-of-sequence attention sink, strongest for discourse
    and function tokens, with weak diffuse causal attention elsewhere."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_linguistic_gating", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        text = tokens[i].lstrip("Ġ").lstrip("▁")
        words = [doc[k] for k in alignment[i]]
        word = max(words, key=lambda w: len(w.text)) if words else None

        # A strong sink competes with a small, accumulating causal background.
        sink_strength = 32.0
        if word is not None:
            pos = word.pos_
            if pos in ("NOUN", "PROPN"):
                sink_strength = 10.0
            elif pos in ("ADJ", "NUM"):
                sink_strength = 14.0
            elif pos == "VERB":
                sink_strength = 19.0
            elif pos in ("PRON", "DET", "AUX", "ADP", "PART"):
                sink_strength = 32.0
            elif pos in ("CCONJ", "SCONJ"):
                sink_strength = 65.0
            elif pos == "ADV":
                sink_strength = 42.0

            if word.dep_ in ("mark", "cc", "advmod"):
                sink_strength *= 1.15
            if word.is_punct or word.is_space:
                sink_strength = 45.0

        if not text or text.isspace():
            sink_strength = 50.0

        # Initial tokens have especially little competition for the sink.
        if i <= 3:
            sink_strength = max(sink_strength, 34.0)

        positions = np.arange(1, i + 1)
        distances = i - positions
        residual = 0.035 + 0.18 * np.exp(-distances / 5.0)
        residual[-1] += 0.55

        attention[i, 0] = sink_strength
        attention[i, 1:i + 1] = residual

    return "bos_sink_with_linguistic_gating", make_row_stochastic(attention)


def prog_L3H10(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention-sink head with weak causal background attention.
    Function words favor the sink most; content words retain more residual mass.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_weak_background", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    function_pos = {"DET", "PRON", "AUX", "ADP", "CCONJ", "SCONJ", "PART"}
    content_pos = {"NOUN", "PROPN", "VERB", "ADJ"}

    attention[0, 0] = 1.0
    for i in range(1, n):
        aligned = [doc[k] for k in alignment[i]]
        positions = {word.pos_ for word in aligned}

        if positions & function_pos:
            background, recent = 0.00065, 0.0025
        elif positions & content_pos:
            background, recent = 0.0018, 0.005
        else:
            background, recent = 0.0009, 0.003

        if aligned and all(word.is_punct or word.is_space for word in aligned):
            background, recent = 0.00055, 0.002
        elif tokens[i].isspace():
            background, recent = 0.00055, 0.002

        # Position zero is the observed sink. Residual mass grows gently
        # with context length, without introducing an unsupported syntax head.
        distance = i - np.arange(1, i + 1)
        attention[i, 1:i + 1] = background + recent * np.exp(-distance / 3.0)
        attention[i, 0] = 1.0

    return "bos_sink_with_weak_background", make_row_stochastic(attention)


def prog_L3H11(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with a mild positional decay and weak local syntactic residual."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_residual", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, word_ids in enumerate(alignment):
        for word_id in word_ids:
            inverse[word_id].append(i)

    attention[0, 0] = 1.0

    for i in range(1, n):
        # The sink dominates even at long distances; early queries are
        # especially close to exclusively attending to the first position.
        sink_mass = 0.82 + 0.175 * np.exp(-(i - 1) / 7.0)
        word_ids = alignment[i]
        word = doc[word_ids[-1]] if word_ids else None

        # Small corrections, rather than treating this as a dependency head.
        correction_scale = 1.0 - np.exp(-(i - 1) / 4.0)
        correction = 0.0
        if word is not None:
            if word.pos_ in ("DET", "ADP", "PART", "SCONJ", "ADV"):
                correction += 0.035
            elif word.pos_ in ("NOUN", "PROPN"):
                correction -= 0.025
            elif word.pos_ == "PUNCT":
                correction -= 0.035

        sink_mass = float(np.clip(
            sink_mass + correction_scale * correction, 0.70, 0.999
        ))

        # Allocate the much smaller nonsink component mostly locally.
        positions = np.arange(1, i + 1)
        residual = np.exp(-(i - positions) / 2.5)
        residual[-1] *= 0.65

        if word is not None:
            # A preceding syntactic governor can attract a little residual.
            for j in inverse[word.head.i]:
                if 0 < j <= i:
                    residual[j - 1] += 0.35

            # Auxiliary queries can weakly favor an already-seen subject.
            if word.pos_ in ("AUX", "VERB"):
                governor = word.head if word.pos_ == "AUX" else word
                for child in governor.children:
                    if child.dep_ in ("nsubj", "nsubjpass", "csubj"):
                        for j in inverse[child.i]:
                            if 0 < j < i:
                                residual[j - 1] += 0.65

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * residual / residual.sum()
        )

    return "bos_sink_with_local_residual", attention


def prog_L3H12(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with a local exception for quotation and whitespace restarts.
    Boundary-triggered attention is transferred from BOS, preserving self-attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_boundary_restart", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    spans = _char_spans(sentence, tokenizer)

    attention[0, 0] = 1.0
    for i in range(1, n):
        sink_mass = 0.885 + 0.040 * np.exp(-(i - 2) / 2.0)
        if i == 1:
            sink_mass = 0.983

        aligned = alignment[i]
        if aligned and all(doc[k].is_punct for k in aligned):
            sink_mass += 0.025

        sink_mass = np.clip(sink_mass, 0.0, 0.995)
        attention[i, 0] = sink_mass

        # Preserve the original residual distribution and self-attention.
        distances = i - np.arange(1, i + 1)
        local = np.exp(-distances / 4.0)
        local /= local.sum()
        residual = 0.75 / i + 0.25 * local
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

        # Only lexical onsets immediately after a quote/spacing boundary
        # receive additional attention to the boundary token.
        if i > 1 and aligned and i < len(spans):
            current = doc[aligned[0]]
            previous = alignment[i - 1]
            start, end = spans[i - 1]
            boundary_text = sentence[start:end]
            whitespace_boundary = bool(boundary_text) and boundary_text.isspace()
            quote_boundary = any(c in "\"'“”‘’«»" for c in boundary_text)
            symbol_boundary = bool(previous) and all(
                doc[k].pos_ in ("SYM", "X") for k in previous
            )
            word_onset = (
                not current.is_punct
                and not current.is_space
                and aligned[0] not in previous
            )

            if word_onset and (
                whitespace_boundary or quote_boundary or symbol_boundary
            ):
                recent_end = any(
                    any(c in ".!?" for c in tokens[j])
                    for j in range(max(1, i - 4), i)
                )
                strong_restart = recent_end and current.pos_ in ("PRON", "PROPN")
                target_sink = 0.49 if strong_restart else 0.82
                transfer = max(0.0, attention[i, 0] - target_sink)
                attention[i, 0] -= transfer
                attention[i, i - 1] += transfer

    return "bos_sink_with_boundary_restart", make_row_stochastic(attention)


def prog_L3H13(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with mild POS-dependent strength.
    Residual attention is diffuse and weakly biased toward recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_pos_modulated", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        clean = tokens[i].lstrip("Ġ").lstrip("▁")
        aligned = alignment[i]
        sink_mass = 0.89

        if aligned:
            word = doc[aligned[0]]
            pos = word.pos_

            if pos == "PROPN":
                sink_mass = 0.945
            elif pos == "VERB":
                sink_mass = 0.925
            elif pos == "NOUN":
                sink_mass = 0.905
            elif pos == "ADJ":
                sink_mass = 0.905
            elif pos == "ADV":
                sink_mass = 0.895
            elif pos == "PRON":
                sink_mass = 0.865
            elif pos == "DET":
                sink_mass = 0.85
            elif pos == "AUX":
                sink_mass = 0.85
            elif pos in ("ADP", "PART", "CCONJ", "SCONJ"):
                sink_mass = 0.85
            elif pos == "PUNCT":
                sink_mass = 0.88

            if word.dep_ == "ROOT" and pos == "VERB":
                sink_mass += 0.01

        if not clean or clean.isspace():
            sink_mass = 0.945
        elif any(mark in clean for mark in (".", "!", "?")):
            sink_mass = 0.955

        if i == 1:
            sink_mass = 0.975

        # Allocate the small non-sink component without inventing strong
        # syntactic links unsupported by the observed attention edges.
        distance = i - np.arange(1, i + 1, dtype=np.float64)
        residual = 0.35 + np.exp(-distance / 3.0)
        residual /= residual.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_pos_modulated", make_row_stochastic(attention)


def prog_L3H14(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with linguistic modulation; commas closing nominal adjuncts
    additionally attend to the preceding noun, without changing self-attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_adjunct_boundary", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    pos_strength = {
        "NOUN": 0.885,
        "PROPN": 0.880,
        "ADJ": 0.855,
        "ADV": 0.795,
        "VERB": 0.785,
        "AUX": 0.770,
        "PRON": 0.760,
        "DET": 0.775,
        "ADP": 0.790,
        "CCONJ": 0.765,
        "SCONJ": 0.755,
        "PART": 0.760,
        "NUM": 0.810,
        "INTJ": 0.790,
        "PUNCT": 0.805,
        "SPACE": 0.870,
    }

    for i in range(1, n):
        aligned = alignment[i]
        sink = 0.790

        if aligned:
            sink = max(pos_strength.get(doc[k].pos_, 0.790) for k in aligned)
            if any(doc[k].ent_type_ for k in aligned):
                sink = max(sink, 0.870)
            if any(doc[k].pos_ == "PUNCT" for k in aligned):
                sink = max(sink, 0.850 if i == n - 1 else 0.795)
        elif tokens[i].strip("ĠĊ▁ \t\r\n") == "":
            sink = 0.870

        if i == 1:
            sink = 0.790 if aligned and doc[aligned[0]].pos_ == "DET" else 0.870

        distances = i - np.arange(1, i + 1)
        residual = 0.65 * np.exp(-distances / 2.5) + 0.35 / i
        residual /= residual.sum()

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual

        # A comma closing a nominal adjunct can retain its final noun.
        # Transfer only BOS mass: preserve the diagonal and original decay.
        if i > 1 and tokens[i].strip("ĠĊ▁ \t\r\n") == ",":
            previous = alignment[i - 1]
            if any(
                doc[k].pos_ in ("NOUN", "PROPN")
                and (
                    doc[k].dep_ in ("npadvmod", "obl:tmod")
                    or (
                        doc[k].dep_ == "pobj"
                        and doc[k].head.pos_ == "ADP"
                        and doc[k].head.dep_ == "prep"
                        and doc[k].head.head.pos_ in ("VERB", "AUX")
                    )
                )
                for k in previous
            ):
                transfer = min(0.150, attention[i, 0])
                attention[i, 0] -= transfer
                attention[i, i - 1] += transfer

    return "bos_sink_with_adjunct_boundary", attention


def prog_L3H15(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Predict a dominant BOS attention sink with gradual positional dilution.
    Linguistic features modestly adjust sink strength; residual attention is diffuse.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_positional_dilution", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    pos_factors = {
        "DET": 0.65,
        "NOUN": 0.85,
        "PROPN": 0.80,
        "PRON": 1.45,
        "VERB": 1.30,
        "AUX": 1.10,
        "ADJ": 1.50,
        "ADV": 1.55,
        "ADP": 1.00,
        "CCONJ": 0.90,
        "SCONJ": 1.05,
        "PART": 1.30,
        "PUNCT": 0.95,
        "SPACE": 0.35,
    }

    for i in range(1, n):
        factor = 1.0
        if alignment[i]:
            word = doc[alignment[i][0]]
            factor = pos_factors.get(word.pos_, 1.0)

            if word.dep_ in ("poss", "det"):
                factor *= 0.85
            if word.ent_type_:
                factor *= 0.95
            if word.is_punct and i == n - 1:
                factor *= 0.65

        clean = tokens[i].replace("\u0120", " ").replace("\u010a", "\n")
        if clean.isspace():
            factor = 0.35

        dilution = 0.014 * (i ** 0.85) * factor
        sink_mass = 1.0 / (1.0 + dilution)

        positions = np.arange(1, i + 1, dtype=np.float64)
        residual = 0.75 + 0.25 * np.exp(-(i - positions) / 5.0)
        residual[-1] *= 1.15
        residual /= residual.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_positional_dilution", attention


def prog_L3H16(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with position decay; sentence-final punctuation releases some
    sink mass to preceding content tokens, especially in longer contexts.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_terminal_readout", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    # The examples consistently identify the initial special token as the sink.
    attention[0, 0] = 1.0

    for i in range(1, n):
        features = [doc[k] for k in alignment[i] if k < len(doc)]
        adjustment = 0.0

        if features:
            word = features[0]
            if word.pos_ in ("DET", "ADP", "SCONJ", "CCONJ"):
                adjustment += 0.035
            if word.dep_ in ("poss", "nmod:poss"):
                adjustment += 0.085
            if word.tag_ == "MD":
                adjustment += 0.12
            if word.tag_ in ("WDT", "WP", "WP$", "WRB"):
                adjustment += 0.07
            if word.pos_ == "PUNCT":
                adjustment -= 0.025
            if word.pos_ in ("NOUN", "PROPN") and word.dep_ in ("obj", "dobj", "pobj"):
                adjustment -= 0.035

        # Preserve the highly consistent first-token weight; lexical and
        # grammatical variation matters more once the prefix grows.
        modulation = 1.0 - np.exp(-(i - 1) / 3.0)
        sink_mass = (
            0.61
            + 0.36 * np.exp(-(i - 1) / 5.0)
            + modulation * adjustment
        )
        sink_mass = float(np.clip(sink_mass, 0.48, 0.98))

        positions = np.arange(1, i + 1, dtype=np.float64)
        residual = 0.7 + 0.3 * np.exp(-(i - positions) / 5.0)
        residual /= residual.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

        # Terminal readout only: preserve the diagonal and all other rows.
        if (
            i == n - 1
            and features
            and all(w.pos_ == "PUNCT" for w in features)
            and any(c in w.text for w in features for c in ".!?")
        ):
            targets = np.zeros(i, dtype=np.float64)
            for j in range(1, i):
                words = [doc[k] for k in alignment[j] if k < len(doc)]
                if words and words[0].pos_ in ("NOUN", "PROPN", "VERB", "ADJ", "ADV"):
                    weight = 1.5 if words[0].pos_ in ("NOUN", "PROPN") else 0.7
                    # Split-word pieces share a single lexical target's weight.
                    pieces = sum(words[0].i in alignment[t] for t in range(1, i))
                    targets[j] = weight * np.exp(-(i - j) / 18.0) / max(pieces, 1)

            if targets.sum() > 0.0:
                released = min(
                    0.10 + 0.008 * max(i - 22, 0),
                    0.44,
                    attention[i, 0],
                )
                attention[i, 0] -= released
                attention[i, :i] += released * targets / targets.sum()

    return "bos_sink_with_terminal_readout", attention


def prog_L3H17(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with mildly position-dependent strength.
    Residual attention is diffuse and weakly biased toward recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_diffuse_residual", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.915 - 0.0017 * min(i, 70)

        if alignment[i]:
            word = doc[alignment[i][0]]
            if word.pos_ in ("ADP", "ADJ", "PART"):
                sink_mass += 0.012
            elif word.pos_ == "PRON" and word.dep_ != "poss":
                sink_mass -= 0.025
            elif word.pos_ == "PUNCT":
                sink_mass -= 0.025

        sink_mass = np.clip(sink_mass, 0.74, 0.94)

        positions = np.arange(1, i + 1, dtype=np.float64)
        residual = 0.65 / i + 0.35 * np.exp(-(i - positions) / 5.0)
        residual /= residual.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_diffuse_residual", attention


def prog_L3H18(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, strongest near sentence starts, with weak local residual attention."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_residual", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    sentence_start = 1
    previous_spacy_index = -1

    for i in range(1, n):
        aligned = alignment[i]
        punctuation = False

        if aligned:
            word = doc[aligned[0]]
            if word.is_sent_start and word.i != previous_spacy_index:
                sentence_start = i
            previous_spacy_index = word.i
            punctuation = all(doc[k].is_punct for k in aligned)

        # A strong absolute-position sink, mildly refreshed at sentence boundaries.
        sink_mass = 0.82 + 0.17 * np.exp(-(i - 1) / 6.0)
        if sentence_start > 1:
            sink_mass += 0.09 * np.exp(-(i - sentence_start) / 3.0)
        if punctuation:
            sink_mass -= 0.10
        sink_mass = np.clip(sink_mass, 0.60, 0.995)

        # The examples constrain the sink much more than the residual;
        # use a conservative causal recency distribution for the latter.
        positions = np.arange(1, i + 1)
        residual = np.exp(-(i - positions) / 3.0)
        if i > 1:
            residual[-2] *= 1.5
        residual /= residual.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_local_residual", attention


def prog_L3H19(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Dominant beginning-of-sequence attention sink with weak local residual attention.
    Sink strength is highest near the start and remains strong throughout the sequence.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_local_residual", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        sink_weight = 0.93 + 0.05 * np.exp(-(i - 1) / 5.0)
        positions = np.arange(1, i + 1)
        residual = np.exp(-(i - positions) / 6.0)
        residual /= residual.sum()

        attention[i, 0] = sink_weight
        attention[i, 1:i + 1] = (1.0 - sink_weight) * residual

    return "bos_sink_with_local_residual", attention


def prog_L3H20(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with weak position- and POS-dependent leakage.
    Residual attention is distributed locally over the causal prefix.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_leakage", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        aligned = alignment[i]
        word = doc[aligned[-1]] if aligned else None

        # The sink remains dominant; leakage grows mildly with position.
        leakage = 0.018 + 0.00065 * i
        if word is not None:
            if word.pos_ in ("DET", "ADP", "AUX", "PART"):
                leakage -= 0.008
            elif word.pos_ == "VERB":
                leakage -= 0.005
            elif word.pos_ in ("NOUN", "PROPN", "PRON"):
                leakage += 0.012
            elif word.pos_ in ("ADJ", "ADV"):
                leakage += 0.006
            elif word.pos_ == "PUNCT":
                leakage += 0.018

        leakage = float(np.clip(leakage, 0.004, 0.14))
        attention[i, 0] = 1.0 - leakage

        # The examples do not identify a reliable non-BOS target:
        # use a conservative mixture of diffuse and recent attention.
        distances = i - np.arange(1, i + 1)
        residual = 0.25 / i + 0.75 * np.exp(-distances / 3.0)
        residual /= residual.sum()
        attention[i, 1:i + 1] = leakage * residual

    return "bos_sink_with_local_leakage", attention


def prog_L3H21(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, strongest early in the sequence and on salient content.
    Residual attention is diffuse and mildly biased toward recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_content_modulation", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    pos_baseline = {
        "NOUN": 0.74,
        "PROPN": 0.81,
        "ADJ": 0.66,
        "ADV": 0.59,
        "VERB": 0.58,
        "AUX": 0.65,
        "PRON": 0.53,
        "DET": 0.55,
        "ADP": 0.55,
        "PART": 0.52,
        "CCONJ": 0.51,
        "SCONJ": 0.51,
        "NUM": 0.68,
        "PUNCT": 0.43,
        "SPACE": 0.52,
    }

    for i in range(1, n):
        baseline = 0.57
        if alignment[i]:
            words = [doc[k] for k in alignment[i]]
            word = max(words, key=lambda w: not (w.is_space or w.is_punct))
            baseline = pos_baseline.get(word.pos_, baseline)

            if word.ent_type_:
                baseline += 0.025
            if word.dep_ in ("nsubj", "nsubjpass", "attr"):
                baseline += 0.025
            if word.dep_ in ("amod", "compound"):
                baseline += 0.025

        # Strong initial sink preference gradually approaches a POS-dependent floor.
        early_strength = 0.94 * np.exp(-(i - 1) / 2.8)
        sink_mass = baseline + (0.98 - baseline) * early_strength
        sink_mass = float(np.clip(sink_mass, 0.35, 0.985))

        # Reserve the remaining probability for causal, non-BOS context.
        distances = i - np.arange(1, i + 1, dtype=np.float64)
        local = np.exp(-distances / 4.0)
        local /= local.sum()
        residual = 0.6 * local + 0.4 / i

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_content_modulation", make_row_stochastic(attention)


def prog_L3H22(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with selective retrieval of prior content at anaphoric and clause boundaries.
    Transfer only BOS mass to earlier anchors, preserving baseline self-attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_selective_content_retrieval", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special_tokens = set(tokenizer.all_special_tokens)

    # Represent each linguistic anchor by its final model-token piece.
    word_ends = {}
    for ti, indices in enumerate(alignment):
        if ti > 0 and tokens[ti] not in special_tokens:
            for wi in indices:
                word_ends[wi] = ti

    attention[0, 0] = 1.0

    for i in range(1, n):
        aligned = alignment[i]
        word = None
        if aligned:
            word = doc[aligned[0]]
            for index in aligned:
                if not doc[index].is_space and not doc[index].is_punct:
                    word = doc[index]
                    break

        competition = 1.0
        if word is not None:
            if word.pos_ in ("NOUN", "PROPN"):
                competition = 0.82
            elif word.pos_ == "ADJ":
                competition = 0.72
            elif word.pos_ in ("VERB", "AUX"):
                competition = 1.12
            elif word.pos_ == "PRON":
                competition = 1.10
            elif word.pos_ == "PUNCT":
                competition = 1.35

        # Suppress linguistic corrections near the beginning, where the
        # nearly universal sink behavior is strongest.
        competition = 1.0 + (competition - 1.0) * (1.0 - np.exp(-i / 5.0))

        if tokens[i] in special_tokens:
            competition *= 0.75

        sink_mass = 1.0 / (1.0 + 0.026 * (i ** 0.8) * competition)
        attention[i, 0] = sink_mass

        positions = np.arange(1, i + 1, dtype=np.float64)
        residual = 0.65 + 0.35 * np.exp(-(i - positions) / 6.0)
        residual /= residual.sum()
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

        # Special case: reference-bearing queries and clause boundaries
        # retrieve completed content words rather than further diluting BOS.
        if word is not None and tokens[i] not in special_tokens:
            reference = word.pos_ == "PRON" or word.dep_ == "poss"
            boundary = word.is_punct
            coordination = word.pos_ == "CCONJ"
            clause_verb = (
                word.pos_ == "VERB" and word.dep_ in ("conj", "advcl")
            )
            after_nominal = (
                word.pos_ == "ADP"
                and word.i > 0
                and doc[word.i - 1].pos_ in ("NOUN", "PROPN")
            )

            if reference or boundary or coordination or clause_verb or after_nominal:
                anchors = np.zeros(i, dtype=np.float64)
                has_object = False
                for wi, j in word_ends.items():
                    if not (0 < j < i) or i - j > 32:
                        continue
                    candidate = doc[wi]
                    if candidate.i >= word.i:
                        continue
                    weight = 0.0
                    if candidate.pos_ in ("NOUN", "PROPN"):
                        is_object = candidate.dep_ in (
                            "dobj", "obj", "pobj", "iobj", "attr", "oprd"
                        )
                        weight = 3.0 if is_object else 1.6
                        has_object = has_object or is_object
                    elif candidate.pos_ == "VERB" and (reference or boundary):
                        weight = 0.7
                    elif candidate.pos_ == "ADJ" and boundary:
                        weight = 0.8
                    if boundary and i - j <= 2:
                        weight *= 2.5
                    anchors[j] = weight * np.exp(-(i - j) / 18.0)

                total = anchors.sum()
                if total > 0:
                    if boundary:
                        transfer = 0.30 + 0.002 * min(i, 60)
                    elif reference:
                        transfer = 0.20 + 0.08 * has_object
                    elif coordination:
                        transfer = 0.20
                    elif clause_verb:
                        transfer = 0.15
                    else:
                        transfer = 0.14
                    transfer *= 1.0 - np.exp(-max(i - 2, 0) / 3.0)
                    transfer = min(transfer, 0.75 * attention[i, 0])
                    attention[i, 0] -= transfer
                    attention[i, :i] += transfer * anchors / total

    return "bos_sink_with_selective_content_retrieval", make_row_stochastic(attention)


def prog_L3H23(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, strongest near the sequence start, with mild POS modulation.
    Unobserved residual attention is approximated by a causal recency distribution.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_pos_modulation", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)

    # The supplied observations support a sink, not a specific syntactic target.
    pos_prior = {
        "NOUN": 0.78,
        "PROPN": 0.81,
        "DET": 0.79,
        "ADJ": 0.71,
        "NUM": 0.76,
        "VERB": 0.64,
        "AUX": 0.54,
        "PRON": 0.59,
        "ADP": 0.68,
        "ADV": 0.60,
        "PART": 0.62,
        "CCONJ": 0.55,
        "SCONJ": 0.60,
        "PUNCT": 0.57,
        "SPACE": 0.62,
    }

    attention[0, 0] = 1.0
    for i in range(1, n):
        base = 0.68
        if aligned[i]:
            word = doc[aligned[i][0]]
            base = pos_prior.get(word.pos_, base)

        # A short prefix is particularly sink-dominated. Later rows retain
        # substantial sink mass rather than switching to another target.
        prefix_strength = np.exp(-(i - 1) / 4.0)
        sink_mass = base + (0.975 - base) * prefix_strength

        positions = np.arange(1, i + 1, dtype=np.float64)
        residual = np.exp(-(i - positions) / 5.0)
        residual /= residual.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_pos_modulation", attention


def prog_L4H0(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with an early-position boost and mild POS modulation.
    Residual attention is diffuse and weakly biased toward recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_position_decay", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        early = np.exp(-(i - 1) / 6.0)
        sink_mass = 0.735 + 0.249 * early

        # Content-bearing nominals retain slightly more sink attention.
        correction = 0.0
        if aligned[i]:
            word = doc[aligned[i][-1]]
            if word.pos_ in ("NOUN", "PROPN"):
                correction = 0.045
            elif word.pos_ in ("VERB", "ADJ", "ADV"):
                correction = -0.025
            elif word.pos_ == "PUNCT":
                correction = -0.015

        sink_mass = np.clip(
            sink_mass + (1.0 - early) * correction, 0.60, 0.99
        )

        # No demonstrated non-BOS target dominates: use a conservative mixture
        # of uniform causal attention and a short-range positional prior.
        distance = i - np.arange(1, i + 1, dtype=np.float64)
        residual = 0.65 / i + 0.35 * (
            np.exp(-distance / 4.0) / np.exp(-distance / 4.0).sum()
        )
        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_position_decay", make_row_stochastic(attention)


def prog_L4H1(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with selective release at sentence-ending punctuation and negated auxiliaries.
    Released mass goes to earlier context without changing the original self-attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_boundary_release", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        aligned = alignment[i]
        pos = doc[aligned[0]].pos_ if aligned else ""

        if pos == "PUNCT":
            sink_mass = 0.82
        elif pos in ("NOUN", "PROPN", "ADJ", "VERB", "AUX", "ADP"):
            sink_mass = 0.93
        elif pos in ("DET", "PRON", "ADV", "PART", "NUM"):
            sink_mass = 0.91
        elif pos in ("CCONJ", "SCONJ"):
            sink_mass = 0.88
        else:
            sink_mass = 0.90

        # The first ordinary token consistently assigns almost all mass to BOS.
        if i == 1:
            sink_mass = 0.97

        distances = i - np.arange(1, i + 1, dtype=np.float64)
        residual = np.exp(-distances / 3.0)
        residual /= residual.sum()
        residual = 0.75 * residual + 0.25 / i

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

        # Special cases release BOS mass only; the diagonal stays unchanged.
        if i > 1:
            surface = tokens[i].lstrip("ĠĊ").strip()
            boundary = (
                any(c in ".!?" for c in surface)
                and all(c in ".!?\"'“”‘’" for c in surface)
            )
            negated_aux = False
            if aligned and pos == "AUX":
                k = aligned[0]
                first_piece = k not in alignment[i - 1]
                negated_aux = first_piece and (
                    any(child.dep_ == "neg" for child in doc[k].children)
                    or (k + 1 < len(doc) and doc[k + 1].dep_ == "neg")
                )

            if boundary or negated_aux:
                if negated_aux:
                    target_sink = 0.25
                    diffuse_fraction = 0.80
                else:
                    quoted = any(c in "\"'“”‘’" for c in surface)
                    target_sink = 0.32 if "." in surface else (0.52 if quoted else 0.69)
                    diffuse_fraction = 0.55

                released = max(0.0, sink_mass - target_sink)
                prior = residual[:-1] / residual[:-1].sum()
                prior = (
                    (1.0 - diffuse_fraction) * prior
                    + diffuse_fraction / (i - 1)
                )
                attention[i, 0] -= released
                attention[i, 1:i] += released * prior

    return "bos_sink_boundary_release", make_row_stochastic(attention)


def prog_L4H2(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with a quoted-dialogue exception: later tokens retrieve the
    preceding utterance, especially its closing punctuation and pronouns.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_dialogue_retrieval", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        pos = {doc[k].pos_ for k in alignment[i]}
        sink_mass = 0.970
        if "PUNCT" in pos:
            sink_mass = 0.935
        elif pos.intersection({"CCONJ", "SCONJ", "PRON", "AUX"}):
            sink_mass = 0.955

        # Modest dilution over longer contexts, without losing the sink.
        sink_mass -= min(0.020, 0.00035 * i)
        attention[i, 0] = sink_mass

        positions = np.arange(1, i + 1)
        residual = np.exp(-(i - positions) / 4.0)
        residual /= residual.sum()
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    # Activate only after a completed quoted question. Later completed
    # utterances can replace it as the dialogue-retrieval anchor.
    utterances = []
    opening = None
    terminal = ""
    dialogue_active = False
    for j in range(1, n):
        for char in tokens[j]:
            if char in '"“”':
                if opening is None:
                    opening = j
                    terminal = ""
                else:
                    if terminal == "?":
                        dialogue_active = True
                    if dialogue_active and terminal and j > opening:
                        utterances.append((opening, j))
                    opening = None
                    terminal = ""
            elif opening is not None and char in "?!.":
                terminal = char

    if utterances:
        active = -1
        for i in range(1, n):
            while active + 1 < len(utterances) and utterances[active + 1][1] < i:
                active += 1
            if active < 0:
                continue

            start, end = utterances[active]
            pos = {doc[k].pos_ for k in alignment[i]}
            clean = tokens[i].lstrip("\u0120").strip()

            extra = 0.075
            if "VERB" in pos:
                extra = 0.32
            elif "PUNCT" in pos:
                extra = 0.25
            elif "PRON" in pos:
                extra = 0.23
            elif pos.intersection({"DET", "PROPN"}) and i - end <= 4:
                extra = 0.27
            elif "ADP" in pos and i - end <= 6:
                extra = 0.24
            elif not clean:
                extra = 0.13

            if clean and all(c in '"“”' for c in clean):
                extra = 0.38

            extra *= np.exp(-max(0, i - end - 6) / 32.0)
            extra *= 1.15 if end - start <= 5 else 1.0
            extra = min(extra, attention[i, 0] - 0.30)

            targets = np.arange(start + 1, end + 1)
            weights = np.ones(len(targets), dtype=np.float64)
            for offset, j in enumerate(targets):
                target_pos = {doc[k].pos_ for k in alignment[j]}
                if "PRON" in target_pos:
                    weights[offset] = 3.0
                elif "VERB" in target_pos:
                    weights[offset] = 2.0
            weights[-1] = 5.0
            weights /= weights.sum()

            # Transfer only BOS mass; preserve the original diagonal and
            # every original local-residual contribution.
            attention[i, 0] -= extra
            attention[i, targets] += extra * weights

    return "bos_sink_with_dialogue_retrieval", attention


def prog_L4H3(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """A dominant BOS attention sink, strongest near the start and on salient content.
    Residual attention mixes local context with preceding syntactic governors.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_syntactic_residual", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for ti, word_ids in enumerate(alignment):
        for wi in word_ids:
            inverse[wi].append(ti)

    attention[0, 0] = 1.0
    for i in range(1, n):
        word = doc[alignment[i][-1]] if alignment[i] else None
        early = np.exp(-(i - 1) / 4.5)
        sink = 0.70 + 0.265 * early

        governor = None
        distance = 0
        if word is not None:
            candidates = [
                j for j in inverse[word.head.i]
                if 0 < j < i and j not in inverse[word.i]
            ]
            if candidates:
                governor = candidates[-1]
                distance = i - governor

            correction = 0.0
            if word.pos_ == "PROPN":
                correction += 0.14
            elif word.pos_ == "NOUN":
                correction += 0.055
            elif word.pos_ in ("VERB", "ADJ", "ADV"):
                correction += 0.045
            elif word.pos_ in ("PRON", "AUX"):
                correction -= 0.04
            elif word.pos_ in ("ADP", "PART"):
                correction -= 0.15
            elif word.pos_ == "PUNCT":
                correction -= 0.10

            if word.dep_ in ("nsubj", "nsubjpass", "ROOT"):
                correction += 0.035
            if word.is_sent_start:
                correction += 0.12
            sink += (1.0 - early) * correction

            if word.pos_ == "ADP" and governor is not None:
                sink -= 0.22 * (1.0 - np.exp(-distance / 8.0))

        if tokens[i].isspace() or not tokens[i].strip("Ġ▁"):
            sink = max(sink, 0.86)

        sink = float(np.clip(sink, 0.25, 0.98))
        if i == 1:
            attention[i, 0] = sink
            attention[i, i] = 1.0 - sink
            continue

        positions = np.arange(1, i + 1)
        residual = np.exp(-(i - positions) / 3.5)
        residual /= residual.sum()

        if governor is not None:
            syntax_share = 0.40
            if word.pos_ == "ADP":
                syntax_share = 0.85
            residual *= 1.0 - syntax_share
            residual[governor - 1] += syntax_share

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual

    return "bos_sink_with_syntactic_residual", make_row_stochastic(attention)


def prog_L4H4(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with weak POS modulation; quoted dialogue additionally routes
    sink mass to the current token and its immediate causal neighborhood.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_dialogue_locality", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    # Leave non-dialogue inputs and the pre-dialogue prefix unchanged.
    quote_marks = ('"', '“', '”')
    first_quote = next(
        (j for j, token in enumerate(tokens)
         if any(mark in token for mark in quote_marks)),
        n,
    )

    for i in range(1, n):
        sink_mass = 0.745 + 0.065 * np.exp(-(i - 1) / 7.0)
        aligned = alignment[i]
        if aligned:
            word = doc[aligned[-1]]
            if word.pos_ in ("NOUN", "PROPN", "VERB", "ADJ"):
                sink_mass += 0.035
            elif word.pos_ in ("CCONJ", "SCONJ", "PART"):
                sink_mass -= 0.050
            elif word.pos_ in ("PRON", "AUX"):
                sink_mass -= 0.025
            elif word.pos_ == "PUNCT":
                sink_mass -= 0.110
            elif word.pos_ == "SPACE":
                sink_mass -= 0.045

        if i == 1:
            sink_mass = 0.840

        sink_mass = float(np.clip(sink_mass, 0.55, 0.90))
        positions = np.arange(1, i + 1)
        residual = 0.7 + 0.3 * np.exp(-(i - positions) / 12.0)

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * residual / residual.sum()
        )

        if i >= first_quote and i > 1:
            pos = doc[aligned[-1]].pos_ if aligned else ""
            transfer = 0.12
            if pos in ("PRON", "DET", "ADV", "SPACE"):
                transfer = 0.16
            elif pos == "PUNCT":
                transfer = 0.17

            has_quote = any(mark in tokens[i] for mark in quote_marks)
            opens_quote = has_quote and not any(
                mark in tokens[i] for mark in (".", "!", "?")
            )
            comma_before_quote = (
                "," in tokens[i]
                and i + 1 < n
                and any(mark in tokens[i + 1] for mark in quote_marks)
            )
            if opens_quote or comma_before_quote:
                transfer = 0.28

            transfer = min(transfer, attention[i, 0])
            attention[i, 0] -= transfer
            attention[i, i] += 0.80 * transfer
            local = np.exp(-(i - positions) / 2.0)
            attention[i, 1:i + 1] += (
                0.20 * transfer * local / local.sum()
            )

    return "bos_sink_with_dialogue_locality", attention


def prog_L4H5(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with gradually weakening positional dominance.
    Linguistic features modestly modulate sink strength; residual attention is diffuse and local.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_positional_decay", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    pos_adjustment = {
        "DET": 0.035,
        "PRON": 0.040,
        "PROPN": 0.075,
        "NOUN": -0.015,
        "VERB": -0.025,
        "AUX": -0.060,
        "ADJ": -0.040,
        "ADV": -0.020,
        "ADP": -0.035,
        "CCONJ": -0.035,
        "SCONJ": 0.010,
        "PART": 0.015,
        "PUNCT": -0.045,
        "SPACE": 0.055,
    }

    attention[0, 0] = 1.0
    for i in range(1, n):
        sink_mass = 0.60 + 0.35 * np.exp(-0.065 * (i - 1))

        if alignment[i]:
            word = doc[alignment[i][0]]
            correction = pos_adjustment.get(word.pos_, 0.0)

            if word.dep_ in ("nsubj", "nsubjpass", "csubj"):
                correction += 0.025
            if word.ent_type_:
                correction += 0.020

            # Keep the first content token strongly anchored regardless of POS.
            sink_mass += correction * (1.0 - np.exp(-(i - 1) / 2.0))
        elif tokens[i].isspace() or tokens[i].strip("Ġ▁") == "":
            sink_mass += 0.045

        sink_mass = float(np.clip(sink_mass, 0.48, 0.975))

        # The examples identify the sink, but do not resolve residual targets.
        # Use a conservative mixture of diffuse causal mass and recency.
        distance = i - np.arange(1, i + 1, dtype=np.float64)
        residual = 0.55 / i + 0.45 * (
            np.exp(-distance / 4.0) / np.exp(-distance / 4.0).sum()
        )
        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_positional_decay", make_row_stochastic(attention)


def prog_L4H6(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with gradual positional dilution and weak POS modulation.
    Non-sink attention is diffuse, with a mild recency preference.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_positional_dilution", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special_tokens = tokenizer.all_special_tokens

    attention[0, 0] = 1.0

    for i in range(1, n):
        aligned = alignment[i]
        word = None
        if aligned:
            word = doc[aligned[0]]
            for k in aligned:
                if not doc[k].is_space:
                    word = doc[k]
                    break

        # The sink remains dominant, but competes with an expanding prefix.
        competition = 0.055 * float(i) ** 0.65

        if word is not None:
            if word.pos_ in ("DET", "AUX", "ADP", "PART", "SCONJ"):
                competition *= 0.82
            elif word.pos_ in ("NOUN", "PROPN"):
                competition *= 1.20
            elif word.pos_ == "PRON":
                competition *= 1.08

            if word.is_punct:
                competition *= 0.90

            # Continuation pieces have a somewhat stronger local alternative.
            if i > 1 and any(k in alignment[i - 1] for k in aligned):
                competition *= 1.25

        if tokens[i] in special_tokens or tokens[i].isspace():
            competition *= 0.85

        sink_mass = 1.0 / (1.0 + competition)
        if i == 1:
            sink_mass = 0.96

        distances = i - np.arange(1, i + 1, dtype=np.float64)
        residual = (1.0 + distances) ** -0.30
        residual /= residual.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_positional_dilution", make_row_stochastic(attention)


def prog_L4H7(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with a strong early-position bias and mild POS modulation.
    Remaining attention follows a diffuse causal recency prior.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_position_decay", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    # Token zero is the observed sink (normally the tokenizer's BOS token).
    attention[0, 0] = 1.0

    pos_adjustments = {
        "VERB": 0.025,
        "AUX": 0.020,
        "ADP": 0.010,
        "DET": 0.010,
        "PROPN": 0.015,
        "NOUN": -0.020,
        "ADJ": -0.035,
        "ADV": -0.010,
        "PRON": 0.005,
        "PUNCT": -0.010,
    }

    for i in range(1, n):
        sink_mass = 0.715 + 0.185 * np.exp(-(i - 1) / 3.0)

        if alignment[i]:
            word = doc[alignment[i][-1]]
            sink_mass += pos_adjustments.get(word.pos_, 0.0)

        # With only BOS and the initial text token available, sink attention
        # is particularly stable and strong.
        if i == 1:
            sink_mass = 0.900

        sink_mass = float(np.clip(sink_mass, 0.60, 0.94))
        attention[i, 0] = sink_mass

        positions = np.arange(1, i + 1, dtype=np.float64)
        recency = np.exp(-(i - positions) / 4.0)
        recency /= recency.sum()
        residual = 0.65 * recency + 0.35 / i
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_position_decay", make_row_stochastic(attention)


def prog_L4H8(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with mild decay; quoted dialogue activates a stronger
    diagonal and a small previous-token component.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_dialogue_diagonal", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0
    dialogue_context = False

    for i in range(1, n):
        sink_mass = 0.89 - 0.09 * (1.0 - np.exp(-(i - 1) / 24.0))

        if alignment[i]:
            word = doc[alignment[i][0]]
            if word.pos_ in ("DET", "ADP", "PART"):
                sink_mass += 0.02
            elif word.pos_ in ("AUX", "CCONJ", "SCONJ"):
                sink_mass += 0.01
            elif word.pos_ in ("NOUN", "PROPN", "VERB"):
                sink_mass -= 0.01
            elif word.is_punct:
                sink_mass -= 0.015

        sink_mass = float(np.clip(sink_mass, 0.74, 0.94))
        attention[i, 0] = sink_mass

        positions = np.arange(1, i + 1, dtype=np.float64)
        residual = 0.6 + 0.4 * np.exp(-(i - positions) / 6.0)
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * residual / residual.sum()
        )

        # Only quoted-dialogue prefixes activate the additional component.
        if any(mark in tokens[i] for mark in ('"', '“', '”', '«', '»')):
            dialogue_context = True

        if dialogue_context:
            self_transfer = 0.135
            previous_transfer = 0.015 if i > 1 else 0.0
            attention[i, 0] -= self_transfer + previous_transfer
            attention[i, i] += self_transfer
            if i > 1:
                attention[i, i - 1] += previous_transfer

    return "bos_sink_with_dialogue_diagonal", attention


def prog_L4H9(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with an adjacent-token channel at local linguistic transitions.
    Transfer only BOS mass to the predecessor, preserving self-attention and other edges.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_adjacent_transition", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    pos_prior = {
        "VERB": 0.815,
        "AUX": 0.815,
        "NOUN": 0.810,
        "PROPN": 0.815,
        "ADJ": 0.805,
        "ADV": 0.770,
        "ADP": 0.775,
        "DET": 0.745,
        "PRON": 0.745,
        "CCONJ": 0.790,
        "SCONJ": 0.755,
        "PART": 0.780,
        "NUM": 0.790,
        "PUNCT": 0.855,
        "SPACE": 0.855,
    }

    for i in range(1, n):
        if i == 1:
            sink_mass = 0.965
        else:
            aligned = alignment[i]
            if aligned:
                word = doc[aligned[-1]]
                sink_mass = pos_prior.get(word.pos_, 0.795)
                if word.dep_ == "ROOT":
                    sink_mass += 0.025
                if word.dep_ in ("poss", "nmod", "pobj"):
                    sink_mass += 0.010
            else:
                clean = tokens[i].replace("Ġ", " ").replace("Ċ", "\n")
                if not clean.strip():
                    sink_mass = 0.855
                elif all(not c.isalnum() for c in clean.strip()):
                    sink_mass = 0.855
                else:
                    sink_mass = 0.795

            if i == 2:
                sink_mass += 0.025
            sink_mass = float(np.clip(sink_mass, 0.70, 0.91))

        attention[i, 0] = sink_mass
        distances = i - np.arange(1, i + 1, dtype=np.float64)
        residual = 0.55 / i + 0.45 * (
            np.exp(-distances / 4.0) /
            np.exp(-distances / 4.0).sum()
        )
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

        # Only adjacent aligned words or pieces of the same word qualify.
        if i >= 2 and alignment[i] and alignment[i - 1]:
            current = doc[alignment[i][-1]]
            previous = doc[alignment[i - 1][-1]]
            if (
                current.pos_ != "SPACE"
                and previous.pos_ != "SPACE"
                and current.i in (previous.i, previous.i + 1)
            ):
                target = None
                if current.i == previous.i:
                    target = 0.15
                elif current.pos_ in ("DET", "PRON") and previous.pos_ in (
                    "VERB", "AUX", "ADP", "SCONJ", "CCONJ"
                ):
                    target = 0.23
                elif current.pos_ in ("ADP", "SCONJ", "PART") and previous.pos_ in (
                    "VERB", "AUX", "NOUN", "PROPN", "PRON", "ADJ", "ADV"
                ):
                    target = 0.19
                elif current.pos_ in ("VERB", "AUX") and previous.pos_ in (
                    "NOUN", "PROPN", "PRON", "VERB", "AUX", "PART", "ADV"
                ):
                    target = 0.18
                elif (
                    current.head.i == previous.i
                    or previous.head.i == current.i
                    or (current.pos_ == "ADJ" and previous.pos_ == "ADJ")
                ):
                    target = 0.15
                elif current.pos_ in ("PUNCT", "CCONJ") and previous.pos_ != "PUNCT":
                    target = 0.14

                if target is not None:
                    transfer = min(
                        max(0.0, target - attention[i, i - 1]),
                        max(0.0, attention[i, 0] - 0.60),
                    )
                    attention[i, 0] -= transfer
                    attention[i, i - 1] += transfer

    return "bos_sink_with_adjacent_transition", make_row_stochastic(attention)


def prog_L4H10(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Predict a dominant beginning-of-sequence attention sink.
    Sink strength decays mildly with position; residual attention is diffuse and recent.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_weak_recency", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink = 0.77 + 0.19 * np.exp(-(i - 1) / 3.6)

        # Linguistic corrections remain small: the examples overwhelmingly
        # support a positional sink rather than a syntactic routing rule.
        if alignment[i]:
            word = doc[alignment[i][-1]]
            correction = 0.0
            if word.pos_ in ("NOUN", "PROPN", "AUX"):
                correction += 0.02
            elif word.pos_ in ("ADJ", "ADV"):
                correction -= 0.015
            if word.is_punct:
                correction -= 0.015
            sink += (1.0 - np.exp(-(i - 1) / 4.0)) * correction

        sink = np.clip(sink, 0.70, 0.97)
        attention[i, 0] = sink

        positions = np.arange(1, i + 1)
        distances = i - positions
        residual = 0.35 + np.exp(-distances / 4.0)
        attention[i, 1:i + 1] = (1.0 - sink) * residual / residual.sum()

    return "bos_sink_with_weak_recency", attention


def prog_L4H11(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with POS gating; closing punctuation additionally reads the
    preceding word, especially at adverbial phrase boundaries.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_punctuation_boundary", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    sink_by_pos = {
        "DET": 0.935,
        "ADJ": 0.935,
        "NOUN": 0.910,
        "PROPN": 0.925,
        "PRON": 0.910,
        "ADP": 0.895,
        "PART": 0.900,
        "VERB": 0.885,
        "ADV": 0.865,
        "AUX": 0.840,
        "CCONJ": 0.825,
        "SCONJ": 0.850,
        "PUNCT": 0.835,
        "SPACE": 0.900,
    }

    for i in range(1, n):
        aligned = alignment[i]
        if aligned:
            sink = sum(
                sink_by_pos.get(doc[k].pos_, 0.900) for k in aligned
            ) / len(aligned)
        else:
            sink = 0.900

        # The first ordinary token has especially strong sink attention.
        if i == 1:
            sink = 0.955

        attention[i, 0] = sink

        positions = np.arange(1, i + 1, dtype=np.float64)
        residual = 0.5 / i + 0.5 * (
            np.exp(-(i - positions) / 4.0)
            / np.exp(-(i - positions) / 4.0).sum()
        )
        attention[i, 1:i + 1] = (1.0 - sink) * residual

        # Transfer only BOS mass: preserve self-attention and every other edge.
        if (
            i > 1
            and aligned
            and all(doc[k].pos_ == "PUNCT" for k in aligned)
            and alignment[i - 1]
        ):
            previous = alignment[i - 1]
            word = doc[max(previous)]
            closes_phrase = any(
                char in doc[k].text
                for k in aligned
                for char in ",.;:!?"
            )
            if closes_phrase and word.pos_ in {
                "NOUN", "PROPN", "PRON", "VERB", "ADJ", "ADV", "ADP", "PART"
            }:
                target = 0.11
                if word.pos_ == "PRON":
                    target = 0.40
                elif word.pos_ == "ADV":
                    is_comma = any("," in doc[k].text for k in aligned)
                    target = 0.22 if is_comma else 0.35
                    if is_comma and word.i > 0 and doc[word.i - 1].pos_ == "ADV":
                        target = 0.65
                elif word.pos_ in {"ADP", "PART"}:
                    target = 0.20
                elif word.pos_ in {"VERB", "ADJ"}:
                    target = 0.16
                elif any(
                    char in doc[k].text
                    for k in aligned
                    for char in "\"”"
                ):
                    target = 0.30

                transfer = min(
                    attention[i, 0],
                    max(0.0, target - attention[i, i - 1]),
                )
                attention[i, 0] -= transfer
                attention[i, i - 1] += transfer

    return "bos_sink_punctuation_boundary", make_row_stochastic(attention)


def prog_L4H12(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, strongest at boundaries and clause scaffolding.
    Content words retain more diffuse, recency-biased causal attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_linguistic_gating", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special_tokens = tokenizer.all_special_tokens

    base_by_pos = {
        "NOUN": 0.62,
        "PROPN": 0.66,
        "ADJ": 0.70,
        "ADV": 0.79,
        "VERB": 0.83,
        "AUX": 0.88,
        "PRON": 0.81,
        "DET": 0.73,
        "ADP": 0.73,
        "PART": 0.76,
        "CCONJ": 0.89,
        "SCONJ": 0.89,
        "INTJ": 0.75,
        "PUNCT": 0.92,
        "SPACE": 0.94,
    }

    attention[0, 0] = 1.0
    in_quote = False

    for i in range(1, n):
        text = tokens[i].replace("Ġ", " ").replace("Ċ", "\n").strip()
        aligned = alignment[i]
        word = doc[aligned[0]] if aligned else None
        pos = word.pos_ if word is not None else ""
        dep = word.dep_ if word is not None else ""

        base = base_by_pos.get(pos, 0.76)
        if dep in ("dobj", "obj", "pobj", "attr"):
            base -= 0.06
        elif dep in ("ROOT", "conj") and pos == "VERB":
            base += 0.02
        if word is not None and word.tag_ in ("VBG", "VBN"):
            base -= 0.12

        early = np.exp(-(i - 1) / 5.0)
        sink = base + (0.985 - base) * early

        if in_quote:
            sink -= 0.10 * (1.0 - early)

        if text and all(c in ".,;:!?" for c in text):
            sink = 0.92 + 0.05 * early
        if not text or tokens[i] in special_tokens:
            sink = 0.94

        has_quote = any(c in text for c in "\"“”")
        if has_quote:
            sink = max(sink, 0.84 if not in_quote else 0.76)
            if sum(c in "\"“”" for c in text) % 2:
                in_quote = not in_quote

        if i == 1:
            sink = 0.983

        sink = float(np.clip(sink, 0.40, 0.995))
        attention[i, 0] = sink

        # The examples constrain the sink far more than the residual targets.
        # Use a broad causal background rather than inventing a sharp relation.
        distances = i - np.arange(1, i + 1)
        residual = 0.5 + np.exp(-distances / 7.0)
        attention[i, 1:i + 1] = (1.0 - sink) * residual / residual.sum()

    return "bos_sink_with_linguistic_gating", attention


def prog_L4H13(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with linguistic gating; clause boundaries release BOS mass
    to the preceding phrase while preserving the original self-attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_boundary_release", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        words = [doc[k] for k in alignment[i]]
        pos = words[-1].pos_ if words else ""
        dep = words[-1].dep_ if words else ""

        sink = 0.88
        if pos in ("ADJ", "ADV"):
            sink = 0.935
        elif pos in ("PRON", "DET", "AUX", "PART"):
            sink = 0.905
        elif pos in ("NOUN", "PROPN"):
            sink = 0.85
        elif pos in ("VERB", "ADP"):
            sink = 0.885
        elif pos in ("CCONJ", "SCONJ"):
            sink = 0.84
        elif pos == "PUNCT":
            sink = 0.76

        if dep in ("amod", "advmod", "poss"):
            sink = max(sink, 0.935)

        # Early queries have particularly little incentive to leave the sink.
        early_strength = np.exp(-(i - 1) / 2.0)
        sink += (0.98 - sink) * early_strength

        # Preserve the original residual distribution exactly.
        positions = np.arange(1, i + 1, dtype=np.float64)
        residual = 0.25 / i + 0.75 * np.exp(-(i - positions) / 3.0)
        residual /= residual.sum()

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual

        # Only clause/phrase boundaries release additional BOS mass.
        boundary_punct = (
            pos == "PUNCT"
            and words[-1].text in (".", "!", "?", ",", ";", ":")
        )
        if i >= 5 and (pos == "CCONJ" or boundary_punct):
            targets = []
            weights = []
            for j in range(max(1, i - 8), i):
                previous = [doc[k] for k in alignment[j]]
                if not previous or previous[-1].pos_ == "PUNCT":
                    continue
                weight = 1.0
                if previous[-1].pos_ == "DET" or previous[-1].dep_ == "poss":
                    weight = 1.4
                if j == i - 1 and (
                    pos == "CCONJ" or words[-1].text in (",", ";", ":")
                ):
                    weight *= 1.7
                targets.append(j)
                weights.append(weight)

            if targets:
                if pos == "CCONJ":
                    boundary_sink = max(0.30, 0.82 - 0.042 * i)
                elif words[-1].text in (".", "!", "?"):
                    boundary_sink = 0.34
                else:
                    boundary_sink = 0.40

                released = max(0.0, attention[i, 0] - boundary_sink)
                distribution = np.asarray(weights, dtype=np.float64)
                distribution /= distribution.sum()
                attention[i, 0] -= released
                attention[i, targets] += released * distribution

    return "bos_sink_with_boundary_release", attention


def prog_L4H14(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with a repeated-token retrieval exception in multi-turn dialogue.
    Move only sink mass to matching earlier tokens; preserve the original residual.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_diffuse_residual", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        attention[i, 0] = 0.98
        attention[i, 1:i + 1] = 0.02 / i

    # Repeated dialogue frames are the main exception to the sink behavior.
    if sentence.count('"') >= 4 or sentence.count("“") >= 2:
        doc = spacy_parse(sentence)
        aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
        pos = [doc[sids[0]].pos_ if sids else "" for sids in aligned]
        clean = [t.replace("Ġ", " ").replace("Ċ", "\n").strip()
                 for t in tokens]
        targets = {}

        for i in range(1, n):
            best_j, best_score = -1, 0.0
            mass = 0.0

            # Punctuation and standalone whitespace repeat dialogue framing.
            if not clean[i] or pos[i] == "PUNCT":
                for j in range(1, i):
                    if clean[i] == clean[j]:
                        best_j = j
                if best_j >= 0:
                    if not clean[i]:
                        mass = 0.30
                    elif clean[i] in ('"', "“"):
                        mass = 0.40
                    elif clean[i] == ",":
                        mass = 0.10
                    else:
                        mass = 0.06
            else:
                for j in range(1, i):
                    if not pos[i] or pos[i] != pos[j]:
                        continue
                    score = embedding_similarity(tokens, i, j, tokenizer)
                    if score >= 0.72 and score >= best_score:
                        best_j, best_score = j, score

                if best_j >= 0:
                    if pos[i] in ("NOUN", "PROPN", "VERB"):
                        mass = 0.38
                    elif pos[i] == "PRON":
                        mass = 0.30
                    elif pos[i] in ("DET", "ADP", "AUX"):
                        mass = 0.12
                    else:
                        mass = 0.15

                    # Consecutive retrievals indicate a repeated phrase.
                    if targets.get(i - 1) == best_j - 1:
                        mass = min(0.72, mass + 0.32)
                    mass *= min(1.0, (best_score - 0.60) / 0.30)

            if best_j >= 0 and mass > 0.0:
                attention[i, 0] -= mass
                attention[i, best_j] += mass
                targets[i] = best_j

        return "bos_sink_with_dialogue_retrieval", attention

    return "bos_sink_with_diffuse_residual", attention


def prog_L4H15(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention-sink head with gradually declining sink mass.
    Linguistic features mildly modulate an otherwise diffuse causal remainder.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_position_decay", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        position = i - 1
        sink_mass = (
            0.975
            - 0.065 * np.log1p(position / 3.0)
            - 0.0018 * position
        )

        if i > 1 and alignment[i]:
            word = doc[alignment[i][0]]
            if word.pos_ in ("DET", "PRON", "AUX", "PART", "SCONJ"):
                sink_mass += 0.025
            elif word.pos_ in ("NOUN", "PROPN"):
                sink_mass -= 0.015
            elif word.pos_ == "VERB":
                sink_mass -= 0.025

            if word.dep_ in ("poss", "mark"):
                sink_mass += 0.015

        # Standalone whitespace also behaves like a strong sink query.
        clean = tokens[i].replace("Ġ", " ").replace("Ċ", "\n")
        if not clean.strip():
            sink_mass += 0.065

        sink_mass = np.clip(sink_mass, 0.35, 0.985)
        attention[i, 0] = sink_mass

        # The supplied edges do not identify a specific non-BOS target:
        # use a broad residual distribution with only a mild recency bias.
        distances = i - np.arange(1, i + 1)
        residual = 0.65 + 0.35 * np.exp(-distances / 12.0)
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * residual / residual.sum()
        )

    return "bos_sink_with_position_decay", attention


def prog_L4H16(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with a small, recency-biased causal background.
    Non-BOS competition gradually reduces sink mass as context grows.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    for i in range(n):
        attention[i, 0] = 1.0
        if i > 0:
            distances = i - np.arange(1, i + 1)
            attention[i, 1:i + 1] = (
                0.0007 + 0.0023 * np.exp(-distances / 3.0)
            )

    return "bos_sink_with_weak_recency", make_row_stochastic(attention)


def prog_L4H17(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Predict a dominant first-token/BOS attention sink, strongest near the start.
    Linguistic features weakly gate sink strength; residual attention is diffuse and local.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_linguistic_gating", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        # Strong initial sink, with a modest decline as context accumulates.
        initial_strength = np.exp(-(i - 1) / 5.0)
        sink = 0.79 + 0.16 * initial_strength
        correction = 0.0

        sids = alignment[i]
        if sids:
            word = doc[sids[0]]
            pos = word.pos_
            dep = word.dep_

            if pos in ("SCONJ", "ADV"):
                correction += 0.075
            elif pos in ("AUX", "PRON", "CCONJ"):
                correction += 0.035
            elif pos in ("NOUN", "PROPN"):
                correction -= 0.055
            elif pos in ("ADJ", "VERB"):
                correction -= 0.025

            if dep in ("mark", "cc", "advmod"):
                correction += 0.025
            if dep in ("dobj", "obj", "pobj", "attr"):
                correction -= 0.035
            if word.is_punct:
                correction += 0.015
        elif tokens[i].isspace() or not tokens[i].strip("ĠĊ \t\r\n"):
            correction += 0.025

        # POS has less influence on the unusually stable opening-token sink.
        sink += correction * (1.0 - 0.8 * initial_strength)
        sink = float(np.clip(sink, 0.55, 0.985))
        attention[i, 0] = sink

        # Unobserved non-sink edges receive a conservative, diffuse causal prior.
        distances = i - np.arange(1, i + 1)
        residual = 0.5 + np.exp(-distances / 8.0)
        attention[i, 1:i + 1] = (1.0 - sink) * residual / residual.sum()

    return "bos_sink_with_linguistic_gating", attention


def prog_L4H18(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, strongest for names, nominal content, and boundaries.
    Approximate the unobserved residual with a weak causal recency distribution.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_lexical_gating", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    has_bos = tokens[0] == tokenizer.bos_token
    first_content = 1 if has_bos else 0
    attention[0, 0] = 1.0

    for i in range(1, n):
        clean = tokens[i].replace("\u0120", " ").replace("\u010a", "\n")
        words = [
            doc[k] for k in aligned[i]
            if 0 <= k < len(doc) and not doc[k].is_space
        ]
        word = max(
            words,
            key=lambda w: (
                w.pos_ == "PROPN",
                w.pos_ == "NOUN",
                not w.is_punct,
            ),
            default=None,
        )

        sink_mass = 0.59

        if word is not None:
            pos = word.pos_
            if pos == "PROPN":
                sink_mass = 0.91
            elif pos == "NOUN":
                sink_mass = 0.83
            elif pos == "ADJ":
                sink_mass = 0.75 if word.dep_ == "amod" else 0.60
            elif pos in ("VERB", "AUX"):
                sink_mass = 0.57
                if i <= first_content + 2:
                    sink_mass = 0.77
            elif pos == "DET":
                sink_mass = 0.64
                if word.head.pos_ in ("NOUN", "PROPN"):
                    sink_mass += 0.08
            elif pos == "PRON":
                sink_mass = 0.56
            elif pos == "ADV":
                sink_mass = 0.58
            elif pos in ("ADP", "PART"):
                sink_mass = 0.54
            elif pos in ("CCONJ", "SCONJ"):
                sink_mass = 0.60
            elif pos == "NUM":
                sink_mass = 0.70
            elif pos == "PUNCT":
                sink_mass = 0.69

            if word.ent_type_ and pos in ("NOUN", "PROPN"):
                sink_mass += 0.02

            # Nominal phrase modifiers often share the strong sink tendency.
            if word.dep_ in ("amod", "poss") and word.head.pos_ == "NOUN":
                sink_mass += 0.025

            if word.is_sent_start:
                sink_mass = max(sink_mass, 0.82)

        if clean and clean.isspace():
            sink_mass = 0.91
        elif clean.strip() and all(
            not c.isalnum() for c in clean.strip()
        ):
            sink_mass = max(sink_mass, 0.70)
            if any(c in ".!?" for c in clean):
                sink_mass = max(sink_mass, 0.78)

        if i == first_content and has_bos:
            sink_mass = 0.96
        elif i > 30:
            sink_mass += 0.025

        sink_mass = float(np.clip(sink_mass, 0.45, 0.97))

        # The examples constrain the sink much more than non-sink destinations.
        distances = i - np.arange(1, i + 1, dtype=np.float64)
        residual = 0.65 / i + 0.35 * (
            np.exp(-distances / 5.0)
            / np.exp(-distances / 5.0).sum()
        )
        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_lexical_gating", make_row_stochastic(attention)


def prog_L4H19(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with a sentence-final punctuation exception that pools clause structure.
    The exception transfers only BOS mass, preserving the original self-attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_terminal_pooling", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    pos_prior = {
        "NOUN": 0.965,
        "PROPN": 0.965,
        "ADJ": 0.935,
        "NUM": 0.935,
        "VERB": 0.925,
        "AUX": 0.915,
        "DET": 0.925,
        "PRON": 0.880,
        "ADP": 0.885,
        "PART": 0.855,
        "ADV": 0.850,
        "CCONJ": 0.770,
        "SCONJ": 0.790,
        "PUNCT": 0.755,
        "SPACE": 0.820,
    }

    for i in range(1, n):
        mapped = alignment[i]
        word = doc[mapped[0]] if mapped else None

        if word is None:
            sink = 0.840
            if tokens[i].isspace():
                sink = 0.810
        else:
            sink = pos_prior.get(word.pos_, 0.860)
            if word.dep_ in ("nsubj", "nsubjpass", "dobj", "pobj"):
                sink += 0.008
            if word.ent_type_:
                sink += 0.006

        # Early queries have fewer competing keys; later ones leak modestly.
        sink -= 0.045 * (1.0 - np.exp(-(i - 1) / 20.0))
        if i == 1:
            sink = 0.967
        sink = float(np.clip(sink, 0.60, 0.98))

        # Preserve the original residual distribution and self-attention.
        positions = np.arange(1, i + 1)
        residual = (
            0.65 * np.exp(-(i - positions) / 3.0)
            + 0.35 / np.sqrt(i)
        )
        residual /= residual.sum()

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual

        # Sentence-closing punctuation pools earlier clause material rather
        # than retaining the ordinary punctuation-level BOS sink.
        if (
            i >= 6
            and word is not None
            and word.pos_ == "PUNCT"
            and word.is_sent_end
            and any(c in word.text for c in ".!?")
        ):
            pooling = np.zeros(i - 1, dtype=np.float64)
            for j in range(1, i):
                key_mapped = alignment[j]
                if not key_mapped:
                    continue
                key = doc[key_mapped[0]]
                if key.i >= word.i or key.is_space:
                    continue
                weight = {
                    "VERB": 2.0,
                    "CCONJ": 1.8,
                    "SCONJ": 1.8,
                    "ADP": 1.3,
                    "PUNCT": 2.6,
                }.get(key.pos_, 1.0)
                # Do not multiply a word's contribution when it is split.
                pieces = sum(
                    1 for k in range(1, i)
                    if key.i in alignment[k]
                )
                pooling[j - 1] = weight / max(pieces, 1)

            if pooling.sum() > 0.0:
                transfer = min(0.38, attention[i, 0])
                attention[i, 0] -= transfer
                attention[i, 1:i] += transfer * pooling / pooling.sum()

    return "bos_sink_with_terminal_pooling", attention


def prog_L4H20(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with a strong early-position bias.
    Residual attention is diffuse and mildly favors recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_position_decay", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        early = np.exp(-(i - 1) / 5.0)
        sink_mass = 0.715 + 0.185 * early

        aligned = alignment[i]
        if aligned:
            word = doc[aligned[0]]
            correction = 0.0
            if word.pos_ in ("NOUN", "PROPN"):
                correction = 0.035
            elif word.pos_ in ("ADJ", "ADV"):
                correction = 0.030
            elif word.pos_ == "PRON":
                correction = -0.045
            elif word.pos_ == "PUNCT":
                correction = -0.085
            elif word.pos_ in ("VERB", "AUX"):
                correction = -0.015
            sink_mass += correction * (1.0 - early)

        sink_mass = float(np.clip(sink_mass, 0.52, 0.94))
        attention[i, 0] = sink_mass

        positions = np.arange(1, i + 1, dtype=np.float64)
        residual = 0.35 / i + np.exp(-(i - positions) / 4.0)
        residual /= residual.sum()
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_position_decay", attention


def prog_L4H21(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with weak recency, plus sparse dialogue-boundary links.
    Quoted sentence breaks create secondary anchors for later boundary tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_dialogue_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        positions = alignment[i]
        pos_tags = {doc[k].pos_ for k in positions}

        residual = 0.010
        if pos_tags and pos_tags <= {"PUNCT", "SPACE", "SYM"}:
            residual = 0.045
        elif pos_tags & {"NOUN", "ADJ", "ADP", "DET", "NUM"}:
            residual = 0.007
        elif pos_tags & {"VERB", "PROPN", "PRON", "CCONJ"}:
            residual = 0.015

        if i == 1:
            residual = 0.005

        distances = i - np.arange(1, i + 1)
        weights = np.exp(-distances / 3.0)
        attention[i, 1:i + 1] = residual * weights / weights.sum()
        attention[i, 0] = 1.0 - residual

    # Activate only for quoted sentence endings followed by standalone space.
    clean = [t.replace("Ġ", " ").replace("Ċ", "\n").strip() for t in tokens]
    quote_marks = {'"', "“", "”"}
    quoted = [
        i for i in range(1, n)
        if any(c in quote_marks for c in clean[i])
    ]
    endings = [
        i for i in quoted
        if any(c in ".!?" for c in clean[i])
        or (i > 1 and clean[i - 1] in {".", "!", "?"})
    ]
    gaps = [
        i for i in range(2, n)
        if not clean[i] and i - 1 in endings
    ]
    starts = [i + 1 for i in gaps if i + 1 < n and clean[i + 1]]

    if gaps:
        opening = [
            i for i in quoted
            if i not in endings and clean[i] in quote_marks
        ]
        speech_verbs = [
            i for i in range(1, n)
            if any(doc[k].pos_ == "VERB" for k in alignment[i])
        ]

        for i in range(1, n):
            extra = np.zeros(n, dtype=np.float64)
            prior_open = [j for j in opening if j < i]
            prior_end = [j for j in endings if j < i]
            prior_start = [j for j in starts if j < i]
            prior_verbs = [j for j in speech_verbs if j < i]
            pos_tags = {doc[k].pos_ for k in alignment[i]}
            punctuation = (
                bool(clean[i])
                and bool(pos_tags)
                and pos_tags <= {"PUNCT", "SYM"}
            )

            if i in gaps or i in starts:
                if prior_open:
                    extra[prior_open[0]] += 0.035
                if prior_verbs:
                    extra[prior_verbs[0]] += 0.030
                extra[1] += 0.020
                if i in starts:
                    extra[i - 1] += 0.050
                elif prior_start:
                    extra[prior_start[0]] += 0.390

            elif punctuation or i in quoted:
                if prior_open:
                    extra[prior_open[0]] += 0.035
                if prior_end:
                    extra[prior_end[-1]] += 0.045
                if clean[i] == ",":
                    prior_commas = [
                        j for j in range(1, i) if clean[j] == ","
                    ]
                    if prior_commas:
                        extra[prior_commas[0]] += 0.020
                if prior_start and any(c in ".!?" for c in clean[i]):
                    extra[prior_start[0]] += 0.045

            # Transfer only BOS mass; retain all original recency and diagonal
            # weights exactly, including for the special-case rows.
            extra[i:] = 0.0
            mass = extra.sum()
            if mass > 0.0:
                scale = min(1.0, attention[i, 0] / mass)
                attention[i] += scale * extra
                attention[i, 0] -= scale * mass

    return "bos_sink_with_dialogue_anchors", attention


def prog_L4H22(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with weak position-dependent leakage.
    Punctuation slightly increases the small causal, recency-biased residual.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_weak_leakage", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    attention[0, 0] = 1.0
    for i in range(1, n):
        leakage = 0.004 + 0.004 * np.log1p(i - 1)

        if any(doc[k].pos_ == "PUNCT" for k in alignment[i]):
            leakage += 0.015

        leakage = min(leakage, 0.06)
        attention[i, 0] = 1.0 - leakage

        # The examples constrain the sink much more than the residual edges.
        # Use a smooth local background rather than inventing syntactic links.
        positions = np.arange(1, i + 1)
        residual = np.exp((positions - i) / 5.0)
        attention[i, 1:i + 1] = leakage * residual / residual.sum()

    return "bos_sink_with_weak_leakage", attention


def prog_L4H23(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with a targeted exception for multi-adjective noun phrases.
    Their modifiers attract local attention and nearby pronominal references.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_modifier_clusters", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    # Only coordinated descriptive clusters activate the exception.
    first_piece = {}
    for ti in range(1, n):
        for si in alignment[ti]:
            if si not in first_piece:
                first_piece[si] = ti

    clusters = []
    for word in doc:
        if word.pos_ not in ("NOUN", "PROPN"):
            continue
        modifiers = [
            c.i for c in word.children
            if c.dep_ == "amod" and c.pos_ == "ADJ"
            and c.i < word.i and c.i in first_piece
        ]
        if len(modifiers) >= 2:
            clusters.append((word.i, modifiers))

    attention[0, 0] = 1.0

    for i in range(1, n):
        aligned = alignment[i]
        pos = doc[aligned[0]].pos_ if aligned else ""

        sink_mass = 0.84 + 0.135 * np.exp(-(i - 1) / 2.5)

        if pos == "PROPN":
            sink_mass += 0.045
        elif pos in ("NOUN", "PRON", "AUX"):
            sink_mass += 0.01
        elif pos in ("ADJ", "ADV"):
            sink_mass -= 0.025
        elif pos == "PUNCT":
            sink_mass -= 0.115

        if not aligned:
            clean = tokens[i].replace("Ġ", " ").replace("Ċ", "\n")
            if clean.isspace():
                sink_mass -= 0.035

        sink_mass = float(np.clip(sink_mass, 0.65, 0.985))
        attention[i, 0] = sink_mass

        distances = i - np.arange(1, i + 1)
        residual = 0.75 * np.exp(-distances / 3.5) + 0.25
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * residual / residual.sum()
        )

        # Transfer only BOS mass to strictly earlier modifiers. The original
        # self-attention and all other residual weights remain unchanged.
        if aligned and clusters:
            si = aligned[0]
            for head, modifiers in reversed(clusters):
                in_phrase = si == head or si in modifiers
                nearby_reference = (
                    0 < si - head <= 6
                    and pos in ("ADP", "CCONJ", "PRON")
                )
                targets = [first_piece[m] for m in modifiers
                           if first_piece[m] < i]
                if not targets or not (in_phrase or nearby_reference):
                    continue

                boost = 0.22 if pos == "ADJ" else 0.30
                if nearby_reference:
                    boost = 0.40 if pos == "PRON" else 0.30
                # Interior subword pieces are not reliable retrieval cues.
                if si == head and i > first_piece.get(head, i):
                    if i + 1 < n and head in alignment[i + 1]:
                        continue

                weights = np.exp(-(i - np.asarray(targets)) / 12.0)
                mass = min(boost, attention[i, 0])
                attention[i, 0] -= mass
                attention[i, targets] += mass * weights / weights.sum()
                break

    return "bos_sink_with_modifier_clusters", attention


def prog_L5H0(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with stronger suppression of non-BOS attention on nouns.
    A small, diffuse causal remainder has a weak recency preference.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_pos_modulated", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    sink_by_pos = {
        "NOUN": 0.977,
        "PROPN": 0.979,
        "ADJ": 0.958,
        "NUM": 0.954,
        "DET": 0.943,
        "ADP": 0.935,
        "PRON": 0.925,
        "VERB": 0.922,
        "AUX": 0.907,
        "ADV": 0.928,
        "PART": 0.922,
        "CCONJ": 0.917,
        "SCONJ": 0.915,
        "INTJ": 0.925,
        "PUNCT": 0.865,
        "SPACE": 0.938,
    }

    for i in range(1, n):
        sids = alignment[i]
        sink = 0.935
        if sids:
            # Subword pieces inherit their containing word's linguistic features.
            sink = 0.0
            for sid in sids:
                word = doc[sid]
                value = sink_by_pos.get(word.pos_, 0.935)
                if word.ent_type_:
                    value = max(value, 0.970)
                sink += value
            sink /= len(sids)

        # The first ordinary token is consistently almost entirely BOS-directed.
        if i == 1:
            sink = 0.979
        else:
            sink = min(0.992, sink + 0.008 * np.exp(-(i - 2) / 7.0))

        positions = np.arange(1, i + 1, dtype=np.float64)
        remainder = 0.7 / i + 0.3 * (
            np.exp((positions - i) / 5.0)
            / np.exp((positions - i) / 5.0).sum()
        )
        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * remainder

    return "bos_sink_pos_modulated", make_row_stochastic(attention)


def prog_L5H1(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with a strong early-position prior and mild syntactic modulation.
    Residual attention is diffuse and biased toward recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_syntactic_modulation", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        words = [doc[k] for k in alignment[i] if k < len(doc)]
        sink = 0.73 + 0.24 * np.exp(-(i - 1) / 3.0)

        if words:
            word = max(words, key=lambda w: len(w.text))
            if word.pos_ == "PROPN":
                sink += 0.16
            elif word.pos_ == "NOUN":
                sink += 0.12
            elif word.pos_ == "ADJ":
                sink += 0.07
            elif word.pos_ in ("PRON", "PART"):
                sink -= 0.08
            elif word.pos_ in ("ADP", "DET", "CCONJ", "SCONJ"):
                sink -= 0.02

            if word.dep_ in ("nsubj", "nsubjpass", "appos"):
                sink += 0.03
            if word.ent_type_:
                sink += 0.025

        if tokens[i].isspace() or tokens[i] in tokenizer.all_special_tokens:
            sink += 0.10

        if i == 1:
            sink = 0.97
        sink = float(np.clip(sink, 0.55, 0.985))

        positions = np.arange(1, i + 1, dtype=np.float64)
        residual = 0.45 / i + 0.55 * np.exp(-(i - positions) / 4.0)
        residual /= residual.sum()

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual

    return "bos_sink_with_syntactic_modulation", attention


def prog_L5H2(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with an early-position boost and weak linguistic modulation.
    Residual attention follows a diffuse, mildly recency-biased causal distribution.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_weak_recency", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    inside_quote = False
    quote_marks = ('"', '“', '”', '„', '«', '»')

    for i in range(1, n):
        text = tokens[i].replace("Ġ", " ").replace("Ċ", "\n")
        quote_count = sum(text.count(mark) for mark in quote_marks)

        sink_mass = 0.845 + 0.13 * np.exp(-(i - 1) / 3.0)

        if alignment[i]:
            word = doc[alignment[i][0]]
            if word.pos_ in ("DET", "PRON"):
                sink_mass += 0.015
            elif word.pos_ in ("NOUN", "PROPN", "ADJ"):
                sink_mass -= 0.015
            elif word.pos_ == "PUNCT":
                sink_mass += 0.01

        if text.isspace():
            sink_mass += 0.035

        # Quoted speech exhibits weaker sink dominance in the examples.
        if inside_quote:
            sink_mass -= 0.085
        if quote_count % 2:
            inside_quote = not inside_quote

        sink_mass = float(np.clip(sink_mass, 0.65, 0.99))
        attention[i, 0] = sink_mass

        positions = np.arange(1, i + 1, dtype=np.float64)
        residual = 0.65 / i + 0.35 * (
            np.exp(-(i - positions) / 5.0)
            / np.exp(-(i - positions) / 5.0).sum()
        )
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_weak_recency", make_row_stochastic(attention)


def prog_L5H3(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with a local tail; repeated dialogue additionally retrieves
    earlier utterance roles, related words, and quotation boundaries.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_dialogue_retrieval", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        # The original behavior is unchanged.
        elapsed = max(0, i - 10)
        sink_mass = 0.965 - 0.39 * (1.0 - np.exp(-elapsed / 26.0))

        sids = alignment[i]
        if sids:
            word = doc[sids[-1]]
            if word.pos_ in ("AUX", "NOUN", "ADJ"):
                sink_mass += 0.012
            elif word.pos_ in ("PRON", "DET"):
                sink_mass -= 0.018
            if word.dep_ in ("poss", "nmod:poss"):
                sink_mass -= 0.035
            if word.is_punct:
                sink_mass += 0.008

        sink_mass = float(np.clip(sink_mass, 0.50, 0.99))

        positions = np.arange(1, i + 1)
        local_weights = np.exp(-(i - positions) / 4.0)
        local_weights[-1] *= 0.7

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * local_weights / local_weights.sum()
        )

    # Restrict retrieval to multi-turn quoted dialogue. Non-dialogue matrices
    # remain exactly unchanged; updates transfer only BOS mass, never self mass.
    quotes = [
        i for i, token in enumerate(tokens)
        if any(mark in token for mark in ('"', '“', '”'))
    ]
    if len(quotes) >= 4:
        words = [doc[sids[-1]] if sids else None for sids in alignment]
        content_pos = ("NOUN", "PROPN", "VERB", "ADJ", "ADP")
        similarities = {}

        for i in range(quotes[0] + 1, n):
            word = words[i]
            if word is None:
                continue

            extra = np.zeros(i, dtype=np.float64)

            # Sparse semantic recurrence, including morphological variants.
            if word.pos_ in content_pos:
                for j in range(1, i):
                    previous = words[j]
                    if previous is None or previous.pos_ != word.pos_:
                        continue
                    if previous.i == word.i:
                        continue
                    key = (i, j)
                    if key not in similarities:
                        similarities[key] = embedding_similarity(
                            tokens, i, j, tokenizer
                        )
                    similarity = similarities[key]
                    if similarity > 0.70:
                        extra[j] = max(
                            extra[j], 0.34 * (similarity - 0.70) / 0.30
                        )

            # Retrieve the preceding completed utterance, not recent tokens.
            completed = [
                (quotes[k], quotes[k + 1])
                for k in range(0, len(quotes) - 1, 2)
                if quotes[k + 1] < i
            ]
            if completed:
                start, end = completed[-1]
                extra[end] = max(
                    extra[end],
                    0.16 if word.is_punct or word.pos_ == "PRON" else 0.08
                )

                candidates = [
                    j for j in range(start + 1, end)
                    if words[j] is not None and not words[j].is_punct
                ]
                # Turn openings align; subjects retain their conversational role
                # even when speaker-dependent pronoun forms change.
                openings = [q for q in quotes[::2] if end < q <= i]
                if openings and i - openings[-1] <= 3:
                    if word.pos_ == "PRON":
                        matches = [
                            j for j in candidates
                            if words[j].pos_ == "PRON"
                            and words[j].dep_ == word.dep_
                        ]
                        if matches:
                            extra[matches[0]] = max(extra[matches[0]], 0.30)
                    if i == openings[-1] + 1 and candidates:
                        extra[candidates[0]] = max(
                            extra[candidates[0]], 0.28
                        )

            # Induction: after a repeated entity, retrieve its earlier successor.
            if i > 1 and words[i - 1] is not None:
                previous = words[i - 1]
                if previous.pos_ in ("NOUN", "PROPN"):
                    for j in range(1, i - 1):
                        if words[j] is None or words[j].pos_ != previous.pos_:
                            continue
                        if words[j].i == previous.i:
                            continue
                        similarity = embedding_similarity(
                            tokens, i - 1, j, tokenizer
                        )
                        if similarity > 0.85:
                            extra[j + 1] = max(
                                extra[j + 1],
                                0.20 * (similarity - 0.85) / 0.15
                            )

            total = extra.sum()
            if total > 0:
                transfer = min(float(total), 0.75 * attention[i, 0])
                attention[i, 0] -= transfer
                attention[i, :i] += transfer * extra / total

    return "bos_sink_with_dialogue_retrieval", attention


def prog_L5H4(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with gradually increasing diffuse causal competition.
    Linguistic features mildly modulate the otherwise positional pattern.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_diffuse_competition", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    # The initial token is the sink; Llama normally supplies BOS here.
    attention[0, 0] = 1.0
    key_weights = np.ones(n, dtype=np.float64)
    query_scale = np.ones(n, dtype=np.float64)

    for i in range(1, n):
        if not alignment[i]:
            continue
        word = doc[alignment[i][0]]
        if word.is_punct:
            key_weights[i] = 0.80
            query_scale[i] = 0.85
        elif word.pos_ in ("ADJ", "ADV", "ADP", "AUX"):
            query_scale[i] = 1.12
        elif word.pos_ in ("NOUN", "PROPN", "VERB"):
            key_weights[i] = 1.10
        elif word.pos_ == "PRON":
            query_scale[i] = 0.92

    for i in range(1, n):
        positions = np.arange(1, i + 1)
        distances = i - positions

        # Residual attention is mostly diffuse, with a modest recent-token bias.
        residual = key_weights[1:i + 1] * (
            0.65 + 0.35 * np.exp(-distances / 6.0)
        )
        residual[-1] *= 0.80
        attention[i, 1:i + 1] = residual

        # A roughly fixed sink logit naturally loses probability as the
        # number of competing causal keys increases.
        attention[i, 0] = 55.0 * query_scale[i]

    return (
        "bos_sink_with_diffuse_competition",
        make_row_stochastic(attention),
    )


def prog_L5H5(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, with gradually increasing diffuse causal attention.
    The examples support a positional pattern rather than a syntactic target.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_position_decay", attention

    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.99 / (1.0 + 0.0015 * i + 0.00017 * i * i)

        # No non-BOS target is established by the supplied edges, so spread
        # the residual conservatively across the remaining causal positions.
        attention[i, 1:i + 1] = (1.0 - sink_mass) / i
        attention[i, 0] = sink_mass

    return "bos_sink_with_position_decay", attention


def prog_L5H6(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with a dialogue-only induction exception:
    repeated or related tokens retrieve successors of their earlier occurrences.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    for i in range(n):
        if i == 0:
            attention[i, 0] = 1.0
        else:
            residual = min(0.025, 0.001 + 0.0003 * (i - 1))
            attention[i, 0] = 1.0 - residual
            attention[i, 1:i + 1] = residual / i

    # Leave ordinary prose completely unchanged.
    quote_count = sum(sentence.count(q) for q in ('"', '“', '”'))
    if quote_count >= 3:
        doc = spacy_parse(sentence)
        aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
        pos = [doc[a[0]].pos_ if a else "" for a in aligned]
        clean = [t.lstrip("\u0120").strip() for t in tokens]

        openings = []
        inside_quote = False
        first_opening = n
        for i in range(1, n):
            targets = []
            mass = 0.0
            has_quote = any(q in clean[i] for q in ('"', '“', '”'))
            opening = has_quote and not inside_quote

            if opening:
                first_opening = min(first_opening, i)
                if openings and openings[-1] + 1 < i:
                    j = openings[-1]
                    targets = [(j, 0.6), (j + 1, 0.4)]
                    mass = 0.18
                openings.append(i)

            elif i > first_opening and pos[i] in (
                "NOUN", "PROPN", "VERB", "ADJ", "ADV", "DET", "PRON", "ADP"
            ):
                best_j, best_score = -1, 0.0
                for j in range(1, i - 1):
                    if pos[j] != pos[i]:
                        continue
                    similarity = embedding_similarity(tokens, i, j, tokenizer)
                    threshold = 0.68 if pos[i] == "VERB" else 0.78
                    if similarity < threshold:
                        continue
                    context = 0.0
                    if i > 1 and j > 1:
                        context = max(
                            0.0,
                            embedding_similarity(tokens, i - 1, j - 1, tokenizer)
                        )
                    score = similarity + 0.15 * context
                    if score > best_score:
                        best_j, best_score = j, score

                if best_j >= 0:
                    j = best_j
                    mass = {
                        "NOUN": 0.35, "PROPN": 0.20, "VERB": 0.20,
                        "ADJ": 0.10, "ADV": 0.06, "DET": 0.08,
                        "PRON": 0.09, "ADP": 0.22,
                    }[pos[i]]
                    mass *= min(1.0, max(0.0, (best_score - 0.65) / 0.35))
                    targets = [(j + 1, 1.0)]

                    if j + 2 < i:
                        next_has_quote = any(
                            q in clean[j + 2] for q in ('"', '“', '”')
                        )
                        if next_has_quote:
                            targets = [(j + 1, 0.6), (j + 2, 0.4)]
                            if pos[i] == "NOUN":
                                mass = max(mass, 0.45)
                        elif pos[j + 1] == "AUX":
                            targets = [(j + 1, 0.5), (j + 2, 0.5)]

                    # A matching predecessor strengthens phrase induction.
                    if i > 1 and j > 1 and pos[i] == "NOUN":
                        context = embedding_similarity(tokens, i - 1, j - 1, tokenizer)
                        if context > 0.72:
                            mass = max(mass, 0.65)

            if has_quote:
                inside_quote = not inside_quote

            # Transfer only BOS mass; preserve the original diagonal and remainder.
            if targets and mass > 0.0:
                mass = min(mass, attention[i, 0])
                attention[i, 0] -= mass
                for j, weight in targets:
                    attention[i, j] += mass * weight

    return "bos_sink_with_dialogue_induction", attention


def prog_L5H7(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink: nearly all attention targets the initial token.
    Distribute the tiny unresolved residual uniformly over other causal tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    for i in range(n):
        if i == 0:
            attention[i, 0] = 1.0
        else:
            attention[i, 0] = 0.999
            attention[i, 1:i + 1] = 0.001 / i

    return "bos_attention_sink", attention


def prog_L5H8(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with quote-gated induction: repeated expressions retrieve their
    earlier continuations, while dialogue boundaries act as secondary anchors.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_quote_induction", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, indices in enumerate(alignment):
        for k in indices:
            inverse[k].append(i)

    # Only activate the additional mechanism after a completed quotation.
    quotes = [
        i for i, token in enumerate(tokens)
        if any(c in token for c in ('"', '“', '”'))
    ]
    dialogue = len(quotes) >= 2

    attention[0, 0] = 1.0
    for i in range(1, n):
        sink_mass = 0.975 - 0.00055 * min(i, 80)
        word = doc[alignment[i][-1]] if alignment[i] else None

        if word is not None:
            if word.pos_ in ("ADJ", "ADV"):
                sink_mass += 0.012
            elif word.pos_ in ("PRON", "AUX"):
                sink_mass -= 0.018
            elif word.pos_ == "PUNCT":
                sink_mass -= 0.008

        if i == 1:
            sink_mass = 0.996

        sink_mass = float(np.clip(sink_mass, 0.88, 0.995))

        # Residual mass stays causal and favors nearby positions, including self.
        positions = np.arange(1, i + 1)
        residual = np.exp(-(i - positions) / 5.0)
        residual[-1] += 0.4

        # A modest syntactic correction, not a competing dominant mechanism.
        if word is not None and word.head.i != word.i:
            targets = [
                j for j in inverse[word.head.i] if 0 < j <= i
            ]
            if targets:
                residual[targets[-1] - 1] += 0.6

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * residual / residual.sum()
        )

        if dialogue and i > quotes[1]:
            extra = np.zeros(i, dtype=np.float64)

            # Match earlier expressions, then retrieve tokens AFTER the match.
            if word is not None and word.pos_ in (
                "NOUN", "PROPN", "VERB", "DET", "ADP"
            ):
                best, best_score = None, 0.0
                threshold = 0.65 if word.pos_ == "VERB" else 0.78
                for j in range(1, i - 3):
                    if not alignment[j]:
                        continue
                    previous = doc[alignment[j][-1]]
                    if previous.pos_ != word.pos_:
                        continue
                    if j != inverse[previous.i][-1]:
                        continue
                    score = embedding_similarity(tokens, i, j, tokenizer)
                    if score >= threshold and score >= best_score - 1e-6:
                        best, best_score = j, score

                if best is not None:
                    successors = np.arange(best + 1, min(best + 4, i))
                    weights = np.exp(-np.arange(len(successors)) / 1.15)
                    mass = 0.40
                    if word.pos_ in ("NOUN", "PROPN"):
                        mass = 0.68
                    elif word.pos_ == "VERB":
                        mass = 0.58
                    elif word.pos_ == "ADP":
                        mass = 0.48

                    # Punctuation immediately following a repeated referent is
                    # particularly diagnostic of dialogue-boundary induction.
                    if alignment[best + 1]:
                        following = doc[alignment[best + 1][-1]]
                        if following.pos_ == "PUNCT":
                            mass = 0.80
                            weights[:] = 0.0
                            weights[0] = 1.0
                            if best + 2 in quotes and len(weights) > 1:
                                weights[0] = 0.55
                                weights[1] = 0.45
                        elif following.pos_ == "ADP" and word.pos_ == "NOUN":
                            mass = 0.80

                    extra[successors] += mass * weights / weights.sum()

            # Between quotations, discourse punctuation and reporting verbs
            # can retrieve the first opening boundary even without repetition.
            if len(quotes) >= 3 and i <= quotes[2]:
                if i == quotes[2]:
                    extra[quotes[0]] += 0.25
                    if quotes[0] + 1 < i:
                        extra[quotes[0] + 1] += 0.14
                elif word is not None:
                    if word.pos_ == "PUNCT":
                        extra[quotes[0]] += 0.16
                    elif word.pos_ == "VERB" and word.dep_ in ("ROOT", "conj"):
                        extra[quotes[0]] += 0.22

            # Transfer only BOS mass: all original self/local weights survive.
            added = extra.sum()
            if added > 0.0:
                scale = min(1.0, (attention[i, 0] - 0.03) / added)
                attention[i, :i] += scale * extra
                attention[i, 0] -= scale * added

    return "bos_sink_with_quote_induction", attention


def prog_L5H9(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with weak POS-dependent strength.
    Remaining attention follows a diffuse causal prior with mild recency bias.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_weak_recency", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    pos_adjustment = {
        "NOUN": 0.015,
        "PROPN": 0.020,
        "ADJ": 0.005,
        "VERB": -0.010,
        "AUX": -0.010,
        "ADP": -0.025,
        "CCONJ": -0.025,
        "SCONJ": -0.025,
        "PUNCT": 0.010,
        "SPACE": 0.080,
    }

    attention[0, 0] = 1.0
    for i in range(1, n):
        # Most queries deposit roughly three quarters of their mass at BOS.
        sink_mass = 0.725 + 0.045 * np.exp(-(i - 2) / 3.0)

        if alignment[i]:
            word = doc[alignment[i][0]]
            sink_mass += pos_adjustment.get(word.pos_, 0.0)

        clean = tokens[i].replace("\u0120", " ").replace("\u010a", "\n")
        if clean and clean.isspace():
            sink_mass = 0.815

        # The first content query has a particularly stable sink preference.
        if i == 1:
            sink_mass = 0.840

        sink_mass = np.clip(sink_mass, 0.65, 0.87)
        attention[i, 0] = sink_mass

        distances = i - np.arange(1, i + 1, dtype=np.float64)
        background = np.full(i, 1.0 / i, dtype=np.float64)
        recent = np.exp(-distances / 4.0)
        recent /= recent.sum()
        residual = 0.65 * background + 0.35 * recent
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_weak_recency", make_row_stochastic(attention)


def prog_L5H10(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with targeted retrieval of split-word and prepositional anchors.
    Anchor retrieval draws only from BOS, preserving self-attention and decay.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_phrase_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink = 0.83
        if alignment[i]:
            word = doc[alignment[i][0]]
            pos = word.pos_

            if pos in ("NOUN", "PROPN"):
                sink += 0.045
            elif pos == "ADJ":
                sink += 0.05
            elif pos == "DET":
                sink += 0.025
            elif pos in ("VERB", "AUX"):
                sink += 0.005
            elif pos in ("CCONJ", "SCONJ"):
                sink -= 0.09
            elif pos in ("PUNCT", "SPACE", "SYM"):
                sink -= 0.17

            if word.ent_type_:
                sink += 0.015
        elif tokens[i].isspace() or tokens[i] == "\u0120":
            sink -= 0.12

        # Early queries consistently allocate especially high mass to BOS.
        if i == 1:
            sink = 0.965
        elif i == 2:
            sink = 0.92 + 0.15 * (sink - 0.83)
        else:
            sink += 0.025 * np.exp(-(i - 3) / 3.0)

        sink = np.clip(sink, 0.55, 0.98)
        attention[i, 0] = sink

        positions = np.arange(1, i + 1, dtype=np.float64)
        residual = 0.35 / i + np.exp(-(i - positions) / 4.0)
        residual /= residual.sum()
        attention[i, 1:i + 1] = (1.0 - sink) * residual

        # Special case: recover lexical/phrase anchors without rescaling
        # any existing non-BOS weight, including the diagonal.
        if i > 2 and alignment[i] and alignment[i - 1]:
            word = doc[alignment[i][0]]
            previous = doc[alignment[i - 1][0]]
            anchors = []
            boost = 0.0

            if word.i == previous.i and word.pos_ in ("NOUN", "PROPN"):
                anchors = [
                    j for j in range(1, i) if word.i in alignment[j]
                ]
                boost = min(0.44, 0.15 + 0.29 * (len(anchors) - 1))
            elif word.pos_ == "ADP" and previous.pos_ in ("NOUN", "PROPN"):
                anchors = [
                    j for j in range(1, i) if previous.i in alignment[j]
                ]
                boost = min(0.36, 0.22 + 0.07 * (len(anchors) - 1))
            elif (
                word.pos_ in ("NOUN", "PROPN")
                and word.dep_ == "pobj"
                and word.head.pos_ == "ADP"
            ):
                anchors = [
                    j for j in range(1, i) if word.head.i in alignment[j]
                ]
                boost = 0.13
            elif (
                word.pos_ == "CCONJ"
                and previous.dep_ == "pobj"
                and previous.head.pos_ == "ADP"
            ):
                anchors = [
                    j for j in range(1, i)
                    if previous.head.i in alignment[j]
                ]
                boost = 0.18

            if anchors:
                # Prefer the initial piece of a multi-token lexical anchor.
                weights = np.ones(len(anchors), dtype=np.float64)
                weights[0] = 2.0
                weights /= weights.sum()
                transfer = min(boost, max(0.0, attention[i, 0] - 0.25))
                attention[i, 0] -= transfer
                attention[i, anchors] += transfer * weights

    return "bos_sink_with_phrase_anchors", attention


def prog_L5H11(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, strongest near sequence start and on content tokens.
    Residual attention is diffuse and mildly recency-biased."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_positional_decay", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        maturity = 1.0 - np.exp(-(i - 1) / 8.0)
        sink_mass = 0.83 + 0.14 * np.exp(-(i - 1) / 5.0)

        linked = alignment[i]
        if linked:
            word = doc[linked[-1]]
            if word.pos_ in ("NOUN", "PROPN", "ADJ", "NUM"):
                sink_mass += 0.025 * maturity
            elif word.pos_ in ("CCONJ", "SCONJ"):
                sink_mass -= 0.09 * maturity
            elif word.pos_ == "PUNCT":
                sink_mass -= 0.12 * maturity
            elif word.pos_ == "SPACE":
                sink_mass -= 0.15 * maturity
        elif tokens[i].isspace():
            sink_mass -= 0.15 * maturity

        sink_mass = np.clip(sink_mass, 0.60, 0.985)
        attention[i, 0] = sink_mass

        # The supplied edges establish the sink, not a specific residual target.
        distance = i - np.arange(1, i + 1, dtype=np.float64)
        residual = 0.5 / i + 0.5 * (
            np.exp(-distance / 4.0) / np.exp(-distance / 4.0).sum()
        )
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_positional_decay", make_row_stochastic(attention)


def prog_L5H12(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with position-dependent dilution and linguistic modulation.
    Residual attention favors salient content, syntactic heads, and discourse boundaries.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_salient_residual", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    words = [
        doc[indices[0]] if indices else None
        for indices in alignment
    ]
    clean = [t.lstrip("Ġ▁").strip() for t in tokens]

    # Static key salience: content-bearing tokens compete more effectively
    # for the attention left over after the sink.
    salience = np.ones(n, dtype=np.float64)
    for j in range(1, n):
        word = words[j]
        if word is not None:
            if word.pos_ == "PROPN":
                salience[j] = 2.5
            elif word.pos_ == "NOUN":
                salience[j] = 1.8
            elif word.pos_ in ("VERB", "ADJ"):
                salience[j] = 1.2
            elif word.pos_ in ("DET", "ADP", "PART", "AUX"):
                salience[j] = 0.65
            if word.dep_ in ("nsubj", "nsubjpass", "ROOT"):
                salience[j] *= 1.25
        if any(c in clean[j] for c in ".!?"):
            salience[j] *= 1.8
        if not clean[j]:
            salience[j] *= 0.6

    attention[0, 0] = 1.0
    for i in range(1, n):
        word = words[i]
        sink = 0.25 + 0.65 * np.exp(-(i - 1) / 12.0)

        if word is not None and i > 2:
            if word.pos_ in ("CCONJ", "SCONJ"):
                sink += 0.13
            elif word.pos_ == "AUX":
                sink += 0.07
            elif word.pos_ == "ADV":
                sink += 0.04
            elif word.pos_ in ("NOUN", "PROPN", "VERB"):
                sink -= 0.045

        surface = clean[i]
        if surface and all(not c.isalnum() for c in surface):
            if any(c in surface for c in ".!?"):
                sink += 0.30 if i == n - 1 else 0.06
            elif "," in surface:
                sink += 0.08
            elif any(c in surface for c in "\"'“”‘’"):
                sink += 0.10
        elif not surface:
            sink += 0.10

        sink = float(np.clip(sink, 0.18, 0.96))
        positions = np.arange(1, i + 1)
        residual = salience[1:i + 1].copy()
        residual *= 0.55 + 0.45 * np.exp(-(i - positions) / 18.0)

        # Causal syntactic links are a secondary correction, not the main rule.
        if word is not None:
            for j in range(1, i + 1):
                target = words[j]
                if target is not None and target.i == word.head.i:
                    residual[j - 1] *= 1.6

        residual[-1] *= 1.15
        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual / residual.sum()

    return "bos_sink_with_salient_residual", attention


def prog_L5H13(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, strongest early and at discourse boundaries.
    Content-bearing tokens divert residual attention toward themselves and nearby context.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_residual", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    pos_adjustment = {
        "NOUN": -0.17,
        "PROPN": -0.18,
        "PRON": -0.07,
        "DET": -0.05,
        "ADP": -0.07,
        "VERB": -0.03,
        "AUX": 0.10,
        "ADJ": -0.02,
        "ADV": 0.13,
        "CCONJ": 0.10,
        "SCONJ": 0.12,
        "PART": 0.02,
        "NUM": -0.08,
        "PUNCT": 0.08,
        "SPACE": 0.12,
    }

    for i in range(1, n):
        raw = tokens[i]
        clean = raw.replace("Ġ", " ").replace("Ċ", "\n").strip()
        aligned = alignment[i]
        word = doc[aligned[-1]] if aligned else None

        sink = 0.64 + 0.29 * np.exp(-(i - 1) / 4.5)

        if word is not None:
            sink += pos_adjustment.get(word.pos_, 0.0)
            if word.dep_ in ("ROOT", "advcl", "ccomp"):
                sink += 0.05
            elif word.dep_ in ("dobj", "obj", "pobj", "attr"):
                sink -= 0.06
            if word.ent_type_:
                sink -= 0.03

        if not clean:
            sink = max(sink, 0.77)
        elif all(c in "\"'“”‘’«»" for c in clean):
            sink = max(sink, 0.82)
        elif clean == ",":
            sink = max(sink, 0.77 + 0.15 * np.exp(-i / 8.0))

        if i == 1:
            sink = 0.95
        sink = float(np.clip(sink, 0.20, 0.98))
        attention[i, 0] = sink

        # No supported non-BOS syntactic target is evident in the examples.
        # Use a conservative self-biased, recency-decaying residual instead.
        positions = np.arange(1, i + 1)
        residual = np.exp(-(i - positions) / 3.0)
        residual[-1] += 1.5

        if word is not None and word.is_sent_start:
            residual[-1] += 1.0

        attention[i, 1:i + 1] = (1.0 - sink) * residual / residual.sum()

    return "bos_sink_with_local_residual", attention


def prog_L5H14(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with mild positional decay and a diffuse causal remainder.
    Punctuation slightly strengthens local/self attention rather than syntactic links.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_residual", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.69 + 0.20 * np.exp(-(i - 1) / 20.0)

        aligned = alignment[i]
        if aligned:
            word = doc[aligned[0]]
            if word.pos_ in ("AUX", "ADJ", "ADV", "CCONJ", "SCONJ"):
                sink_mass += 0.025
            elif word.pos_ == "PUNCT":
                sink_mass -= 0.055

        if i == 1:
            sink_mass = 0.91

        # Keep a broad background rather than inventing unsupported syntax edges.
        positions = np.arange(1, i + 1)
        residual = 0.45 / i + 0.55 * np.exp(-(i - positions) / 6.0)
        residual[-1] += 0.30
        if i > 1:
            residual[-2] += 0.15

        if aligned and doc[aligned[0]].pos_ == "PUNCT":
            residual[-1] += 0.75

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual / residual.sum()

    return "bos_sink_with_local_residual", attention


def prog_L5H15(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Hypothesis: a dominant first-token attention sink with a small,
    diffuse causal remainder biased toward recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "first_token_sink_with_recency", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        positions = np.arange(1, i + 1)
        distances = i - positions

        # A fixed sink competes with weak background and local attention.
        attention[i, 0] = 80.0
        attention[i, 1:i + 1] = (
            0.065 + 0.95 * np.exp(-distances / 2.0)
        )
        attention[i] /= attention[i].sum()

    return "first_token_sink_with_recency", attention


def prog_L5H16(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink: nearly all attention goes to the first token.
    A small residual is spread causally, with a weak recency preference.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_weak_recency", attention

    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.89 + 0.07 * np.exp(-(i - 1) / 28.0)

        distances = i - np.arange(1, i + 1)
        residual = 0.7 / i + 0.3 * (
            np.exp(-distances / 6.0)
            / np.exp(-distances / 6.0).sum()
        )

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_weak_recency", attention


def prog_L5H17(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with gradual positional dilution.
    A small residual favors recent tokens, with weak POS-based modulation.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_positional_dilution", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        # The data overwhelmingly support a first-token sink rather than
        # a specific syntactic or semantic retrieval operation.
        sink_mass = 0.965 - 0.0022 * max(i - 4, 0)

        mapped = alignment[i]
        if mapped:
            word = doc[mapped[-1]]
            if word.pos_ in ("AUX", "ADP", "SCONJ", "PRON"):
                sink_mass += 0.010
            elif word.pos_ in ("NOUN", "PROPN"):
                sink_mass -= 0.012
            elif word.pos_ == "PUNCT":
                sink_mass -= 0.008

        # The first lexical token has only BOS and itself available.
        if i == 1:
            sink_mass = 0.94

        sink_mass = float(np.clip(sink_mass, 0.72, 0.985))
        attention[i, 0] = sink_mass

        distances = i - np.arange(1, i + 1, dtype=np.float64)
        residual = 0.35 + np.exp(-distances / 4.0)
        residual /= residual.sum()
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_positional_dilution", attention


def prog_L5H18(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with gradual positional dilution and weak POS modulation.
    Residual attention is diffuse and mildly biased toward recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_positional_dilution", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    pos_adjustment = {
        "NOUN": 0.045,
        "PROPN": 0.060,
        "ADJ": 0.025,
        "NUM": 0.020,
        "VERB": 0.000,
        "AUX": -0.025,
        "PRON": -0.035,
        "DET": -0.015,
        "ADP": -0.020,
        "ADV": -0.020,
        "CCONJ": -0.025,
        "SCONJ": -0.025,
        "PART": -0.035,
        "PUNCT": -0.010,
        "SPACE": 0.020,
    }

    attention[0, 0] = 1.0
    for i in range(1, n):
        sink_mass = 0.978 - 0.066 * np.log(float(i)) - 0.0012 * (i - 1)

        if i > 1:
            aligned = alignment[i]
            if aligned:
                adjustment = np.mean([
                    pos_adjustment.get(doc[k].pos_, 0.0)
                    for k in aligned
                ])
                sink_mass += adjustment
            elif tokens[i].replace("Ġ", "").replace("Ċ", "").isspace():
                sink_mass += 0.020

        sink_mass = float(np.clip(sink_mass, 0.40, 0.985))
        attention[i, 0] = sink_mass

        positions = np.arange(1, i + 1)
        distances = i - positions
        residual = 0.65 + 0.35 * np.exp(-distances / 6.0)
        residual /= residual.sum()
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_positional_dilution", make_row_stochastic(attention)


def prog_L5H19(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with an early-position bias and mild syntactic modulation.
    Residual attention is diffuse and weakly favors recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_position_bias", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        # Sink dominance is strongest at the beginning, but persists far away.
        sink = 0.61 + 0.37 * np.exp(-(i - 1) / 6.0)
        mapped = alignment[i]

        if mapped:
            word = doc[mapped[-1]]
            dep = word.dep_
            pos = word.pos_

            if dep in ("nsubj", "nsubjpass", "csubj", "csubjpass"):
                sink += 0.12
            elif dep in ("dobj", "obj", "pobj", "attr", "oprd"):
                sink -= 0.045

            if pos == "PROPN":
                sink += 0.10
            elif pos in ("VERB", "AUX") and dep in (
                "xcomp", "ccomp", "advcl", "relcl"
            ):
                sink -= 0.10

            if dep in ("mark", "cc"):
                sink += 0.025

        clean = tokens[i].lstrip("Ġ▁")
        if not clean or clean.isspace():
            sink += 0.10
        elif all(c in ",;:\"'“”‘’" for c in clean):
            sink += 0.04

        # At the first text token, the observed sink is almost total.
        if i == 1:
            sink = 0.978
        sink = float(np.clip(sink, 0.32, 0.985))

        # Avoid inventing strong non-BOS edges unsupported by the examples.
        distances = i - np.arange(1, i + 1, dtype=np.float64)
        residual = 0.65 + 0.35 * np.exp(-distances / 5.0)
        attention[i, 1:i + 1] = (
            (1.0 - sink) * residual / residual.sum()
        )
        attention[i, 0] = sink

    return "bos_sink_with_position_bias", attention


def prog_L5H20(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with weak position/POS modulation.
    Residual attention is diffuse and mildly biased toward recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_diffuse_residual", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        # The supplied edges overwhelmingly target the initial token.
        sink_mass = 0.89 - 0.0015 * min(i, 60)
        sink_mass += 0.025 * np.exp(-(i - 1) / 6.0)

        if alignment[i]:
            word = doc[alignment[i][0]]
            if word.pos_ in ("NOUN", "PROPN", "ADJ"):
                sink_mass += 0.025
            elif word.pos_ == "PUNCT":
                sink_mass -= 0.035

        sink_mass = float(np.clip(sink_mass, 0.72, 0.94))
        attention[i, 0] = sink_mass

        # No non-BOS target is evidenced strongly enough to dominate.
        distance = i - np.arange(1, i + 1)
        residual = 0.65 * np.exp(-distance / 8.0) + 0.35
        residual /= residual.sum()
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_diffuse_residual", attention


def prog_L5H21(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, strongest near the start and for nominal content.
    Residual attention is diffuse and mildly biased toward recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_lexical_modulation", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        words = [doc[k] for k in alignment[i]]
        word = max(words, key=lambda w: len(w.text)) if words else None

        sink_mass = 0.58 + 0.28 * np.exp(-(i - 1) / 8.0)
        if word is not None:
            if word.pos_ == "PROPN":
                sink_mass += 0.14
            elif word.pos_ == "NOUN":
                sink_mass += 0.12
            elif word.pos_ == "ADJ":
                sink_mass += 0.055
            elif word.pos_ in ("VERB", "ADV", "CCONJ", "SCONJ"):
                sink_mass -= 0.035
            elif word.pos_ == "DET":
                sink_mass -= 0.025

            if word.ent_type_:
                sink_mass += 0.025
        elif tokens[i].isspace() or tokens[i].strip("Ġ▁") == "":
            sink_mass += 0.04

        if i == 1:
            sink_mass = 0.94

        sink_mass = float(np.clip(sink_mass, 0.45, 0.96))
        attention[i, 0] = sink_mass

        positions = np.arange(1, i + 1)
        residual = 0.7 / i + 0.3 * (
            np.exp(-(i - positions) / 6.0)
            / np.exp(-(i - positions) / 6.0).sum()
        )
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_lexical_modulation", make_row_stochastic(attention)


def prog_L5H22(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, strongest near the opening and at clause backbones.
    Residual attention is diffuse and weakly biased toward recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_clause_modulation", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        clean = tokens[i].lstrip("Ġ").lstrip("▁")
        aligned = alignment[i]
        word = doc[aligned[0]] if aligned else None

        sink = 0.79
        if word is not None:
            pos = word.pos_
            dep = word.dep_

            if pos in ("VERB", "AUX"):
                sink = 0.89
            elif pos == "PRON":
                sink = 0.82
            elif pos == "PROPN":
                sink = 0.83
            elif pos == "NOUN":
                sink = 0.72
            elif pos in ("DET", "ADP", "PART"):
                sink = 0.70
            elif pos in ("ADJ", "ADV"):
                sink = 0.80
            elif pos in ("CCONJ", "SCONJ"):
                sink = 0.79
            elif pos == "PUNCT":
                sink = 0.77

            if dep in ("nsubj", "nsubjpass", "csubj", "csubjpass"):
                sink = max(sink, 0.90)
            elif dep in ("ROOT", "conj") and pos in ("VERB", "AUX"):
                sink = max(sink, 0.91)
            elif dep in ("dobj", "obj", "pobj", "poss"):
                sink -= 0.04

            if word.is_sent_start:
                sink = max(sink, 0.87)

        if not clean.strip():
            sink = max(sink, 0.85)

        # Opening tokens overwhelmingly select the first-position sink.
        opening_prior = 0.67 + 0.317 * np.exp(-(i - 1) / 5.0)
        sink = float(np.clip(max(sink, opening_prior), 0.60, 0.992))

        # No non-BOS target is identifiable from the supplied edges.
        # Use a conservative, broad causal background rather than a sharp link.
        positions = np.arange(1, i + 1, dtype=np.float64)
        residual = 0.65 / i + 0.35 * (
            np.exp(-(i - positions) / 6.0)
            / np.exp(-(i - positions) / 6.0).sum()
        )
        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual

    return "bos_sink_with_clause_modulation", attention


def prog_L5H23(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with an early-position boost and weak linguistic modulation.
    Residual attention is causal, mostly local, with a small syntactic preference.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_residual", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, indices in enumerate(aligned):
        for k in indices:
            inverse[k].append(i)

    attention[0, 0] = 1.0

    for i in range(1, n):
        position_boost = np.exp(-(i - 1) / 4.5)
        sink_mass = 0.82 + 0.16 * position_boost
        adjustment = 0.0
        word = None

        if aligned[i]:
            word = doc[aligned[i][-1]]
            if word.pos_ in ("NOUN", "PROPN"):
                adjustment += 0.055
            elif word.pos_ == "ADJ":
                adjustment += 0.025
            elif word.pos_ in ("VERB", "AUX"):
                adjustment -= 0.035
            elif word.pos_ in ("ADP", "PART"):
                adjustment -= 0.055
            elif word.pos_ in ("CCONJ", "SCONJ"):
                adjustment -= 0.12
            elif word.pos_ in ("PUNCT", "SPACE"):
                adjustment -= 0.15

            if word.ent_type_:
                adjustment += 0.025
            if word.dep_ in ("nsubj", "nsubjpass", "dobj", "pobj"):
                adjustment += 0.015

        sink_mass += (1.0 - position_boost) * adjustment
        sink_mass = float(np.clip(sink_mass, 0.55, 0.985))

        positions = np.arange(1, i + 1)
        residual = 0.15 + np.exp(-(i - positions) / 3.0)
        residual[-1] += 0.35
        if i > 1:
            residual[-2] += 0.45

        if word is not None:
            for j in inverse[word.head.i]:
                if 1 <= j <= i:
                    residual[j - 1] += 0.35

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * residual / residual.sum()
        )

    return "bos_sink_with_local_residual", attention


def prog_L6H0(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, strongest near the start and on descriptive content;
    residual attention is weak and locally distributed."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_content_bias", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    attention[0, 0] = 1.0
    for i in range(1, n):
        aligned = alignment[i]
        word = max(
            (doc[k] for k in aligned),
            key=lambda w: (not w.is_space, not w.is_punct, len(w.text)),
            default=None,
        )

        base = 0.82
        if word is not None:
            if word.pos_ in ("NOUN", "PROPN"):
                base = 0.90
            elif word.pos_ == "ADJ":
                base = 0.89
            elif word.pos_ == "VERB":
                base = 0.84
            elif word.pos_ in ("AUX", "ADV", "NUM"):
                base = 0.83
            elif word.pos_ in ("DET", "ADP", "PART"):
                base = 0.79
            elif word.pos_ in ("PRON", "CCONJ", "SCONJ"):
                base = 0.76
            elif word.is_punct:
                base = 0.62
            elif word.is_space:
                base = 0.70

            if word.ent_type_:
                base = min(0.94, base + 0.015)

        sink_mass = base + (0.987 - base) * np.exp(-(i - 1) / 2.2)
        attention[i, 0] = sink_mass

        # The examples constrain the sink, not the precise residual targets.
        # Use a conservative mixture of diffuse causal and recent attention.
        positions = np.arange(1, i + 1)
        residual = 0.55 / i + 0.45 * (
            np.exp(-(i - positions) / 3.0)
            / np.exp(-(i - positions) / 3.0).sum()
        )
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_content_bias", attention


def prog_L6H1(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with a small, recency-biased causal residual.
    Sink dominance weakens slightly with distance from the sequence start.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_causal_residual", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        sink_mass = 0.995 - 0.020 * (1.0 - np.exp(-(i - 1) / 20.0))
        positions = np.arange(1, i + 1)
        residual = np.exp(-(i - positions) / 4.0)
        residual /= residual.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_causal_residual", attention


def prog_L6H2(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink: dominant first-token attention with mild positional decay.
    Residual attention is diffuse and weakly biased toward recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_diffuse_recency", attention

    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.80 + 0.11 * np.exp(-(i - 1) / 18.0)

        positions = np.arange(1, i + 1, dtype=np.float64)
        recent = np.exp(-(i - positions) / 5.0)
        recent /= recent.sum()
        residual = 0.65 / i + 0.35 * recent

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_diffuse_recency", attention


def prog_L6H3(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with mildly position-dependent strength.
    A weak causal recency prior approximates the unobserved residual attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_weak_recency", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.82 - 0.13 * (1.0 - np.exp(-(i - 1) / 28.0))

        aligned = alignment[i]
        if aligned:
            pos = doc[aligned[0]].pos_
            if pos in ("NOUN", "PROPN", "ADJ"):
                sink_mass += 0.025
            elif pos == "PUNCT":
                sink_mass -= 0.045
            elif pos in ("PART", "SCONJ"):
                sink_mass -= 0.015

        sink_mass = float(np.clip(sink_mass, 0.62, 0.88))
        attention[i, 0] = sink_mass

        distances = i - np.arange(1, i + 1, dtype=np.float64)
        recency = np.exp(-distances / 5.0)
        recency /= recency.sum()
        residual = 0.55 * recency + 0.45 / i
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_weak_recency", attention


def prog_L6H4(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with position-dependent decay and a secondary
    preference for earlier subject/entity anchors and syntactic context.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_subject_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for ti, indices in enumerate(alignment):
        for si in indices:
            inverse[si].append(ti)

    attention[0, 0] = 1.0
    anchor_strength = np.zeros(n, dtype=np.float64)

    for j in range(1, n):
        for si in alignment[j]:
            word = doc[si]
            strength = 0.0
            if word.dep_ in ("nsubj", "nsubjpass", "csubj"):
                strength = 2.6
            elif word.pos_ == "PROPN" or word.ent_type_:
                strength = 1.5
            elif word.pos_ in ("NOUN", "PRON"):
                strength = 0.5
            # Share an anchor's mass across any constituent subword tokens.
            anchor_strength[j] += strength / max(1, len(inverse[si]))

    for i in range(1, n):
        clean = tokens[i].replace("Ġ", " ").replace("Ċ", "\n").strip()
        indices = alignment[i]
        word = doc[indices[-1]] if indices else None

        logit = 4.05 - 0.29 * min(i - 1, 10)
        logit -= 0.022 * max(i - 11, 0)

        if word is not None:
            if word.pos_ in ("CCONJ", "SCONJ"):
                logit += 0.65
            elif word.pos_ in ("ADP", "AUX"):
                logit += 0.22
            elif word.pos_ in ("NOUN", "PROPN"):
                logit -= 0.30
            elif word.pos_ in ("VERB", "ADJ"):
                logit -= 0.38

            if word.dep_ in ("nsubj", "nsubjpass", "csubj"):
                logit += 0.20
            if i <= 8 and word.dep_ in ("prep", "pobj", "advmod", "det"):
                logit += 0.30

        if not clean:
            logit += 0.45
        elif all(not c.isalnum() for c in clean):
            logit += 0.80
            if i == n - 1:
                logit += 0.75

        sink_mass = float(np.clip(1.0 / (1.0 + np.exp(-logit)), 0.18, 0.992))
        if i == 1:
            sink_mass = 0.985

        positions = np.arange(1, i + 1)
        weights = 0.12 * np.exp(-(i - positions) / 5.0)
        weights += anchor_strength[1:i + 1] * np.exp(-(positions - 1) / 24.0)
        weights[-1] += 0.08

        # Only already-visible dependency heads may receive additional mass.
        if word is not None and word.head.i != word.i:
            for j in inverse[word.head.i]:
                if 0 < j < i:
                    weights[j - 1] += 0.45

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * weights / weights.sum()

    return "bos_sink_with_subject_anchors", attention


def prog_L6H5(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with a strong early-position bias.
    Residual attention favors recent tokens and local syntactic context.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_syntax", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = align_spacy_to_tokens(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        word = None
        if alignment[i]:
            word = doc[alignment[i][-1]]

        # The sink remains dominant far beyond the initial few positions.
        early = np.exp(-(i - 1) / 3.0)
        correction = 0.0
        if word is not None:
            if word.pos_ in ("NOUN", "PROPN"):
                correction += 0.10
            elif word.pos_ == "ADJ":
                correction += 0.07
            elif word.pos_ in ("PRON", "AUX", "PART"):
                correction -= 0.07
            elif word.pos_ in ("CCONJ", "SCONJ"):
                correction -= 0.15
            elif word.pos_ == "PUNCT":
                correction -= 0.13
            if word.ent_type_:
                correction += 0.025

        sink_mass = 0.69 + 0.255 * early + correction * (1.0 - early)
        if tokens[i].isspace():
            sink_mass += 0.06
        sink_mass = np.clip(sink_mass, 0.45, 0.97)

        positions = np.arange(1, i + 1)
        residual = np.exp(-(i - positions) / 3.0)
        residual[-1] *= 0.75

        if word is not None:
            # Dependency links contribute only when their targets are causal.
            if word.head.i != word.i:
                for j in inverse[word.head.i]:
                    if 0 < j <= i:
                        residual[j - 1] += 0.8

            if word.pos_ in ("CCONJ", "SCONJ", "PUNCT") and i > 1:
                residual[i - 2] += 1.5

            # Keep pieces of a split lexical token locally connected.
            for j in inverse[word.i]:
                if 0 < j < i:
                    residual[j - 1] += 0.6

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * residual / residual.sum()
        )

    return "bos_sink_with_local_syntax", make_row_stochastic(attention)


def prog_L6H6(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with stronger early-position concentration.
    Linguistic query features mildly modulate the sink; residual mass is diffuse.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_early_bias", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink = 0.78 + 0.20 * np.exp(-(i - 1) / 2.2)

        # The first content position is dominated by position, not syntax.
        if i > 1:
            linked = alignment[i]
            if linked:
                word = doc[linked[0]]
                if word.pos_ in ("NOUN", "PROPN"):
                    sink += 0.025
                elif word.pos_ in ("PRON", "DET"):
                    sink += 0.012
                elif word.pos_ == "ADJ":
                    sink += 0.008
                if word.ent_type_:
                    sink += 0.008
            elif tokens[i].lstrip("Ġ▁").isspace() or not tokens[i].lstrip("Ġ▁"):
                sink += 0.08

        sink = float(np.clip(sink, 0.65, 0.985))

        positions = np.arange(1, i + 1, dtype=np.float64)
        recency = np.exp(-(i - positions) / 4.0)
        recency /= recency.sum()
        residual = 0.75 / i + 0.25 * recency

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual

    return "bos_sink_with_early_bias", make_row_stochastic(attention)


def prog_L6H7(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, strongest at sequence starts and discourse boundaries.
    Linguistic features modulate sink strength; residual attention is diffuse and causal.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "boundary_modulated_bos_sink", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special_tokens = set(tokenizer.all_special_tokens)
    attention[0, 0] = 1.0

    for i in range(1, n):
        text = tokens[i].replace("\u0120", " ").replace("\u010a", "\n")
        clean = text.strip()
        aligned = alignment[i]
        word = doc[aligned[-1]] if aligned else None
        pos = word.pos_ if word is not None else ""
        dep = word.dep_ if word is not None else ""

        sink = 0.75
        if pos in ("NOUN", "ADJ"):
            sink = 0.66
        elif pos == "PROPN":
            sink = 0.77
        elif pos in ("VERB", "AUX"):
            sink = 0.78
        elif pos == "PRON":
            sink = 0.81
        elif pos in ("DET", "ADP", "PART"):
            sink = 0.74
        elif pos in ("CCONJ", "SCONJ", "ADV"):
            sink = 0.77

        if dep in ("nsubj", "nsubjpass", "csubj"):
            sink += 0.025
        if dep in ("ROOT", "conj", "advcl", "ccomp"):
            sink += 0.025

        is_punctuation = bool(clean) and all(
            not c.isalnum() for c in clean
        )
        if is_punctuation or pos == "PUNCT":
            sink = 0.87
        if not clean:
            sink = 0.89
        if tokens[i] in special_tokens:
            sink = 0.92

        if i == 1:
            sink = 0.98
            if pos == "DET":
                sink = 0.945
            elif pos in ("ADP", "ADV", "NUM", "SCONJ"):
                sink = 0.963
        elif i == 2:
            sink = max(sink, 0.89 if pos in ("VERB", "AUX") else 0.84)
        elif i == 3:
            sink = max(sink, 0.79)

        if word is not None and word.is_sent_start and i > 1:
            sink = max(sink, 0.84)

        sink = float(np.clip(sink, 0.58, 0.995))
        attention[i, 0] = sink

        # No non-BOS target is established by the observations: spread the
        # remaining mass with only a weak recency bias.
        distances = i - np.arange(1, i + 1, dtype=np.float64)
        residual = 0.6 + 0.4 * np.exp(-distances / 8.0)
        attention[i, 1:i + 1] = (1.0 - sink) * residual / residual.sum()

    return "boundary_modulated_bos_sink", attention


def prog_L6H8(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, strongest near sequence/clause starts.
    Residual attention is diffuse and recency-biased, with weak syntactic support.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_residual", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        word = None
        if alignment[i]:
            word = doc[alignment[i][0]]

        sink_mass = 0.74 + 0.235 * np.exp(-(i - 1) / 3.0)

        if word is not None:
            if word.pos_ == "VERB":
                sink_mass += 0.045
            elif word.pos_ == "AUX":
                sink_mass -= 0.055
            elif word.pos_ in ("ADP", "PART"):
                sink_mass -= 0.035

            if word.dep_ in ("dobj", "obj", "pobj", "attr"):
                sink_mass -= 0.04

            # Clause openings often restore the strong sink preference.
            if word.is_sent_start:
                sink_mass += 0.09
            elif word.i > 0 and doc[word.i - 1].is_punct:
                sink_mass += 0.045

            if word.is_punct and word.text in (".", "!", "?", '!"', '?"'):
                sink_mass -= 0.10
        elif tokens[i].isspace() or tokens[i] == "Ġ":
            sink_mass += 0.10

        if i == 1:
            sink_mass = 0.98

        sink_mass = float(np.clip(sink_mass, 0.52, 0.99))

        positions = np.arange(1, i + 1)
        residual = 0.25 + np.exp(-(i - positions) / 4.0)

        # Keep syntax subordinate to the overwhelming positional sink.
        if word is not None:
            for j in range(1, i + 1):
                if alignment[j] and word.head.i in alignment[j]:
                    residual[j - 1] += 0.25

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * residual / residual.sum()
        )

    return "bos_sink_with_local_residual", attention


def prog_L6H9(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, strongest in opening phrases, with residual attention
    to nearby subjects and possessors, especially at predicates."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    matrix = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_subject_residual", matrix

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for ti, indices in enumerate(alignment):
        for si in indices:
            if si < len(doc):
                inverse[si].append(ti)

    matrix[0, 0] = 1.0
    first_predicate = n
    for i in range(1, n):
        if any(doc[k].pos_ in ("VERB", "AUX") for k in alignment[i]):
            first_predicate = i
            break

    for i in range(1, n):
        word = doc[alignment[i][-1]] if alignment[i] else None
        pos = word.pos_ if word is not None else ""
        dep = word.dep_ if word is not None else ""

        sink = {
            "DET": 0.71, "PRON": 0.65, "PROPN": 0.73,
            "NOUN": 0.65, "ADJ": 0.61, "ADV": 0.53,
            "ADP": 0.59, "AUX": 0.66, "VERB": 0.43,
            "CCONJ": 0.58, "SCONJ": 0.52, "PUNCT": 0.48,
            "NUM": 0.65, "PART": 0.51,
        }.get(pos, 0.64)

        if dep in ("nsubj", "nsubjpass", "csubj"):
            sink += 0.07
        if dep in ("poss", "det"):
            sink += 0.03
        if dep in ("acomp", "attr", "oprd"):
            sink -= 0.15

        # Opening scene-setting phrases mostly ignore lexical predecessors.
        if i < first_predicate:
            opening = 0.57 + 0.40 * np.exp(-0.085 * (i - 1))
            sink = max(sink, opening)
        elif i <= 3 and pos == "AUX":
            sink = max(sink, 0.85 - 0.035 * (i - 2))
        elif i == 2 and pos == "VERB":
            sink = max(sink, 0.64)

        if i == 1:
            sink = 0.94 if pos == "PRON" else 0.955

        raw = tokens[i]
        if not raw.lstrip("\u0120").strip():
            sink = max(sink, 0.75)

        if word is not None and word.is_sent_start and i > 1:
            sink = max(sink, 0.79)

        targets = []
        if word is not None:
            governors = [word]
            if pos in ("AUX", "ADJ", "ADV", "CCONJ"):
                governors.append(word.head)

            for governor in governors:
                for child in governor.children:
                    if child.dep_ in ("nsubj", "nsubjpass", "csubj"):
                        eligible = [j for j in inverse[child.i] if 0 < j < i]
                        if eligible:
                            targets.append((eligible[-1], 1.0))

            if pos in ("NOUN", "PROPN"):
                for child in word.children:
                    if child.dep_ == "poss":
                        eligible = [j for j in inverse[child.i] if 0 < j < i]
                        if eligible:
                            targets.append((eligible[-1], 1.5))
                            sink = min(sink, 0.40)

        if targets and pos in ("VERB", "ADJ"):
            nearest = max(j for j, _ in targets)
            if i - nearest <= 4:
                sink = min(sink, 0.36 if pos == "ADJ" else 0.43)

        sink = float(np.clip(sink, 0.18, 0.98))

        # Allocate the non-sink mass causally, retaining a modest local tail.
        js = np.arange(1, i + 1)
        residual = np.exp(-(i - js) / 4.0)
        residual[-1] *= 0.40
        residual /= residual.sum()

        if targets:
            residual *= 0.28
            total = sum(weight for _, weight in targets)
            for j, weight in targets:
                residual[j - 1] += 0.72 * weight / total

        matrix[i, 0] = sink
        matrix[i, 1:i + 1] = (1.0 - sink) * residual

    return "bos_sink_with_subject_residual", make_row_stochastic(matrix)


def prog_L6H10(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with position-dependent dilution.
    Linguistic features weakly modulate a diffuse, mildly recency-biased remainder.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_positional_dilution", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    pos = [
        doc[indices[0]].pos_ if indices else ""
        for indices in alignment
    ]

    attention[0, 0] = 1.0
    for i in range(1, n):
        # A roughly constant per-token background competes with the sink,
        # explaining its gradual dilution as the causal context grows.
        competition = 0.024 * i
        correction = 0.0
        if pos[i] == "PRON":
            correction = 0.12
        elif pos[i] == "AUX":
            correction = 0.08
        elif pos[i] in ("NOUN", "PROPN"):
            correction = 0.04
        elif pos[i] == "VERB":
            correction = -0.10
        elif pos[i] in ("ADJ", "ADV"):
            correction = -0.05

        if i == 1 and pos[i] == "DET":
            correction -= 0.80

        sink_mass = 1.0 / (1.0 + competition * np.exp(-correction))

        distances = i - np.arange(1, i + 1, dtype=np.float64)
        background = 0.75 + 0.25 * np.exp(-distances / 8.0)
        for j in range(1, i + 1):
            if pos[j] == "PUNCT":
                background[j - 1] *= 0.85

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * background / background.sum()
        )

    return "bos_sink_with_positional_dilution", attention


def prog_L6H11(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, strongest near the start, with mild POS modulation.
    Remaining attention follows a diffuse causal recency prior.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_position_decay", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        # A persistent sink plus a rapidly fading initial-position bonus.
        early_bonus = np.exp(-((i - 1) / 4.5) ** 1.35)
        sink_mass = 0.60 + 0.365 * early_bonus

        aligned = alignment[i]
        if aligned:
            word = doc[aligned[0]]
            correction = 0.0
            if word.pos_ in ("NOUN", "PROPN"):
                correction = 0.035
            elif word.pos_ in ("PRON", "CCONJ", "SCONJ"):
                correction = -0.025
            elif word.pos_ == "PUNCT":
                correction = -0.09
            elif word.pos_ == "ADJ":
                correction = 0.015
            sink_mass += (1.0 - early_bonus) * correction
        elif tokens[i].isspace():
            sink_mass -= 0.06 * (1.0 - early_bonus)

        sink_mass = float(np.clip(sink_mass, 0.40, 0.985))
        attention[i, 0] = sink_mass

        # No non-BOS destination is established by the supplied edges.
        # Use a conservative mixture of uniform and local causal attention.
        distances = i - np.arange(1, i + 1)
        recent = np.exp(-distances / 5.0)
        recent /= recent.sum()
        residual = 0.5 / i + 0.5 * recent
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_position_decay", make_row_stochastic(attention)


def prog_L6H12(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with a local prepositional-phrase anchor.
    Nominal complements shift some BOS mass to their introducing preposition.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_pp_anchor", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, indices in enumerate(aligned):
        for k in indices:
            inverse[k].append(i)

    attention[0, 0] = 1.0
    for i in range(1, n):
        word = None
        if aligned[i]:
            word = doc[aligned[i][-1]]

        baseline = 0.77
        if word is not None:
            if word.pos_ == "VERB":
                baseline += 0.09
            elif word.pos_ in ("ADJ", "ADV"):
                baseline += 0.055
            elif word.pos_ in ("CCONJ", "SCONJ", "AUX"):
                baseline += 0.025
            elif word.pos_ in ("DET", "PRON"):
                baseline -= 0.075
            elif word.pos_ in ("NOUN", "PROPN"):
                baseline -= 0.045

            if word.dep_ in ("dobj", "obj", "pobj", "poss"):
                baseline -= 0.045
            if word.dep_ == "ROOT":
                baseline += 0.025

        clean = tokens[i].replace("Ġ", " ").replace("Ċ", "\n").strip()
        if not clean:
            baseline = 0.77
        elif any(c in clean for c in ('"', "“", "”")):
            baseline += 0.045

        # The first few query positions exhibit especially strong sink mass.
        early = np.exp(-(i - 1) / 1.8)
        sink_mass = float(np.clip(
            baseline + (0.99 - baseline) * early, 0.55, 0.995
        ))

        positions = np.arange(1, i + 1)
        residual = 0.35 / i + 0.65 * np.exp(-(i - positions) / 5.0)

        if word is not None and word.head.i != word.i:
            head_positions = [j for j in inverse[word.head.i] if 0 < j <= i]
            if head_positions:
                residual[head_positions[-1] - 1] += 0.2

        residual /= residual.sum()
        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

        # Only verb-attached PP complements receive this correction.
        # Transfer BOS mass directly, preserving self and all other edges.
        if word is not None and word.pos_ in (
            "DET", "PRON", "ADJ", "NOUN", "PROPN"
        ):
            anchor = word
            for _ in range(4):
                if anchor.head.i == anchor.i:
                    break
                anchor = anchor.head
                if anchor.pos_ == "ADP":
                    break
                if anchor.pos_ not in ("NOUN", "PROPN", "PRON", "ADJ"):
                    break

            if (
                anchor.pos_ == "ADP"
                and anchor.head.pos_ in ("VERB", "AUX")
                and 0 < word.i - anchor.i <= 4
            ):
                anchor_positions = [
                    j for j in inverse[anchor.i] if 0 < j < i
                ]
                if anchor_positions:
                    amount = (
                        0.26 if word.pos_ in ("DET", "PRON")
                        else 0.29 if word.pos_ == "ADJ"
                        else 0.22
                    )
                    amount = min(amount, attention[i, 0])
                    attention[i, 0] -= amount
                    attention[i, anchor_positions[-1]] += amount

    return "bos_sink_with_pp_anchor", attention


def prog_L6H13(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with a mild positional decline and linguistic modulation.
    Remaining attention is diffuse and weakly biased toward recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_diffuse_residual", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.81 + 0.16 * np.exp(-(i - 1) / 12.0)
        aligned = alignment[i]
        pos = {doc[k].pos_ for k in aligned}
        deps = {doc[k].dep_ for k in aligned}

        if i > 1:
            if not tokens[i].lstrip("Ġ▁").strip():
                sink_mass += 0.045
            elif "PUNCT" in pos:
                sink_mass += 0.025
            elif "CCONJ" in pos:
                sink_mass += 0.035
            elif "DET" in pos or "ADP" in pos:
                sink_mass += 0.015
            elif "PRON" in pos and "poss" not in deps:
                sink_mass -= 0.025

        sink_mass = float(np.clip(sink_mass, 0.72, 0.985))
        attention[i, 0] = sink_mass

        positions = np.arange(1, i + 1)
        residual = 0.5 + np.exp(-(i - positions) / 8.0)
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * residual / residual.sum()
        )

    return "bos_sink_with_diffuse_residual", attention


def prog_L6H14(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with a short-lived opening-quotation anchor.
    Inside quotations, redirect only BOS mass; preserve self-attention exactly.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_quote_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0
    quote_anchor = None

    for i in range(1, n):
        words = [doc[k] for k in alignment[i]]
        pos = {word.pos_ for word in words}
        deps = {word.dep_ for word in words}
        surface = tokens[i].replace("\u0120", " ").replace("\u010a", "\n")

        maturation = 1.0 - np.exp(-i / 5.0)
        sink = 0.52 + 0.44 * np.exp(-(i - 1) / 5.0)

        if surface.isspace():
            sink += 0.24 * maturation
        elif "PUNCT" in pos or (
            surface.strip()
            and all(not char.isalnum() for char in surface.strip())
        ):
            sink += 0.17 * maturation
        elif pos & {"CCONJ", "SCONJ"}:
            sink += 0.12 * maturation
        elif pos & {"AUX", "PRON"}:
            sink += 0.045 * maturation
        elif pos & {"NOUN", "PROPN", "ADJ"}:
            sink -= 0.035 * maturation

        if deps & {"mark", "cc"}:
            sink += 0.025 * maturation

        if i == 1:
            sink = 0.983
        sink = float(np.clip(sink, 0.35, 0.99))

        positions = np.arange(1, i + 1)
        recent = np.exp(-(i - positions) / 5.0)
        recent /= recent.sum()
        residual = 0.65 / i + 0.35 * recent

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual

        # Quoted speech temporarily uses its opening delimiter as a second sink.
        # This transfer leaves the diagonal and every other destination untouched.
        if any(char in surface for char in "“«"):
            quote_anchor = i
        elif any(char in surface for char in "”»"):
            quote_anchor = None
        elif '"' in surface:
            if quote_anchor is not None:
                quote_anchor = None
            elif not any(char in surface for char in ".!?"):
                quote_anchor = i
        elif quote_anchor is not None:
            distance = i - quote_anchor
            if 1 <= distance <= 6:
                transfer = min(
                    0.25 * np.exp(-(distance - 1) / 5.0),
                    0.60 * attention[i, 0],
                )
                attention[i, 0] -= transfer
                attention[i, quote_anchor] += transfer

    return "bos_sink_with_quote_anchors", make_row_stochastic(attention)


def prog_L6H15(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with an early-position boost and boundary sensitivity.
    Residual attention mixes self, recency, and weak syntactic/entity links.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_boundary_and_recency", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    words = []
    for ids in alignment:
        candidates = [doc[k] for k in ids if not doc[k].is_space]
        words.append(candidates[-1] if candidates else None)

    attention[0, 0] = 1.0
    quote_seen = False

    for i in range(1, n):
        text = tokens[i].replace("Ġ", " ").replace("Ċ", "\n").strip()
        word = words[i]
        pos = word.pos_ if word is not None else ""
        is_quote = any(c in text for c in "\"“”«»")
        is_space = not text

        # The first position acts as a sink, rather than a semantic target.
        sink = 0.36 + 0.55 * np.exp(-(i - 1) / 4.0)
        if quote_seen:
            sink += 0.055

        if pos == "DET":
            sink += 0.025
        elif pos in ("ADP", "AUX", "CCONJ", "SCONJ", "PART"):
            sink += 0.035
        elif pos in ("NOUN", "PROPN"):
            sink -= 0.025
        elif pos == "ADV":
            sink += 0.015

        boundary_scale = 1.0 - 0.5 * np.exp(-(i - 1) / 3.0)
        if is_quote:
            sink += 0.19 * boundary_scale
        elif is_space:
            sink += 0.21 * boundary_scale
        elif pos == "PUNCT":
            sink += 0.12 * boundary_scale

        sink = float(np.clip(sink, 0.22, 0.95))

        # Diffuse causal background, with modest self and local preferences.
        previous = np.arange(1, i + 1)
        distance = i - previous
        weights = 0.12 + np.exp(-distance / 3.5)

        for offset, j in enumerate(previous):
            prior = words[j]
            if prior is None:
                continue
            if prior.pos_ in ("NOUN", "PROPN"):
                weights[offset] += 0.22
            if (
                word is not None
                and j < i
                and prior.i == word.head.i
                and prior.i != word.i
            ):
                weights[offset] += 0.55

        weights[-1] += 1.0

        # A weak antecedent preference supplements the sink for pronouns.
        if pos == "PRON":
            candidates = [
                j for j in range(1, i)
                if words[j] is not None
                and words[j].pos_ in ("NOUN", "PROPN")
                and (word is None or words[j].i != word.i)
            ]
            if candidates:
                target = candidates[-1]
                weights[target - 1] += 1.3

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * weights / weights.sum()
        quote_seen = quote_seen or is_quote

    return "bos_sink_with_boundary_and_recency", make_row_stochastic(attention)


def prog_L6H16(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, strongest for content tokens and early positions.
    Residual attention is diffuse and mildly recency-biased.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_content_modulated", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    pos_prior = {
        "NOUN": 0.83,
        "PROPN": 0.85,
        "ADJ": 0.85,
        "NUM": 0.79,
        "VERB": 0.70,
        "AUX": 0.69,
        "ADV": 0.66,
        "ADP": 0.70,
        "DET": 0.69,
        "PRON": 0.60,
        "PART": 0.57,
        "CCONJ": 0.55,
        "SCONJ": 0.58,
        "PUNCT": 0.59,
        "SPACE": 0.55,
        "INTJ": 0.69,
        "X": 0.72,
    }

    attention[0, 0] = 1.0

    for i in range(1, n):
        aligned = alignment[i]
        if aligned:
            word = doc[aligned[-1]]
            sink_mass = pos_prior.get(word.pos_, 0.70)

            if word.ent_type_:
                sink_mass += 0.025

            # Later tokens have more alternatives to the attention sink.
            sink_mass -= 0.13 * (1.0 - np.exp(-(i - 1) / 24.0))
            sink_mass += 0.09 * np.exp(-(i - 1) / 3.5)

            # Later pronominal and connective material is less sink-dominated.
            if word.dep_ in ("cc", "mark", "aux", "auxpass"):
                sink_mass -= 0.035
        else:
            sink_mass = 0.57 - 0.07 * (1.0 - np.exp(-i / 24.0))

        if i == 1:
            sink_mass = 0.85

        sink_mass = float(np.clip(sink_mass, 0.40, 0.92))
        attention[i, 0] = sink_mass

        # No non-BOS target is supported by the examples; use a conservative
        # diffuse causal background rather than inventing syntactic edges.
        positions = np.arange(1, i + 1, dtype=np.float64)
        distances = i - positions
        residual = 0.65 / i + 0.35 * np.exp(-distances / 6.0)
        residual /= residual.sum()
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_content_modulated", attention


def prog_L6H17(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with pronominal residual attention.
    At sentence boundaries, release some sink mass to preceding content, preserving self-attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_boundary_release", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    words = []
    for indices in alignment:
        candidates = [doc[k] for k in indices if not doc[k].is_space]
        words.append(candidates[-1] if candidates else None)

    attention[0, 0] = 1.0
    for i in range(1, n):
        word = words[i]
        pos = word.pos_ if word is not None else ""
        early = np.exp(-(i - 1) / 12.0)

        if i == 1:
            sink = 0.95
        elif pos in ("NOUN", "PROPN"):
            sink = 0.86 + 0.09 * early
        elif pos == "ADJ":
            sink = 0.77 + 0.16 * early
        elif pos in ("VERB", "AUX"):
            sink = 0.64 + 0.24 * early
        elif pos in ("DET", "ADP", "NUM"):
            sink = 0.69 + 0.24 * early
        elif pos == "PRON":
            sink = 0.56 + 0.27 * early
        elif pos in ("PUNCT", "CCONJ", "SCONJ", "PART", "ADV"):
            sink = 0.57 + 0.25 * early
        else:
            sink = 0.76 + 0.15 * early

        residual = np.zeros(i + 1, dtype=np.float64)
        positions = np.arange(1, i + 1)
        residual[1:] = np.exp(-(i - positions) / 3.0)

        antecedents = np.zeros(i + 1, dtype=np.float64)
        if pos == "PRON" and word is not None:
            seen = set()
            for j in range(i - 1, 0, -1):
                candidate = words[j]
                if candidate is None or candidate.i in seen:
                    continue
                seen.add(candidate.i)
                if candidate.i >= word.i:
                    continue
                if candidate.pos_ not in ("NOUN", "PROPN"):
                    continue

                number = word.morph.get("Number")
                candidate_number = candidate.morph.get("Number")
                compatibility = 1.0
                if number and candidate_number and number != candidate_number:
                    compatibility *= 0.15
                if word.morph.get("Gender") and candidate.ent_type_ == "PERSON":
                    compatibility *= 1.4
                if candidate.dep_ in ("nsubj", "nsubjpass", "dobj", "obj", "pobj"):
                    compatibility *= 1.3
                antecedents[j] = compatibility * np.exp(-(i - j) / 18.0)

        if antecedents.sum() > 0:
            sink = max(0.38, sink - 0.12)
            residual /= residual.sum()
            antecedents /= antecedents.sum()
            residual = 0.30 * residual + 0.70 * antecedents
        else:
            residual /= residual.sum()

        attention[i, :i + 1] = (1.0 - sink) * residual
        attention[i, 0] = sink

        # Boundary-only correction: transfer BOS mass, never self-attention.
        if pos == "PUNCT" and any(mark in tokens[i] for mark in (".", "!", "?")):
            boundary = np.zeros(i, dtype=np.float64)
            seen = set()
            nearest = None
            for j in range(i - 1, 0, -1):
                candidate = words[j]
                if candidate is None or candidate.i in seen:
                    continue
                seen.add(candidate.i)
                if candidate.i >= word.i:
                    continue
                if candidate.pos_ not in ("NOUN", "PROPN", "VERB", "ADJ", "ADP"):
                    continue
                if nearest is None:
                    nearest = candidate
                boundary[j] = np.exp(-(i - j) / 3.0)

            if boundary.sum() > 0:
                fraction = 0.65 if nearest.pos_ == "VERB" else 0.35
                released = fraction * attention[i, 0]
                attention[i, 0] -= released
                attention[i, :i] += released * boundary / boundary.sum()

    return "bos_sink_with_boundary_release", attention


def prog_L6H18(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Dominant first-token attention sink, with mild positional weakening.
    Model the small unresolved remainder using a causal recency prior.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "first_token_sink", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        sink_mass = (
            0.985
            - 0.09 * (1.0 - np.exp(-i / 30.0))
            - 0.035 * np.exp(-(i - 1) / 1.5)
        )

        distances = i - np.arange(1, i + 1, dtype=np.float64)
        residual = 0.25 / i + 0.75 * (
            np.exp(-distances / 4.0)
            / np.exp(-distances / 4.0).sum()
        )

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "first_token_sink", attention


def prog_L6H19(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with a small, length-growing causal background.
    Residual attention is diffuse, with a weak recency preference.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_diffuse_background", attention

    attention[0, 0] = 1.0

    for i in range(1, n):
        # The examples support a positional sink, not a linguistic target.
        background_mass = min(0.15, 0.009 + 0.0011 * i)
        distances = i - np.arange(1, i + 1)
        recency = np.exp(-distances / 5.0)
        recency /= recency.sum()
        background = 0.8 / i + 0.2 * recency

        attention[i, 0] = 1.0 - background_mass
        attention[i, 1:i + 1] = background_mass * background

    return "bos_sink_with_diffuse_background", attention


def prog_L6H20(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention-sink head with an early-position boost.
    Residual attention is diffuse and mildly recency-biased, not strongly syntactic.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_position_decay", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        early_boost = np.exp(-(i - 1) / 3.5)
        sink_mass = 0.79 + 0.18 * early_boost

        # Small linguistic corrections; the sink remains the dominant target.
        aligned = alignment[i]
        if aligned:
            word = doc[aligned[-1]]
            correction = 0.0
            if word.pos_ in ("NOUN", "PROPN", "VERB", "AUX", "ADP"):
                correction = 0.025
            elif word.pos_ in ("PUNCT", "CCONJ", "SCONJ"):
                correction = -0.045
            elif word.pos_ in ("DET", "PART"):
                correction = -0.02
            sink_mass += (1.0 - early_boost) * correction

        sink_mass = float(np.clip(sink_mass, 0.65, 0.985))
        attention[i, 0] = sink_mass

        positions = np.arange(1, i + 1)
        residual = 0.65 / i + 0.35 * np.exp(-(i - positions) / 4.0)
        residual /= residual.sum()
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_position_decay", attention


def prog_L6H21(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with weak, recency-biased causal leakage.
    Sink dominance gradually decreases as the available context grows.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_recency_leakage", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        sink_mass = 0.985 - 0.0015 * min(i - 1, 80)
        attention[i, 0] = sink_mass

        distances = i - np.arange(1, i + 1)
        residual = 0.75 * np.exp(-distances / 4.0) + 0.25
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * residual / residual.sum()
        )

    return "bos_sink_with_recency_leakage", attention


def prog_L6H22(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, with a small causal recency/syntax residual.
    Function words and punctuation have somewhat weaker sink preference.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_weak_local_structure", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, word_ids in enumerate(alignment):
        for word_id in word_ids:
            inverse[word_id].append(i)

    attention[0, 0] = 1.0

    for i in range(1, n):
        word = doc[alignment[i][0]] if alignment[i] else None
        sink_mass = 0.965

        if word is not None:
            if word.pos_ == "DET":
                sink_mass = 0.982
            elif word.pos_ in ("NOUN", "PROPN", "ADJ"):
                sink_mass = 0.970
            elif word.pos_ in ("AUX", "CCONJ", "SCONJ"):
                sink_mass = 0.900
            elif word.pos_ in ("PRON", "ADP", "PART"):
                sink_mass = 0.940
            elif word.is_punct:
                sink_mass = 0.850

        # The first ordinary token has only itself and the sink available.
        if i == 1:
            sink_mass = 0.975

        residual = np.zeros(i, dtype=np.float64)
        positions = np.arange(1, i + 1)
        residual[:] = 0.12 / i
        residual += np.exp(-(i - positions) / 2.0)

        if word is not None:
            # Add only causally available syntactic links.
            for j in inverse[word.head.i]:
                if 0 < j <= i and word.head.i != word.i:
                    residual[j - 1] += 0.7

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * residual / residual.sum()
        )

    return "bos_sink_with_weak_local_structure", attention


def prog_L6H23(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with an early-position boost and syntactic modulation.
    Residual attention is diffuse, mildly favoring recent tokens and syntactic heads.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_syntax_modulated", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, indices in enumerate(alignment):
        for k in indices:
            inverse[k].append(i)

    attention[0, 0] = 1.0
    for i in range(1, n):
        indices = alignment[i]
        word = None
        if indices:
            word = doc[indices[-1]]

        sink_mass = 0.63 + 0.29 * np.exp(-(i - 1) / 2.8)

        if word is not None:
            if word.pos_ in ("NOUN", "PROPN"):
                sink_mass += 0.10
            elif word.pos_ in ("VERB", "AUX"):
                sink_mass += 0.055
            elif word.pos_ in ("CCONJ", "SCONJ", "PART"):
                sink_mass -= 0.12
            elif word.pos_ == "PUNCT":
                sink_mass -= 0.13
            elif word.pos_ == "ADP":
                sink_mass -= 0.04
            elif word.pos_ == "ADJ":
                sink_mass += 0.015

            if word.dep_ in ("nsubj", "nsubjpass", "ROOT"):
                sink_mass += 0.045
            if word.is_sent_start:
                sink_mass += 0.07
            if word.ent_type_:
                sink_mass += 0.035

        if not tokens[i].strip("Ġ▁ \t\r\n"):
            sink_mass -= 0.08

        sink_mass = float(np.clip(sink_mass, 0.40, 0.95))
        if i == 1:
            sink_mass = 0.97

        positions = np.arange(1, i + 1)
        residual = 0.35 + np.exp(-(i - positions) / 5.0)

        if word is not None:
            for j in inverse[word.head.i]:
                if 0 < j <= i:
                    residual[j - 1] += 0.45

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * residual / residual.sum()
        )

    return "bos_sink_syntax_modulated", attention


def prog_L7H0(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with local context; punctuation redirects predecessor mass
    toward BOS and earlier boundary or syntactic anchors, preserving the diagonal.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_boundary_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        aligned = alignment[i]
        word = doc[aligned[-1]] if aligned else None
        pos = word.pos_ if word is not None else ""
        dep = word.dep_ if word is not None else ""

        # The overwhelming regularity is a largely position-independent sink.
        sink = 0.59 + 0.12 * np.exp(-(i - 1) / 5.0)
        if pos in ("ADJ", "PROPN"):
            sink += 0.055
        elif pos in ("NOUN", "AUX"):
            sink += 0.025
        elif pos in ("ADP", "PART", "SCONJ"):
            sink -= 0.045
        elif pos == "CCONJ":
            sink -= 0.25
        elif pos == "PUNCT":
            sink -= 0.22

        if i == 1:
            sink = 0.78
            if pos in ("PRON", "PROPN"):
                sink += 0.06
            elif pos == "DET":
                sink -= 0.025

        sink = float(np.clip(sink, 0.20, 0.88))

        # Residual mass favors immediate context, with a modest self channel.
        positions = np.arange(1, i + 1)
        local = np.exp(-(i - positions) / 3.0)
        local[-1] *= 0.45
        if i > 1:
            local[-2] += 1.6
            if pos in ("CCONJ", "PUNCT"):
                local[-2] += 3.0

        # A small causal syntactic contribution, never overriding the sink.
        if word is not None and word.head.i != word.i:
            for j in range(1, i):
                if word.head.i in alignment[j]:
                    local[j - 1] += 0.35

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * local / local.sum()

        # Boundary tokens do not inherit the strong predecessor channel.
        # Redistribute only off-diagonal mass; leave the original self weight.
        if pos == "PUNCT" and i > 1:
            anchor = None
            for j in range(i - 2, 0, -1):
                if alignment[j]:
                    previous = doc[alignment[j][-1]]
                    if previous.is_punct and previous.text in (",", ";", ":", ".", "!", "?"):
                        anchor = j
                        break

            if anchor is None and word.head.i != word.i:
                for j in range(i - 2, 0, -1):
                    if word.head.i in alignment[j]:
                        anchor = j
                        break

            fraction = 0.75 if anchor is not None else 0.40
            moved = fraction * attention[i, i - 1]
            attention[i, i - 1] -= moved
            if anchor is None:
                attention[i, 0] += moved
            else:
                attention[i, 0] += 0.60 * moved
                attention[i, anchor] += 0.40 * moved

    return "bos_sink_with_boundary_anchors", make_row_stochastic(attention)


def prog_L7H1(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with a weak local/syntactic residual.
    Content words favor the sink; auxiliaries retain more subject attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_residual", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    word_tokens = [[] for _ in doc]
    for ti, word_ids in enumerate(alignment):
        for wi in word_ids:
            if wi < len(doc):
                word_tokens[wi].append(ti)

    sink_by_pos = {
        "NOUN": 0.69,
        "PROPN": 0.73,
        "ADJ": 0.65,
        "VERB": 0.57,
        "AUX": 0.45,
        "PRON": 0.57,
        "DET": 0.57,
        "ADP": 0.54,
        "ADV": 0.53,
        "PART": 0.54,
        "CCONJ": 0.49,
        "SCONJ": 0.49,
        "NUM": 0.63,
        "PUNCT": 0.57,
    }

    attention[0, 0] = 1.0
    for i in range(1, n):
        word_ids = alignment[i]
        word = doc[word_ids[-1]] if word_ids else None
        sink_mass = sink_by_pos.get(word.pos_, 0.60) if word is not None else 0.60

        if tokens[i].isspace() or not tokens[i].strip("Ġ▁"):
            sink_mass = 0.62

        if i == 1:
            sink_mass = 0.95
        elif i == 2:
            sink_mass = max(sink_mass, 0.73)

        if word is not None:
            pieces = word_tokens[word.i]
            if pieces and i > pieces[0]:
                sink_mass = min(0.80, sink_mass + 0.05)

        # Keep the remaining probability causal, mainly local, and nonzero.
        positions = np.arange(1, i + 1)
        residual = np.exp(-(i - positions) / 3.0)
        residual[-1] *= 0.55

        if word is not None:
            head_pieces = word_tokens[word.head.i]
            earlier_head = [j for j in head_pieces if 0 < j < i]
            if earlier_head:
                residual[earlier_head[-1] - 1] += 0.65

            if word.pos_ == "AUX":
                subjects = [
                    child for child in word.head.children
                    if child.dep_ in ("nsubj", "nsubjpass", "csubj")
                ]
                if word.head.pos_ in ("NOUN", "PROPN", "PRON"):
                    subjects.append(word.head)
                for subject in subjects:
                    earlier = [j for j in word_tokens[subject.i] if 0 < j < i]
                    if earlier:
                        residual[earlier[-1] - 1] += 2.5

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * residual / residual.sum()
        )

    return "bos_sink_with_local_residual", attention


def prog_L7H2(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with gradual positional dilution.
    Residual attention is diffuse and mildly biased toward recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_positional_dilution", attention

    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.98 / (1.0 + 0.004 * i)

        positions = np.arange(1, i + 1)
        residual = 0.25 + np.exp(-(i - positions) / 4.0)
        residual /= residual.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_positional_dilution", attention


def prog_L7H3(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with position-dependent dilution.
    Residual attention favors recent tokens, syntactic anchors, and quote boundaries.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_syntactic_residual", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    representatives = [
        doc[indices[-1]] if indices else None for indices in alignment
    ]

    first_piece = {}
    for i, indices in enumerate(alignment):
        for index in indices:
            if index not in first_piece:
                first_piece[index] = i

    attention[0, 0] = 1.0
    last_quote = None
    for i in range(1, n):
        word = representatives[i]
        pos = word.pos_ if word is not None else ""
        dep = word.dep_ if word is not None else ""
        clean = tokens[i].lstrip("Ġ▁")
        is_quote = any(c in clean for c in ('"', "“", "”", "«", "»"))

        sink = 0.27 + 0.70 * np.exp(-(i - 1) / 22.0)
        if i > 2:
            if pos == "DET":
                sink += 0.075
            elif pos in ("ADJ", "ADV", "CCONJ"):
                sink += 0.045
            elif pos in ("VERB", "AUX"):
                sink -= 0.065
            elif pos == "PRON":
                sink -= 0.085
            if dep in ("dobj", "obj", "pobj"):
                sink -= 0.035

        if word is not None and word.is_sent_start and i > 3:
            sink += 0.15
        if not clean.strip():
            sink += 0.10
        if is_quote:
            sink += 0.035
        sink = float(np.clip(sink, 0.22, 0.985))

        positions = np.arange(1, i + 1)
        weights = 0.20 + np.exp(-(i - positions) / 5.5)

        for j in range(1, i + 1):
            candidate = representatives[j]
            if candidate is None:
                continue
            if candidate.pos_ in ("NOUN", "PROPN"):
                weights[j - 1] += 0.45 * np.exp(-(i - j) / 24.0)
            if candidate.dep_ in ("nsubj", "nsubjpass", "csubj"):
                weights[j - 1] += 1.15 * np.exp(-(i - j) / 28.0)

        if word is not None:
            head_position = first_piece.get(word.head.i)
            if head_position is not None and 0 < head_position < i:
                weights[head_position - 1] += 1.8
            if word.tag_ in ("WDT", "WP", "WP$", "WRB"):
                for j in range(i - 1, 0, -1):
                    candidate = representatives[j]
                    if candidate is not None and candidate.pos_ in ("NOUN", "PROPN"):
                        weights[j - 1] += 3.5
                        sink -= 0.07
                        break

        if last_quote is not None:
            distance = i - last_quote
            if distance <= 12:
                weights[last_quote - 1] += 1.5 * np.exp(-distance / 7.0)

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * weights / weights.sum()
        if is_quote:
            last_quote = i

    return "bos_sink_with_syntactic_residual", attention


def prog_L7H4(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with gradual positional dilution.
    Linguistic features weakly modulate sink strength; residual attention is diffuse.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_positional_dilution", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        aligned = alignment[i]
        word = doc[aligned[0]] if aligned else None
        pos = word.pos_ if word is not None else ""
        dep = word.dep_ if word is not None else ""

        # The first position remains the dominant destination. Additional
        # causal keys gradually dilute its probability as context grows.
        dilution = 0.015 * i ** 0.98

        # Early determiners and nominal/prepositional openings have slightly
        # weaker sink attention than pronominal openings.
        early = np.exp(-(i - 1) / 4.0)
        if pos == "DET":
            dilution *= 1.0 + 1.45 * early
        elif pos in ("NOUN", "PROPN", "ADP"):
            dilution *= 1.0 + 0.65 * early

        if pos in ("CCONJ", "SCONJ"):
            dilution *= 0.80
        elif pos == "PUNCT":
            dilution *= 0.85
        elif dep in ("mark", "cc"):
            dilution *= 0.85

        if tokens[i].isspace() or tokens[i].strip("ĠĊ") == "":
            dilution *= 0.80

        sink_probability = 1.0 / (1.0 + dilution)
        attention[i, 0] = sink_probability

        # No non-BOS destination is supported by the observed edges, so use
        # a diffuse residual with only a mild recency preference.
        distances = i - np.arange(1, i + 1)
        residual = 0.75 + 0.25 * np.exp(-distances / 8.0)
        attention[i, 1:i + 1] = (
            (1.0 - sink_probability) * residual / residual.sum()
        )

    return "bos_sink_with_positional_dilution", attention


def prog_L7H5(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with gradual positional dilution and small linguistic corrections.
    Residual attention is diffuse, with a weak preference for recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_positional_dilution", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        correction = 0.0
        aligned = alignment[i]

        if aligned:
            word = doc[aligned[-1]]
            if word.is_space:
                correction += 0.35
            elif word.is_punct:
                correction += 0.23
            elif word.pos_ in ("AUX", "CCONJ", "SCONJ", "ADV"):
                correction += 0.14
            elif word.pos_ in ("DET", "ADP"):
                correction += 0.06
            elif word.pos_ in ("NOUN", "PROPN", "PRON"):
                correction -= 0.10

            if word.ent_type_:
                correction -= 0.05
        elif tokens[i].replace("Ġ", " ").replace("Ċ", "\n").isspace():
            correction += 0.35

        # A nearly constant sink competes with an expanding causal context.
        attention[i, 0] = 55.0 * np.exp(correction)
        distances = i - np.arange(1, i + 1)
        attention[i, 1:i + 1] = 1.0 + 0.25 * np.exp(-distances / 4.0)

    return "bos_sink_with_positional_dilution", make_row_stochastic(attention)


def prog_L7H6(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with an early-position boost and weak POS modulation.
    Remaining attention is diffuse and mildly biased toward recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_position_decay", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    pos_adjustment = {
        "PROPN": 0.045,
        "NOUN": 0.025,
        "ADJ": 0.025,
        "VERB": 0.015,
        "AUX": 0.010,
        "ADP": 0.020,
        "ADV": 0.015,
        "PRON": -0.030,
        "DET": -0.025,
        "CCONJ": -0.015,
        "SCONJ": -0.010,
        "PART": -0.035,
        "PUNCT": -0.045,
    }
    first_pos_mass = {
        "PRON": 0.865,
        "PROPN": 0.880,
        "DET": 0.770,
        "ADP": 0.855,
        "ADV": 0.850,
        "NUM": 0.855,
        "SCONJ": 0.835,
        "CCONJ": 0.835,
    }

    attention[0, 0] = 1.0
    for i in range(1, n):
        aligned = alignment[i]
        word = doc[aligned[0]] if aligned else None
        pos = word.pos_ if word is not None else ""

        sink_mass = (
            0.45
            + 0.36 * np.exp(-(i - 1) / 8.0)
            + pos_adjustment.get(pos, 0.0)
        )
        if i == 1:
            sink_mass = first_pos_mass.get(pos, 0.855)

        if word is not None and word.is_space:
            sink_mass += 0.035

        # Byte fragments and unusual punctuation often retain substantial
        # attention to the sink rather than participating in syntax.
        if word is None and tokens[i].strip("ĠĊ▁").strip() == "":
            sink_mass += 0.035

        sink_mass = float(np.clip(sink_mass, 0.30, 0.93))

        positions = np.arange(1, i + 1)
        distances = i - positions
        residual = (distances + 1.0) ** -0.65

        # A modest self component; no unsupported sharp syntactic edges.
        residual[-1] *= 1.15
        residual /= residual.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_position_decay", attention


def prog_L7H7(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with gradual dilution and sparse backward action links.
    Interrogative action slots and governing predicates attract residual attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    matrix = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_action_links", matrix

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for ti, indices in enumerate(aligned):
        for si in indices:
            inverse[si].append(ti)

    special_tokens = set(tokenizer.all_special_tokens)
    sink = 0
    matrix[0, 0] = 1.0

    # Identify unresolved action questions, without lexical matching.
    questions = []
    for sent in doc.sents:
        if not any("?" in w.text for w in sent):
            continue
        verbs = [w for w in sent if w.pos_ == "VERB"]
        if not verbs:
            continue
        root = sent.root
        action = root if root.pos_ == "VERB" else verbs[-1]
        prepositions = [
            w for w in sent
            if w.pos_ == "ADP" and w.head.i == action.i
        ]
        anchor = prepositions[-1] if prepositions else action
        if inverse[anchor.i]:
            questions.append((sent.end, inverse[anchor.i][0]))

    for i in range(1, n):
        indices = aligned[i]
        word = doc[indices[0]] if indices else None

        # A broad, mildly recency-biased background, not a previous-token head.
        positions = np.arange(1, i + 1)
        background = 0.35 + 0.25 * np.exp(-(i - positions) / 14.0)
        for j in range(1, i + 1):
            if aligned[j]:
                key = doc[aligned[j][0]]
                if key.pos_ == "VERB":
                    background[j - 1] *= 1.35
                elif key.pos_ in ("NOUN", "PROPN"):
                    background[j - 1] *= 1.15
                elif key.pos_ == "PUNCT":
                    background[j - 1] *= 0.55
            elif tokens[j] in special_tokens:
                background[j - 1] *= 0.1

        sink_mass = 0.98 / (1.0 + 0.020 * max(i - 1, 0))
        if word is not None:
            if word.pos_ == "PUNCT":
                sink_mass += 0.035
            elif word.pos_ in ("DET", "AUX", "CCONJ", "SCONJ"):
                sink_mass += 0.025
            elif word.pos_ in ("VERB", "ADJ"):
                sink_mass -= 0.035
            if i == 1:
                if word.pos_ == "PRON":
                    sink_mass = 0.986
                elif word.pos_ == "DET":
                    sink_mass = 0.950
                else:
                    sink_mass = 0.975
        sink_mass = float(np.clip(sink_mass, 0.30, 0.99))

        matrix[i, 1:i + 1] = (
            (1.0 - sink_mass) * background / background.sum()
        )
        matrix[i, sink] = sink_mass

        links = {}
        if word is not None:
            # Follow only causal syntactic governors, including through prepositions.
            governor = word.head
            if governor.pos_ == "ADP":
                governor = governor.head
            if governor.i != word.i and governor.pos_ == "VERB":
                candidates = [j for j in inverse[governor.i] if 0 < j < i]
                if candidates:
                    strength = 0.08
                    if word.dep_ in ("pobj", "obl", "prep", "nmod"):
                        strength = 0.20
                        if governor.tag_ in ("VB", "VBG"):
                            strength = 0.38
                    links[candidates[0]] = strength

            # Answers to action questions can retrieve an earlier open action slot.
            earlier = [(end, j) for end, j in questions
                       if end <= word.i and j < i]
            if earlier:
                end, anchor = earlier[-1]
                distance = word.i - end
                root = word
                for _ in range(4):
                    if root.head.i == root.i:
                        break
                    root = root.head
                imperative = root.pos_ == "VERB" and root.tag_ == "VB"
                if imperative and distance < 24:
                    strength = 0.56 * np.exp(-distance / 45.0)
                    if word.pos_ in ("VERB", "AUX", "PART"):
                        strength += 0.08
                    links[anchor] = max(links.get(anchor, 0.0), strength)

        if links:
            total = sum(links.values())
            mixture = min(total, 0.72)
            matrix[i] *= 1.0 - mixture
            for j, strength in links.items():
                matrix[i, j] += mixture * strength / total

    return "bos_sink_with_action_links", make_row_stochastic(
        apply_causal_mask(matrix)
    )


def prog_L7H8(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with weaker, recency-weighted nominal anchors.
    Pronouns and clause continuations divert attention toward salient prior nouns.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    matrix = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_nominal_anchors", matrix

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = align_spacy_to_tokens(sentence, tokens, tokenizer)

    words = []
    for indices in alignment:
        if indices:
            words.append(doc[max(indices, key=lambda k: len(doc[k].text))])
        else:
            words.append(None)

    nominal_pos = {"NOUN", "PROPN"}
    subject_deps = {"nsubj", "nsubjpass", "csubj"}
    object_deps = {"dobj", "obj", "pobj", "iobj", "attr", "oprd"}

    # Represent each nominal word by its final subtoken, avoiding duplicate anchors.
    anchors = []
    for word in doc:
        if word.pos_ in nominal_pos and inverse[word.i]:
            anchors.append((max(inverse[word.i]), word))

    base_sink = {
        "NOUN": 0.71, "PROPN": 0.76, "DET": 0.73,
        "ADJ": 0.57, "VERB": 0.48, "AUX": 0.48,
        "ADP": 0.55, "ADV": 0.46, "PRON": 0.43,
        "CCONJ": 0.36, "SCONJ": 0.44, "PART": 0.48,
        "PUNCT": 0.44, "NUM": 0.69,
    }

    matrix[0, 0] = 1.0
    for i in range(1, n):
        word = words[i]
        pos = word.pos_ if word is not None else ""
        dep = word.dep_ if word is not None else ""
        prior = [(j, w) for j, w in anchors if 0 < j < i]

        sink = base_sink.get(pos, 0.60)
        sink += 0.20 * np.exp(-(i - 1) / 6.0)

        if i == 1:
            sink = 0.95
        elif not prior:
            if pos in nominal_pos:
                sink = max(sink, 0.92 if dep in subject_deps else 0.83)
            elif pos in {"DET", "ADP", "NUM"}:
                sink = max(sink, 0.91)
            elif pos == "PUNCT" and i <= 4:
                sink = max(sink, 0.91)
            elif pos in {"VERB", "AUX"} and i <= 3:
                sink = max(sink, 0.80)

        if word is not None and word.is_space:
            sink = 0.58

        # Referential pronouns are the clearest exceptions to the sink.
        if prior and pos == "PRON" and dep in subject_deps | object_deps:
            sink = 0.24 if dep in object_deps else 0.30
        if prior and pos == "CCONJ":
            sink = min(sink, 0.38)
        if tokens[i] in tokenizer.all_special_tokens:
            sink = 0.96

        sink = float(np.clip(sink, 0.10, 0.98))
        residual = np.zeros(i + 1, dtype=np.float64)

        # Small causal background, favoring nearby tokens.
        distances = i - np.arange(1, i + 1)
        residual[1:] = 0.035 * np.exp(-distances / 4.0)

        for j, antecedent in prior:
            score = np.exp(-(i - j) / 22.0)
            if antecedent.dep_ in subject_deps:
                score *= 1.35
            if antecedent.dep_ in object_deps:
                score *= 1.25

            if word is not None:
                if word.head.i == antecedent.i:
                    score *= 2.4
                if pos == "PRON":
                    if dep in subject_deps and antecedent.dep_ in subject_deps:
                        score *= 2.0
                    elif dep in object_deps and antecedent.dep_ in object_deps:
                        score *= 2.3
                    genders = word.morph.get("Gender")
                    if "Neut" in genders and antecedent.ent_type_ == "PERSON":
                        score *= 0.15
                    numbers = word.morph.get("Number")
                    ant_numbers = antecedent.morph.get("Number")
                    if numbers and ant_numbers and numbers != ant_numbers:
                        score *= 0.35
                if pos == "CCONJ" and antecedent.dep_ in subject_deps:
                    score *= 2.0

            residual[j] += score

        # With no noun anchor, leave the remainder broadly local.
        if not prior:
            residual[1:] += np.exp(-distances / 3.5)

        total = residual.sum()
        matrix[i, 0] = sink
        if total > 0:
            matrix[i, :i + 1] += (1.0 - sink) * residual / total
        else:
            matrix[i, 0] = 1.0

    return "bos_sink_with_nominal_anchors", make_row_stochastic(matrix)


def prog_L7H9(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with a strong prefix prior and weaker causal verb anchors.
    Clause openings favor the sink; predicate complements redistribute attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_predicate_residual", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for ti, indices in enumerate(alignment):
        for si in indices:
            inverse[si].append(ti)

    special_tokens = tokenizer.all_special_tokens
    representatives = []
    for i, indices in enumerate(alignment):
        if tokens[i] in special_tokens or not indices:
            representatives.append(None)
        else:
            representatives.append(doc[indices[0]])

    attention[0, 0] = 1.0
    sentence_start = 1

    for i in range(1, n):
        word = representatives[i]
        if word is not None and word.is_sent_start:
            mapped = inverse[word.i]
            if mapped and i == mapped[0]:
                sentence_start = i

        sink = 0.53 + 0.46 * np.exp(-(i - 1) / 3.2)

        if sentence_start > 1:
            sink += 0.23 * np.exp(-(i - sentence_start) / 3.0)

        if word is not None:
            if word.pos_ in ("VERB", "AUX"):
                sink += 0.045
            if word.dep_ in ("nsubj", "nsubjpass", "csubj", "cc", "mark"):
                sink += 0.055
            if word.dep_ in ("dobj", "obj", "pobj", "attr", "oprd"):
                sink -= 0.13
            if word.dep_ in ("amod", "acomp"):
                sink -= 0.08
            if word.pos_ == "DET" and word.head.dep_ in (
                "dobj", "obj", "pobj", "attr", "oprd"
            ):
                sink -= 0.09
            if word.pos_ == "PROPN":
                sink += 0.04
            if word.is_punct and "," in word.text:
                sink += 0.10

        if tokens[i].isspace() or tokens[i].strip("Ġ▁") == "":
            sink += 0.08
        if i == 1:
            sink = 0.99
        sink = float(np.clip(sink, 0.25, 0.995))

        positions = np.arange(1, i + 1)
        residual = 0.08 + 0.30 * np.exp(-(i - positions) / 5.0)

        # Content-addressable residual: preceding predicates and syntactic heads.
        for j in range(1, i + 1):
            key = representatives[j]
            if key is not None and key.pos_ == "VERB":
                residual[j - 1] += 0.9 * np.exp(-(i - j) / 18.0)

        if word is not None:
            head = word.head
            for _ in range(3):
                candidates = [j for j in inverse[head.i] if 0 < j <= i]
                if candidates and head.i != word.i:
                    strength = 2.2 if head.pos_ == "VERB" else 0.65
                    residual[candidates[-1] - 1] += strength
                if head.pos_ == "VERB" or head.head.i == head.i:
                    break
                head = head.head

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual / residual.sum()

    return "bos_sink_with_predicate_residual", attention


def prog_L7H10(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with localized release at coordinated phrase boundaries.
    Transfer only BOS mass to the preceding phrase, preserving self-attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_phrase_boundary_release", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    boundary_position = -n
    boundary_targets = []

    for i in range(1, n):
        strength = 0.92 - 0.13 * (1.0 - np.exp(-(i - 1) / 35.0))
        words = [doc[k] for k in alignment[i] if k < len(doc)]

        if words:
            pos = words[0].pos_
            if pos in ("NOUN", "PROPN", "ADJ"):
                strength += 0.025
            elif pos in ("PRON", "CCONJ", "SCONJ"):
                strength -= 0.025
            elif pos == "PUNCT":
                # Clause punctuation is less disruptive than sentence endings.
                terminal = any(
                    any(c in ".!?" for c in word.text)
                    for word in words
                )
                strength -= 0.18 if terminal else 0.025

            if words[0].is_sent_start and i > 1:
                strength -= 0.07

        strength = float(np.clip(strength, 0.60, 0.97))

        positions = np.arange(1, i + 1)
        residual = np.exp(-(i - positions) / 4.0)
        residual += 0.12 / np.sqrt(positions)
        residual /= residual.sum()

        attention[i, 0] = strength
        attention[i, 1:i + 1] = (1.0 - strength) * residual

        # A conjunction or non-introductory comma can expose a completed
        # nominal/adjectival phrase, with a short-lived spillover afterward.
        if words and (
            words[0].pos_ == "CCONJ"
            or any(word.text == "," for word in words)
        ):
            targets = []
            for j in range(i - 1, max(0, i - 5), -1):
                preceding = [doc[k] for k in alignment[j] if k < len(doc)]
                if not preceding or preceding[0].pos_ not in ("NOUN", "PROPN", "ADJ"):
                    break
                targets.append(j)

            if targets:
                previous = doc[alignment[targets[0]][0]]
                if previous.pos_ == "ADJ" or previous.dep_ in (
                    "dobj", "obj", "pobj", "attr", "oprd", "conj"
                ):
                    boundary_position = i
                    boundary_targets = targets

        distance = i - boundary_position
        if boundary_targets and 0 <= distance <= 3:
            adjectival = any(
                doc[alignment[j][0]].pos_ == "ADJ"
                for j in boundary_targets
            )
            release = (0.28 if adjectival else 0.22) * np.exp(-distance / 2.5)
            transfer = min(float(release), attention[i, 0])
            target_weights = np.exp(-0.25 * np.arange(len(boundary_targets)))
            target_weights /= target_weights.sum()
            attention[i, 0] -= transfer
            for j, weight in zip(boundary_targets, target_weights):
                attention[i, j] += transfer * weight

    return "bos_sink_with_phrase_boundary_release", attention


def prog_L7H11(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with a strong initial-position prior.
    Residual attention favors recent context, syntactic heads, and sentence boundaries.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_boundary_residual", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = align_spacy_to_tokens(sentence, tokens, tokenizer)
    boundaries = []

    attention[0, 0] = 1.0

    for i in range(1, n):
        clean = tokens[i].replace("Ġ", " ").replace("Ċ", "\n").strip()
        sids = aligned[i]
        word = doc[sids[-1]] if sids else None
        pos = word.pos_ if word is not None else ""
        is_boundary = any(c in ".!?" for c in clean)

        # Sink dominance weakens with context length and completed sentences.
        sink = (
            0.79
            + 0.18 * np.exp(-i / 3.0)
            - 0.0015 * i
            - 0.075 * min(len(boundaries), 3)
        )

        if pos in ("NOUN", "PROPN"):
            sink += 0.045
        elif pos in ("VERB", "ADV"):
            sink -= 0.055
        elif pos == "PRON":
            sink -= 0.025

        if clean and all(c in ",;:" for c in clean):
            sink += 0.075
        elif is_boundary:
            sink += 0.055
        elif not clean:
            sink += 0.015

        if i == 1:
            sink = 0.96

        sink = float(np.clip(sink, 0.28, 0.975))
        attention[i, 0] = sink

        positions = np.arange(1, i + 1)
        residual = (
            0.20 / np.sqrt(i - positions + 1.0)
            + 0.35 * np.exp(-(i - positions) / 5.0)
        )

        # Completed sentence/quotation boundaries are secondary anchor keys.
        for boundary in boundaries:
            residual[boundary - 1] += 2.8 * np.exp(
                -(i - boundary) / 30.0
            )

        if word is not None:
            head_index = word.head.i
            for j in inverse[head_index]:
                if 0 < j <= i:
                    residual[j - 1] += 0.30

        attention[i, 1:i + 1] = (
            (1.0 - sink) * residual / residual.sum()
        )

        if is_boundary:
            boundaries.append(i)

    return "bos_sink_with_boundary_residual", make_row_stochastic(attention)


def prog_L7H12(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, strongest early and in narrative scaffolding.
    Dialogue and embedded predicate/object material weaken the sink."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_syntactic_gating", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special_tokens = set(tokenizer.all_special_tokens)
    quoted = False

    attention[0, 0] = 1.0
    for i in range(1, n):
        text = tokens[i].replace("Ġ", " ").replace("Ċ", "\n")
        stripped = text.strip()
        is_special = tokens[i] in special_tokens
        is_quote = any(c in text for c in ('"', '“', '”', '«', '»'))
        inside_dialogue = quoted

        sids = alignment[i]
        word = None
        for sid in sids:
            candidate = doc[sid]
            if word is None or (
                word.pos_ in ("PUNCT", "SPACE")
                and candidate.pos_ not in ("PUNCT", "SPACE")
            ):
                word = candidate

        logit = 4.4 - 0.8 * np.log1p(i)

        if inside_dialogue:
            logit -= 1.6

        if word is not None:
            pos = word.pos_
            dep = word.dep_

            if dep in ("nsubj", "nsubjpass", "csubj"):
                logit += 0.2
            elif dep in ("dobj", "obj", "iobj", "pobj", "attr", "oprd"):
                logit -= 1.25
            elif dep in ("xcomp", "ccomp", "relcl", "acl"):
                logit -= 1.1
            elif dep in ("amod", "poss", "det"):
                logit -= 0.5

            if pos in ("CCONJ", "SCONJ"):
                logit += 0.3
            elif pos in ("NOUN", "PROPN"):
                logit -= 0.25
            elif pos == "VERB":
                if dep == "ROOT":
                    logit += 0.15
                if "Inf" in word.morph.get("VerbForm"):
                    logit -= 0.9
            elif pos == "PART":
                logit -= 0.65

            if dep in ("amod", "det", "poss") and word.head.dep_ in (
                "dobj", "obj", "iobj", "pobj", "attr"
            ):
                logit -= 0.45

            if pos == "PUNCT" and not inside_dialogue:
                logit += 0.35

        if not stripped or is_special:
            logit += 0.5
        if is_quote and not inside_dialogue:
            logit += 0.2

        sink_mass = float(1.0 / (1.0 + np.exp(-logit)))
        if i == 1:
            sink_mass = 0.985

        # The unobserved residual is diffuse, with a modest recency bias.
        distances = i - np.arange(1, i + 1, dtype=np.float64)
        residual = 0.45 / i + 0.55 * np.exp(-distances / 5.0)
        residual /= residual.sum()
        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

        if is_quote:
            quote_count = sum(text.count(c) for c in ('"', '“', '”', '«', '»'))
            if quote_count % 2:
                quoted = not quoted

    return "bos_sink_with_syntactic_gating", attention


def prog_L7H13(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with a weaker backward, predicate-centered component.
    Objects and complements preferentially retrieve recent nonfinite predicates.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_predicate_backoff", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, indices in enumerate(alignment):
        for k in indices:
            inverse[k].append(i)

    attention[0, 0] = 1.0

    for i in range(1, n):
        indices = alignment[i]
        word = doc[indices[-1]] if indices else None
        weights = np.exp(-0.12 * (i - np.arange(1, i + 1)))
        sink = 0.66

        if word is None:
            sink = 0.80
        else:
            pos = word.pos_
            dep = word.dep_

            if pos == "PUNCT":
                sink = 0.77
            elif pos == "SPACE":
                sink = 0.84
            elif pos == "VERB":
                sink = 0.79 if dep in ("ROOT", "conj", "ccomp") else 0.64
            elif pos == "AUX":
                sink = 0.73
            elif pos in ("NOUN", "PROPN"):
                sink = 0.53
            elif pos == "PRON":
                sink = 0.56
            elif pos == "ADJ":
                sink = 0.64
            elif pos in ("CCONJ", "SCONJ"):
                sink = 0.75
            elif pos == "DET":
                sink = 0.66
            elif pos in ("ADP", "PART"):
                sink = 0.59

            # Recover a preceding governing predicate, including through
            # intervening nominal and prepositional structure.
            ancestor = word.head
            predicate = None
            for _ in range(6):
                if ancestor.pos_ == "VERB":
                    candidates = [j for j in inverse[ancestor.i] if 0 < j < i]
                    if candidates:
                        predicate = (ancestor, candidates[0])
                        break
                if ancestor.head.i == ancestor.i:
                    break
                ancestor = ancestor.head

            if predicate is not None:
                verb, target = predicate
                distance = i - target
                nonfinite = (
                    verb.tag_ in ("VBG", "VBN", "VB")
                    and verb.dep_ in ("xcomp", "advcl", "acl", "pcomp")
                )
                direct_object = (
                    word.head.i == verb.i
                    and dep in ("dobj", "obj", "attr", "oprd")
                )
                strength = 2.0 * np.exp(-distance / 18.0)
                if nonfinite:
                    strength *= 2.8
                if direct_object:
                    strength *= 2.0
                    sink -= 0.12
                    if nonfinite:
                        sink -= 0.13
                weights[target - 1] += strength

            # Modifiers and function words can also retrieve their local head.
            if word.head.i != word.i:
                candidates = [j for j in inverse[word.head.i] if 0 < j < i]
                if candidates:
                    weights[candidates[0] - 1] += 0.8

        # The first few positions overwhelmingly use the sink.
        early = np.exp(-(i - 1) / 2.6)
        sink = float(np.clip(sink + (0.988 - sink) * early, 0.24, 0.99))
        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * weights / weights.sum()

    return "bos_sink_with_predicate_backoff", attention


def prog_L7H14(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink: strongest at the prefix, with a persistent baseline.
    Linguistic features mildly modulate the sink; residual attention is diffuse.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_prefix_decay", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.48 + 0.507 * np.exp(-(i - 1) / 7.0)
        aligned = alignment[i]

        if aligned:
            word = doc[aligned[0]]
            if word.pos_ in ("DET", "ADP"):
                sink_mass += 0.025
            elif word.pos_ in ("PRON", "AUX", "CCONJ", "SCONJ"):
                sink_mass -= 0.025

            if word.dep_ in ("nsubj", "nsubjpass") or word.ent_type_:
                sink_mass += 0.02

        text = tokens[i].lstrip("Ġ").lstrip("▁")
        if not text.strip():
            sink_mass += 0.12
        elif text and all(c in ",\"'“”‘’" for c in text):
            sink_mass += 0.07
        elif text and all(c in ".!?;:" for c in text):
            sink_mass -= 0.06

        if i == 1:
            sink_mass = 0.987

        sink_mass = float(np.clip(sink_mass, 0.30, 0.995))
        attention[i, 0] = sink_mass

        # No non-BOS target is supported strongly by the observations.
        # Use a broad causal background with a mild recency preference.
        distances = i - np.arange(1, i + 1)
        background = 0.7 + 0.3 * np.exp(-distances / 8.0)
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * background / background.sum()
        )

    return "bos_sink_with_prefix_decay", attention


def prog_L7H15(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with position-dependent decay and small syntactic corrections.
    Remaining attention is diffuse, with a weak preference for recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_decay", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink = 0.41 + 0.54 / (1.0 + 0.18 * (i - 1))
        aligned = alignment[i]
        word = doc[aligned[0]] if aligned else None

        if word is not None:
            if word.pos_ in ("NOUN", "PROPN"):
                sink -= 0.035
            elif word.pos_ in ("VERB", "AUX"):
                sink += 0.015
            elif word.pos_ in ("CCONJ", "SCONJ"):
                sink += 0.055
            elif word.pos_ == "ADJ":
                sink -= 0.020

            if word.dep_ in ("mark", "cc"):
                sink += 0.020

            if word.is_punct and any(c in tokens[i] for c in ('"', "“", "”")):
                sink += 0.055

        if i == 1:
            sink = 0.944
            if word is not None:
                if word.pos_ in ("DET", "ADP"):
                    sink = 0.956
                elif word.pos_ == "PROPN":
                    sink = 0.955
                elif word.pos_ == "PRON":
                    sink = 0.937

        sink = np.clip(sink, 0.38, 0.97)
        attention[i, 0] = sink

        distances = i - np.arange(1, i + 1, dtype=np.float64)
        residual = 0.65 + 0.35 * np.exp(-distances / 5.0)
        residual[-1] *= 0.85
        attention[i, 1:i + 1] = (1.0 - sink) * residual / residual.sum()

    return "bos_sink_with_decay", attention


def prog_L7H16(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with a dialogue-specific exception: quoted discourse redirects
    diagonal mass toward BOS, quotation boundaries, and the current speaker.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_dialogue_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    pos_adjustment = {
        "NOUN": -0.065,
        "PROPN": -0.035,
        "VERB": -0.070,
        "AUX": 0.015,
        "ADJ": -0.035,
        "ADV": 0.025,
        "DET": 0.065,
        "PRON": 0.035,
        "ADP": 0.025,
        "CCONJ": 0.045,
        "SCONJ": 0.045,
        "PART": -0.015,
        "PUNCT": 0.090,
        "SPACE": 0.130,
    }

    for i in range(1, n):
        sink = 0.28 + 0.68 * np.exp(-(i - 1) / 6.0)
        mapped = alignment[i]

        if mapped:
            word = doc[mapped[-1]]
            sink += pos_adjustment.get(word.pos_, 0.0)

            # Temporal and framing material tends to preserve the opening sink.
            if word.dep_ in ("npadvmod", "discourse"):
                sink += 0.070
            elif word.dep_ in ("ROOT", "xcomp", "ccomp"):
                sink -= 0.025

            if word.is_punct and any(c in word.text for c in ',:"“”'):
                sink += 0.040
            if word.is_space:
                sink += 0.040
        else:
            clean = tokens[i].replace("Ġ", " ").replace("Ċ", "\n")
            if clean.isspace():
                sink += 0.140
            elif clean.strip() and all(
                not c.isalnum() for c in clean.strip()
            ):
                sink += 0.090

        # The first lexical query has almost no alternative to the sink.
        if i == 1:
            sink = 0.96

        sink = float(np.clip(sink, 0.16, 0.98))
        attention[i, 0] = sink

        positions = np.arange(1, i + 1)
        tail = (
            0.65 * np.exp(-(i - positions) / 3.5)
            + 0.35 / np.sqrt(i - positions + 1.0)
        )
        tail /= tail.sum()

        residual = 1.0 - sink
        attention[i, 1:i + 1] = residual * 0.48 * tail
        attention[i, i] += residual * 0.52

    # Only quoted discourse activates this correction; unquoted inputs retain
    # the original matrix, including its diagonal weights and decay rates.
    first_quote = None
    in_quote = False
    anchor = None
    subject = None
    quote_count = 0

    for i in range(1, n):
        clean = tokens[i].replace("Ġ", " ").replace("Ċ", "\n")
        mapped = alignment[i]

        if not in_quote and mapped:
            word = doc[mapped[-1]]
            if word.dep_ in ("nsubj", "nsubjpass", "csubj"):
                subject = i

        if any(c in clean for c in '"“”'):
            opening = "“" in clean or ("”" not in clean and not in_quote)
            if opening:
                if first_quote is None:
                    first_quote = i
                anchor = i
                # Later speech turns often anchor on their introducing comma.
                if quote_count > 0 and i > 1:
                    previous = tokens[i - 1].replace("Ġ", " ").strip()
                    if previous in (",", ":"):
                        anchor = i - 1
                quote_count += 1
                in_quote = True
            else:
                in_quote = False

        if first_quote is None or i <= first_quote:
            continue

        # Move only diagonal mass; preserve all existing off-diagonal weights.
        retained = 0.055 + 0.25 * np.exp(-(i - first_quote) / 8.0)
        moved = attention[i, i] * (1.0 - retained)
        attention[i, i] -= moved

        target_sink = 0.45 + 0.12 * np.exp(-(i - 1) / 12.0)
        if mapped and doc[mapped[-1]].is_punct:
            target_sink += 0.05
        to_bos = min(moved * 0.55, max(0.0, target_sink - attention[i, 0]))
        attention[i, 0] += to_bos

        remainder = moved - to_bos
        weights = np.zeros(i, dtype=np.float64)
        positions = np.arange(1, i)
        weights[1:i] = 0.15 * np.exp(-(i - positions) / 5.0)
        if anchor is not None and 0 < anchor < i:
            weights[anchor] += 0.65
        if subject is not None and 0 < subject < i:
            weights[subject] += 0.20
        weights /= weights.sum()
        attention[i, :i] += remainder * weights

    return "bos_sink_with_dialogue_anchors", make_row_stochastic(attention)


def prog_L7H17(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with gradually increasing diffuse causal leakage.
    Linguistic features weakly modulate the otherwise positional sink preference.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_causal_leakage", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = (
            0.995
            - 0.060 * np.log1p((i - 1) / 2.0)
            - 0.0012 * (i - 1)
        )

        sids = alignment[i]
        if sids:
            word = doc[sids[0]]
            if word.pos_ == "PUNCT":
                sink_mass += 0.012
            elif word.pos_ in ("AUX", "CCONJ", "SCONJ"):
                sink_mass += 0.008
            elif word.dep_ in ("poss", "det"):
                sink_mass -= 0.010

        sink_mass = float(np.clip(sink_mass, 0.55, 0.997))
        attention[i, 0] = sink_mass

        # The examples identify the sink, not a reliable secondary target.
        # Spread the remaining mass, with only a mild recency preference.
        positions = np.arange(1, i + 1, dtype=np.float64)
        distances = i - positions
        leakage = 0.65 / i + 0.35 * np.exp(-distances / 8.0)
        leakage /= leakage.sum()
        attention[i, 1:i + 1] = (1.0 - sink_mass) * leakage

    return "bos_sink_with_causal_leakage", attention


def prog_L7H18(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, with weaker sink preference after sentence boundaries.
    Residual attention favors recent tokens and preceding sentence-end punctuation.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_boundary_leakage", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0
    last_boundary = None

    for i in range(1, n):
        clean = tokens[i].replace("Ġ", " ").replace("Ċ", "\n").strip()
        aligned = alignment[i]
        word = doc[aligned[-1]] if aligned else None

        is_punct = (
            word is not None and word.pos_ == "PUNCT"
        ) or (bool(clean) and all(not c.isalnum() for c in clean))
        is_space = not clean
        is_boundary = any(c in ".!?" for c in clean)

        # Position zero is the overwhelmingly dominant target in the examples.
        sink_mass = 0.978 - 0.0015 * min(i - 1, 60)
        if last_boundary is not None:
            sink_mass -= 0.105
        if is_punct:
            sink_mass -= 0.085
        if is_space:
            sink_mass -= 0.19

        if word is not None and i > 3:
            if word.pos_ in ("PRON", "AUX"):
                sink_mass -= 0.035 if last_boundary is None else 0.09
            elif word.pos_ in ("NOUN", "PROPN", "ADJ"):
                sink_mass += 0.012

        sink_mass = float(np.clip(sink_mass, 0.48, 0.989))

        # Keep the small non-sink component causal and locally concentrated.
        positions = np.arange(1, i + 1)
        residual = np.exp(-(i - positions) / 5.0)
        residual[-1] *= 0.65

        if last_boundary is not None:
            residual[last_boundary - 1] += 3.0
            if is_punct:
                residual[last_boundary - 1] += 3.0

        residual /= residual.sum()
        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

        if is_boundary:
            last_boundary = i

    return "bos_sink_with_boundary_leakage", attention


def prog_L7H19(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with gradually increasing contextual competition.
    Residual attention favors nearby tokens and causal syntactic antecedents.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_contextual_competition", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, indices in enumerate(alignment):
        for k in indices:
            inverse[k].append(i)

    attention[0, 0] = 1.0
    for i in range(1, n):
        positions = np.arange(1, i + 1)
        weights = 0.15 + np.exp(-(i - positions) / 5.0)
        odds = 0.018 + 0.0045 * i ** 1.3

        if alignment[i]:
            word = doc[alignment[i][0]]

            # Early function tokens show modestly weaker sink attraction.
            if word.pos_ == "DET":
                odds += 0.025 * np.exp(-i / 12.0)
            elif word.pos_ in ("ADP", "AUX"):
                odds += 0.012 * np.exp(-i / 12.0)

            # Only use dependencies whose target is already visible.
            for k in alignment[i]:
                current = doc[k]
                candidates = [
                    j for j in inverse[current.head.i]
                    if 0 < j < i
                ]
                if candidates:
                    target = candidates[-1]
                    weights[target - 1] += 1.5

                    # Coordinated content words can substantially compete
                    # with the otherwise dominant BOS sink.
                    if (
                        current.dep_ == "conj"
                        and current.pos_ in ("NOUN", "PROPN", "ADJ", "VERB")
                    ):
                        weights[target - 1] += 8.0
                        odds += 0.65

                # Keep split pieces of a word weakly linked.
                for j in inverse[k]:
                    if 0 < j < i:
                        weights[j - 1] += 0.5

        sink_mass = 1.0 / (1.0 + odds)
        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * weights / weights.sum()
        )

    return "bos_sink_with_contextual_competition", attention


def prog_L7H20(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """A dominant beginning-of-sequence sink, weakening with position,
    with occasional attention to earlier related or coordinated nominals.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_nominal_links", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    representatives = []
    for indices in alignment:
        representatives.append(
            max(indices, key=lambda k: len(doc[k].text)) if indices else None
        )

    nominal_positions = []
    attention[0, 0] = 1.0

    for i in range(1, n):
        si = representatives[i]
        word = doc[si] if si is not None else None

        # A high sink probability initially, with gradual competition later.
        sink = 0.968 - 0.39 * (1.0 - np.exp(-max(i - 5, 0) / 27.0))
        if word is not None and word.is_punct:
            sink = min(0.98, sink + 0.025)

        # Spread the small nonsink component over causal, mostly local keys.
        positions = np.arange(1, i + 1)
        background = np.exp(-(i - positions) / 5.0)
        background += 0.08
        background /= background.sum()
        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * background

        is_nominal = word is not None and word.pos_ in ("NOUN", "PROPN")
        first_piece = is_nominal and (
            i == 1 or representatives[i - 1] != si
        )

        if first_piece:
            best_j = None
            best_strength = 0.0

            for j in nominal_positions[-8:]:
                sj = representatives[j]
                previous = doc[sj]
                if sj == si:
                    continue

                strength = 0.0
                if word.dep_ == "conj" and word.head.i == sj:
                    strength = 0.86
                else:
                    similarity = embedding_similarity(tokens, i, j, tokenizer)
                    semantic = np.clip((similarity - 0.24) / 0.46, 0.0, 1.0)
                    strength = 0.62 * semantic

                    subject_roles = ("nsubj", "nsubjpass", "csubj")
                    if (
                        word.dep_ in subject_roles
                        and previous.dep_ in subject_roles
                    ):
                        strength = max(strength, 0.34)

                    if (
                        word.ent_type_
                        and word.ent_type_ == previous.ent_type_
                    ):
                        strength = max(strength, 0.27)

                if strength > best_strength:
                    best_j = j
                    best_strength = strength

            if best_j is not None:
                attention[i] *= 1.0 - best_strength
                attention[i, best_j] += best_strength

            nominal_positions.append(i)

    return "bos_sink_with_nominal_links", make_row_stochastic(attention)


def prog_L7H21(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with gradually declining dominance and mild POS modulation.
    Remaining attention is diffuse and weakly biased toward recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_positional_decay", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    attention[0, 0] = 1.0
    for i in range(1, n):
        competition = 0.055 * (i ** 0.72)
        aligned = alignment[i]

        if aligned:
            word = doc[aligned[-1]]
            if word.pos_ == "PRON":
                competition *= 0.78
            elif word.pos_ == "PROPN":
                competition *= 0.80
            elif word.pos_ in ("NOUN", "ADJ"):
                competition *= 0.94
            elif word.pos_ in ("VERB", "AUX"):
                competition *= 1.10
            elif word.pos_ in ("ADP", "CCONJ", "SCONJ", "PART"):
                competition *= 1.18
            elif word.is_punct:
                competition *= 1.35
            elif word.is_space:
                competition *= 1.45

        sink_mass = 1.0 / (1.0 + competition)
        attention[i, 0] = sink_mass

        positions = np.arange(1, i + 1, dtype=np.float64)
        recency = np.exp(-(i - positions) / (6.0 + 0.30 * i))
        recency /= recency.sum()
        background = 0.35 / i + 0.65 * recency
        attention[i, 1:i + 1] = (1.0 - sink_mass) * background

    return "bos_sink_positional_decay", make_row_stochastic(attention)


def prog_L7H22(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention-sink head: strongest near the beginning, with weak
    linguistic modulation and a diffuse, recency-biased residual."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_recency", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)

    pos_adjustment = {
        "NOUN": 0.065,
        "PROPN": 0.075,
        "DET": 0.025,
        "ADJ": 0.025,
        "ADP": 0.010,
        "VERB": -0.015,
        "AUX": -0.025,
        "ADV": -0.025,
        "PRON": -0.090,
        "CCONJ": -0.060,
        "SCONJ": -0.075,
        "PART": -0.045,
        "PUNCT": -0.130,
    }

    attention[0, 0] = 1.0
    for i in range(1, n):
        word = doc[aligned[i][-1]] if aligned[i] else None

        # The first-token sink dominates even at long distances; its
        # unusually strong initial advantage relaxes over the first few tokens.
        early = np.exp(-(i - 1) / 4.8)
        adjustment = 0.0
        if word is not None:
            adjustment = pos_adjustment.get(word.pos_, 0.0)
            if word.dep_ in ("nsubj", "nsubjpass", "pobj", "dobj", "obj"):
                adjustment += 0.020
            if word.ent_type_:
                adjustment += 0.015
        elif tokens[i].isspace():
            adjustment = 0.050

        sink = 0.555 + 0.425 * early + (1.0 - early) * adjustment
        sink = float(np.clip(sink, 0.30, 0.985))
        attention[i, 0] = sink

        # Keep the unobserved residual broad rather than inventing a
        # strong lexical or syntactic retrieval mechanism.
        positions = np.arange(1, i + 1)
        residual = 0.35 + np.exp(-(i - positions) / 5.0)
        for j in range(1, i + 1):
            if aligned[j]:
                key = doc[aligned[j][-1]]
                if key.pos_ in ("NOUN", "PROPN"):
                    residual[j - 1] *= 1.25
                if word is not None and key.i == word.head.i and key.i != word.i:
                    residual[j - 1] *= 1.15
                if key.is_punct:
                    residual[j - 1] *= 0.80

        attention[i, 1:i + 1] = (1.0 - sink) * residual / residual.sum()

    return "bos_sink_with_recency", attention


def prog_L7H23(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with slowly declining dominance as the prefix grows.
    Residual attention is diffuse, with weak recency and syntactic biases.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_prefix_decay", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for ti, sids in enumerate(alignment):
        for si in sids:
            inverse[si].append(ti)

    attention[0, 0] = 1.0
    for i in range(1, n):
        # A fixed, strong sink competes with a growing pool of other keys.
        sink_mass = 1.0 / (1.0 + 0.037 * float(i) ** 0.85)
        sids = alignment[i]
        word = doc[sids[-1]] if sids else None

        # Small linguistic corrections, subordinate to the positional effect.
        if word is not None:
            if word.pos_ == "ADJ":
                sink_mass += 0.025
            elif word.pos_ == "PROPN" and i > 2:
                sink_mass -= 0.035
            elif word.pos_ == "PRON" and i > 4:
                sink_mass -= 0.035
        sink_mass = float(np.clip(sink_mass, 0.12, 0.985))

        positions = np.arange(1, i + 1)
        distance = i - positions
        residual = 0.65 + 0.35 * np.exp(-distance / 7.0)

        if word is not None:
            for j in inverse[word.head.i]:
                if 0 < j < i:
                    residual[j - 1] += 0.25
            for j in inverse[word.i]:
                if 0 < j < i:
                    residual[j - 1] += 0.20

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * residual / residual.sum()
        )

    return "bos_sink_with_prefix_decay", attention


def prog_L8H0(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with weak recency and sentence-boundary fallback.
    Sink strength decreases mildly with position, especially in quoted discourse.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_boundary_fallback", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    boundaries = []
    quote_seen = False

    attention[0, 0] = 1.0
    for i in range(1, n):
        text = tokens[i].lstrip("Ġ▁")
        if any(c in text for c in ('"', "“", "”", "«", "»")):
            quote_seen = True

        mapped = alignment[i]
        pos = doc[mapped[-1]].pos_ if mapped else ""

        sink = 0.93 - 0.055 * (1.0 - np.exp(-i / 24.0))
        sink += 0.066 * np.exp(-(i - 1) / 2.8)
        if quote_seen:
            sink -= 0.075 * (1.0 - np.exp(-i / 15.0))
        if pos in ("PRON", "DET") and i > 8:
            sink -= 0.025
        sink = float(np.clip(sink, 0.72, 0.997))

        if i == 1:
            sink = 0.996

        indices = np.arange(1, i + 1)
        residual = np.exp(-(i - indices) / 4.0)
        residual[-1] *= 0.35
        residual /= residual.sum()

        if boundaries:
            boundary_weights = np.zeros(i, dtype=np.float64)
            for j, quoted in boundaries:
                boundary_weights[j - 1] += (
                    (2.5 if quoted else 1.0)
                    * np.exp(-(i - j) / 36.0)
                )
            boundary_weights /= boundary_weights.sum()
            boundary_mix = 0.65 if quote_seen else 0.30
            residual = (
                (1.0 - boundary_mix) * residual
                + boundary_mix * boundary_weights
            )

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual

        if any(c in text for c in (".", "!", "?")):
            boundaries.append((
                i,
                any(c in text for c in ('"', "”", "»"))
            ))

    return "bos_sink_with_boundary_fallback", make_row_stochastic(attention)


def prog_L8H1(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with gradually increasing diffuse causal attention.
    Linguistic features weakly modulate sink strength and the residual attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_diffuse_decay", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        words = [doc[k] for k in alignment[i]]
        pos = words[0].pos_ if words else ""
        punctuation = bool(words) and all(w.is_punct for w in words)
        whitespace = tokens[i].replace("Ġ", "").replace("Ċ", "").isspace()
        whitespace = whitespace or tokens[i] in ("Ġ", "Ċ")

        # An approximately fixed BOS logit competes with a growing key set.
        competition = 0.027
        if punctuation or whitespace:
            competition *= 0.82
        elif pos in ("CCONJ", "SCONJ", "AUX"):
            competition *= 0.86
        elif pos in ("PRON", "PROPN"):
            competition *= 1.12

        positions = np.arange(1, i + 1)
        distances = i - positions
        residual = np.exp(-0.008 * distances)
        residual[-1] *= 1.15
        if i > 1:
            residual[-2] *= 1.10

        # Keep syntactic effects subordinate to the observed positional sink.
        for word in words:
            head_index = word.head.i
            if head_index != word.i:
                for j in range(1, i + 1):
                    if head_index in alignment[j]:
                        residual[j - 1] *= 1.15

        attention[i, 0] = 1.0
        attention[i, 1:i + 1] = competition * residual

    return "bos_sink_with_diffuse_decay", make_row_stochastic(attention)


def prog_L8H2(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with weak, diffuse causal leakage.
    Sink dominance decreases slightly with position; no clear syntactic targeting is evident.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    for i in range(n):
        if i == 0:
            attention[i, 0] = 1.0
            continue

        leakage = min(0.03, 0.002 + 0.0004 * (i - 1))
        positions = np.arange(1, i + 1, dtype=np.float64)
        residual = np.exp(-(i - positions) / 12.0)
        residual /= residual.sum()

        attention[i, 0] = 1.0 - leakage
        attention[i, 1:i + 1] = leakage * residual

    return "bos_sink_with_weak_causal_leakage", attention


def prog_L8H3(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with weak recency; subword locality is bounded and lexical.
    Spurious continuation edges return mass to BOS without changing self-attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_bounded_subword_locality", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    spans = _char_spans(sentence, tokenizer)

    attention[0, 0] = 1.0

    for i in range(1, n):
        sids = aligned[i]
        word = doc[sids[0]] if sids else None
        pos = word.pos_ if word is not None else ""

        sink_mass = 0.56 + 0.20 * np.exp(-(i - 1) / 3.0)
        if pos in ("NOUN", "PROPN", "ADJ"):
            sink_mass += 0.025
        elif pos in ("DET", "PRON"):
            sink_mass += 0.015

        if i == 1:
            if pos in ("PRON", "PROPN"):
                sink_mass = 0.83
            elif pos == "DET":
                sink_mass = 0.74
            else:
                sink_mass = 0.79

        # Shared spaCy membership identifies pieces of the same lexical token.
        continuation = False
        if i > 1 and word is not None and i < len(spans):
            start, end = spans[i]
            continuation = (
                end > start
                and start > word.idx
                and sids[0] in aligned[i - 1]
                and not word.is_punct
                and not word.is_space
            )

        if continuation:
            sink_mass = 0.32

        sink_mass = float(np.clip(sink_mass, 0.20, 0.88))
        attention[i, 0] = sink_mass

        positions = np.arange(1, i + 1)
        distance = i - positions
        background = (
            0.45 / i
            + 0.55 * np.exp(-distance / 4.0)
            / np.exp(-distance / 4.0).sum()
        )

        if continuation:
            background *= 0.28
            background[-2] += 0.72

        # Small causal syntactic correction; BOS remains the main target.
        if word is not None and not continuation and word.head.i != word.i:
            targets = [
                j for j in range(1, i)
                if word.head.i in aligned[j]
            ]
            if targets:
                background *= 0.94
                for j in targets:
                    background[j - 1] += 0.06 / len(targets)

        background /= background.sum()
        attention[i, 1:i + 1] = (1.0 - sink_mass) * background

        # Correct only the continuation branch. Preserve its diagonal and
        # every unrelated edge; move excess predecessor mass conservatively.
        if continuation:
            lexical_piece = (
                len(sids) == 1
                and word.text.isalpha()
                and sentence[start:end].isalpha()
                and start >= spans[i - 1][1]
            )
            cap = 0.20 if lexical_piece else 0.05
            excess = max(0.0, attention[i, i - 1] - cap)
            attention[i, i - 1] -= excess

            earlier_pieces = [
                j for j in range(1, i - 1)
                if sids[0] in aligned[j]
            ] if lexical_piece else []

            if earlier_pieces:
                # Later pieces also address the lexical onset, not just
                # their immediate predecessor.
                attention[i, earlier_pieces[0]] += 0.5 * excess
                attention[i, 0] += 0.5 * excess
            else:
                attention[i, 0] += excess

    return "bos_sink_bounded_subword_locality", make_row_stochastic(attention)


def prog_L8H4(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with a clause-ending release toward recent content.
    Terminal punctuation and following whitespace redirect only BOS mass.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_boundary_release", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        early = np.exp(-(i - 1) / 3.5)
        sink_mass = 0.75 + 0.22 * early

        aligned = alignment[i] if i < len(alignment) else []
        if aligned:
            word = doc[aligned[0]]
            adjustment = 0.0
            if word.pos_ in ("DET", "ADJ"):
                adjustment = 0.035
            elif word.pos_ in ("NOUN", "PROPN", "PRON"):
                adjustment = 0.015
            elif word.pos_ in ("CCONJ", "SCONJ", "ADV"):
                adjustment = -0.025
            elif word.is_punct:
                adjustment = -0.10
            sink_mass += (1.0 - early) * adjustment

        sink_mass = float(np.clip(sink_mass, 0.55, 0.985))
        attention[i, 0] = sink_mass

        distances = i - np.arange(1, i + 1)
        local = np.exp(-distances / 3.0)
        local /= local.sum()
        residual = 0.55 / i + 0.45 * local
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

        # Release sink mass at sentence boundaries; keep self-attention
        # and every existing non-BOS weight intact, adding only to past keys.
        text = tokens[i].replace("\u0120", " ").strip()
        previous = tokens[i - 1].replace("\u0120", " ").strip()
        terminal = (
            bool(text)
            and any(c in ".!?" for c in text)
            and all(c in ".!?\"'”’»" for c in text)
        )
        trailing_space = (
            not text
            and bool(previous)
            and any(c in ".!?" for c in previous)
            and all(c in ".!?\"'”’»" for c in previous)
        )

        if terminal or trailing_space:
            weights = np.zeros(i, dtype=np.float64)
            for j in range(max(1, i - 10), i):
                sids = alignment[j] if j < len(alignment) else []
                if sids:
                    key = doc[sids[0]]
                    if not key.is_punct and not key.is_space:
                        strength = (
                            1.0 if key.pos_ in ("NOUN", "PROPN", "VERB")
                            else 0.7 if key.pos_ in ("ADJ", "ADV")
                            else 0.35 if key.pos_ == "PRON"
                            else 0.10
                        )
                        weights[j] = strength * np.exp(-(i - j - 1) / 2.5)
                if trailing_space and j == i - 1:
                    weights[j] = 0.8

            if weights.sum() > 0.0:
                released = min(
                    attention[i, 0],
                    0.35 + 0.12 * (1.0 - np.exp(-i / 25.0)),
                )
                attention[i, 0] -= released
                attention[i, :i] += released * weights / weights.sum()

    return "bos_sink_with_boundary_release", attention


def prog_L8H5(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with positional decay; sentence-ending punctuation releases
    some sink mass to preceding content anchors, leaving self-attention intact.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_terminal_release", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        pos_adjustment = 0.0
        if alignment[i]:
            word = doc[alignment[i][0]]
            if word.pos_ == "PUNCT":
                pos_adjustment = -0.12
            elif word.pos_ in ("PROPN", "AUX"):
                pos_adjustment = 0.035
            elif word.pos_ in ("ADJ", "ADP", "DET"):
                pos_adjustment = 0.015
            elif word.pos_ in ("PRON", "CCONJ", "SCONJ"):
                pos_adjustment = -0.035

        sink_mass = (
            0.575
            + 0.39 * np.exp(-(i - 1) / 2.2)
            + pos_adjustment * (1.0 - np.exp(-(i - 1) / 2.0))
        )
        if i == 1:
            sink_mass = 0.963
        sink_mass = np.clip(sink_mass, 0.30, 0.975)

        # Preserve the original causal remainder and self-attention exactly.
        positions = np.arange(1, i + 1)
        distances = i - positions
        remainder = 0.18 + np.exp(-distances / 5.0)
        remainder[-1] *= 0.8
        remainder /= remainder.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * remainder

        # Only sentence-ending punctuation invokes the new path.
        if (
            i >= 12
            and alignment[i]
            and all(doc[k].pos_ == "PUNCT" for k in alignment[i])
            and any(c in ".!?" for k in alignment[i] for c in doc[k].text)
        ):
            anchors = np.zeros(i, dtype=np.float64)
            for j in range(1, i):
                if not alignment[j]:
                    continue
                k = alignment[j][-1]
                # Represent split words by their final model token only.
                if k in alignment[j + 1]:
                    continue
                source = doc[k]
                if source.pos_ in ("NOUN", "PROPN", "VERB", "ADJ", "ADV"):
                    weight = 0.18 + np.exp(-(i - j) / 5.0)
                    if source.pos_ == "VERB":
                        weight *= 2.0
                    if source.dep_ == "ROOT":
                        weight *= 2.0
                    anchors[j] = weight

            if anchors.sum() > 0.0:
                terminal_sink = 0.08 + 0.20 * np.exp(-(i - 12) / 10.0)
                released = max(0.0, attention[i, 0] - terminal_sink)
                attention[i, 0] -= released
                attention[i, :i] += released * anchors / anchors.sum()

    return "bos_sink_with_terminal_release", attention


def prog_L8H6(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with dilution; dialogue rementions divert sink mass to earlier
    semantic anchors, with a brief contextual spillover."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_dialogue_rementions", attention

    attention[0, 0] = 1.0

    for i in range(1, n):
        # More available keys gradually dilute the dominant first-token sink.
        residual_odds = 0.0018 * i + 0.00002 * i * i
        sink_mass = 1.0 / (1.0 + residual_odds)

        distances = i - np.arange(1, i + 1)
        recent = np.exp(-distances / 8.0)
        recent /= recent.sum()
        residual = 0.65 / i + 0.35 * recent

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    # Restrict the exception to multi-turn quoted discourse.
    quote_count = sum(sentence.count(q) for q in ('"', '“', '”'))
    if quote_count >= 4:
        doc = spacy_parse(sentence)
        aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
        representatives = [
            doc[ids[0]] if ids else None for ids in aligned
        ]
        content_pos = {"NOUN", "PROPN", "VERB"}
        active_targets = np.zeros(n, dtype=np.float64)
        active_at = -100

        for i in range(1, n):
            word = representatives[i]
            targets = np.zeros(n, dtype=np.float64)
            mass = 0.0

            if word is not None and word.pos_ in content_pos:
                best_similarity = 0.0
                for j in range(1, i):
                    earlier = representatives[j]
                    if earlier is None or earlier.i >= word.i:
                        continue
                    compatible = (
                        earlier.pos_ == word.pos_
                        or {earlier.pos_, word.pos_} <= {"NOUN", "PROPN"}
                    )
                    if not compatible:
                        continue

                    similarity = embedding_similarity(tokens, i, j, tokenizer)
                    if similarity > 0.48:
                        targets[j] = ((similarity - 0.48) / 0.52) ** 2
                        best_similarity = max(best_similarity, similarity)

                if targets.sum() > 0:
                    targets /= targets.sum()
                    strength = np.clip(
                        (best_similarity - 0.48) / 0.40, 0.0, 1.0
                    )
                    peak = 0.40 if word.pos_ == "PROPN" else 0.34
                    mass = peak * strength
                    active_targets = targets.copy()
                    active_at = i

            if mass == 0.0 and 0 < i - active_at <= 2:
                targets = active_targets.copy()
                mass = 0.09 * np.exp(-(i - active_at - 1) / 1.5)

            if mass > 0.0:
                # Transfer only from BOS: preserve the original diagonal,
                # decay, and every non-target residual weight exactly.
                transfer = min(mass, attention[i, 0])
                attention[i, 0] -= transfer
                attention[i] += transfer * targets

    return "bos_sink_with_dialogue_rementions", attention


def prog_L8H7(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with weak, diffuse causal attention elsewhere.
    Sink mass gradually decreases as more competing tokens become available.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    for i in range(n):
        attention[i, :i + 1] = 0.009
        attention[i, 0] = 1.0

    return "bos_sink_with_diffuse_causal_tail", make_row_stochastic(attention)


def prog_L8H8(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, with occasional diversion to a related earlier content token.
    Predict strongest lexical retrieval for repeated nouns and proper nouns.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_lexical_retrieval", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    content_pos = {"NOUN", "PROPN", "VERB", "ADJ"}
    pos = []
    for indices in alignment:
        candidates = [doc[k].pos_ for k in indices]
        content = [p for p in candidates if p in content_pos]
        pos.append(content[0] if content else (candidates[0] if candidates else ""))

    attention[0, 0] = 1.0

    for i in range(1, n):
        # The first position absorbs almost all mass even without lexical matches.
        sink_mass = 0.978 - min(0.045, 0.0008 * i)
        if pos[i] in {"NOUN", "PROPN", "PRON"}:
            sink_mass -= 0.012
        if i == 1:
            sink_mass = 0.993

        distances = i - np.arange(1, i + 1)
        background = np.exp(-distances / 6.0) + 0.15
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * background / background.sum()
        )
        attention[i, 0] = sink_mass

        if pos[i] not in content_pos:
            continue

        best_j = -1
        best_score = 0.0
        for j in range(1, i - 2):
            compatible = (
                pos[j] == pos[i]
                or {pos[j], pos[i]} <= {"NOUN", "PROPN"}
            )
            if not compatible:
                continue

            similarity = embedding_similarity(tokens, i, j, tokenizer)
            strength = max(0.0, min(1.0, (similarity - 0.78) / 0.22))
            score = strength * strength
            if score > best_score:
                best_score = score
                best_j = j

        if best_j >= 0:
            ceiling = 0.86 if pos[i] in {"NOUN", "PROPN"} else 0.60
            transfer = min(attention[i, 0], ceiling * best_score)
            attention[i, 0] -= transfer
            attention[i, best_j] += transfer

    return "bos_sink_with_lexical_retrieval", make_row_stochastic(attention)


def prog_L8H9(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with an early-position boost and weak linguistic modulation.
    Residual attention is diffuse and mildly biased toward recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_position_decay", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        aligned = alignment[i]
        word = doc[aligned[-1]] if aligned else None
        pos = word.pos_ if word is not None else ""
        dep = word.dep_ if word is not None else ""

        early = np.exp(-(i - 1) / 4.0)
        sink_mass = 0.55 + 0.29 * early

        if pos == "PROPN":
            sink_mass += 0.065
        elif pos in ("NOUN", "ADJ", "NUM"):
            sink_mass += 0.045
        elif pos in ("VERB", "AUX"):
            sink_mass -= 0.035
        elif pos == "DET":
            sink_mass -= 0.015
        elif pos in ("PUNCT", "SPACE"):
            sink_mass -= 0.065

        if dep in ("amod", "npadvmod"):
            sink_mass += 0.025
        if pos == "PUNCT" and i <= 4:
            sink_mass += 0.14

        if i == 1:
            if pos == "PROPN":
                sink_mass = 0.91
            elif pos == "PRON":
                sink_mass = 0.85
            elif pos == "DET":
                sink_mass = 0.81
            else:
                sink_mass = 0.83

        sink_mass = float(np.clip(sink_mass, 0.38, 0.93))
        attention[i, 0] = sink_mass

        # Non-sink edges are unobserved here: use a conservative broad prior.
        distances = i - np.arange(1, i + 1)
        residual = 0.65 + 0.35 * np.exp(-distances / 4.0)
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * residual / residual.sum()
        )

    return "bos_sink_with_position_decay", attention


def prog_L8H10(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with a weak position-dependent decline;
    residual attention favors recent context and earlier nominal subjects.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_nominal_residual", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    representatives = [
        doc[indices[-1]] if indices else None for indices in aligned
    ]
    attention[0, 0] = 1.0

    for i in range(1, n):
        word = representatives[i]
        maturity = 1.0 - np.exp(-(i - 1) / 12.0)
        sink_mass = 0.989 - 0.19 * (1.0 - np.exp(-(i - 1) / 28.0))

        if word is not None:
            pos = word.pos_
            if pos in ("NOUN", "PROPN"):
                sink_mass -= 0.16 * maturity
            elif pos == "PRON":
                sink_mass -= 0.10 * maturity
            elif pos in ("VERB", "AUX"):
                sink_mass -= 0.035 * maturity
            elif pos == "DET":
                sink_mass -= 0.045 * maturity
            elif pos in ("CCONJ", "SCONJ", "ADP", "ADV"):
                sink_mass += 0.035 * maturity
            elif pos == "PUNCT":
                sink_mass += 0.025 * maturity

        if tokens[i].isspace():
            sink_mass += 0.025 * maturity

        residual = np.zeros(i + 1, dtype=np.float64)
        for j in range(1, i + 1):
            residual[j] = (1.0 + i - j) ** -0.65
        residual[i] *= 0.45

        if word is not None:
            # Syntactic connections only supplement the dominant sink.
            for j in range(1, i):
                previous = representatives[j]
                if previous is None:
                    continue
                if previous.i == word.head.i and previous.i != word.i:
                    residual[j] += 0.8
                if previous.head.i == word.i and previous.i != word.i:
                    residual[j] += 0.25

            # A new nominal subject can retrieve the preceding discourse subject.
            if word.pos_ in ("NOUN", "PROPN") and word.dep_ in (
                "nsubj", "nsubjpass", "csubj"
            ):
                for j in range(i - 1, 0, -1):
                    previous = representatives[j]
                    if (
                        previous is not None
                        and previous.i != word.i
                        and previous.pos_ in ("NOUN", "PROPN")
                        and previous.dep_ in ("nsubj", "nsubjpass", "csubj")
                    ):
                        gap = i - j
                        if gap > 3:
                            retrieval = 0.38 * maturity * np.exp(-gap / 100.0)
                            sink_mass -= retrieval
                            residual[j] += 8.0
                        break

        sink_mass = float(np.clip(sink_mass, 0.25, 0.995))
        attention[i, 0] = sink_mass
        total = residual.sum()
        if total > 0.0:
            attention[i, 1:i + 1] = (
                (1.0 - sink_mass) * residual[1:i + 1] / total
            )
        else:
            attention[i, 0] = 1.0

    return "bos_sink_with_nominal_residual", make_row_stochastic(attention)


def prog_L8H11(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with local syntax, plus a predicative-adjective anchor at coordination.
    Coordinators and coordinated predicates redirect copular attention to the adjective."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_predicative_anchor", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for ti, sids in enumerate(alignment):
        for si in sids:
            if si < len(doc):
                inverse[si].append(ti)

    special_tokens = tokenizer.all_special_tokens
    attention[0, 0] = 1.0

    for i in range(1, n):
        clean = tokens[i].replace("Ġ", " ").replace("Ċ", "\n")
        sids = alignment[i]
        word = None
        for si in sids:
            candidate = doc[si]
            if word is None or (word.is_space and not candidate.is_space):
                word = candidate

        # The first few positions are almost entirely absorbed by the sink.
        opening = np.exp(-(i - 1) / 3.5)
        correction_scale = 1.0 - opening
        sink = 0.48 + 0.506 * opening

        if word is not None:
            pos = word.pos_
            correction = 0.0
            if pos in ("NOUN", "PROPN"):
                correction += 0.075
            elif pos == "DET":
                correction += 0.035
            elif pos in ("VERB", "AUX"):
                correction -= 0.065
            elif pos in ("ADJ", "ADV"):
                correction -= 0.035

            if word.dep_ in ("nsubj", "nsubjpass", "csubj"):
                correction += 0.045
            if word.dep_ in ("conj", "xcomp", "advcl"):
                correction -= 0.045
            if word.is_space:
                correction += 0.13
            elif word.is_punct:
                correction += 0.09 if word.text == "," else -0.045

            sink += correction_scale * correction
        elif clean.isspace():
            sink += correction_scale * 0.13

        if tokens[i] in special_tokens:
            sink = max(sink, 0.95)

        sink = float(np.clip(sink, 0.30, 0.995))

        # Allocate the smaller non-sink component locally, with a broad tail.
        positions = np.arange(1, i + 1)
        distances = i - positions
        residual = (
            0.7 * np.exp(-distances / 2.5)
            + 0.3 * np.exp(-distances / 12.0)
        )
        residual[-1] *= 0.45

        if word is not None:
            # Only already-visible syntactic relations can receive attention.
            head = word.head
            if head.i != word.i:
                for j in inverse[head.i]:
                    if 0 < j <= i:
                        residual[j - 1] += 0.8

                # Coordinated predicates can refer back to the earlier
                # predicate's descriptive modifiers.
                if word.dep_ == "conj":
                    for modifier in get_modifying_adjectives(head):
                        for j in inverse[modifier.i]:
                            if 0 < j <= i:
                                residual[j - 1] += 2.0

            for child in word.children:
                if child.dep_ in ("amod", "advmod", "compound"):
                    for j in inverse[child.i]:
                        if 0 < j < i:
                            residual[j - 1] += 0.45

            # Preserve a modest connection across pieces of the same word.
            for si in sids:
                for j in inverse[si]:
                    if 0 < j < i:
                        residual[j - 1] += 0.35

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual / residual.sum()

        # Predicative complements (acomp/oprd) are not ordinary modifiers.
        # Redirect only coordination rows, preserving self and all unrelated edges.
        if (
            word is not None
            and tokens[i] not in special_tokens
            and (
                word.dep_ == "cc"
                or (
                    word.dep_ == "conj"
                    and word.pos_ in ("VERB", "AUX", "ADJ")
                )
            )
        ):
            governor = word.head
            if word.dep_ == "cc" and governor.dep_ == "conj":
                governor = governor.head

            adjectives = []
            if governor.pos_ == "ADJ":
                adjectives.append(governor)
            elif governor.pos_ in ("VERB", "AUX"):
                adjectives.extend(
                    child for child in governor.children
                    if child.pos_ == "ADJ"
                    and child.dep_ in ("acomp", "attr", "oprd")
                )

            targets = [
                j
                for adjective in adjectives
                for j in inverse[adjective.i]
                if 0 < j < i
            ]
            if targets:
                target = max(targets)
                moved = 0.08 * correction_scale * attention[i, 0]
                attention[i, 0] -= moved

                if governor.pos_ in ("VERB", "AUX"):
                    for j in inverse[governor.i]:
                        if 0 < j < i and j != target:
                            amount = 0.85 * attention[i, j]
                            attention[i, j] -= amount
                            moved += amount

                attention[i, target] += moved

    return "bos_sink_with_predicative_anchor", make_row_stochastic(attention)


def prog_L8H12(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, strongest near the beginning, with weak POS modulation.
    Residual attention is mostly local and self-directed rather than syntactic.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_residual", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        pos = ""
        if alignment[i]:
            pos = doc[alignment[i][-1]].pos_

        sink = (
            0.49
            + 0.23 * np.exp(-max(i - 2, 0) / 10.0)
            + 0.05 * np.exp(-((i - 2) / 2.5) ** 2)
        )

        if pos in ("NOUN", "PROPN"):
            sink += 0.06
        elif pos == "ADJ":
            sink += 0.055
        elif pos == "ADV":
            sink += 0.025
        elif pos == "AUX":
            sink += 0.035
        elif pos == "VERB":
            sink += 0.025
        elif pos == "PRON":
            sink -= 0.035
        elif pos == "DET":
            sink -= 0.025
        elif pos == "PUNCT":
            sink -= 0.07

        clean = tokens[i].lstrip("Ġ▁").strip()
        is_quote = bool(clean) and all(c in "\"'“”‘’«»" for c in clean)
        if is_quote:
            sink -= 0.08

        sink = float(np.clip(sink, 0.35, 0.90))

        # Keep BOS mass independent of the number of available causal keys.
        distances = i - np.arange(1, i + 1, dtype=np.float64)
        local = np.exp(-distances / 2.5)
        local /= local.sum()

        residual = 0.45 * local + 0.15 / i
        residual[-1] += 0.40

        if is_quote:
            residual *= 0.5
            residual[-1] += 0.5

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual

    return "bos_sink_with_local_residual", make_row_stochastic(attention)


def prog_L8H13(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with a strong opening-position bias.
    Linguistic context modestly adjusts sink strength; residual attention is causal and local.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_opening_decay", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    words = [
        doc[indices[0]] if indices else None
        for indices in alignment
    ]

    special_tokens = set(tokenizer.all_special_tokens)
    has_bos = tokens[0] in special_tokens
    sink = 0
    attention[0, 0] = 1.0

    first_index = 1 if has_bos else 0
    first_word = words[first_index] if first_index < n else None
    introductory = (
        first_word is not None
        and (
            first_word.pos_ in ("ADP", "ADV", "NUM", "SCONJ")
            or first_word.dep_ in ("advmod", "npadvmod", "prep", "mark")
        )
    )

    for i in range(1, n):
        word = words[i]
        position = i if has_bos else i + 1
        opening = np.exp(-((position - 1.0) / 3.8) ** 1.35)
        sink_mass = 0.48 + 0.51 * opening

        if word is not None:
            pos = word.pos_
            if pos in ("ADP", "AUX", "ADV", "SCONJ"):
                sink_mass += 0.035
            elif pos in ("DET", "PRON"):
                sink_mass -= 0.025 * (1.0 - opening)
            elif pos == "PROPN":
                sink_mass -= 0.045
            elif pos in ("NOUN", "VERB"):
                sink_mass -= 0.015

            if word.dep_ in ("advmod", "npadvmod", "acomp"):
                sink_mass += 0.025

        if introductory and position > 1:
            sink_mass += 0.10 * np.exp(-((position - 3.0) / 3.5) ** 2)

        if position == 1:
            sink_mass = 0.985
            if word is not None:
                if word.pos_ == "PRON":
                    sink_mass = 0.990
                elif word.pos_ == "DET":
                    sink_mass = 0.979

        sink_mass = float(np.clip(sink_mass, 0.32, 0.992))

        # Keep the unexplained mass broad rather than inventing a sharp
        # syntactic mechanism unsupported by the dominant BOS edges.
        indices = np.arange(1, i + 1)
        residual = 0.45 / max(i, 1) + 0.55 * np.exp(
            -(i - indices) / 5.0
        )

        if word is not None:
            for k, j in enumerate(indices):
                previous = words[j]
                if previous is not None:
                    if previous.pos_ in ("NOUN", "PROPN", "VERB"):
                        residual[k] *= 1.12
                    if previous.i == word.head.i and j < i:
                        residual[k] *= 1.30

        # Opening quotation tokens can divert attention to a preceding comma.
        clean = tokens[i].lstrip("Ġ▁").strip()
        previous_clean = tokens[i - 1].lstrip("Ġ▁").strip()
        if clean in ('"', "“", "‘") and previous_clean == "," and i > 2:
            sink_mass = min(sink_mass, 0.40)
            residual[i - 2] += 4.0 * residual.sum()

        attention[i, sink] = sink_mass
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * residual / residual.sum()
        )

    return "bos_sink_with_opening_decay", make_row_stochastic(attention)


def prog_L8H14(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """A dominant first-token attention sink, strongest near sequence onset.
    Linguistic features mildly modulate sink strength; residual attention is local.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_position_decay", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        # Early queries overwhelmingly favor BOS; later queries retain a
        # substantial sink rather than switching to a syntactic target.
        sink = 0.63 + 0.345 * np.exp(-(i - 1) / 4.8)
        adjustment = 0.0

        if alignment[i]:
            word = doc[alignment[i][0]]
            if word.pos_ in ("NOUN", "PROPN"):
                adjustment = 0.035
            elif word.pos_ in ("VERB", "AUX"):
                adjustment = 0.025
            elif word.pos_ in ("ADJ", "ADV"):
                adjustment = 0.015
            elif word.pos_ in ("DET", "PRON", "PART"):
                adjustment = -0.045
            elif word.pos_ == "PUNCT":
                adjustment = -0.10
            elif word.pos_ == "SPACE":
                adjustment = -0.15

        # Preserve the especially strong, largely positional onset effect.
        sink += adjustment * (1.0 - np.exp(-(i - 1) / 3.0))
        sink = float(np.clip(sink, 0.35, 0.985))
        attention[i, 0] = sink

        # The examples establish the sink but not a reliable secondary target:
        # use a broad causal background with a modest recency preference.
        distances = i - np.arange(1, i + 1)
        residual = 0.25 + np.exp(-distances / 5.0)
        attention[i, 1:i + 1] = (1.0 - sink) * residual / residual.sum()

    return "bos_sink_with_position_decay", attention


def prog_L8H15(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with a strong early-position bias and modest subject boosts.
    Residual attention is diffuse and weakly recency-biased, rather than syntactic retrieval.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_position_subject", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        # The sink remains prominent even far from the beginning.
        early = np.exp(-(i - 1) / 3.5)
        sink = 0.46 + 0.50 * early

        aligned = alignment[i]
        if aligned:
            word = doc[aligned[0]]
            pos = word.pos_
            dep = word.dep_

            if pos == "PRON":
                sink += 0.065
                if dep in ("nsubj", "nsubjpass", "csubj", "csubjpass"):
                    sink += 0.075
            elif pos in ("NOUN", "PROPN"):
                if dep in ("nsubj", "nsubjpass"):
                    sink += 0.045
                elif pos == "PROPN":
                    sink -= 0.025
            elif pos in ("VERB", "AUX"):
                sink -= 0.025
            elif pos == "ADP":
                sink -= 0.020

            if pos == "PUNCT":
                if any(c in tokens[i] for c in ",\"'“”‘’"):
                    sink += 0.025
                elif any(c in tokens[i] for c in ".!?;:"):
                    sink -= 0.065

            # Clause openings mildly renew the preference for the sink.
            if word.is_sent_start and i > 1:
                sink += 0.035

        if i == 1:
            sink = 0.96
            if aligned and doc[aligned[0]].pos_ == "PRON":
                sink += 0.01
            elif aligned and doc[aligned[0]].pos_ == "PROPN":
                sink -= 0.025

        sink = float(np.clip(sink, 0.32, 0.98))
        attention[i, 0] = sink

        # The examples identify the sink, not particular non-BOS targets.
        # Use a conservative, broadly distributed causal residual.
        positions = np.arange(1, i + 1, dtype=np.float64)
        residual = (
            0.65 / i
            + 0.35
            * np.exp(-(i - positions) / 5.0)
            / np.exp(-(i - positions) / 5.0).sum()
        )
        attention[i, 1:i + 1] = (1.0 - sink) * residual

    return "bos_sink_position_subject", make_row_stochastic(attention)


def prog_L8H16(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with position-dependent decay and punctuation boosts.
    Residual attention is diffuse, with a weak causal recency preference.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_decay", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        surface = tokens[i].replace("\u0120", " ").replace("\u010a", "\n")
        aligned = alignment[i]
        word = None
        if aligned:
            word = max(
                (doc[k] for k in aligned),
                key=lambda w: len(w.text.strip())
            )

        sink = 0.26 + 0.60 / (1.0 + 0.055 * max(i - 2, 0))

        if word is not None:
            if word.pos_ in ("NOUN", "PROPN"):
                sink -= 0.055
            elif word.pos_ == "VERB":
                sink -= 0.035
            elif word.pos_ in ("AUX", "CCONJ"):
                sink += 0.045
            elif word.pos_ in ("DET", "ADP"):
                sink += 0.025
            elif word.pos_ in ("ADJ", "ADV"):
                sink -= 0.025

        stripped = surface.strip()
        punctuation = bool(stripped) and all(
            not c.isalnum() for c in stripped
        )
        if not stripped:
            sink += 0.18
        elif punctuation:
            if any(c in ".!?" for c in stripped):
                sink += 0.22
            elif "," in stripped or ";" in stripped or ":" in stripped:
                sink += 0.16
            else:
                sink += 0.08

        if i == 1:
            sink = 0.98
        sink = float(np.clip(sink, 0.20, 0.985))

        distances = i - np.arange(1, i + 1, dtype=np.float64)
        residual = 0.75 + 0.25 * np.exp(-distances / 6.0)
        residual /= residual.sum()

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual

    return "bos_sink_with_decay", attention


def prog_L8H17(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with mild positional decay and lexical-category modulation.
    Residual attention is diffuse and weakly biased toward recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_position_decay", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        distance = i - 1
        sink_mass = (
            0.64
            + 0.09 * np.exp(-distance / 12.0)
            - 0.11 * (1.0 - np.exp(-distance / 35.0))
        )

        aligned = alignment[i]
        if aligned:
            word = doc[aligned[0]]
            if word.pos_ in ("NOUN", "PROPN", "ADJ"):
                sink_mass += 0.045
            elif word.pos_ == "DET":
                sink_mass -= 0.035
            elif word.pos_ in ("PUNCT", "SPACE"):
                sink_mass -= 0.085
            elif word.pos_ == "AUX":
                sink_mass -= 0.025

        sink_mass = float(np.clip(sink_mass, 0.40, 0.83))
        attention[i, 0] = sink_mass

        positions = np.arange(1, i + 1, dtype=np.float64)
        residual = (
            0.70 / i
            + 0.30
            * np.exp(-(i - positions) / 5.0)
            / np.exp(-(i - positions) / 5.0).sum()
        )
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_position_decay", make_row_stochastic(attention)


def prog_L8H18(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with gradually weakening positional dominance.
    Residual attention favors recent content tokens and local syntactic links.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_content_residual", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    content_pos = ("NOUN", "PROPN", "VERB", "ADJ")
    salience = np.ones(n, dtype=np.float64)

    for j in range(1, n):
        if alignment[j]:
            word = doc[alignment[j][-1]]
            if word.pos_ in ("NOUN", "PROPN"):
                salience[j] = 2.0
            elif word.pos_ in ("VERB", "ADJ"):
                salience[j] = 1.25
            elif word.is_punct or word.is_space:
                salience[j] = 0.45

    attention[0, 0] = 1.0
    for i in range(1, n):
        sink = 0.995 / (1.0 + 0.018 * (i - 1))
        current = doc[alignment[i][-1]] if alignment[i] else None

        if current is not None:
            if current.pos_ in content_pos:
                sink += 0.025 * (1.0 - np.exp(-(i - 1) / 8.0))
            elif current.is_punct:
                sink -= 0.05 * (1.0 - np.exp(-(i - 1) / 8.0))
        sink = np.clip(sink, 0.20, 0.997)

        positions = np.arange(1, i + 1)
        weights = salience[1:i + 1] * (
            0.75 * np.exp(-(i - positions) / 7.0)
            + 0.25 / np.sqrt(i - positions + 1.0)
        )
        weights[-1] *= 0.65

        if current is not None:
            for j in range(1, i):
                if alignment[j]:
                    previous = doc[alignment[j][-1]]
                    if current.head.i == previous.i or previous.head.i == current.i:
                        weights[j - 1] *= 1.35
            if current.is_punct and i > 1:
                weights[-2] *= 2.5

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * weights / weights.sum()

    return "bos_sink_with_content_residual", make_row_stochastic(attention)


def prog_L8H19(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with gradual positional dilution and boundary boosts.
    Residual attention is diffuse and mildly biased toward recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_positional_dilution", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        # The first token remains the dominant destination, particularly
        # near the beginning of the sequence.
        dilution = 0.055 * (i - 1) ** 0.85
        sink_probability = 0.995 / (1.0 + dilution)

        mapped = alignment[i]
        word = None
        for k in mapped:
            if not doc[k].is_space:
                word = doc[k]
                break

        surface = tokens[i].replace("Ġ", " ").replace("Ċ", "\n")
        if surface.isspace():
            sink_probability += 0.20 * (1.0 - sink_probability)
        elif word is not None:
            if word.is_punct:
                sink_probability += 0.10 * (1.0 - sink_probability)
            elif word.pos_ in ("CCONJ", "SCONJ"):
                sink_probability += 0.12 * (1.0 - sink_probability)
            elif word.pos_ in ("DET", "ADP", "AUX"):
                sink_probability += 0.04 * (1.0 - sink_probability)

        sink_probability = float(np.clip(sink_probability, 0.05, 0.998))
        attention[i, 0] = sink_probability

        distances = i - np.arange(1, i + 1, dtype=np.float64)
        residual = 0.35 / i + 0.65 * np.exp(-distances / 8.0)
        residual /= residual.sum()
        attention[i, 1:i + 1] = (1.0 - sink_probability) * residual

    return "bos_sink_with_positional_dilution", attention


def prog_L8H20(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with a strong early-position prior and modest linguistic modulation.
    Residual attention is diffuse and mildly recency-biased, rather than dependency-focused.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_position_decay", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        aligned = alignment[i]
        word = doc[aligned[0]] if aligned else None
        surface = tokens[i].replace("Ġ", " ").replace("Ċ", "\n").strip()
        onset = 1.0 - np.exp(-(i - 1) / 5.0)

        # A persistent sink, strongest at the beginning of the sequence.
        sink = (
            0.66
            + 0.325 * np.exp(-(i - 1) / 3.8)
            - 0.0018 * (i - 1)
        )

        if not surface:
            sink += 0.15 * onset
        elif word is not None:
            if word.pos_ == "PUNCT":
                sink += 0.10 * onset
            elif word.pos_ in ("CCONJ", "SCONJ"):
                sink += 0.10 * onset
            elif word.pos_ in ("VERB", "AUX"):
                sink += 0.055 * onset
            elif word.pos_ in ("ADP", "PART", "ADV"):
                sink += 0.025 * onset
            elif word.pos_ in ("PRON", "DET"):
                sink -= 0.10 * onset
            elif word.pos_ in ("NOUN", "PROPN"):
                sink -= 0.055 * onset
            elif word.pos_ == "ADJ":
                sink -= 0.025 * onset

            if word.dep_ in ("poss", "nmod"):
                sink -= 0.035 * onset

        sink = float(np.clip(sink, 0.30, 0.995))

        # The supplied edges identify the sink, but not specific residual targets.
        # Use a conservative mixture of diffuse and local causal attention.
        positions = np.arange(1, i + 1)
        residual = 0.65 / i + 0.35 * (
            np.exp(-(i - positions) / 5.0)
            / np.exp(-(i - positions) / 5.0).sum()
        )
        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual

    return "bos_sink_with_position_decay", make_row_stochastic(attention)


def prog_L8H21(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with positional decay and sparse clause-boundary routing.
    Quotes and interrogative boundaries favor preceding discourse anchors.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    matrix = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_boundary_anchors", matrix

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = align_spacy_to_tokens(sentence, tokens, tokenizer)
    special = tokenizer.all_special_tokens
    words = [doc[ids[-1]] if ids else None for ids in aligned]

    # Track typographic quotation boundaries without lexical word tests.
    quote_open = [False] * n
    quote_close = [False] * n
    in_quote = False
    for i, token in enumerate(tokens):
        if token in special:
            continue
        text = token.lstrip("Ġ").lstrip("▁")
        if any(c in text for c in ('"', "“", "”", "«", "»")):
            closing = in_quote
            if any(c in text for c in ("”", "»")):
                closing = True
            elif any(c in text for c in ("“", "«")):
                closing = False
            quote_close[i] = closing
            quote_open[i] = not closing
            in_quote = not closing

    matrix[0, 0] = 1.0
    for i in range(1, n):
        word = words[i]
        position = float(i)
        sink = 0.43 + 0.57 * np.exp(-((position / 13.0) ** 1.45))

        if word is not None:
            if word.pos_ in ("NOUN", "PROPN") and word.dep_ in (
                "dobj", "obj", "iobj", "dative", "attr", "oprd"
            ):
                sink -= 0.20
            elif word.dep_ in ("pobj", "ROOT") and i > 5:
                sink -= 0.05
            if word.pos_ in ("CCONJ", "AUX"):
                sink += 0.05

        scores = np.zeros(i + 1, dtype=np.float64)
        for j in range(1, i + 1):
            distance = i - j
            score = np.exp(-distance / 5.5)
            target = words[j]
            if target is not None:
                if target.pos_ in ("NOUN", "PROPN"):
                    score *= 1.5
                if target.dep_ in ("dobj", "obj", "iobj", "attr", "oprd"):
                    score *= 2.2
                if target.pos_ == "VERB":
                    score *= 1.4
                if target.is_punct:
                    score *= 0.35
            if quote_close[j]:
                score *= 3.0
            if j == i:
                score *= 0.30
            scores[j] = score

        # A backward syntactic governor provides a modest residual route.
        if word is not None and word.head.i != word.i:
            candidates = [j for j in inverse[word.head.i] if 0 < j < i]
            if candidates:
                scores[candidates[-1]] += 1.5

        anchor = None
        anchor_fraction = 0.0
        if quote_open[i]:
            # Opening speech often selects the preceding recipient/object.
            for j in range(i - 1, max(0, i - 9), -1):
                target = words[j]
                if target is not None and target.pos_ in ("NOUN", "PROPN"):
                    anchor = j
                    anchor_fraction = 0.82
                    sink = 0.16
                    break

            # Later speech turns can instead reference the last closed turn.
            previous_closes = [j for j in range(1, i) if quote_close[j]]
            if previous_closes and i - previous_closes[-1] < 12:
                anchor = previous_closes[-1]
                anchor_fraction = 0.66
                sink = 0.36

        if word is not None and word.tag_ in ("WDT", "WP", "WP$", "WRB"):
            for j in range(i - 1, max(0, i - 5), -1):
                target = words[j]
                if target is None or target.is_punct:
                    continue
                if target.pos_ in ("NOUN", "PROPN"):
                    anchor = j
                    anchor_fraction = 0.95
                    sink = 0.055
                elif target.pos_ == "VERB":
                    anchor = j
                    anchor_fraction = 0.78
                    sink = 0.36
                break

        if word is not None and word.is_punct and i > 1:
            previous = words[i - 1]
            if previous is not None and previous.dep_ == "vocative":
                anchor = i - 1
                anchor_fraction = 0.96
                sink = 0.06

        sink = float(np.clip(sink, 0.025, 0.995))
        residual = 1.0 - sink
        total = scores.sum()
        if total > 0:
            scores /= total
        else:
            scores[i] = 1.0

        if anchor is not None:
            scores *= 1.0 - anchor_fraction
            scores[anchor] += anchor_fraction

        matrix[i, :i + 1] = residual * scores
        matrix[i, 0] = sink

    return "bos_sink_with_boundary_anchors", make_row_stochastic(
        apply_causal_mask(matrix)
    )


def prog_L8H22(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with dialogue-recipient reactivation and weaker
    syntactic, local, and semantic-repetition attention."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_dialogue_reactivation", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = align_spacy_to_tokens(sentence, tokens, tokenizer)
    spans = _char_spans(sentence, tokenizer)

    words = [doc[ids[-1]] if ids else None for ids in aligned]
    content_pos = ("NOUN", "PROPN", "VERB", "ADJ")
    object_deps = ("dobj", "obj", "iobj", "dative", "pobj")

    # Locate quoted turns and their most plausible preceding addressee.
    turns = []
    opening = None
    for char_index, char in enumerate(sentence):
        if char not in ('"', "“", "”"):
            continue
        if opening is None:
            opening = char_index
        else:
            turns.append((opening, char_index))
            opening = None
    if opening is not None:
        turns.append((opening, len(sentence)))

    dialogue = []
    previous_anchor = None
    for start, end in turns:
        preceding = [
            w for w in doc
            if w.idx < start and start - w.idx < 100
        ]
        anchor = None
        verbs = [w for w in preceding if w.pos_ == "VERB"]
        if verbs:
            reporting = verbs[-1]
            candidates = [
                w for w in preceding
                if w.i > reporting.i
                and w.dep_ in object_deps
                and (
                    w.head.i == reporting.i
                    or w.head.head.i == reporting.i
                )
                and w.pos_ in ("NOUN", "PROPN", "PRON")
            ]
            if candidates:
                target = candidates[-1]
                mapped = [
                    j for j in inverse[target.i]
                    if j > 0 and spans[j][0] < start
                ]
                if mapped:
                    anchor = mapped[-1]
        if anchor is None:
            anchor = previous_anchor
        dialogue.append((start, end, anchor))
        if anchor is not None:
            previous_anchor = anchor

    attention[0, 0] = 1.0
    for i in range(1, n):
        word = words[i]
        pos = word.pos_ if word is not None else ""
        background = np.zeros(i + 1, dtype=np.float64)

        # Weak causal background, biased toward recent tokens.
        positions = np.arange(1, i + 1)
        background[1:] = 0.035 + 0.10 * np.exp(-(i - positions) / 7.0)
        background[i] += 0.08

        if word is not None:
            for j in inverse[word.head.i]:
                if 0 < j <= i:
                    background[j] += 0.18

            # Semantic recurrence can compete with the sink, especially for
            # repeated objects across clauses.
            if pos in content_pos:
                candidates = [
                    j for j in range(1, i)
                    if words[j] is not None
                    and words[j].i != word.i
                    and words[j].pos_ in content_pos
                ]
                for j in candidates[-16:]:
                    similarity = embedding_similarity(tokens, i, j, tokenizer)
                    if similarity > 0.48:
                        background[j] += 5.0 * (
                            (similarity - 0.48) / 0.52
                        ) ** 3

        sink = 0.28 + 0.71 * np.exp(-(i - 1) / 28.0)
        if pos == "PUNCT":
            sink = min(0.96, sink + 0.07)

        semantic_peak = float(background.max())
        if semantic_peak > 1.0:
            sink *= 1.0 / (1.0 + 0.22 * semantic_peak)

        background /= background.sum()
        attention[i, :i + 1] = (1.0 - sink) * background
        attention[i, 0] = sink

        start_char, end_char = spans[i]
        for start, end, anchor in dialogue:
            if anchor is None or anchor >= i:
                continue

            strength = 0.0
            if start < end_char and start_char <= end:
                if pos == "PRON":
                    strength = 0.64
                elif pos == "VERB":
                    strength = 0.48
                elif pos == "AUX":
                    strength = 0.16
                elif pos in ("NOUN", "PROPN", "ADJ", "ADV"):
                    strength = 0.26
                if word is not None and word.tag_.startswith("W"):
                    strength = 0.43
                elif pos == "AUX" and start_char - start < 4:
                    strength = 0.78
            elif 0 < start_char - end < 45 and pos == "VERB":
                strength = 0.43

            if strength:
                attention[i, :i + 1] *= 1.0 - strength
                attention[i, anchor] += strength
                break

    return (
        "bos_sink_dialogue_reactivation",
        make_row_stochastic(apply_causal_mask(attention)),
    )


def prog_L8H23(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with position-dependent strength and small POS corrections.
    Residual attention is diffuse and mildly biased toward recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_positional_decay", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.46 + 0.52 * np.exp(-(i - 1) / 10.0)

        # Linguistic corrections are deliberately weak: the evidence primarily
        # supports an attention sink, not a syntactic retrieval mechanism.
        correction = 0.0
        if alignment[i]:
            word = doc[alignment[i][0]]
            if word.pos_ in ("ADJ", "NOUN", "PROPN"):
                correction = 0.025
            elif word.pos_ in ("PRON", "CCONJ", "SCONJ"):
                correction = -0.025
            elif word.is_punct:
                correction = -0.035
        correction *= 1.0 - np.exp(-(i - 1) / 5.0)
        sink_mass = float(np.clip(sink_mass + correction, 0.05, 0.99))

        positions = np.arange(1, i + 1, dtype=np.float64)
        residual = 0.7 + 0.3 * np.exp(-(i - positions) / 6.0)
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual / residual.sum()
        attention[i, 0] = sink_mass

    return "bos_sink_with_positional_decay", attention


def prog_L9H0(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with position-dependent decay and weaker attention
    to recent context, syntactic links, and discourse-boundary punctuation.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_boundary_backoff", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    features = []
    boundary_strength = np.ones(n, dtype=np.float64)

    for j, token in enumerate(tokens):
        aligned = alignment[j]
        word = doc[aligned[0]] if aligned else None
        features.append(word)

        clean = token.lstrip("Ġ▁").strip()
        if clean and all(c in ".,;:!?\"'“”‘’()[]{}—–-" for c in clean):
            boundary_strength[j] = 1.7
            if any(c in ".!?" for c in clean):
                boundary_strength[j] = 4.5
            elif any(c in ";:" for c in clean):
                boundary_strength[j] = 2.5
        elif not clean:
            boundary_strength[j] = 1.4

    attention[0, 0] = 1.0

    for i in range(1, n):
        word = features[i]

        # The dominant signal is an absolute-position-dependent BOS sink.
        sink = 0.97 / (1.0 + 0.075 * i) ** 0.90
        if word is not None:
            if word.pos_ in ("NOUN", "PROPN"):
                sink += 0.035
            elif word.pos_ in ("VERB", "AUX"):
                sink -= 0.035
            elif word.pos_ in ("PRON", "SCONJ"):
                sink -= 0.025
            if word.dep_ in ("nsubj", "nsubjpass") and i <= 4:
                sink += 0.025

        clean = tokens[i].lstrip("Ġ▁").strip()
        if not clean:
            sink += 0.055
        elif clean and all(c in ",;:" for c in clean):
            sink += 0.08

        if i == 1:
            sink = 0.93
            if word is not None and word.pos_ == "DET":
                sink = 0.90
        sink = float(np.clip(sink, 0.12, 0.97))

        keys = np.arange(1, i + 1)
        distance = i - keys
        weights = (
            0.35 + np.exp(-distance / 14.0)
        ) * boundary_strength[1:i + 1]

        # Prefer completed boundaries over punctuation at the query itself.
        if boundary_strength[i] > 1.0:
            weights[-1] *= 0.45

        if word is not None:
            for k, j in enumerate(range(1, i + 1)):
                previous = features[j]
                if previous is None:
                    continue
                if previous.i != word.i and (
                    previous.i == word.head.i or previous.head.i == word.i
                ):
                    weights[k] *= 1.25
                if previous.i == word.i and j != i:
                    weights[k] *= 1.35

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * weights / weights.sum()

    return "bos_sink_with_boundary_backoff", attention


def prog_L9H1(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with positional decay and weaker clause-boundary anchors.
    Content words retain more sink attention than punctuation and clause transitions.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_boundary_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    pos = [""] * n
    dep = [""] * n
    punctuation = np.zeros(n, dtype=bool)
    whitespace = np.zeros(n, dtype=bool)
    boundary = np.zeros(n, dtype=bool)
    key_strength = np.zeros(n, dtype=np.float64)

    for j, token in enumerate(tokens):
        clean = token.replace("Ġ", " ").replace("Ċ", "\n")
        whitespace[j] = bool(clean) and clean.isspace()
        punctuation[j] = bool(clean.strip()) and all(
            not c.isalnum() for c in clean.strip()
        )
        boundary[j] = any(c in ".!?" for c in clean)

        if alignment[j]:
            words = [doc[k] for k in alignment[j]]
            word = max(
                words,
                key=lambda w: (not w.is_space, not w.is_punct, len(w.text)),
            )
            pos[j] = word.pos_
            dep[j] = word.dep_

        strength = 0.12
        if pos[j] in ("NOUN", "PROPN"):
            strength += 0.85
        elif pos[j] in ("VERB", "ADJ"):
            strength += 0.30
        if dep[j] in ("ROOT", "nsubj", "obj", "pobj"):
            strength += 0.25
        strength *= 0.45 + np.exp(-j / 18.0)

        if boundary[j]:
            strength += 3.5
        elif punctuation[j]:
            strength += 0.25
        if whitespace[j]:
            strength *= 0.15
        key_strength[j] = strength

    attention[0, 0] = 1.0
    for i in range(1, n):
        sink = 0.40 + 0.57 * np.exp(-(i - 1) / 23.0)

        if pos[i] in ("NOUN", "PROPN"):
            sink += 0.055
        elif pos[i] == "DET":
            sink += 0.025
        elif pos[i] in ("VERB", "ADV", "SCONJ"):
            sink -= 0.045

        if punctuation[i]:
            sink -= 0.12 * (1.0 - np.exp(-(i - 1) / 7.0))
        if whitespace[i]:
            sink -= 0.16
        if i == 1:
            sink = 0.97

        sink = float(np.clip(sink, 0.24, 0.98))
        attention[i, 0] = sink

        indices = np.arange(1, i + 1)
        distances = i - indices
        weights = key_strength[1:i + 1] * (
            0.35 + np.exp(-distances / 24.0)
        )
        weights += 0.06 * np.exp(-distances / 3.0)
        weights[-1] *= 0.45

        attention[i, 1:i + 1] = (1.0 - sink) * weights / weights.sum()

    return "bos_sink_with_boundary_anchors", attention


def prog_L9H2(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with syntactic residuals; dialogue redirects residual attention
    toward quotation boundaries and speakers rather than preceding objects.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_dialogue_boundaries", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, indices in enumerate(alignment):
        for k in indices:
            inverse[k].append(i)

    special_tokens = tokenizer.all_special_tokens
    has_bos = tokens[0] in special_tokens
    features = []
    for i, token in enumerate(tokens):
        candidates = alignment[i]
        word = doc[candidates[-1]] if candidates else None
        clean = token.replace("Ġ", " ").replace("Ċ", "\n").strip()
        features.append((word, clean))

    # Activate only for comma-introduced speech following a nearby verb.
    dialogue_start = next(
        (
            j for j in range(1, n)
            if features[j][1] in ('"', "“")
            and "," in features[j - 1][1]
            and any(
                features[k][0] is not None
                and features[k][0].pos_ == "VERB"
                for k in range(max(1, j - 7), j)
            )
        ),
        n,
    )

    attention[0, 0] = 1.0

    for i in range(1, n):
        word, clean = features[i]
        pos = word.pos_ if word is not None else ""
        dep = word.dep_ if word is not None else ""

        # Most queries retain a strong null/BOS component, especially early.
        sink = 0.20 + 0.76 * np.exp(-0.16 * (i - 1))
        if pos == "AUX":
            sink += 0.13
        elif pos in ("CCONJ", "SCONJ"):
            sink += 0.10
        elif pos in ("ADP", "DET"):
            sink += 0.05
        elif pos == "PRON" and i > 4:
            sink -= 0.04

        if clean and all(c in ",;:" for c in clean):
            sink = max(sink, 0.89 * np.exp(-0.025 * max(i - 14, 0)))
        elif clean and all(c in ".!?" for c in clean):
            sink = max(sink, 0.88 * np.exp(-0.024 * max(i - 16, 0)))
        elif clean and all(c in ".!?\"'“”‘’" for c in clean):
            sink = max(sink, 0.67 * np.exp(-0.025 * max(i - 12, 0)))
        elif not clean:
            sink = max(sink, 0.93 * np.exp(-0.018 * i))

        if i == 1 and has_bos:
            sink = 0.96
        sink = float(np.clip(sink, 0.12, 0.98))

        residual = np.zeros(i + 1, dtype=np.float64)
        start = 1 if has_bos else 0
        for j in range(start, i + 1):
            previous, previous_clean = features[j]
            distance = i - j
            residual[j] = 0.18 / np.sqrt(1.0 + distance)

            if previous is not None:
                if previous.pos_ == "PROPN":
                    residual[j] += 0.22 / (1.0 + 0.025 * distance)
                if previous.dep_ in ("nsubj", "nsubjpass", "csubj"):
                    residual[j] += 0.14 / (1.0 + 0.035 * distance)

        residual[i] += 0.45
        if i - 1 >= start:
            residual[i - 1] += 0.25

        if word is not None:
            # Only causal dependency links are eligible.
            for j in inverse[word.head.i]:
                if start <= j <= i and word.head.i != word.i:
                    residual[j] += 0.95

            for child in word.children:
                for j in inverse[child.i]:
                    if start <= j < i:
                        residual[j] += 0.35

            # Keep the original fallback outside detected reporting dialogue.
            quote_positions = [
                j for j in range(start, i)
                if any(c in "\"“”" for c in features[j][1])
            ]
            if quote_positions and i < dialogue_start:
                boundary = quote_positions[-1]
                anchors = [
                    j for j in range(start, boundary)
                    if features[j][0] is not None
                    and features[j][0].pos_ in ("NOUN", "PROPN")
                    and features[j][0].dep_ in ("dobj", "obj", "iobj", "pobj")
                ]
                if anchors and i - boundary <= 12:
                    residual[anchors[-1]] += 1.4

        if i >= dialogue_start:
            # Speech boundaries persist across the following narrative clause.
            openings = [
                j for j in range(dialogue_start, i + 1)
                if features[j][1] in ('"', "“")
                and "," in features[j - 1][1]
            ]
            boundary = openings[-1]
            residual[boundary] += 1.25
            residual[boundary - 1] += 0.95
            closings = [
                j for j in range(boundary + 1, i + 1)
                if any(c in "\"”" for c in features[j][1])
            ]
            if closings:
                residual[closings[-1]] += 1.10

            speakers = [
                j for j in range(start, boundary)
                if features[j][0] is not None
                and features[j][0].dep_ in ("nsubj", "nsubjpass", "csubj")
                and features[j][0].pos_ in ("NOUN", "PROPN", "PRON")
            ]
            if speakers:
                residual[speakers[-1]] += 1.0

            if clean and all(c in ",;:\"“”" for c in clean):
                sink = min(sink, 0.36)
            elif pos == "AUX" and not closings:
                sink = min(sink, 0.28)
            elif pos in ("NOUN", "PROPN", "PRON", "VERB", "DET"):
                sink = max(sink, 0.42)

        total = residual.sum()
        if has_bos:
            attention[i, 0] = sink
            if total > 0:
                attention[i, :i + 1] += (1.0 - sink) * residual / total
            else:
                attention[i, i] += 1.0 - sink
        elif total > 0:
            attention[i, :i + 1] = residual / total
        else:
            attention[i, i] = 1.0

    return "bos_sink_with_dialogue_boundaries", make_row_stochastic(
        apply_causal_mask(attention)
    )


def prog_L9H3(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Dominant BOS attention sink with a mild positional decay.
    Residual attention is diffuse and recency-biased, with small POS corrections.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_diffuse_recency", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = (
            0.740
            + 0.100 * np.exp(-(i - 1) / 3.0)
            + 0.035 * np.exp(-(i - 1) / 35.0)
        )

        aligned = alignment[i]
        if aligned:
            word = doc[aligned[0]]
            if word.pos_ in ("ADP", "DET", "AUX", "CCONJ", "SCONJ"):
                sink_mass += 0.010
            elif word.pos_ == "PUNCT":
                sink_mass -= 0.025

        sink_mass = np.clip(sink_mass, 0.65, 0.90)
        attention[i, 0] = sink_mass

        positions = np.arange(1, i + 1, dtype=np.float64)
        residual = 0.60 / i + 0.40 * (
            np.exp(-(i - positions) / 5.0)
            / np.exp(-(i - positions) / 5.0).sum()
        )
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_diffuse_recency", make_row_stochastic(attention)


def prog_L9H4(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, strongest near the start, with weak local syntactic spillover."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_spillover", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = align_spacy_to_tokens(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink = 0.76 + 0.20 * np.exp(-(i - 1) / 4.0)
        linked = alignment[i]
        word = doc[linked[0]] if linked else None

        if word is not None:
            if word.pos_ == "PUNCT":
                sink -= 0.055 * (1.0 - np.exp(-(i - 1) / 4.0))
            elif word.pos_ in ("VERB", "AUX"):
                sink += 0.015
            if word.is_sent_start and i > 1:
                sink += 0.035

        # Opening quotation marks weakly reset the sink-dominated regime.
        for distance in range(1, min(i, 5) + 1):
            clean = tokens[i - distance].lstrip("Ġ▁").strip()
            if clean and clean[0] in ('"', "“", "«"):
                sink += 0.065 * np.exp(-(distance - 1) / 4.0)
                break

        sink = float(np.clip(sink, 0.60, 0.97))
        positions = np.arange(1, i + 1)
        residual = 0.35 / i + np.exp(-(i - positions) / 4.0)

        if word is not None:
            for j in inverse[word.head.i]:
                if 1 <= j <= i and word.head.i != word.i:
                    residual[j - 1] += 0.35

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual / residual.sum()

    return "bos_sink_with_local_spillover", attention


def prog_L9H5(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with slowly increasing leakage as context grows.
    Residual attention is diffuse and mildly recency-biased."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_position_decay", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        # Linguistic modulation is deliberately small: the visible evidence
        # overwhelmingly supports a positional sink, not a dependency head.
        leakage_scale = 1.0
        aligned = alignment[i]
        if aligned:
            pos = doc[aligned[0]].pos_
            if pos in ("NOUN", "PROPN"):
                leakage_scale = 1.18
            elif pos in ("VERB", "ADJ"):
                leakage_scale = 1.08
            elif pos in ("DET", "AUX", "PRON", "ADP"):
                leakage_scale = 0.92

        odds = 0.014 * (i ** 0.8) * leakage_scale
        sink_mass = 1.0 / (1.0 + odds)
        attention[i, 0] = sink_mass

        positions = np.arange(1, i + 1, dtype=np.float64)
        recency = np.exp(-(i - positions) / 8.0)
        recency /= recency.sum()
        residual = 0.7 / i + 0.3 * recency
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_position_decay", attention


def prog_L9H6(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with boundary boosts; quoted dialogue sustains the sink and
    briefly anchors attention to its opening quotation mark.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_quote_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special_tokens = tokenizer.all_special_tokens
    words = [
        doc[indices[0]] if indices else None
        for indices in alignment
    ]
    attention[0, 0] = 1.0

    in_quote = False
    dialogue_seen = False
    quote_anchor = -1

    for i in range(1, n):
        word = words[i]
        surface = tokens[i].replace("Ġ", " ").replace("Ċ", "\n").strip()
        sink = 0.30 + 0.668 * np.exp(-0.24 * (i - 1))

        if i > 1:
            if word is not None:
                if word.pos_ in ("VERB", "AUX"):
                    sink += 0.035
                elif word.pos_ in ("CCONJ", "SCONJ"):
                    sink += 0.085
                elif word.pos_ in ("NOUN", "PROPN", "ADJ"):
                    sink -= 0.035

                if word.is_sent_start:
                    sink += 0.14
                if word.dep_ == "neg":
                    sink += 0.13

            if not surface:
                sink += 0.34
            elif surface in (".", "!", "?"):
                sink += 0.32
            elif surface == ",":
                sink += 0.22
            elif all(c in ".,!?;:—–-\"'“”‘’()[]" for c in surface):
                sink += 0.15

            if tokens[i] in special_tokens:
                sink += 0.20

        sink = float(np.clip(sink, 0.16, 0.985))
        attention[i, 0] = sink

        positions = np.arange(1, i + 1)
        weights = (
            0.30 / i
            + 0.70 * np.exp(-(i - positions) / 4.5)
        )
        weights[-1] *= 0.65

        if word is not None:
            for j in range(1, i + 1):
                previous = words[j]
                if previous is None:
                    continue
                if word.head.i == previous.i and word.i != previous.i:
                    weights[j - 1] += 0.30
                if j < i and previous.pos_ == "ADP" and word.head.i == previous.i:
                    weights[j - 1] += 0.80

        attention[i, 1:i + 1] = (1.0 - sink) * weights / weights.sum()

        # Only quoted passages activate this correction. Self-attention is
        # excluded from every transfer, preserving its original value exactly.
        if any(c in surface for c in "\"“”«»"):
            in_quote = not in_quote
            dialogue_seen = True
            if in_quote:
                quote_anchor = i

        if dialogue_seen:
            targets = []
            if word is not None and not word.is_punct and surface:
                floor = 0.47
                if word.pos_ == "VERB" and word.dep_ in ("xcomp", "ccomp"):
                    floor = 0.35
                targets.append((0, floor))
            if in_quote and 0 < quote_anchor < i and i - quote_anchor <= 6:
                targets.append((quote_anchor, 0.28))

            for target, floor in targets:
                deficit = max(0.0, floor - attention[i, target])
                if deficit == 0.0:
                    continue
                donors = attention[i, :i].copy()
                donors[0] = 0.0
                donors[target] = 0.0
                available = donors.sum()
                if available > 0.0:
                    transfer = min(deficit, available)
                    attention[i, :i] -= donors * (transfer / available)
                    attention[i, target] += transfer

    return "bos_sink_with_quote_anchors", attention


def prog_L9H7(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with an early-position bias and clause-boundary boosts.
    Residual attention follows local context and preceding phrase structure.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_phrase_structure", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for ti, sids in enumerate(alignment):
        for si in sids:
            inverse[si].append(ti)

    attention[0, 0] = 1.0
    sentence_age = 100
    quotation_marks = ('"', "'", "“", "”", "‘", "’", "«", "»")

    for i in range(1, n):
        sids = alignment[i]
        word = doc[sids[-1]] if sids else None
        surface = tokens[i].replace("Ġ", " ").replace("Ċ", "\n").strip()
        previous = tokens[i - 1].replace("Ġ", " ").strip()

        # Most of the head's probability remains on the initial sink.
        sink = 0.31 + 0.667 * np.exp(-(i - 1) / 3.5)

        first_piece = (
            word is not None
            and inverse[word.i]
            and inverse[word.i][0] == i
        )
        if first_piece and word.is_sent_start and i > 1:
            sentence_age = 0
        else:
            sentence_age += 1

        if sentence_age < 4 and not any(q in previous for q in quotation_marks):
            sink += 0.30 * np.exp(-sentence_age / 1.7)

        if word is not None:
            if word.pos_ in ("VERB", "AUX"):
                if word.dep_ in ("ROOT", "conj", "ccomp", "advcl"):
                    sink += 0.11
                else:
                    sink += 0.035
            elif word.pos_ in ("CCONJ", "SCONJ"):
                sink += 0.09
            elif word.pos_ in ("DET", "PRON"):
                sink += 0.025
            elif word.pos_ in ("NOUN", "PROPN"):
                sink -= 0.035
            if word.dep_ in ("neg",):
                sink += 0.20

        if surface and all(c in ",;:" for c in surface):
            sink += 0.21
        elif surface and all(c in ".!?" for c in surface):
            sink += 0.25
        elif surface and any(q in surface for q in quotation_marks):
            sink += 0.12

        if not surface:
            sink += 0.32

        sink = float(np.clip(sink, 0.20, 0.94))
        if i == 1:
            sink = 0.977

        residual = np.zeros(i + 1, dtype=np.float64)
        positions = np.arange(1, i + 1)
        residual[1:] = 0.20 * np.exp(-(i - positions) / 4.0)
        residual[i] += 0.12
        if i > 1:
            residual[i - 1] += 0.62

        if word is not None:
            # Retain subword continuity without lexical identity tests.
            earlier_pieces = [j for j in inverse[word.i] if 0 < j < i]
            if earlier_pieces:
                residual[earlier_pieces[-1]] += 0.45

            head_indices = [
                j for j in inverse[word.head.i]
                if 0 < j < i
            ]
            if head_indices and word.head.i != word.i:
                distance = i - head_indices[-1]
                bonus = 0.30 * np.exp(-distance / 12.0)
                if word.dep_ in ("pobj", "dobj", "obj", "attr", "acomp"):
                    bonus += 0.65
                residual[head_indices[-1]] += bonus

            # Nouns often look back to the beginning of their local phrase.
            if word.pos_ in ("NOUN", "PROPN"):
                for child in word.children:
                    if child.dep_ in ("det", "poss"):
                        candidates = [
                            j for j in inverse[child.i]
                            if 0 < j < i
                        ]
                        if candidates:
                            residual[candidates[-1]] += (
                                0.55 * np.exp(-(i - candidates[-1]) / 6.0)
                            )

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (
            (1.0 - sink) * residual[1:] / residual[1:].sum()
        )

    return "bos_sink_with_local_phrase_structure", make_row_stochastic(attention)


def prog_L9H8(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with local syntax; dialogue delimiters bypass the immediately
    preceding token while preserving the original self-attention weights."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_dialogue_delimiters", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for ti, indices in enumerate(alignment):
        for si in indices:
            if si < len(doc):
                inverse[si].append(ti)

    special_tokens = set(tokenizer.all_special_tokens)
    attention[0, 0] = 1.0

    for i in range(1, n):
        indices = alignment[i]
        word = doc[indices[-1]] if indices else None
        pos = word.pos_ if word is not None else ""
        dep = word.dep_ if word is not None else ""

        sink = 0.52
        if pos in ("NOUN", "PROPN"):
            sink = 0.57
        elif pos == "ADJ":
            sink = 0.62
        elif pos in ("VERB", "AUX"):
            sink = 0.54
        elif pos in ("PRON", "DET", "NUM"):
            sink = 0.55
        elif pos == "ADV":
            sink = 0.49
        elif pos in ("ADP", "PART", "SCONJ"):
            sink = 0.43
        elif pos == "CCONJ":
            sink = 0.36
        elif pos == "PUNCT":
            sink = 0.40

        sink += 0.16 * np.exp(-max(i - 2, 0) / 3.5)
        if word is not None and word.ent_type_:
            sink += 0.025
        if tokens[i] in special_tokens:
            sink = 0.75
        if i == 1:
            sink = 0.89
        sink = float(np.clip(sink, 0.25, 0.92))

        local = np.exp(-(i - np.arange(1, i + 1)) / 3.0)
        local *= 0.12 / local.sum()
        local[-1] += 0.16
        if i > 1:
            local[-2] += 0.60

        # Only syntactic heads already in the causal context can receive mass.
        if word is not None and word.head.i != word.i:
            preceding = [j for j in inverse[word.head.i] if 0 < j < i]
            if preceding:
                strength = 0.20 if dep in (
                    "prep", "cc", "mark", "case", "aux", "prt"
                ) else 0.10
                local[preceding[-1] - 1] += strength

        # Preserve a modest connection across subword pieces of one spaCy token.
        if i > 1 and indices and alignment[i - 1]:
            if any(si in alignment[i - 1] for si in indices):
                local[-2] += 0.12

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * local / local.sum()

        # Dialogue openings: a comma after a verb is not a strong verb edge,
        # and an opening quote looks past that comma to the reporting clause.
        # Transfer only predecessor mass; leave self-attention exactly intact.
        if i > 2 and pos == "PUNCT" and tokens[i] not in special_tokens:
            previous = (
                doc[alignment[i - 1][-1]] if alignment[i - 1] else None
            )
            earlier = (
                doc[alignment[i - 2][-1]] if alignment[i - 2] else None
            )
            text = tokens[i].lstrip("Ġ").strip()
            opening_quote = text in ('"', "“", "‘")
            next_quote = (
                i + 1 < n
                and tokens[i + 1].lstrip("Ġ").strip() in ('"', "“", "‘")
            )

            if (
                text == ","
                and next_quote
                and previous is not None
                and previous.pos_ == "VERB"
            ):
                moved = 0.80 * attention[i, i - 1]
                attention[i, i - 1] -= moved
                attention[i, 0] += 0.50 * moved
                attention[i, i - 2] += 0.50 * moved
            elif (
                opening_quote
                and previous is not None
                and previous.text == ","
                and earlier is not None
                and earlier.pos_ == "VERB"
            ):
                moved = 0.85 * attention[i, i - 1]
                attention[i, i - 1] -= moved
                attention[i, i - 2] += 0.75 * moved
                attention[i, 0] += 0.25 * moved

    return "bos_sink_dialogue_delimiters", attention


def prog_L9H9(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with gradual positional dilution.
    Linguistic features weakly modulate leakage into a causal recency background.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_positional_dilution", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        pos = ""
        if alignment[i]:
            pos = doc[alignment[i][0]].pos_

        leakage_factor = 1.0
        if pos == "PRON":
            leakage_factor = 1.20
        elif pos in ("NOUN", "PROPN"):
            leakage_factor = 0.88
        elif pos in ("DET", "PUNCT"):
            leakage_factor = 1.08

        leakage_odds = 0.016 * (i ** 1.10) * leakage_factor

        # The first lexical token shows particularly strong sink attention.
        if i == 1:
            if pos == "PRON":
                leakage_odds = 0.006
            elif pos == "PROPN":
                leakage_odds = 0.011
            else:
                leakage_odds = 0.019

        sink_mass = 1.0 / (1.0 + leakage_odds)
        attention[i, 0] = sink_mass

        # The examples constrain the sink much more than the residual edges.
        # Use a diffuse, mildly recency-weighted causal distribution for those.
        distances = i - np.arange(1, i + 1, dtype=np.float64)
        background = 0.65 + 0.35 * np.exp(-distances / 8.0)
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * background / background.sum()
        )

    return "bos_sink_with_positional_dilution", attention


def prog_L9H10(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Dominant BOS attention sink, gradually diluted by context length.
    Residual attention weakly favors recent tokens and salient antecedents.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_antecedent_backoff", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    features = []
    for indices in alignment:
        if indices:
            word = doc[indices[-1]]
            features.append((word.pos_, word.dep_, bool(word.ent_type_)))
        else:
            features.append(("", "", False))

    attention[0, 0] = 1.0
    for i in range(1, n):
        query_pos, query_dep, _ = features[i]
        weights = np.ones(i, dtype=np.float64)
        antecedent_found = False

        for j in range(1, i + 1):
            key_pos, key_dep, key_entity = features[j]
            distance = i - j
            weight = 0.45 + 0.55 * np.exp(-distance / 18.0)

            if key_pos in ("NOUN", "PROPN"):
                weight *= 1.35
            if key_dep in ("nsubj", "nsubjpass", "csubj"):
                weight *= 1.35
            if key_entity:
                weight *= 1.10
            if key_pos == "PUNCT":
                weight *= 0.65

            if j < i and query_pos in ("NOUN", "PROPN", "PRON"):
                if key_pos in ("NOUN", "PROPN"):
                    weight *= 1.35
                    if key_dep in ("nsubj", "nsubjpass"):
                        weight *= 1.25
                        antecedent_found = True

            weights[j - 1] = weight

        competition = 0.011 * i ** 1.15
        if antecedent_found and query_dep in ("nsubj", "nsubjpass"):
            competition *= 1.25

        sink_mass = 1.0 / (1.0 + competition)
        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * weights / weights.sum()
        )

    return "bos_sink_with_antecedent_backoff", make_row_stochastic(attention)


def prog_L9H11(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with gradual positional dilution.
    Residual attention weakly favors recent context and nominal antecedents of pronouns.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_weak_antecedents", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    words = [
        doc[indices[-1]] if indices else None
        for indices in alignment
    ]

    attention[0, 0] = 1.0
    for i in range(1, n):
        word = words[i]
        positions = np.arange(1, i + 1)
        weights = np.exp(-(i - positions) / 32.0)

        # Keep the sink dominant; accumulated competing keys dilute it.
        competition = 0.018 * i
        if word is not None:
            if word.pos_ == "PRON" and word.dep_ != "expl":
                competition *= 1.55
            elif word.pos_ in ("ADP", "AUX", "CCONJ"):
                competition *= 0.85
            elif word.pos_ == "PUNCT":
                competition *= 1.10

            for j in range(1, i + 1):
                previous = words[j]
                if previous is None:
                    continue

                if (
                    word.pos_ == "PRON"
                    and word.dep_ != "expl"
                    and j < i
                    and previous.pos_ in ("NOUN", "PROPN")
                ):
                    bonus = 2.0
                    if previous.dep_ in ("nsubj", "nsubjpass", "dobj", "obj", "pobj"):
                        bonus += 1.0
                    if previous.ent_type_ == "PERSON":
                        bonus += 0.5
                    weights[j - 1] *= bonus

                if previous.i == word.head.i and previous.i != word.i:
                    weights[j - 1] *= 1.15

        sink_mass = 1.0 / (1.0 + competition)
        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * weights / weights.sum()
        )

    return "bos_sink_with_weak_antecedents", attention


def prog_L9H12(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with positional decay and syntactic gating.
    Clause scaffolding favors the sink; content-bearing arguments weaken it.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_syntactic_decay", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        words = [doc[k] for k in alignment[i]]
        word = max(
            words,
            key=lambda w: (not w.is_space, not w.is_punct, len(w.text)),
            default=None,
        )

        # Strong sink at the beginning, with slower decay over long contexts.
        maturity = 1.0 - np.exp(-(i - 1) / 3.0)
        logit = 3.67 - 0.86 * np.log(float(i)) - 0.50 * maturity
        correction = 0.0

        if word is not None:
            pos = word.pos_
            dep = word.dep_

            if pos in ("VERB", "AUX"):
                correction += 0.45
                if dep in ("ROOT", "conj", "parataxis"):
                    correction += 0.65
                elif dep in ("xcomp", "ccomp", "acl", "relcl"):
                    correction -= 0.75
            elif pos in ("CCONJ", "SCONJ"):
                correction += 0.70
            elif pos in ("NOUN", "PROPN"):
                correction -= 0.65
            elif pos in ("ADJ", "ADV"):
                correction -= 0.20
            elif pos in ("DET", "PRON", "ADP", "PART"):
                correction -= 0.35

            if dep in ("dobj", "obj", "pobj", "attr", "oprd"):
                correction -= 0.65
            elif dep in ("nsubj", "nsubjpass", "csubj"):
                correction -= 0.15

            if word.is_punct:
                correction += 0.85
            if word.is_space:
                correction += 0.90

        clean = tokens[i].replace("Ġ", " ").replace("Ċ", "\n")
        if clean.isspace():
            correction += 0.75
        elif clean.strip() and all(
            not c.isalnum() and not c.isspace() for c in clean
        ):
            correction += 0.35

        sink_probability = 1.0 / (
            1.0 + np.exp(-(logit + maturity * correction))
        )

        # The observed structure chiefly identifies the sink; approximate the
        # unobserved residual by a broad causal distribution with mild recency.
        positions = np.arange(1, i + 1, dtype=np.float64)
        residual = 0.65 + np.exp(-(i - positions) / 7.0)
        residual /= residual.sum()

        attention[i, 0] = sink_probability
        attention[i, 1:i + 1] = (1.0 - sink_probability) * residual

    return "bos_sink_syntactic_decay", make_row_stochastic(attention)


def prog_L9H13(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with gradually weakening positional dominance.
    Linguistic features mildly modulate sink strength; residual attention is diffuse and local.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_position_decay", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.58 + 0.34 * np.exp(-i / 30.0)

        sids = aligned[i] if i < len(aligned) else []
        if sids:
            word = doc[sids[-1]]
            if word.pos_ in ("ADJ", "ADV"):
                sink_mass += 0.025
            elif word.pos_ in ("VERB", "AUX"):
                sink_mass += 0.010
            elif word.pos_ == "DET":
                sink_mass -= 0.035
            elif word.pos_ in ("NOUN", "PROPN"):
                sink_mass -= 0.015

        if i == 1:
            sink_mass = 0.935

        sink_mass = float(np.clip(sink_mass, 0.50, 0.96))
        attention[i, 0] = sink_mass

        # The examples constrain the sink, not individual residual edges.
        # Use a conservative mixture of diffuse causal and local attention.
        positions = np.arange(1, i + 1, dtype=np.float64)
        local = np.exp(-(i - positions) / 4.0)
        local /= local.sum()
        residual = 0.55 / i + 0.45 * local
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_position_decay", make_row_stochastic(attention)


def prog_L9H14(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with positional decay and punctuation-driven resets.
    Residual attention favors recent context and discourse-boundary anchors.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_discourse_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    pos = [""] * n
    dep = [""] * n
    whitespace = np.zeros(n, dtype=bool)
    punctuation = np.zeros(n, dtype=bool)
    boundary = np.zeros(n, dtype=bool)
    subject = np.zeros(n, dtype=bool)
    sentence_start = np.zeros(n, dtype=bool)

    for i, token in enumerate(tokens):
        clean = token.replace("Ġ", " ").replace("Ċ", "\n")
        whitespace[i] = bool(clean) and not clean.strip()
        stripped = clean.strip()
        punctuation[i] = bool(stripped) and all(
            not c.isalnum() for c in stripped
        )
        boundary[i] = any(c in ".!?\n" for c in clean)

        if alignment[i]:
            word = doc[alignment[i][0]]
            pos[i] = word.pos_
            dep[i] = word.dep_
            subject[i] = word.dep_ in ("nsubj", "nsubjpass", "csubj")
            sentence_start[i] = bool(word.is_sent_start)

    attention[0, 0] = 1.0

    for i in range(1, n):
        # Early queries overwhelmingly use the sink; its share gradually falls.
        sink = 0.28 + 0.696 * np.exp(-0.12 * (i - 1) ** 1.12)

        if i > 1:
            if pos[i] in ("DET", "ADP", "AUX"):
                sink += 0.035
            elif pos[i] in ("ADJ", "ADV"):
                sink -= 0.035
            if dep[i] == "poss":
                sink -= 0.055
            if subject[i] and i <= 5:
                sink += 0.045

            if punctuation[i]:
                sink += 0.24
                if boundary[i]:
                    sink += 0.08
            if whitespace[i]:
                sink += 0.43
            if sentence_start[i]:
                sink += 0.16

        sink = float(np.clip(sink, 0.16, 0.985))
        attention[i, 0] = sink

        # The remaining mass is broad, rather than a sharp previous-token head.
        indices = np.arange(1, i + 1)
        weights = 0.13 / (1.0 + (i - indices) / 8.0) ** 0.65
        weights[-1] += 0.10
        if i > 1:
            weights[-2] += 0.12

        # Closed quoted utterances provide particularly strong persistent anchors.
        last_boundary = -1
        for j in range(1, i):
            if boundary[j]:
                last_boundary = j

        if last_boundary >= 1:
            text = tokens[last_boundary]
            quoted = any(c in text for c in ('"', "”", "’"))
            strength = 3.6 if quoted else 1.3
            strength *= np.exp(-(i - last_boundary) / 75.0)
            weights[last_boundary - 1] += strength

            # A new clause's subject can become a secondary discourse anchor.
            for j in range(last_boundary + 1, i):
                if subject[j] and pos[j] in ("NOUN", "PROPN"):
                    weights[j - 1] += 2.5
                    break

        for j in range(1, i + 1):
            if punctuation[j] and not boundary[j]:
                weights[j - 1] += 0.06
            if subject[j]:
                weights[j - 1] += 0.08

        attention[i, 1:i + 1] = (1.0 - sink) * weights / weights.sum()

    return "bos_sink_with_discourse_anchors", attention


def prog_L9H15(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with position-dependent dilution.
    Linguistic features mildly modulate the sink and diffuse causal remainder.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_positional_dilution", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    pos = [
        doc[indices[0]].pos_ if indices else ""
        for indices in alignment
    ]

    # The observed dominant target is the initial token, not a syntactic head.
    attention[0, 0] = 1.0
    key_weights = np.ones(n, dtype=np.float64)
    for j in range(1, n):
        if pos[j] in ("NOUN", "PROPN", "VERB", "ADJ"):
            key_weights[j] = 1.15
        elif pos[j] == "PUNCT":
            key_weights[j] = 0.75

    for i in range(1, n):
        sink = 0.45 + 0.55 * np.exp(-0.017 * i ** 1.25)

        # Small corrections only: the examples chiefly support a BOS sink.
        correction = 0.0
        if pos[i] in ("NOUN", "PROPN", "ADJ"):
            correction -= 0.025
        elif pos[i] in ("CCONJ", "SCONJ", "ADP"):
            correction += 0.015

        visible = tokens[i].replace("Ġ", " ").replace("Ċ", "\n")
        if visible.isspace():
            correction += 0.075
        elif pos[i] == "PUNCT":
            correction += 0.045

        # Keep the earliest positions overwhelmingly concentrated on BOS.
        correction *= 1.0 - np.exp(-i / 4.0)
        sink = np.clip(sink + correction, 0.35, 0.998)

        indices = np.arange(1, i + 1)
        remainder = key_weights[1:i + 1] * (
            0.65 + 0.35 * np.exp(-(i - indices) / 16.0)
        )
        remainder[-1] *= 0.8
        attention[i, 0] = sink
        attention[i, 1:i + 1] = (
            (1.0 - sink) * remainder / remainder.sum()
        )

    return "bos_sink_with_positional_dilution", attention


def prog_L9H16(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with local syntax; completed dialogue adds a persistent boundary anchor.
    Only post-dialogue off-diagonal mass is redistributed; self-attention is unchanged.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_dialogue_anchor", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, word_ids in enumerate(alignment):
        for word_id in word_ids:
            inverse[word_id].append(i)

    # Question/exclamation endings inside a narrative mark persistent discourse
    # anchors. Include an immediately following closing quote when tokenized apart.
    dialogue_boundaries = []
    for j in range(1, n):
        if any(c in tokens[j] for c in "?!"):
            end = j
            if j + 1 < n:
                following = tokens[j + 1].strip("Ġ▁ \t\r\n")
                if following in ('"', "”", "»"):
                    end = j + 1
            if end < n - 1:
                dialogue_boundaries.append(end)

    attention[0, 0] = 1.0
    for i in range(1, n):
        word_ids = alignment[i]
        word = doc[word_ids[-1]] if word_ids else None

        # Early rows are almost entirely absorbed by the initial token.
        sink = 0.40 + 0.596 * np.exp(-(i - 1) / 12.0)

        if word is not None:
            if word.dep_ in ("dobj", "obj", "iobj", "attr", "oprd"):
                sink -= 0.13 * (1.0 - np.exp(-(i - 1) / 3.0))
            if word.pos_ == "PROPN" and word.dep_ not in (
                "nsubj", "nsubjpass", "ROOT"
            ):
                sink -= 0.08
            if word.pos_ in ("VERB", "AUX") and i > 3:
                sink -= 0.045
            if word.dep_ in ("poss", "det") and i > 6:
                sink -= 0.04

            if word.is_sent_start and i > 1:
                sink += 0.24
            if word.is_punct:
                sink += 0.025
        elif tokens[i].strip("Ġ▁ \t\r\n") == "":
            sink += 0.10

        sink = float(np.clip(sink, 0.25, 0.998))
        if i == 1:
            sink = 0.996

        positions = np.arange(1, i + 1)
        residual = np.exp(-(i - positions) / 3.0)
        residual /= residual.sum()
        residual *= 0.55

        # Causal dependency heads provide a secondary, sharper local target.
        head_targets = []
        if word is not None and word.head.i != word.i:
            head_targets = [
                j for j in inverse[word.head.i] if 0 < j <= i
            ]

        if head_targets:
            residual[head_targets[-1] - 1] += 0.45
        else:
            residual[-1 if i == 1 else -2] += 0.30
            residual[-1] += 0.15

        residual /= residual.sum()
        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual

        previous_boundaries = [j for j in dialogue_boundaries if j < i]
        if previous_boundaries:
            boundary = previous_boundaries[-1]
            targets = np.zeros(i, dtype=np.float64)

            # Spread secondary mass over content landmarks rather than trusting
            # a single dependency head across dialogue/sentence boundaries.
            for w in doc:
                if w.pos_ not in ("VERB", "AUX", "NOUN", "PROPN", "ADJ"):
                    continue
                causal = [j for j in inverse[w.i] if 0 < j < i]
                if causal:
                    j = causal[-1]
                    targets[j] += np.exp(-(i - j) / 24.0)

            if targets.sum() > 0:
                targets *= 0.5 / targets.sum()
                targets[boundary] += 0.5
            else:
                targets[boundary] = 1.0

            # Preserve both the diagonal and the original BOS weight, except
            # for the sentence-start refresh that should favor this boundary.
            movable = 0.70 * attention[i, 1:i].sum()
            attention[i, 1:i] *= 0.30
            if word is not None and word.is_sent_start:
                refresh = min(0.20, max(0.0, attention[i, 0] - 0.25))
                attention[i, 0] -= refresh
                movable += refresh
            attention[i, :i] += movable * targets

    return "bos_sink_with_dialogue_anchor", attention


def prog_L9H17(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with position-dependent decay and weak linguistic modulation.
    Residual attention is diffuse and mildly biased toward recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "decaying_bos_sink", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        # The first ordinary token almost exclusively attends to BOS.
        if i == 1:
            sink_mass = 0.989
        else:
            logit = 3.30 - 0.95 * np.log(float(i))
            sids = alignment[i]
            if sids:
                word = doc[sids[0]]
                pos = word.pos_
                dep = word.dep_

                if pos == "DET":
                    logit += 0.28
                elif pos == "AUX":
                    logit += 0.10
                elif pos == "VERB":
                    logit -= 0.27
                elif pos == "ADJ":
                    logit -= 0.16
                elif pos == "PRON":
                    logit -= 0.13
                elif pos == "CCONJ":
                    logit += 0.12

                # Introductory adjuncts tend to preserve the strong initial sink.
                if i <= 6 and dep in ("advmod", "npadvmod", "pobj", "prep"):
                    logit += 0.38

                if pos == "PUNCT":
                    logit += 0.12

            elif tokens[i].replace("Ġ", "").replace("Ċ", "").strip() == "":
                logit += 0.25

            sink_mass = float(np.clip(
                1.0 / (1.0 + np.exp(-logit)), 0.15, 0.985
            ))

        attention[i, 0] = sink_mass

        # No specific non-BOS target is supported by the supplied edges.
        # Use a broad causal background with a modest recency preference.
        positions = np.arange(1, i + 1, dtype=np.float64)
        residual = (
            0.65 / float(i)
            + 0.35 * np.exp(-(i - positions) / 6.0)
            / np.exp(-(i - positions) / 6.0).sum()
        )
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "decaying_bos_sink", make_row_stochastic(attention)


def prog_L9H18(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with local syntax; closed dialogue creates persistent boundary
    and referent anchors that receive some of the later BOS mass."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_dialogue_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for ti, sids in enumerate(alignment):
        for sid in sids:
            inverse[sid].append(ti)

    attention[0, 0] = 1.0

    for i in range(1, n):
        sids = alignment[i]
        word = doc[sids[-1]] if sids else None

        baseline = 0.64
        if word is not None:
            if word.pos_ in ("DET", "ADP", "PRON"):
                baseline += 0.045
            elif word.pos_ in ("NOUN", "PROPN", "ADJ"):
                baseline += 0.025
            elif word.pos_ in ("VERB", "AUX"):
                baseline -= 0.035
            elif word.pos_ in ("CCONJ", "SCONJ", "PART"):
                baseline -= 0.075
            elif word.is_punct:
                baseline -= 0.17

        early = np.exp(-(i - 1) / 2.8)
        sink_mass = baseline + (0.98 - baseline) * early

        if word is not None and i <= 5:
            if word.dep_ in ("advmod", "npadvmod", "pobj", "prep"):
                sink_mass += 0.055 * np.exp(-(i - 1) / 5.0)
            if word.pos_ in ("VERB", "AUX") and i <= 3:
                sink_mass += 0.035

        sink_mass = float(np.clip(sink_mass, 0.30, 0.987))

        positions = np.arange(1, i + 1)
        residual = np.exp(-(i - positions) / 2.5)
        residual[-1] += 0.20
        if i > 1:
            residual[-2] += 0.65

        if word is not None:
            for j in inverse[word.head.i]:
                if 1 <= j < i:
                    residual[j - 1] += 1.0

            for sid in sids:
                for j in inverse[sid]:
                    if 1 <= j < i:
                        residual[j - 1] += 0.65

            if word.pos_ in ("ADP", "PART") and i > 1:
                residual[-2] += 1.25

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * residual / residual.sum()
        )

    # Special case only: completed direct speech supplies longer-lived anchors.
    # Transfer BOS mass alone, preserving every original local/self weight.
    quote_start = None
    closures = []
    for i in range(1, n):
        text = tokens[i].replace("\u0120", " ").strip()
        has_quote = any(q in text for q in ('"', "\u201c", "\u201d"))
        closing = False

        if has_quote:
            previous = tokens[i - 1].replace("\u0120", " ").strip()
            terminal = any(p in text for p in ".?!")
            terminal = terminal or (
                bool(previous) and previous[-1] in ".?!"
            )
            if quote_start is not None and terminal:
                referent = None
                for j in range(quote_start + 1, i):
                    if alignment[j]:
                        w = doc[alignment[j][-1]]
                        if w.pos_ in ("NOUN", "PROPN", "PRON"):
                            referent = j
                closures.append((i, referent))
                quote_start = None
                closing = True
            elif quote_start is None:
                quote_start = i

        if not closures:
            continue

        sids = alignment[i]
        word = doc[sids[-1]] if sids else None
        age = i - closures[-1][0]
        decay = np.exp(-age / 10.0)

        if closing:
            transfer = 0.18
        elif not text:
            transfer = 0.30
        elif word is not None and word.is_punct:
            transfer = min(0.36, 0.26 + 0.05 * (len(closures) - 1))
        elif word is not None and word.pos_ == "VERB" and any(
            c.dep_ in ("ccomp", "parataxis") for c in word.children
        ):
            transfer = 0.24 * decay
        elif word is not None and word.pos_ in ("DET", "NOUN", "PROPN"):
            transfer = 0.16 * decay
        else:
            transfer = 0.10 * decay

        anchors = np.zeros(i, dtype=np.float64)
        punctuation_row = closing or (
            word is not None and word.is_punct
        ) or not text
        for rank, (boundary, referent) in enumerate(reversed(closures)):
            strength = 0.65 ** rank
            if 1 <= boundary < i:
                anchors[boundary] += strength * (
                    0.65 if punctuation_row else 0.35
                )
            if referent is not None and 1 <= referent < i:
                anchors[referent] += strength * (
                    0.35 if punctuation_row else 0.65
                )

        total = anchors.sum()
        if total > 0:
            transfer = min(transfer, max(0.0, attention[i, 0] - 0.03))
            attention[i, 0] -= transfer
            attention[i, :i] += transfer * anchors / total

    return "bos_sink_with_dialogue_anchors", attention


def prog_L9H19(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with slight positional weakening.
    Small residual attention is distributed over causal tokens with recency bias.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_weak_recency", attention

    attention[0, 0] = 1.0

    for i in range(1, n):
        residual_mass = np.clip(0.014 + 0.001 * (i - 1), 0.014, 0.16)
        positions = np.arange(1, i + 1)
        residual_weights = 0.35 + np.exp(-(i - positions) / 8.0)
        residual_weights /= residual_weights.sum()

        attention[i, 0] = 1.0 - residual_mass
        attention[i, 1:i + 1] = residual_mass * residual_weights

    return "bos_sink_with_weak_recency", attention


def prog_L9H20(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with a boundary-triggered readout of preceding content.
    Boundary readout transfers only BOS mass, preserving self-attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_boundary_readout", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        onset_decay = np.exp(-(i - 1) / 3.0)
        sink_mass = 0.90 + 0.09 * onset_decay
        correction = 0.0

        if alignment[i]:
            word = doc[alignment[i][0]]
            if word.is_punct:
                correction = -0.08
            elif word.pos_ in ("NOUN", "PROPN"):
                correction = 0.015
            elif word.pos_ in ("AUX", "CCONJ", "SCONJ", "ADP"):
                correction = -0.025
            elif word.pos_ in ("ADJ", "ADV"):
                correction = -0.015

        sink_mass += (1.0 - onset_decay) * correction
        sink_mass = np.clip(sink_mass, 0.75, 0.995)

        positions = np.arange(1, i + 1, dtype=np.float64)
        recency = np.exp(-(i - positions) / 6.0)
        recency /= recency.sum()
        remainder = 0.65 * recency + 0.35 / i

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * remainder

        # Read out preceding content at clause/list/sentence boundaries only.
        if i >= 4 and alignment[i]:
            word = doc[alignment[i][0]]
            punctuation_boundary = word.is_punct and any(
                mark in tokens[i] for mark in (".", ",", ";", ":", "!", "?")
            )
            clause_boundary = word.pos_ in ("CCONJ", "SCONJ")
            if punctuation_boundary or clause_boundary:
                terminal = punctuation_boundary and any(
                    mark in tokens[i] for mark in (".", "!", "?")
                )
                target_sink = (
                    0.08 + 0.27 * np.exp(-max(i - 8, 0) / 28.0)
                    if terminal else 0.48 if punctuation_boundary else 0.70
                )
                weights = np.zeros(i - 1, dtype=np.float64)
                for j in range(1, i):
                    if not alignment[j]:
                        continue
                    previous = doc[alignment[j][-1]]
                    if previous.is_space:
                        continue
                    salience = (
                        2.5 if previous.pos_ in ("NOUN", "PROPN")
                        else 1.5 if previous.pos_ in ("ADJ", "VERB")
                        else 0.8 if previous.pos_ == "ADP"
                        else 0.2
                    )
                    distance_weight = np.exp(
                        -(i - 1 - j) / (10.0 if terminal else 3.0)
                    )
                    weights[j - 1] = salience * (
                        distance_weight + (0.25 if terminal else 0.0)
                    )

                if weights.sum() > 0:
                    transfer = max(0.0, attention[i, 0] - target_sink)
                    attention[i, 0] -= transfer
                    attention[i, 1:i] += transfer * weights / weights.sum()

    return "bos_sink_boundary_readout", make_row_stochastic(attention)


def prog_L9H21(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with gradually declining strength and weak local attention.
    Linguistic features make small corrections to the dominant positional prior.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_position_decay", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        pos = ""
        if alignment[i]:
            pos = doc[alignment[i][0]].pos_

        sink = 0.30 + 0.62 * np.exp(-i / 38.0)

        if i == 1:
            sink = 0.84
            if pos == "DET":
                sink -= 0.074
            elif pos == "PRON":
                sink += 0.015
            elif pos == "PROPN":
                sink += 0.045
            elif pos == "ADP":
                sink += 0.05
            elif pos == "ADV":
                sink += 0.015
        elif i == 2:
            sink += 0.025
        elif pos in ("ADJ", "NOUN", "PROPN"):
            sink += 0.015
        elif pos == "PUNCT":
            sink -= 0.025

        sink = np.clip(sink, 0.25, 0.95)

        positions = np.arange(1, i + 1, dtype=np.float64)
        distance = i - positions
        residual = 0.35 / i + 0.65 * np.exp(-distance / 5.0)
        residual /= residual.sum()

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual

    return "bos_sink_with_position_decay", attention


def prog_L9H22(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with gradually declining strength and small linguistic corrections.
    Residual attention is diffuse and mildly biased toward recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_position_decay", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        # A nearly fixed sink score competes with a growing causal context.
        sink_strength = 28.0
        linguistic_factor = 1.0
        mapped = alignment[i]

        if mapped:
            word = doc[mapped[0]]
            pos = word.pos_

            if pos in ("NOUN", "PROPN"):
                linguistic_factor *= 0.82
            elif pos in ("DET", "ADP", "AUX"):
                linguistic_factor *= 1.12
            elif pos in ("CCONJ", "SCONJ"):
                linguistic_factor *= 1.25
            elif pos == "PRON":
                linguistic_factor *= 0.92

            if word.dep_ in ("nsubj", "nsubjpass", "dobj", "obj", "pobj"):
                linguistic_factor *= 0.94

            if word.is_punct:
                linguistic_factor *= 1.18
            if word.is_space:
                linguistic_factor *= 1.45
            if word.is_sent_start and i > 1:
                linguistic_factor *= 1.35

        if tokens[i].isspace() or tokens[i] == "\u0120":
            linguistic_factor *= 1.25

        sink_odds = sink_strength * linguistic_factor / i
        sink_mass = sink_odds / (1.0 + sink_odds)

        # Early queries consistently devote almost all attention to BOS.
        if i == 1:
            sink_mass = 0.965

        positions = np.arange(1, i + 1, dtype=np.float64)
        distances = i - positions
        residual = 0.65 + 0.35 * np.exp(-distances / 8.0)
        residual /= residual.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_position_decay", make_row_stochastic(attention)


def prog_L9H23(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with gradual positional dilution.
    Residual attention favors recent content tokens and causal syntactic links.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_syntactic_residual", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    word_to_tokens = [[] for _ in doc]
    for i, word_ids in enumerate(alignment):
        for wid in word_ids:
            word_to_tokens[wid].append(i)

    attention[0, 0] = 1.0
    content_pos = ("NOUN", "PROPN", "VERB", "ADJ")
    object_deps = ("dobj", "obj", "pobj", "attr", "oprd")

    for i in range(1, n):
        # A nearly pure sink initially, with more competition in longer contexts.
        sink_mass = 0.58 + 0.40 * np.exp(-0.014 * (i - 1))
        word_ids = alignment[i]
        linked_words = set()

        for wid in word_ids:
            word = doc[wid]
            if word.is_punct:
                sink_mass -= 0.06
            elif word.pos_ == "PRON" and i > 5:
                sink_mass -= 0.05

            if word.head.i != wid:
                linked_words.add(word.head.i)
            for child in word.children:
                linked_words.add(child.i)

        sink_mass = float(np.clip(sink_mass, 0.45, 0.985))
        residual = np.zeros(i + 1, dtype=np.float64)

        for j in range(1, i + 1):
            distance = i - j
            score = 0.10 + 0.35 * np.exp(-distance / 6.0)

            for wid in alignment[j]:
                word = doc[wid]
                if word.pos_ in content_pos:
                    score += 0.25 * np.exp(-distance / 28.0)
                if word.dep_ in object_deps:
                    score += 0.20 * np.exp(-distance / 35.0)
                if wid in linked_words:
                    score += 0.60 / max(1, len(word_to_tokens[wid]))
                if word.is_punct:
                    score *= 0.45

            residual[j] = score

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * residual[1:] / residual[1:].sum()
        )

    return "bos_sink_with_syntactic_residual", make_row_stochastic(attention)


def prog_L10H0(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with quotation-local anchors and BOS recovery after quoted speech.
    Outside quotation-bearing passages, retain the original prediction unchanged.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    matrix = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_quote_recovery", matrix

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, indices in enumerate(alignment):
        for k in indices:
            inverse[k].append(i)

    words = []
    cleaned = []
    for i, token in enumerate(tokens):
        cleaned.append(token.lstrip("Ġ▁"))
        indices = alignment[i]
        words.append(doc[indices[-1]] if indices else None)

    # Treat byte-split, mojibake quotation punctuation as a single event,
    # located at the last model token overlapping the punctuation.
    damaged_quote_events = set()
    if "â€" in sentence:
        spans = _char_spans(sentence, tokenizer)
        cursor = 0
        while True:
            start = sentence.find("â€", cursor)
            if start < 0:
                break
            end = start + 2
            if end < len(sentence) and sentence[end] in ("œ", "“", "”", "\x9d"):
                end += 1
            overlapping = [
                j for j, (s, e) in enumerate(spans)
                if s < end and e > start
            ]
            if overlapping:
                damaged_quote_events.add(overlapping[-1])
            cursor = end

    matrix[0, 0] = 1.0
    quote_anchor = None
    quote_marks = ('"', "“", "”", "«", "»")
    special_tokens = set(tokenizer.all_special_tokens)
    quote_seen = False
    speech_anchor = None

    for i in range(1, n):
        text = cleaned[i]
        word = words[i]
        pos = word.pos_ if word is not None else ""
        dep = word.dep_ if word is not None else ""
        is_punct = word is not None and word.is_punct
        has_quote = any(mark in text for mark in quote_marks)
        if i in damaged_quote_events:
            has_quote = True

        opening_quote = False
        closing_quote = False
        if has_quote:
            if quote_anchor is None:
                opening_quote = True
            else:
                closing_quote = True

        sink = 0.30 + 0.68 * np.exp(-(i - 1) / 6.0)
        if pos in ("VERB", "AUX"):
            sink += 0.12
        if dep in ("nsubj", "nsubjpass", "nsubj:pass", "cc"):
            sink += 0.12
        if pos == "ADP" and dep != "mark":
            sink += 0.10
        if dep in ("dobj", "obj", "attr", "acomp", "xcomp"):
            sink -= 0.10

        if quote_anchor is not None and not closing_quote:
            sink -= 0.12
        if is_punct and not opening_quote:
            sink += 0.30
        if not text.strip() or tokens[i] in special_tokens:
            sink += 0.27
        if opening_quote:
            sink = 0.46 + 0.12 * np.exp(-i / 12.0)
        if i == 1:
            sink = 0.982

        sink = float(np.clip(sink, 0.12, 0.99))
        weights = np.zeros(i + 1, dtype=np.float64)
        for j in range(1, i + 1):
            weights[j] = 0.045 * np.exp(-(i - j) / 9.0)
        weights[i] += 0.035
        if i > 1:
            weights[i - 1] += 0.12

        if word is not None:
            # A causal syntactic head supplies a local alternative to BOS.
            head = word.head
            if head.i != word.i:
                candidates = [j for j in inverse[head.i] if 0 < j < i]
                if candidates:
                    j = candidates[0]
                    strength = 0.35
                    if head.pos_ in ("VERB", "AUX", "ADP"):
                        strength = 0.70
                    weights[j] += strength

            # Clausal complements can continue attending to their selecting verb.
            node = word
            visited = set()
            for _ in range(8):
                if node.i in visited:
                    break
                visited.add(node.i)
                parent = node.head
                if parent.i == node.i:
                    break
                if node.dep_ in ("ccomp", "xcomp") and parent.pos_ == "VERB":
                    candidates = [j for j in inverse[parent.i] if 0 < j < i]
                    if candidates:
                        j = candidates[0]
                        weights[j] += 1.8 * np.exp(-(i - j) / 22.0)
                    break
                if node.dep_ in ("conj", "advcl", "relcl"):
                    break
                node = parent

        if quote_anchor is not None and quote_anchor < i:
            weights[quote_anchor] += 2.5 * np.exp(
                -(i - quote_anchor - 1) / 9.0
            )

        total = weights.sum()
        if total > 0:
            matrix[i, :i + 1] = (1.0 - sink) * weights / total
            matrix[i, 0] = sink
        else:
            matrix[i, 0] = 1.0

        # Targeted quotation handler: redistribute only off-diagonal mass.
        # The original self-attention, raw weights, and decay rates are intact.
        if quote_anchor is not None:
            if speech_anchor is not None and speech_anchor < i:
                # A clause-opening pronoun/clitic succeeds the opening quote
                # as the persistent anchor; do not amplify selecting verbs.
                for j in range(1, i):
                    if j != speech_anchor:
                        fraction = 0.65 if j == quote_anchor else 0.25
                        moved = fraction * matrix[i, j]
                        matrix[i, j] -= moved
                        matrix[i, speech_anchor] += moved

            # Register anchors only after predicting their own row.
            if word is not None and not closing_quote:
                first_piece = not inverse[word.i] or i == inverse[word.i][0]
                clitic = text.startswith(("'", "’")) and pos in ("PRON", "PART")
                if first_piece and (
                    (speech_anchor is None and pos == "PRON") or clitic
                ):
                    speech_anchor = i

        elif quote_seen and not opening_quote:
            # Narrative BOS attention recovers after a quotation instead of
            # continuing to decay with absolute position in the entire text.
            target = 0.64
            if pos in ("VERB", "AUX", "ADP"):
                target = 0.73
            if is_punct or not text.strip() or tokens[i] in special_tokens:
                target = 0.80
            available = matrix[i, 1:i].sum()
            increase = min(max(target - matrix[i, 0], 0.0), available)
            if available > 0:
                matrix[i, 1:i] *= (available - increase) / available
                matrix[i, 0] += increase

        if opening_quote:
            quote_anchor = i
            quote_seen = True
            speech_anchor = None
        elif closing_quote:
            quote_anchor = None
            speech_anchor = None

    return "bos_sink_with_quote_recovery", make_row_stochastic(matrix)


def prog_L10H1(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention-sink head, with position-dependent leakage.
    Punctuation reinforces the sink; residual attention is local and weakly syntactic.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_leakage", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, indices in enumerate(aligned):
        for k in indices:
            inverse[k].append(i)

    attention[0, 0] = 1.0
    for i in range(1, n):
        clean = tokens[i].replace("Ġ", " ").replace("Ċ", "\n").strip()
        words = [doc[k] for k in aligned[i]]
        word = max(
            words,
            key=lambda w: sum(c.isalnum() for c in w.text),
            default=None,
        )

        # Sink strength decreases as more competing keys become available.
        logit = 2.15 - 0.045 * i
        if word is not None:
            if word.pos_ in ("NOUN", "PROPN", "ADJ", "VERB"):
                logit -= 0.18
            elif word.pos_ in ("DET", "AUX", "PRON"):
                logit += 0.20
            if word.dep_ in ("ROOT", "nsubj", "nsubjpass"):
                logit += 0.12

        sink = float(1.0 / (1.0 + np.exp(-logit)))

        is_punctuation = (
            bool(clean) and all(not c.isalnum() for c in clean)
        ) or (bool(words) and all(w.is_punct for w in words))
        is_space = not clean or (bool(words) and all(w.is_space for w in words))

        if is_punctuation:
            sink = max(sink, 0.95 - 0.0055 * i)
        if is_space:
            sink = max(sink, 0.98 - 0.020 * max(0, i - 14))
        if i == 1:
            sink = 0.989

        sink = float(np.clip(sink, 0.15, 0.99))

        # Spread unused mass over causal non-sink keys, favoring nearby tokens.
        positions = np.arange(1, i + 1)
        residual = 0.12 + np.exp(-(i - positions) / 4.0)
        if i > 1:
            residual[-2] += 0.65

        if word is not None:
            # Dependency edges are only used when their targets are available.
            for j in inverse[word.head.i]:
                if 0 < j <= i and word.head.i != word.i:
                    residual[j - 1] += 0.65

            # Preserve continuity across pieces of the same spaCy token.
            for j in inverse[word.i]:
                if 0 < j < i:
                    residual[j - 1] += 0.45

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual / residual.sum()

    return "bos_sink_with_local_leakage", attention


def prog_L10H2(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with slowly decaying strength and punctuation boosts.
    Residual attention is diffuse, with a weak recency preference.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_position_decay", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        aligned = alignment[i]
        pos = doc[aligned[-1]].pos_ if aligned else ""
        dep = doc[aligned[-1]].dep_ if aligned else ""
        surface = tokens[i].strip("ĠĊ▁ \t\r\n")

        sink_mass = 0.967 / (1.0 + 0.19 * (i - 1)) ** 0.42

        if pos == "PUNCT":
            boost = 0.14 if any(c in surface for c in ".!?") else 0.065
            sink_mass += boost * i / (i + 6.0)
        elif pos in ("PRON", "DET"):
            sink_mass += 0.018
        elif pos in ("VERB", "AUX"):
            sink_mass -= 0.015

        if dep in ("cc", "mark"):
            sink_mass += 0.025

        if not surface:
            sink_mass += 0.10

        sink_mass = float(np.clip(sink_mass, 0.20, 0.985))

        positions = np.arange(1, i + 1, dtype=np.float64)
        recency = np.exp(-(i - positions) / 7.0)
        recency /= recency.sum()
        residual = 0.80 / i + 0.20 * recency

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_position_decay", attention


def prog_L10H3(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Dominant beginning-of-sequence attention sink with mild positional decay.
    Residual attention is diffuse, favoring recent tokens and nominal anchors.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_diffuse_context", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    salience = np.ones(n, dtype=np.float64)

    for j, indices in enumerate(alignment):
        if any(doc[k].pos_ in ("NOUN", "PROPN") for k in indices):
            salience[j] = 1.5
        elif indices and all(doc[k].pos_ == "PUNCT" for k in indices):
            salience[j] = 0.7

    attention[0, 0] = 1.0
    for i in range(1, n):
        sink_mass = float(np.clip(
            0.975 - 0.0027 * max(0, i - 10), 0.75, 0.975
        ))
        positions = np.arange(1, i + 1)
        residual = salience[1:i + 1] * (
            0.35 + np.exp(-(i - positions) / 10.0)
        )
        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * residual / residual.sum()
        )

    return "bos_sink_with_diffuse_context", attention


def prog_L10H4(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with a dialogue-specific residual retrieval path.
    Quoted exchanges redirect some BOS mass to related earlier discourse tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    for i in range(n):
        if i == 0:
            attention[0, 0] = 1.0
            continue

        sink_mass = 0.96 - 0.14 * (
            1.0 - np.exp(-max(i - 12, 0) / 35.0)
        )
        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) / i

    # Only activate for multi-turn quoted dialogue; ordinary prose is unchanged.
    quote_chars = ('"', '\u201c', '\u201d')
    quote_positions = [
        i for i, token in enumerate(tokens)
        if any(q in token for q in quote_chars)
    ]
    if len(quote_positions) >= 4:
        doc = spacy_parse(sentence)
        alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
        words = [doc[ids[-1]] if ids else None for ids in alignment]
        content_pos = ("NOUN", "PROPN", "VERB", "ADJ")
        first_quote = quote_positions[0]
        first_close = quote_positions[1]

        for i in range(first_quote + 1, n):
            word = words[i]
            if word is None:
                continue

            weights = np.zeros(i, dtype=np.float64)
            strongest_match = 0.0

            for j in range(1, i):
                earlier = words[j]
                if earlier is None or earlier.i == word.i:
                    continue
                if earlier.pos_ not in content_pos + ("PRON",):
                    continue

                similarity = embedding_similarity(tokens, i, j, tokenizer)
                related = max(0.0, similarity - 0.45)
                weights[j] = related ** 3
                strongest_match = max(strongest_match, related)

                # Pronouns can retrieve preceding participants or objects.
                if word.pos_ == "PRON":
                    if earlier.pos_ in ("NOUN", "PROPN"):
                        role_match = (
                            word.dep_ == earlier.dep_
                            or (
                                word.dep_ in ("nsubj", "nsubjpass")
                                and earlier.pos_ == "PROPN"
                            )
                        )
                        if role_match:
                            weights[j] += 0.025 * np.exp(-(i - j) / 24.0)

                # Boundary tokens summarize recent content rather than BOS alone.
                if word.is_punct and i > first_close:
                    weights[j] += 0.012 * np.exp(-(i - j) / 6.0)

            total = weights.sum()
            if total <= 0.0:
                continue

            transfer = min(0.36, 0.65 * strongest_match)
            if word.pos_ == "PRON":
                transfer = max(transfer, 0.14)
            if word.is_punct and i > first_close:
                transfer = max(transfer, 0.12)

            # Later dialogue has stronger retrieval, without changing the
            # original decay or any diagonal (self-attention) entry.
            if i > first_close:
                transfer += 0.04
            transfer = min(transfer, attention[i, 0])
            attention[i, 0] -= transfer
            attention[i, :i] += transfer * weights / total

    return "bos_sink_with_dialogue_retrieval", attention


def prog_L10H5(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with mildly position-dependent strength.
    Residual attention is diffuse and weakly biased toward recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_weak_recency", attention

    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.94 - 0.16 * (1.0 - np.exp(-i / 45.0))
        distances = i - np.arange(1, i + 1)
        residual = 0.5 + 0.5 * np.exp(-distances / 8.0)

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * residual / residual.sum()
        )

    return "bos_sink_with_weak_recency", attention


def prog_L10H6(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with gradually increasing competition from earlier content.
    Residual attention favors recent nominal anchors and syntactically related tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_nominal_competition", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    words = [doc[ids[-1]] if ids else None for ids in alignment]

    attention[0, 0] = 1.0
    nominal = ("NOUN", "PROPN")
    content = ("NOUN", "PROPN", "VERB", "ADJ", "ADV")
    special_tokens = tokenizer.all_special_tokens

    for i in range(1, n):
        word = words[i]
        pos = word.pos_ if word is not None else ""
        progress = 1.0 - np.exp(-i / 12.0)

        # A strong sink at short prefixes, fading without disappearing.
        sink = 0.985 / (1.0 + 0.022 * i) ** 0.82
        if pos in nominal:
            sink -= 0.095 * progress
        elif pos == "PRON":
            sink -= 0.070 * progress
        elif pos == "VERB":
            sink -= 0.060 * progress

        is_boundary = (
            word is not None and (word.is_punct or word.is_space)
        ) or not tokens[i].lstrip("ĠĊ▁").strip()
        if is_boundary:
            sink += 0.055 * progress
        if pos in ("CCONJ", "SCONJ", "ADP", "AUX"):
            sink += 0.025 * progress
        if tokens[i] in special_tokens:
            sink = 0.98

        sink = float(np.clip(sink, 0.28, 0.985))
        weights = np.zeros(i + 1, dtype=np.float64)

        for j in range(1, i + 1):
            previous = words[j]
            previous_pos = previous.pos_ if previous is not None else ""
            distance = i - j

            weight = 0.12 * np.exp(-distance / 14.0)
            if previous_pos in nominal:
                weight += 0.95 * np.exp(-distance / 28.0)
            elif previous_pos in content:
                weight += 0.22 * np.exp(-distance / 18.0)

            if word is not None and previous is not None and j < i:
                # Avoid treating pieces of the current word as separate anchors.
                if previous.i == word.i:
                    weight *= 0.30
                else:
                    if pos in nominal and previous_pos in nominal:
                        weight *= 2.8
                    elif pos == previous_pos and pos in content:
                        weight *= 1.65
                    if pos == "PRON" and previous_pos in nominal:
                        weight *= 1.8
                    if word.head.i == previous.i:
                        weight *= 1.9
                    if previous.head.i == word.i:
                        weight *= 1.25
                    if (
                        word.ent_type_
                        and word.ent_type_ == previous.ent_type_
                    ):
                        weight *= 1.5

            if j == i:
                weight *= 0.45
            weights[j] = weight

        total = weights.sum()
        attention[i, 0] = sink
        if total > 0.0:
            attention[i, 1:i + 1] = (
                (1.0 - sink) * weights[1:i + 1] / total
            )
        else:
            attention[i, i] = 1.0 - sink

    return "bos_sink_with_nominal_competition", attention


def prog_L10H7(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with position decay, plus a local content-anchor exception.
    Function words and punctuation can retain attention on the preceding content word.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_content_anchor", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.49 + 0.435 * np.exp(-(i - 1) / 7.0)
        mapped = alignment[i]

        if mapped:
            word = doc[mapped[0]]
            if word.pos_ in ("DET", "ADP", "AUX"):
                sink_mass += 0.035
            elif word.pos_ in ("ADJ", "PROPN"):
                sink_mass += 0.015
            elif word.pos_ in ("CCONJ", "SCONJ"):
                sink_mass -= 0.035
            elif word.pos_ == "PUNCT":
                if word.text in (".", "!", "?", "..."):
                    sink_mass -= 0.14
                elif word.text in ('"', "'", "“", "”", "‘", "’"):
                    sink_mass += 0.035
                else:
                    sink_mass -= 0.035

            # Continuation pieces have a weaker sink preference.
            if i > 1 and mapped[0] in alignment[i - 1]:
                sink_mass -= 0.07

        # The first non-BOS query consistently gives almost all mass to BOS.
        if i == 1:
            sink_mass = 0.925

        sink_mass = float(np.clip(sink_mass, 0.20, 0.95))
        attention[i, 0] = sink_mass

        positions = np.arange(1, i + 1)
        distances = i - positions
        residual = 0.65 + 0.35 * np.exp(-distances / 6.0)
        residual /= residual.sum()
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

        # Special case: an immediately preceding content anchor.
        # Transfer only off-diagonal mass; self-attention stays exactly unchanged.
        if i > 1 and mapped and alignment[i - 1]:
            previous = doc[alignment[i - 1][-1]]
            continuation = mapped[0] in alignment[i - 1]
            if (
                previous.pos_ in ("NOUN", "PROPN", "ADJ", "PRON")
                and (
                    word.pos_ in (
                        "ADP", "AUX", "CCONJ", "SCONJ",
                        "PART", "PUNCT", "VERB", "PRON"
                    )
                    or continuation
                )
            ):
                bos_transfer = min(0.10, 0.20 * attention[i, 0])
                diffuse_mass = attention[i, 1:i - 1].sum()
                diffuse_transfer = min(0.08, 0.45 * diffuse_mass)
                if diffuse_mass > 0.0:
                    attention[i, 1:i - 1] *= (
                        1.0 - diffuse_transfer / diffuse_mass
                    )
                attention[i, 0] -= bos_transfer
                attention[i, i - 1] += bos_transfer + diffuse_transfer

    return "bos_sink_with_local_content_anchor", attention


def prog_L10H8(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with position-dependent dilution and mild POS modulation.
    Remaining attention is diffuse and weakly biased toward recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_position_dilution", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        # The sink dominates early rows, then gradually loses probability
        # as the available causal context grows.
        dilution = 0.027 * float(i) ** 1.12
        modifier = 1.0

        aligned = alignment[i]
        if aligned:
            word = doc[aligned[0]]
            if word.is_punct:
                modifier = 0.76
            elif word.is_space:
                modifier = 0.85
            elif word.pos_ in ("CCONJ", "SCONJ"):
                modifier = 0.82
            elif word.pos_ in ("NOUN", "PROPN"):
                modifier = 1.18
            elif word.pos_ in ("ADJ", "ADV", "VERB"):
                modifier = 1.15
            elif word.pos_ in ("DET", "AUX", "ADP"):
                modifier = 0.95
        elif not tokens[i].lstrip("Ġ").strip():
            modifier = 0.85

        sink_probability = 1.0 / (1.0 + dilution * modifier)
        attention[i, 0] = sink_probability

        # No non-BOS destination is supported by the observed edges:
        # use a conservative diffuse residual rather than a syntactic rule.
        positions = np.arange(1, i + 1, dtype=np.float64)
        recent = np.exp(-(i - positions) / 6.0)
        recent /= recent.sum()
        residual = 0.8 / i + 0.2 * recent
        attention[i, 1:i + 1] = (1.0 - sink_probability) * residual

    return "bos_sink_with_position_dilution", attention


def prog_L10H9(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Predict a dominant beginning-of-sequence attention sink with positional dilution.
    Punctuation strengthens the sink; residual attention is diffuse and mildly local.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_positional_dilution", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        text = tokens[i].replace("Ġ", " ").replace("Ċ", "\n").strip()
        words = [doc[k] for k in alignment[i]]
        sink_strength = 45.0

        is_punctuation = (
            bool(words) and all(w.is_punct for w in words)
        ) or (
            bool(text) and all(c in ".,;:!?\"'()[]{}—–-…" for c in text)
        )

        if not text:
            sink_strength *= 1.65
        elif is_punctuation:
            sink_strength *= 1.65
            if text and all(c in ".!?" for c in text):
                sink_strength *= 2.5
        elif words:
            pos = words[-1].pos_
            if pos == "PROPN":
                sink_strength *= 0.85
            elif pos == "NOUN":
                sink_strength *= 0.93
            elif pos in ("CCONJ", "SCONJ"):
                sink_strength *= 1.15

        sink_mass = sink_strength / (sink_strength + i)

        # Unobserved non-sink edges receive a conservative diffuse prior.
        positions = np.arange(1, i + 1, dtype=np.float64)
        residual = 0.8 + 0.2 * np.exp(-(i - positions) / 8.0)
        residual /= residual.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_positional_dilution", attention


def prog_L10H10(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with boundary competition; in quoted dialogue, some sink and
    boundary mass instead tracks earlier discourse content and semantic matches.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_dialogue_content", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for ti, indices in enumerate(alignment):
        for si in indices:
            inverse[si].append(ti)

    terminal = np.zeros(n, dtype=bool)
    punctuation = np.zeros(n, dtype=bool)
    special_tokens = tokenizer.all_special_tokens
    for i, token in enumerate(tokens):
        if token in special_tokens:
            continue
        terminal[i] = any(char in ".?!" for char in token)
        punctuation[i] = any(doc[k].is_punct for k in alignment[i])

    # Gate the correction on a completed, double-quoted utterance.
    quoted = np.zeros(n, dtype=bool)
    inside_quote = False
    first_quote = n
    quote_count = 0
    for i, token in enumerate(tokens):
        if token in special_tokens:
            continue
        quoted[i] = inside_quote
        for char in token:
            if char in ('"', '“', '”'):
                first_quote = min(first_quote, i)
                quote_count += 1
                inside_quote = not inside_quote
                quoted[i] = True
    dialogue = quote_count >= 2 and bool(np.any(quoted & terminal))
    content_pos = ("NOUN", "PROPN", "PRON", "VERB", "ADJ")
    content = np.array([
        any(doc[k].pos_ in content_pos for k in indices)
        for indices in alignment
    ], dtype=bool)

    attention[0, 0] = 1.0
    for i in range(1, n):
        sink_mass = 0.94 * np.exp(-(i - 1) / 52.0)
        if i > 1:
            if punctuation[i]:
                sink_mass += 0.045
            if alignment[i]:
                word = doc[alignment[i][0]]
                if word.pos_ in ("CCONJ", "AUX", "DET", "ADP"):
                    sink_mass += 0.025
                elif word.pos_ in ("NOUN", "PROPN", "PRON"):
                    sink_mass -= 0.035
                if word.dep_ in ("nsubj", "nsubjpass") and i > 12:
                    sink_mass -= 0.025

        sink_mass = float(np.clip(sink_mass, 0.22, 0.975))
        positions = np.arange(1, i + 1)
        weights = 0.025 + 0.12 * np.exp(-(i - positions) / 6.0)
        weights[-1] += 0.07

        boundaries = np.flatnonzero(terminal[1:i]) + 1
        for boundary in boundaries:
            weights[boundary - 1] += 1.2 * np.exp(-(i - boundary) / 70.0)
        if len(boundaries):
            weights[boundaries[-1] - 1] += 2.2

        for si in alignment[i]:
            word = doc[si]
            if word.head.i != si:
                for target in inverse[word.head.i]:
                    if 0 < target <= i:
                        weights[target - 1] += 0.10
            for target in inverse[si]:
                if 0 < target < i:
                    weights[target - 1] += 0.08

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * weights / weights.sum()

        # Only dialogue rows change; preserve their original self-attention.
        if dialogue and i > first_quote:
            targets = np.flatnonzero(content[1:i]) + 1
            if len(targets):
                has_prior_utterance = bool(np.any(quoted[boundaries]))
                transfer = attention[i, 0] * (
                    0.40 if has_prior_utterance else 0.20
                )
                attention[i, 0] -= transfer
                for boundary in boundaries:
                    if quoted[boundary]:
                        removed = 0.88 * attention[i, boundary]
                        attention[i, boundary] -= removed
                        transfer += removed

                anchors = np.exp(-(i - targets) / 90.0)
                anchors *= np.where(quoted[targets], 1.8, 1.0)
                for k, target in enumerate(targets):
                    if any(doc[s].pos_ in ("NOUN", "PROPN")
                           for s in alignment[target]):
                        anchors[k] *= 1.5
                    if content[i]:
                        similarity = embedding_similarity(
                            tokens, i, int(target), tokenizer
                        )
                        anchors[k] *= 1.0 + 10.0 * max(
                            0.0, (similarity - 0.35) / 0.65
                        ) ** 2
                attention[i, targets] += transfer * anchors / anchors.sum()

    return "bos_sink_with_dialogue_content", attention


def prog_L10H11(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Dominant first-token attention sink, weakening with position.
    Residual attention is diffuse and mildly recency-biased."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_position_decay", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        # Position is the main predictor; syntax provides only a small correction.
        residual_odds = 0.020 + 0.00012 * i * i
        sids = alignment[i]
        if sids:
            word = doc[sids[-1]]
            if word.pos_ in ("PRON", "SCONJ"):
                residual_odds *= 1.12
            elif word.pos_ in ("AUX", "PUNCT"):
                residual_odds *= 0.90

        sink_mass = 1.0 / (1.0 + residual_odds)
        attention[i, 0] = sink_mass

        positions = np.arange(1, i + 1, dtype=np.float64)
        residual_weights = (
            0.65 / i
            + 0.35 * np.exp(-(i - positions) / 8.0)
        )
        residual_weights /= residual_weights.sum()
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual_weights

    return "bos_sink_with_position_decay", attention


def prog_L10H12(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with left phrase anchors; nominal phrases share an overly
    concentrated governor edge with their determiner and enclosing context.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    matrix = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_nominal_context", matrix

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for ti, indices in enumerate(alignment):
        for si in indices:
            if si < len(doc):
                inverse[si].append(ti)

    matrix[0, 0] = 1.0
    for i in range(1, n):
        indices = alignment[i]
        word = doc[indices[-1]] if indices else None
        pos = word.pos_ if word is not None else ""
        dep = word.dep_ if word is not None else ""

        # The sink remains substantial even far from the beginning.
        base = 0.40
        if pos in ("VERB", "AUX"):
            base = 0.55
        elif pos in ("CCONJ", "SCONJ"):
            base = 0.55
        elif pos == "PUNCT":
            base = 0.48
        elif pos in ("SPACE",):
            base = 0.57
        elif pos == "ADP":
            base = 0.46
        elif pos == "ADV":
            base = 0.49
        elif pos in ("NOUN", "PROPN"):
            base = 0.32
        elif pos in ("DET", "PRON", "ADJ"):
            base = 0.37

        anchors = np.zeros(i + 1, dtype=np.float64)
        has_governor = False
        if word is not None:
            # NP-internal material can point back to the same predicate or
            # preposition as the complete object phrase.
            phrase = word
            if dep in ("det", "poss", "amod", "compound", "nummod"):
                phrase = word.head

            governor = phrase.head
            if governor.i != phrase.i and governor.pos_ in (
                "VERB", "AUX", "ADP"
            ):
                candidates = [
                    j for j in inverse[governor.i] if 0 < j < i
                ]
                if candidates:
                    j = candidates[0]
                    distance = i - j
                    if distance <= 12:
                        strength = 3.0 * np.exp(-max(distance - 3, 0) / 7.0)
                        anchors[j] += strength
                        has_governor = True

            # Direct leftward dependencies supplement phrase-level anchoring.
            head = word.head
            if head.i != word.i:
                candidates = [j for j in inverse[head.i] if 0 < j < i]
                if candidates:
                    j = candidates[0]
                    if i - j <= 10:
                        if head.pos_ in ("VERB", "AUX", "ADP"):
                            anchors[j] += 0.9
                        elif dep in ("pobj", "obj", "dobj", "iobj", "attr"):
                            anchors[j] += 0.6

            # Maintain some continuity across subword pieces.
            pieces = [j for j in inverse[word.i] if 0 < j < i]
            if pieces:
                anchors[pieces[0]] += 0.65

            if has_governor and pos in ("DET", "PRON", "NOUN", "PROPN", "ADJ"):
                base -= 0.13

            # Prenominal modifiers without an available left governor tend
            # to retain the sink instead of selecting a future noun.
            if pos == "ADJ" and dep == "amod" and not has_governor:
                base += 0.16

        # Whitespace and opening quotation marks can act as local boundaries.
        clean = tokens[i].replace("Ġ", " ").replace("Ċ", "\n")
        if not clean.strip():
            base = max(base, 0.55)

        if i > 1:
            previous = tokens[i - 1].replace("Ġ", " ").strip()
            if previous and all(c in "\"“‘«" for c in previous):
                anchors[i - 1] += 3.5
                base = min(base, 0.36)

        sink = base + (0.944 - base) * np.exp(-(i - 1) / 2.2)
        sink = float(np.clip(sink, 0.12, 0.97))

        # A diffuse, causal recency component avoids inventing sharp edges
        # when no syntactic anchor is available.
        positions = np.arange(1, i + 1)
        residual = 0.12 * np.exp(-(i - positions) / 5.0)
        residual[-1] *= 0.65
        if i > 1:
            residual[-2] += 0.28
        residual += anchors[1:]

        matrix[i, 0] = sink
        matrix[i, 1:i + 1] = (1.0 - sink) * residual / residual.sum()

        # Special case: an anchored, determiner-bearing nominal phrase.
        # Redistribute only the dominant governor edge, never the diagonal
        # or the original recency/subword components.
        if (
            word is not None
            and has_governor
            and pos in ("DET", "ADJ", "NOUN", "PROPN")
            and phrase.pos_ in ("NOUN", "PROPN")
        ):
            determiners = [
                j
                for child in phrase.children
                if child.dep_ == "det"
                for j in inverse[child.i]
                if 0 < j < i
            ]
            sources = [
                j for j in inverse[governor.i] if 0 < j < i
            ]
            is_pp = governor.pos_ == "ADP"
            if sources and (determiners or (is_pp and dep == "det")):
                source = sources[0]
                if matrix[i, source] > 0.40:
                    moved = 0.65 * matrix[i, source]
                    matrix[i, source] -= moved

                    # PP objects also retain the preposition's lexical context.
                    outer = governor.head
                    contexts = (
                        [j for j in inverse[outer.i] if 0 < j < source]
                        if is_pp and outer.pos_ in ("VERB", "AUX", "NOUN", "PROPN")
                        else []
                    )
                    if contexts:
                        matrix[i, contexts[0]] += 0.50 * moved
                        matrix[i, 0] += 0.35 * moved
                        if determiners:
                            matrix[i, determiners[0]] += 0.15 * moved
                        else:
                            matrix[i, 0] += 0.15 * moved
                    elif determiners:
                        matrix[i, determiners[0]] += 0.55 * moved
                        matrix[i, 0] += 0.45 * moved
                    else:
                        matrix[i, 0] += moved

    return "bos_sink_nominal_context", make_row_stochastic(matrix)


def prog_L10H13(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with positional decay and punctuation-driven resets.
    Residual attention favors recent tokens and causal syntactic anchors.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_boundary_resets", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, indices in enumerate(alignment):
        for k in indices:
            inverse[k].append(i)

    attention[0, 0] = 1.0
    last_boundary = 0

    for i in range(1, n):
        clean = tokens[i].replace("Ġ", " ").replace("Ċ", "\n")
        stripped = clean.strip()
        whitespace = not stripped
        punctuation = bool(stripped) and all(
            not c.isalnum() and c != "_" for c in stripped
        )

        words = [doc[k] for k in alignment[i]]
        word = next((w for w in words if not w.is_space), None)
        pos = word.pos_ if word is not None else ""
        dep = word.dep_ if word is not None else ""

        sink = 0.25 + 0.52 * np.exp(-max(i - 2, 0) / 11.0)
        if pos in ("NOUN", "PROPN"):
            sink -= 0.08
        elif pos in ("VERB", "AUX"):
            sink += 0.035
        elif pos in ("PRON", "DET", "CCONJ", "SCONJ"):
            sink += 0.055

        if dep in ("nsubj", "nsubjpass") and i - last_boundary <= 3:
            sink += 0.10

        if punctuation:
            sink = 0.44 + 0.44 * np.exp(-i / 32.0)
            if any(c in ".!?" for c in stripped):
                sink += 0.025
            if any(c in "\"'“”‘’" for c in stripped):
                sink -= 0.18
        elif whitespace:
            sink = 0.43 + 0.43 * np.exp(-i / 30.0)

        if i == 1:
            sink = 0.967

        sink = float(np.clip(sink, 0.12, 0.98))
        attention[i, 0] = sink

        indices = np.arange(1, i + 1)
        distance = i - indices
        weights = (
            0.65 * np.exp(-distance / 3.5)
            + 0.25 * np.exp(-distance / 13.0)
            + 0.04
        )
        weights[-1] *= 0.65

        if last_boundary > 0:
            weights[last_boundary - 1] += 0.45

        if word is not None:
            head_indices = [
                j for j in inverse[word.head.i] if 0 < j <= i
            ]
            if word.head.i != word.i and head_indices:
                j = head_indices[0]
                weights[j - 1] += 0.85

            own_indices = [j for j in inverse[word.i] if 0 < j < i]
            if own_indices:
                weights[own_indices[-1] - 1] += 0.55

        attention[i, 1:i + 1] = (1.0 - sink) * weights / weights.sum()

        if punctuation and any(c in ",;:.!?" for c in stripped):
            last_boundary = i

    return "bos_sink_with_boundary_resets", attention


def prog_L10H14(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with a decaying initial-position boost.
    Residual attention favors recent tokens and nearby syntactic anchors.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    matrix = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_syntax", matrix

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    representatives = []

    for i, indices in enumerate(alignment):
        representative = None
        for k in indices:
            inverse[k].append(i)
            if representative is None or (
                doc[representative].is_space and not doc[k].is_space
            ):
                representative = k
        representatives.append(representative)

    matrix[0, 0] = 1.0
    for i in range(1, n):
        weights = np.zeros(i + 1, dtype=np.float64)
        positions = np.arange(1, i + 1)
        distances = i - positions
        weights[1:] = (
            0.65 * np.exp(-distances / 3.5)
            + 0.12 / np.sqrt(distances + 1.0)
        )

        si = representatives[i]
        word = doc[si] if si is not None else None
        sink = 0.435 + 0.435 * np.exp(-(i - 1) / 1.95)
        anchor_strength = 0.0

        if word is not None:
            if word.is_punct:
                sink += 0.035
            elif word.is_space:
                sink += 0.055
            elif word.pos_ in ("DET", "CCONJ", "SCONJ"):
                sink += 0.025

            head = word.head
            if head.i != word.i:
                candidates = [j for j in inverse[head.i] if 0 < j < i]
                if candidates:
                    j = candidates[-1]
                    distance = i - j
                    strength = 0.65 * np.exp(-(distance - 1) / 5.0)
                    if word.dep_ in ("dobj", "obj", "attr", "oprd", "acomp"):
                        strength *= 1.7
                    elif word.dep_ in ("compound", "poss"):
                        strength *= 1.3
                    weights[j] += strength
                    anchor_strength += strength

            # Predicates can point backward to their overt subject.
            if word.pos_ in ("VERB", "AUX", "ADJ"):
                for child in word.children:
                    if child.dep_ not in ("nsubj", "nsubjpass", "csubj"):
                        continue
                    candidates = [j for j in inverse[child.i] if 0 < j < i]
                    if candidates:
                        j = candidates[-1]
                        strength = 0.8 * np.exp(-(i - j - 1) / 4.0)
                        if child.pos_ in ("NOUN", "PROPN"):
                            strength *= 1.4
                        weights[j] += strength
                        anchor_strength += strength

            # Preserve attention within words split into multiple model tokens.
            earlier_pieces = [j for j in inverse[si] if 0 < j < i]
            if earlier_pieces:
                weights[earlier_pieces[-1]] += 0.8

        if i > 2:
            sink -= min(0.14, 0.075 * anchor_strength)

        sink = float(np.clip(sink, 0.26, 0.94))
        residual = weights[1:].sum()
        matrix[i, 0] = sink
        matrix[i, 1:i + 1] = (1.0 - sink) * weights[1:] / residual

    return "bos_sink_with_local_syntax", make_row_stochastic(matrix)


def prog_L10H15(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with gradually declining mass as context grows.
    Residual attention is diffuse, with a weak preference for recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_position_decay", attention

    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.97 / (1.0 + 0.011 * i)
        attention[i, 0] = sink_mass

        distances = i - np.arange(1, i + 1, dtype=np.float64)
        residual_weights = 0.75 + 0.25 * np.exp(-distances / 16.0)
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * residual_weights / residual_weights.sum()
        )

    return "bos_sink_position_decay", attention


def prog_L10H16(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with gradually declining positional dominance.
    Linguistic features weakly modulate the sink; residual attention is diffuse and causal.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_position_decay", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.970 - 0.100 * np.log(float(i))

        if i > 1:
            aligned = alignment[i]
            if aligned:
                word = doc[aligned[-1]]
                if word.pos_ == "PRON":
                    sink_mass -= 0.045
                elif word.pos_ == "DET":
                    sink_mass -= 0.020
                elif word.pos_ in ("VERB", "AUX"):
                    sink_mass += 0.015
                elif word.pos_ in ("CCONJ", "SCONJ"):
                    sink_mass += 0.020
                elif word.is_punct:
                    sink_mass += 0.025

            clean = tokens[i].replace("\u0120", " ").replace("\u010a", "\n")
            if clean.isspace():
                sink_mass += 0.040

        sink_mass = float(np.clip(sink_mass, 0.30, 0.98))
        attention[i, 0] = sink_mass

        # Do not infer a specific syntactic target from BOS-only observations.
        distances = i - np.arange(1, i + 1, dtype=np.float64)
        residual = 1.0 + 0.35 * np.exp(-distances / 5.0)
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual / residual.sum()

    return "bos_sink_with_position_decay", make_row_stochastic(attention)


def prog_L10H17(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with gradually declining strength across positions.
    Remaining attention is diffuse and mildly recency-biased."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_position_decay", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        # Position explains most of the observed variation; linguistic
        # adjustments are deliberately small relative to the sink prior.
        logit = 2.0 - 0.43 * np.log(float(i)) - 0.012 * i
        aligned = alignment[i] if i < len(alignment) else []
        if aligned and i > 1:
            word = doc[aligned[0]]
            if word.pos_ in ("NOUN", "PROPN", "AUX"):
                logit += 0.07
            elif word.pos_ in ("PRON", "ADV"):
                logit -= 0.08
            if word.is_punct:
                logit += 0.03

        sink_mass = 1.0 / (1.0 + np.exp(-logit))
        attention[i, 0] = sink_mass

        # The supplied edges do not identify a strong non-BOS target.
        # Use a conservative broad distribution with a weak local component.
        positions = np.arange(1, i + 1, dtype=np.float64)
        distances = i - positions
        broad = np.full(i, 1.0 / i, dtype=np.float64)
        local = np.exp(-distances / 5.0)
        local /= local.sum()
        residual = 0.8 * broad + 0.2 * local
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_position_decay", attention


def prog_L10H18(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with gradually increasing diffuse causal attention.
    Punctuation and clause boundaries strengthen the sink; syntax mildly modulates it.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_causal_dilution", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    # The supplied tokenization normally places BOS at index zero.
    has_bos = tokens[0] == tokenizer.bos_token
    attention[0, 0] = 1.0

    for i in range(1, n):
        aligned = alignment[i]
        word = doc[aligned[0]] if aligned else None
        clean = tokens[i].replace("Ġ", " ").replace("Ċ", "\n")
        stripped = clean.strip()

        # Increasing competition from ordinary keys weakens the sink slowly.
        sink = 1.0 / (1.0 + 0.066 * float(i) ** 0.90)
        correction = 0.0

        if not stripped:
            correction += 0.18
        elif stripped in (",", ";", ":"):
            correction += 0.10
        elif stripped in (".", "!", "?"):
            correction += 0.16
        elif word is not None:
            if word.pos_ == "PUNCT":
                correction += 0.035
            elif word.pos_ == "AUX":
                correction += 0.035
            elif word.pos_ == "CCONJ":
                correction += 0.055
            elif word.pos_ == "ADP":
                correction += 0.025

            if word.dep_ in ("dobj", "obj", "pobj", "attr", "oprd"):
                correction -= 0.065
            elif word.dep_ in ("nsubj", "nsubjpass") and i > 3:
                correction -= 0.035

        # Early rows are dominated by position rather than grammatical role.
        correction *= min(1.0, float(i - 1) / 5.0)
        sink = float(np.clip(sink + correction, 0.12, 0.97))

        if has_bos:
            keys = np.arange(1, i + 1)
            weights = 0.75 + 0.25 * np.exp(-(i - keys) / 8.0)
            attention[i, 0] = sink
            attention[i, 1:i + 1] = (1.0 - sink) * weights / weights.sum()
        else:
            # Without an explicit BOS, use the initial token as the sink.
            keys = np.arange(1, i + 1)
            weights = 0.75 + 0.25 * np.exp(-(i - keys) / 8.0)
            attention[i, 0] = sink
            attention[i, 1:i + 1] = (1.0 - sink) * weights / weights.sum()

    return "bos_sink_with_causal_dilution", make_row_stochastic(attention)


def prog_L10H19(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with positional decay and small linguistic corrections.
    Residual attention is diffuse and mildly biased toward recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_decay", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    first_word = next((w for w in doc if not w.is_space and not w.is_punct), None)
    nominal_opening = first_word is not None and first_word.pos_ == "DET"

    for i in range(1, n):
        clean = tokens[i].replace("\u0120", " ").replace("\u010a", "\n")
        words = [doc[k] for k in alignment[i] if k < len(doc)]
        word = max(
            words,
            key=lambda w: (not w.is_space, not w.is_punct, len(w.text)),
            default=None,
        )

        # Most of this head's visible structure is attention to position zero.
        sink = 0.22 + 0.74 * np.exp(-(i - 1) / 8.5)

        if word is not None:
            pos = word.pos_
            dep = word.dep_

            if nominal_opening and pos in ("NOUN", "PROPN", "ADJ"):
                sink += 0.065 * np.exp(-(i - 2) / 6.0)

            if pos in ("DET", "ADP"):
                sink += 0.045
            elif pos == "AUX":
                sink += 0.035
            elif pos == "CCONJ":
                sink += 0.075
            elif pos == "ADV":
                sink -= 0.035

            if dep in ("obj", "dobj", "pobj", "attr") and i > 3:
                sink -= 0.035

            if word.is_punct:
                if "," in clean or ";" in clean or ":" in clean:
                    sink += 0.17
                else:
                    sink += 0.065

            if word.is_sent_start and i > 1 and not word.is_punct:
                sink += 0.16 * np.exp(-i / 80.0)

        if clean and clean.isspace():
            sink += 0.15

        # The first lexical token has almost no competing context.
        if i == 1:
            sink = 0.955
            if word is not None and word.pos_ == "PRON":
                sink = 0.965

        sink = float(np.clip(sink, 0.16, 0.97))
        attention[i, 0] = sink

        # No non-BOS destination is supported strongly by the examples:
        # distribute the remaining mass broadly with a weak recency prior.
        positions = np.arange(1, i + 1)
        residual = 0.55 + np.exp(-(i - positions) / 6.0)
        attention[i, 1:i + 1] = (1.0 - sink) * residual / residual.sum()

    return "bos_sink_with_decay", attention


def prog_L10H20(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with position-dependent dilution and weak linguistic modulation.
    Residual attention spreads over causal context, favoring recent content tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_context_dilution", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    pos = [""] * n
    dep = [""] * n
    punctuation = np.zeros(n, dtype=bool)
    whitespace = np.zeros(n, dtype=bool)

    for i in range(n):
        if alignment[i]:
            word = doc[alignment[i][0]]
            pos[i] = word.pos_
            dep[i] = word.dep_
            punctuation[i] = word.is_punct
            whitespace[i] = word.is_space
        else:
            clean = tokens[i].replace("Ġ", " ").replace("Ċ", "\n")
            whitespace[i] = bool(clean) and clean.isspace()

    attention[0, 0] = 1.0
    key_strength = np.ones(n, dtype=np.float64)
    for j in range(1, n):
        if pos[j] in ("NOUN", "PROPN"):
            key_strength[j] = 1.35
        elif pos[j] in ("VERB", "ADJ"):
            key_strength[j] = 1.10
        elif punctuation[j] or whitespace[j]:
            key_strength[j] = 0.65

    for i in range(1, n):
        # Growing context competes with a persistent, strong BOS attractor.
        competition = 0.052 * (i ** 0.94)
        modulation = 0.0
        if pos[i] in ("CCONJ", "SCONJ", "ADP"):
            modulation += 0.22
        elif pos[i] in ("NOUN", "PROPN"):
            modulation -= 0.12
        elif pos[i] in ("AUX", "DET"):
            modulation += 0.08
        if punctuation[i]:
            modulation += 0.12
        if whitespace[i]:
            modulation += 0.10

        sink_mass = 1.0 / (1.0 + competition * np.exp(-modulation))

        indices = np.arange(1, i + 1)
        distances = i - indices
        residual = key_strength[1:i + 1] * (
            0.75 + 0.25 * np.exp(-distances / 8.0)
        )

        # Only a weak structural preference: no evidence for a dedicated
        # dependency-routing head beyond the dominant BOS sink.
        if alignment[i]:
            word = doc[alignment[i][0]]
            head_index = word.head.i
            for j in range(1, i + 1):
                if head_index in alignment[j]:
                    residual[j - 1] *= 1.15

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * residual / residual.sum()
        )

    return "bos_sink_with_context_dilution", attention


def prog_L10H21(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with weak diffuse and recency-weighted causal leakage.
    Sink dominance gradually decreases as more competing keys become available.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    for i in range(n):
        attention[i, 0] = 1.0
        if i > 0:
            distances = i - np.arange(1, i + 1, dtype=np.float64)
            recent = np.exp(-distances / 4.0)
            recent /= recent.sum()
            attention[i, 1:i + 1] = 0.0008 + 0.008 * recent

    return "bos_attention_sink", make_row_stochastic(attention)


def prog_L10H22(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Dominant first-token/BOS attention sink with mild positional decay.
    Remaining attention is diffuse and weakly biased toward recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_diffuse_residual", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        sink_mass = 0.86 + 0.115 * np.exp(-(i - 1) / 20.0)
        attention[i, 0] = sink_mass

        positions = np.arange(1, i + 1, dtype=np.float64)
        residual = 0.7 / i + 0.3 * (
            np.exp(-(i - positions) / 6.0)
            / np.exp(-(i - positions) / 6.0).sum()
        )
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_diffuse_residual", attention


def prog_L10H23(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, with mild positional decay and punctuation reinforcement.
    Residual attention is diffuse and weakly recency-biased.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_weak_recency", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.80 + 0.19 * np.exp(-(i - 1) / 18.0)
        aligned = alignment[i]
        surface = tokens[i].replace("\u0120", " ").replace("\u010a", "\n")

        if surface.isspace():
            sink_mass += 0.045
        elif aligned:
            word = doc[aligned[-1]]
            if word.is_punct:
                sink_mass += 0.065
            elif word.pos_ in ("AUX", "CCONJ", "DET", "PART"):
                sink_mass += 0.015
            elif word.pos_ in ("NOUN", "PROPN"):
                sink_mass -= 0.025

        if i == 1:
            sink_mass = 0.99
        sink_mass = float(np.clip(sink_mass, 0.70, 0.993))

        distances = i - np.arange(1, i + 1)
        residual = 0.65 + 0.35 * np.exp(-distances / 6.0)
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual / residual.sum()
        attention[i, 0] = sink_mass

    return "bos_sink_with_weak_recency", attention


def prog_L11H0(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with position-dependent decay and boundary boosts.
    Residual attention is diffuse and mildly favors nearby syntactic context.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_boundary_boosts", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special_tokens = tokenizer.all_special_tokens

    representatives = []
    for indices in alignment:
        candidates = [doc[k] for k in indices if not doc[k].is_space]
        representatives.append(candidates[0] if candidates else None)

    attention[0, 0] = 1.0

    for i in range(1, n):
        word = representatives[i]
        clean = tokens[i].replace("Ġ", " ").replace("Ċ", "\n")
        stripped = clean.strip()
        pos = word.pos_ if word is not None else ""

        if i == 1:
            sink = 0.960
            if pos in ("PRON", "DET"):
                sink = 0.975 if pos == "PRON" else 0.948
        else:
            logit = 2.25 - 0.94 * np.log(float(i))

            if pos == "AUX":
                logit += 0.45
            elif pos == "VERB":
                logit += 0.25
            elif pos == "PRON":
                logit += 0.20
            elif pos == "DET":
                logit += 0.12
            elif pos == "ADJ":
                logit -= 0.20
            elif pos == "ADP":
                logit -= 0.15
            elif pos == "ADV":
                logit -= 0.10

            if stripped and all(c in ".,;:!?\"'“”‘’()-—" for c in stripped):
                if "." in stripped:
                    logit += 1.70
                elif "," in stripped or ";" in stripped or ":" in stripped:
                    logit += 0.70
                elif "!" in stripped or "?" in stripped:
                    logit += 0.50
                else:
                    logit -= 0.15

            if not stripped and tokens[i] not in special_tokens:
                logit += 2.30

            if word is not None and word.is_sent_start:
                logit += 0.35

            sink = float(1.0 / (1.0 + np.exp(-logit)))

        attention[i, 0] = sink

        positions = np.arange(1, i + 1)
        residual = 1.0 / np.power(i - positions + 1.0, 0.55)
        residual[-1] *= 0.65

        if word is not None:
            for j in range(1, i + 1):
                previous = representatives[j]
                if previous is None:
                    continue
                if previous.i == word.head.i and previous.i != word.i:
                    residual[j - 1] *= 1.35
                if previous.is_punct:
                    residual[j - 1] *= 0.75

        attention[i, 1:i + 1] = (1.0 - sink) * residual / residual.sum()

    return "bos_sink_with_boundary_boosts", attention


def prog_L11H1(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with gradually decreasing dominance over position.
    Remaining attention is diffuse and causal, with a mild recency preference.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_position_decay", attention

    attention[0, 0] = 1.0

    for i in range(1, n):
        # More available keys gradually dilute the initial attention sink.
        sink_mass = 1.0 / (1.04 + 0.023 * (i - 1))
        attention[i, 0] = sink_mass

        distances = i - np.arange(1, i + 1, dtype=np.float64)
        background = (
            0.75 / i
            + 0.25
            * np.exp(-distances / 8.0)
            / np.exp(-distances / 8.0).sum()
        )
        attention[i, 1:i + 1] = (1.0 - sink_mass) * background

    return "bos_sink_with_position_decay", attention


def prog_L11H2(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with positional decay; nominal coordination additionally retrieves
    the earlier conjunct, transferring only BOS mass and preserving self-attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_nominal_coordination", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        mapped = alignment[i]
        word = doc[mapped[0]] if mapped else None

        # Fixed absolute-position decay, independent of total sequence length.
        sink_odds = 11.0 / (1.0 + 0.22 * i) ** 1.15
        correction = 0.0

        if word is not None:
            if word.pos_ == "PRON":
                correction += 0.30
            elif word.pos_ == "DET":
                correction -= 0.24
            elif word.pos_ in ("AUX", "ADV"):
                correction += 0.10
            elif word.pos_ == "ADP":
                correction -= 0.08
            elif word.pos_ == "PUNCT":
                correction -= 0.12

            if word.dep_ in ("nsubj", "nsubjpass"):
                correction += 0.05

        sink_odds *= np.exp(correction)
        sink_probability = sink_odds / (1.0 + sink_odds)

        # Preserve the original diffuse causal residual.
        distances = i - np.arange(1, i + 1)
        residual = 0.70 + 0.30 * np.exp(-distances / 8.0)

        if word is not None:
            head_index = word.head.i
            for j in range(1, i + 1):
                if head_index in alignment[j] and head_index != word.i:
                    residual[j - 1] *= 1.12

        attention[i, 0] = sink_probability
        attention[i, 1:i + 1] = (
            (1.0 - sink_probability) * residual / residual.sum()
        )

        # Special case: nominal conjuncts retrieve the earlier coordinated item.
        # Also handle a coordinator attached to the incoming nominal conjunct.
        conjunct = word
        if word is not None and word.pos_ == "CCONJ":
            conjunct = word.head

        if (
            conjunct is not None
            and conjunct.dep_ == "conj"
            and conjunct.pos_ in ("NOUN", "PROPN")
            and conjunct.head.pos_ in ("NOUN", "PROPN")
            and conjunct.head.i < conjunct.i
        ):
            targets = [
                j for j in range(1, i)
                if conjunct.head.i in alignment[j]
            ]
            if targets:
                transfer = min(0.24, 0.50 * attention[i, 0])
                attention[i, 0] -= transfer
                attention[i, targets] += transfer / len(targets)

    return "bos_sink_nominal_coordination", attention


def prog_L11H3(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with position-dependent decay and modest linguistic modulation.
    Remaining attention is diffuse, with a weak recency preference.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_decay", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special_tokens = tokenizer.all_special_tokens

    attention[0, 0] = 1.0
    for i in range(1, n):
        sink_mass = 0.34 + 0.64 * np.exp(-(i - 1) / 12.0)
        modulation = 0.0

        aligned = alignment[i]
        if aligned and tokens[i] not in special_tokens:
            word = doc[aligned[-1]]
            if word.pos_ == "PROPN":
                modulation += 0.12
            elif word.pos_ == "NOUN":
                modulation += 0.075
            elif word.pos_ == "DET":
                modulation += 0.035
            elif word.pos_ == "PRON":
                modulation -= 0.035
            elif word.pos_ == "VERB":
                modulation -= 0.045

            if word.ent_type_:
                modulation += 0.025
            if word.pos_ == "PUNCT":
                modulation -= 0.025

        # Keep the strong early positional signature largely intact.
        sink_mass += modulation * (1.0 - np.exp(-i / 4.0))
        sink_mass = float(np.clip(sink_mass, 0.20, 0.985))
        attention[i, 0] = sink_mass

        positions = np.arange(1, i + 1, dtype=np.float64)
        residual = 0.65 / i + 0.35 * np.exp(-(i - positions) / 6.0)
        residual /= residual.sum()
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_decay", attention


def prog_L11H4(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with position-dependent dilution.
    Linguistic features weakly modulate the sink; residual attention is diffuse and local.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_positional_dilution", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        # The sink dominates initially and remains substantial at long distances.
        sink_mass = 0.42 + 0.555 * np.exp(-(i - 1) / 12.0)

        aligned = alignment[i]
        if aligned and i > 1:
            word = doc[aligned[0]]
            if word.pos_ in ("NOUN", "DET", "ADP"):
                sink_mass += 0.018
            elif word.pos_ in ("VERB", "AUX", "PRON"):
                sink_mass -= 0.025
            elif word.pos_ == "PROPN":
                sink_mass -= 0.035

            # Early nominal modifiers often retain particularly strong BOS attention.
            if i <= 7 and word.dep_ in ("amod", "compound", "det"):
                sink_mass += 0.020

        sink_mass = np.clip(sink_mass, 0.30, 0.985)

        # The examples establish the sink, not a specific secondary target.
        # Spread the remaining mass with a conservative recency preference.
        positions = np.arange(1, i + 1)
        residual = 0.30 + np.exp(-(i - positions) / 7.0)
        residual /= residual.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_positional_dilution", attention


def prog_L11H5(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Hypothesis: a first-token attention sink, strongest near the beginning,
    with mild linguistic modulation and diffuse, recency-biased residual attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_sink_with_decay", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.62 + 0.32 * np.exp(-(i - 1) / 12.0)

        aligned = alignment[i] if i < len(alignment) else []
        if aligned:
            word = doc[aligned[0]]
            if word.pos_ in ("NOUN", "PROPN"):
                sink_mass += 0.015
            elif word.pos_ in ("PUNCT", "PART"):
                sink_mass -= 0.025
            if word.is_sent_start and i > 1:
                sink_mass += 0.025

        sink_mass = float(np.clip(sink_mass, 0.52, 0.97))
        attention[i, 0] = sink_mass

        # No non-sink target is established by the examples: retain a broad
        # causal background with only a modest preference for recent tokens.
        distances = i - np.arange(1, i + 1)
        recent = np.exp(-distances / 6.0)
        recent /= recent.sum()
        residual = 0.7 / i + 0.3 * recent
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "first_token_sink_with_decay", attention


def prog_L11H6(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with gradually decreasing mass as the prefix grows.
    Linguistic features weakly modulate the sink; remaining attention is diffuse.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_prefix_decay", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        # Increasing competition from available non-sink keys explains the
        # strong early BOS preference and its gradual attenuation.
        competition = 0.030 * (i ** 1.10)

        sids = alignment[i]
        if sids:
            word = doc[sids[-1]]
            if word.pos_ in ("AUX", "DET", "CCONJ", "SCONJ"):
                competition *= 0.92
            elif word.pos_ in ("VERB", "ADJ"):
                competition *= 1.08

        sink_mass = 1.0 / (1.0 + competition)
        attention[i, 0] = sink_mass

        # The examples constrain BOS weights, not individual residual edges;
        # use a broad causal distribution with only a mild recency bias.
        distances = i - np.arange(1, i + 1, dtype=np.float64)
        residual = 0.75 + 0.25 * np.exp(-distances / 8.0)
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * residual / residual.sum()
        )

    return "bos_sink_with_prefix_decay", attention


def prog_L11H7(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Dominant beginning-of-sequence attention sink, weakening with position.
    Remaining attention is diffuse and mildly biased toward recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
